# Local-only Firefox/Chrome authentication synchronization.  The WebExtension sends
# structured cookies through Native Messaging to a Unix-domain socket;
# raw credential values are never logged.
AUTH_SYNC_ENABLED = _ve_env_flag("AUTH_SYNC_ENABLED", "1")
AUTH_SYNC_NATIVE_HOST_NAME = os.getenv(
    "AUTH_SYNC_NATIVE_HOST_NAME", "com.voice_edge.auth_bridge"
).strip()
AUTH_SYNC_NATIVE_HOST_DIR = Path.home() / ".voice-edge" / "native-host"
AUTH_SYNC_NATIVE_HOST_PATH = AUTH_SYNC_NATIVE_HOST_DIR / "auth_bridge.py"
AUTH_SYNC_BRIDGE_SOURCE = '#!/usr/bin/env python3\nimport json\nimport os\nimport socket\nimport struct\nimport sys\nimport threading\nimport time\n\nSOCKET_PATH = os.path.realpath(os.path.expanduser(\n    os.environ.get("FIREFOX_AUTH_SYNC_SOCKET", "~/.voice-edge/auth-sync.sock")\n))\nMAX_NATIVE_MESSAGE = 4 * 1024 * 1024\n_WRITE_LOCK = threading.Lock()\n_STOP = threading.Event()\n_SOCKET_LOCK = threading.RLock()\n_SOCKET = None\n\n\ndef _read_exact(stream, size):\n    chunks = []\n    remaining = int(size)\n    while remaining:\n        data = stream.read(remaining)\n        if not data:\n            return None\n        chunks.append(data)\n        remaining -= len(data)\n    return b"".join(chunks)\n\n\ndef _read_native_message():\n    header = _read_exact(sys.stdin.buffer, 4)\n    if header is None:\n        return None\n    length = struct.unpack("=I", header)[0]\n    if length <= 0 or length > MAX_NATIVE_MESSAGE:\n        raise ValueError("invalid native message length")\n    payload = _read_exact(sys.stdin.buffer, length)\n    if payload is None:\n        return None\n    value = json.loads(payload.decode("utf-8"))\n    if not isinstance(value, dict):\n        raise ValueError("native message must be a JSON object")\n    return value\n\n\ndef _send_native_message(message):\n    payload = json.dumps(message, ensure_ascii=False, separators=(",", ":")).encode("utf-8")\n    if len(payload) > MAX_NATIVE_MESSAGE:\n        payload = json.dumps({"type": "AUTH_ERROR", "message": "native response is too large"}).encode("utf-8")\n    with _WRITE_LOCK:\n        sys.stdout.buffer.write(struct.pack("=I", len(payload)))\n        sys.stdout.buffer.write(payload)\n        sys.stdout.buffer.flush()\n\n\ndef _set_socket(sock):\n    global _SOCKET\n    with _SOCKET_LOCK:\n        _SOCKET = sock\n\n\ndef _get_socket():\n    with _SOCKET_LOCK:\n        return _SOCKET\n\n\ndef _discard_socket(sock):\n    global _SOCKET\n    with _SOCKET_LOCK:\n        if _SOCKET is sock:\n            _SOCKET = None\n    try:\n        sock.close()\n    except OSError:\n        pass\n\n\ndef _connect_socket():\n    while not _STOP.is_set():\n        existing = _get_socket()\n        if existing is not None:\n            return existing\n        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n        try:\n            sock.connect(SOCKET_PATH)\n            sock.settimeout(1.0)\n            _set_socket(sock)\n            return sock\n        except OSError:\n            try:\n                sock.close()\n            except OSError:\n                pass\n            time.sleep(1.0)\n    return None\n\n\ndef _socket_reader():\n    buffer = b""\n    while not _STOP.is_set():\n        sock = _connect_socket()\n        if sock is None:\n            return\n        try:\n            data = sock.recv(65536)\n            if not data:\n                raise OSError("Voice Edge auth socket closed")\n            buffer += data\n            if len(buffer) > MAX_NATIVE_MESSAGE:\n                raise ValueError("Voice Edge socket response is too large")\n            while b"\\n" in buffer:\n                line, buffer = buffer.split(b"\\n", 1)\n                if not line.strip():\n                    continue\n                _send_native_message(json.loads(line.decode("utf-8")))\n        except socket.timeout:\n            continue\n        except Exception as exc:\n            _discard_socket(sock)\n            buffer = b""\n            if not isinstance(exc, OSError):\n                _send_native_message({"type": "AUTH_ERROR", "message": str(exc).replace("\\n", " ")[:500]})\n\n\ndef _send_to_voice_edge(message):\n    payload = json.dumps(message, ensure_ascii=False, separators=(",", ":")).encode("utf-8") + b"\\n"\n    for _attempt in range(2):\n        sock = _connect_socket()\n        if sock is None:\n            break\n        try:\n            sock.sendall(payload)\n            return True\n        except OSError:\n            _discard_socket(sock)\n    _send_native_message({"type": "AUTH_ERROR", "message": "Voice Edge auth socket is unavailable"})\n    return False\n\n\ndef main():\n    threading.Thread(target=_socket_reader, name="voice-edge-auth-socket-reader", daemon=True).start()\n    try:\n        while True:\n            try:\n                message = _read_native_message()\n            except Exception as exc:\n                _send_native_message({"type": "AUTH_ERROR", "message": str(exc).replace("\\n", " ")[:500]})\n                continue\n            if message is None:\n                break\n            _send_to_voice_edge(message)\n    finally:\n        _STOP.set()\n        sock = _get_socket()\n        if sock is not None:\n            _discard_socket(sock)\n\n\nif __name__ == "__main__":\n    main()\n'


# Firefox Native Messaging bootstrap. Firefox extensions cannot install native
# hosts themselves, so Voice Edge installs/repairs its user-local stdio bridge
# and host manifest during service startup.
FIREFOX_AUTH_SYNC_BOOTSTRAP_ENABLED = _ve_env_flag(
    "FIREFOX_AUTH_SYNC_BOOTSTRAP_ENABLED", "1"
)
FIREFOX_AUTH_SYNC_SOCKET = os.path.realpath(
    os.path.expanduser(
        os.getenv(
            "FIREFOX_AUTH_SYNC_SOCKET",
            "~/.voice-edge/auth-sync.sock",
        )
    )
)
FIREFOX_AUTH_SYNC_MAX_MESSAGE_BYTES = max(
    65536,
    int(os.getenv("FIREFOX_AUTH_SYNC_MAX_MESSAGE_BYTES", "2097152")),
)
FIREFOX_AUTH_SYNC_EXTENSION_ID = os.getenv(
    "FIREFOX_AUTH_SYNC_EXTENSION_ID", "voice-edge-auth-sync@local"
).strip()
FIREFOX_AUTH_SYNC_MANIFEST_PATH = (
    Path.home()
    / "Library"
    / "Application Support"
    / "Mozilla"
    / "NativeMessagingHosts"
    / f"{AUTH_SYNC_NATIVE_HOST_NAME}.json"
)


# Chrome/Chromium Native Messaging bootstrap. The bridge script, Unix socket
# and AuthSyncServer are shared with Firefox verbatim; only the host manifest
# differs (Chrome keys the allow-list by extension ORIGIN via `allowed_origins`
# instead of Firefox's `allowed_extensions`, and installs under a different
# per-user directory). The Chrome extension ID is fixed by the `key` field in
# manifest.chrome.json, so it can be pinned here.
CHROME_AUTH_SYNC_BOOTSTRAP_ENABLED = _ve_env_flag(
    "CHROME_AUTH_SYNC_BOOTSTRAP_ENABLED", "1"
)
CHROME_AUTH_SYNC_EXTENSION_ID = os.getenv(
    "CHROME_AUTH_SYNC_EXTENSION_ID", "lbhjpomjdikihplfkgdmdkgjdjnklmak"
).strip()
# Chrome and Chromium read native-host manifests from parallel per-user dirs.
# Install into every channel present so the bridge works regardless of which
# Chromium-family browser loads the extension.
CHROME_AUTH_SYNC_MANIFEST_DIRS = (
    Path.home()
    / "Library"
    / "Application Support"
    / "Google"
    / "Chrome"
    / "NativeMessagingHosts",
    Path.home()
    / "Library"
    / "Application Support"
    / "Chromium"
    / "NativeMessagingHosts",
)


def _write_private_file_if_changed(path: Path, content: bytes, mode: int) -> bool:
    """Atomically create/update one user-private bootstrap file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(path.parent, 0o700)
    except OSError:
        pass
    try:
        current = path.read_bytes()
    except FileNotFoundError:
        current = None
    changed = current != content
    if changed:
        temp_path = path.with_name(
            f".{path.name}.{os.getpid()}.{secrets.token_hex(4)}.tmp"
        )
        try:
            with open(temp_path, "wb") as handle:
                handle.write(content)
                handle.flush()
                os.fsync(handle.fileno())
            os.chmod(temp_path, mode)
            os.replace(temp_path, path)
        finally:
            try:
                temp_path.unlink()
            except FileNotFoundError:
                pass
    try:
        os.chmod(path, mode)
    except OSError:
        pass
    return changed


def _write_native_host_manifest(manifest: dict, manifest_path: Path) -> bool:
    """Serialize and atomically publish one browser's host manifest."""
    return _write_private_file_if_changed(
        manifest_path,
        (
            json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8"),
        0o600,
    )


def ensure_auth_sync_native_host() -> dict:
    """Install or repair the per-user Native Messaging host for Firefox AND
    Chromium-family browsers.

    The stdio bridge script and the Unix socket it talks to are identical
    across browsers, so it is written once. Only the host manifest differs:

      * Firefox keys the allow-list by add-on ID   (`allowed_extensions`) and
        installs under .../Mozilla/NativeMessagingHosts/.
      * Chrome/Chromium key it by extension ORIGIN (`allowed_origins`) and
        install under .../Google/Chrome|Chromium/NativeMessagingHosts/.

    The historical name is kept so the startup call site is unchanged.
    """
    ff_enabled = bool(AUTH_SYNC_ENABLED and FIREFOX_AUTH_SYNC_BOOTSTRAP_ENABLED)
    chrome_enabled = bool(AUTH_SYNC_ENABLED and CHROME_AUTH_SYNC_BOOTSTRAP_ENABLED)
    supported = sys.platform == "darwin"
    result = {
        "enabled": bool(ff_enabled or chrome_enabled),
        "supported": supported,
        "changed": False,
        "host_path": str(AUTH_SYNC_NATIVE_HOST_PATH),
        # Back-compat: this key historically held the single Firefox manifest
        # path. Keep it pointing at Firefox; per-browser detail is in
        # `manifest_paths` below.
        "manifest_path": str(FIREFOX_AUTH_SYNC_MANIFEST_PATH),
        "firefox": {"enabled": ff_enabled, "changed": False},
        "chrome": {"enabled": chrome_enabled, "changed": False, "manifest_paths": []},
    }
    if not (ff_enabled or chrome_enabled):
        _auth_log.info("Auth sync native host bootstrap is disabled")
        return result
    if not supported:
        _auth_log.warning(
            "Auth sync native host auto-install supports macOS only; platform=%s",
            sys.platform,
        )
        return result

    # The bridge script is shared, so write it once for whichever browser(s)
    # are enabled.
    bridge_changed = _write_private_file_if_changed(
        AUTH_SYNC_NATIVE_HOST_PATH,
        AUTH_SYNC_BRIDGE_SOURCE.encode("utf-8"),
        0o700,
    )

    any_changed = bool(bridge_changed)

    # --- Firefox host manifest -------------------------------------------
    if ff_enabled:
        if not FIREFOX_AUTH_SYNC_EXTENSION_ID:
            raise RuntimeError("FIREFOX_AUTH_SYNC_EXTENSION_ID cannot be empty")
        ff_manifest = {
            "name": AUTH_SYNC_NATIVE_HOST_NAME,
            "description": "Local Voice Edge authentication bridge",
            "path": str(AUTH_SYNC_NATIVE_HOST_PATH),
            "type": "stdio",
            "allowed_extensions": [FIREFOX_AUTH_SYNC_EXTENSION_ID],
        }
        ff_changed = _write_native_host_manifest(
            ff_manifest, FIREFOX_AUTH_SYNC_MANIFEST_PATH
        )
        result["firefox"]["changed"] = ff_changed
        any_changed = any_changed or ff_changed
        _auth_log.info(
            "Auth sync Firefox native host ready: changed=%s manifest=%s",
            ff_changed,
            FIREFOX_AUTH_SYNC_MANIFEST_PATH,
        )

    # --- Chrome/Chromium host manifest(s) --------------------------------
    if chrome_enabled:
        if not CHROME_AUTH_SYNC_EXTENSION_ID:
            raise RuntimeError("CHROME_AUTH_SYNC_EXTENSION_ID cannot be empty")
        chrome_manifest = {
            "name": AUTH_SYNC_NATIVE_HOST_NAME,
            "description": "Local Voice Edge authentication bridge",
            "path": str(AUTH_SYNC_NATIVE_HOST_PATH),
            "type": "stdio",
            "allowed_origins": [f"chrome-extension://{CHROME_AUTH_SYNC_EXTENSION_ID}/"],
        }
        for manifest_dir in CHROME_AUTH_SYNC_MANIFEST_DIRS:
            manifest_path = manifest_dir / f"{AUTH_SYNC_NATIVE_HOST_NAME}.json"
            chrome_changed = _write_native_host_manifest(chrome_manifest, manifest_path)
            result["chrome"]["manifest_paths"].append(str(manifest_path))
            result["chrome"]["changed"] = result["chrome"]["changed"] or chrome_changed
            any_changed = any_changed or chrome_changed
            _auth_log.info(
                "Auth sync Chrome native host ready: changed=%s manifest=%s",
                chrome_changed,
                manifest_path,
            )

    result["changed"] = any_changed
    return result


_DOUBAO_LIVE_COOKIES_LOCK = threading.RLock()
_DOUBAO_LIVE_COOKIES: list[dict] = []

# Firefox 插件在 AUTH_SNAPSHOT 顶层显式带上 ttwid（cookies API 缺失时
# 会从 document.cookie 兜底）。该值必须强制覆盖回 Camoufox，避免服务端
# 在页面导航后用 Set-Cookie 写入新的 ttwid 与 Firefox 登录态不一致，
# 进而触发豆包风控（shark_admin / 710022004）。
_DOUBAO_FORCED_TTWID_LOCK = threading.Lock()
_DOUBAO_FORCED_TTWID = ""


def _doubao_live_cookie_snapshot() -> list[dict]:
    with _DOUBAO_LIVE_COOKIES_LOCK:
        return [dict(item) for item in _DOUBAO_LIVE_COOKIES]


def _set_doubao_forced_ttwid(value: str) -> None:
    with _DOUBAO_FORCED_TTWID_LOCK:
        global _DOUBAO_FORCED_TTWID
        _DOUBAO_FORCED_TTWID = str(value or "")


def _doubao_forced_ttwid() -> str:
    """Return the ttwid that must be force-overridden into Camoufox, if any.

    Prefer the explicit value sent by the Firefox plugin; fall back to the
    ttwid contained in the live cookie snapshot.
    """
    with _DOUBAO_FORCED_TTWID_LOCK:
        explicit = _DOUBAO_FORCED_TTWID
    if explicit:
        return explicit
    for cookie in _doubao_live_cookie_snapshot():
        if cookie.get("name") == "ttwid":
            value = str(cookie.get("value") or "")
            if value:
                return value
    return ""


def _set_doubao_live_cookie_snapshot(cookies: list[dict]) -> str:
    """Validate and atomically publish a structured Firefox cookie snapshot."""
    normalized = []
    sessionid = ""
    for raw in cookies or []:
        if not isinstance(raw, dict):
            continue
        name = str(raw.get("name") or "").strip()
        value = str(raw.get("value") or "")
        domain = str(raw.get("domain") or "").strip().lower()
        path = str(raw.get("path") or "/").strip() or "/"
        if (
            not name
            or not value
            or not (domain == "doubao.com" or domain.endswith(".doubao.com"))
        ):
            continue
        item = {
            "name": name,
            "value": value,
            "domain": domain,
            "path": path,
            "secure": bool(raw.get("secure", True)),
            "httpOnly": bool(raw.get("httpOnly", False)),
        }
        same_site = str(raw.get("sameSite") or "").strip().lower()
        same_site_map = {
            "strict": "Strict",
            "lax": "Lax",
            "none": "None",
            "no_restriction": "None",
        }
        if same_site in same_site_map:
            item["sameSite"] = same_site_map[same_site]
        expires = raw.get("expirationDate")
        if expires is not None and not bool(raw.get("session", False)):
            try:
                expires = float(expires)
                if expires > time.time():
                    item["expires"] = expires
            except (TypeError, ValueError):
                pass
        normalized.append(item)
        if name == "sessionid" and not sessionid:
            sessionid = value
    if not normalized:
        raise ValueError("No valid doubao.com cookies were supplied")
    if not sessionid:
        raise ValueError("The Firefox snapshot does not contain sessionid")
    with _DOUBAO_LIVE_COOKIES_LOCK:
        _DOUBAO_LIVE_COOKIES[:] = normalized
    _browser_state_update("doubao", "auth", {"cookies": normalized})
    return sessionid


def _notify_doubao_auth_required(code: int = 710022004) -> None:
    server = globals().get("AUTH_SYNC_SERVER")
    if server is not None:
        server.notify_auth_required("doubao", int(code))


def _load_doubao_cookie_header() -> dict[str, str]:
    """Parse DOUBAO_COOKIE_HEADER without logging any cookie values."""
    stored = _browser_stored_auth("doubao").get("cookies")
    stored_values = (
        {
            str(item.get("name") or ""): str(item.get("value") or "")
            for item in stored
            if isinstance(item, dict)
        }
        if isinstance(stored, list)
        else {}
    )
    raw = os.environ.get("DOUBAO_COOKIE_HEADER", "").strip()
    if stored_values and not VOICE_EDGE_BROWSER_AUTH_ENV_PRIORITY:
        return stored_values
    if not raw:
        return stored_values
    jar = SimpleCookie()
    try:
        jar.load(raw)
    except Exception as exc:
        raise RuntimeError("DOUBAO_COOKIE_HEADER is not a valid Cookie header") from exc
    values = {
        str(name).strip(): str(morsel.value)
        for name, morsel in jar.items()
        if str(name).strip()
    }
    if not values:
        raise RuntimeError("DOUBAO_COOKIE_HEADER did not contain any cookies")
    _browser_state_update(
        "doubao",
        "auth",
        {
            "cookies": [
                {
                    "name": name,
                    "value": value,
                    "domain": ".doubao.com",
                    "path": "/",
                    "secure": True,
                    "httpOnly": False,
                }
                for name, value in values.items()
            ]
        },
    )
    return values


def _doubao_cookie_digest(value: str) -> str:
    return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()[:12]


def _load_doubao_session_ids() -> tuple[str, ...]:
    many = os.environ.get("DOUBAO_SESSION_IDS", "").strip()
    if many:
        values = many.split(",")
    else:
        explicit = os.environ.get("DOUBAO_SESSION_ID", "").strip()
        header_session = _load_doubao_cookie_header().get("sessionid", "")
        values = [explicit or header_session]
    return tuple(dict.fromkeys(value.strip() for value in values if value.strip()))


def _mask_doubao_session_id(value: str) -> str:
    return "***" if len(value) <= 12 else f"{value[:6]}...{value[-4:]}"


class DoubaoMemoryDB:
    """In-process storage adapter used by DoubaoAccountPool only."""

    def __init__(self, initial):
        self._data = initial

    async def load(self):
        return self._data

    async def save(self, data):
        self._data = data

    async def get(self):
        return self._data


def _jitter_seconds() -> float:
    low = max(0, DOUBAO_REQUEST_JITTER_MIN_MS)
    high = max(low, DOUBAO_REQUEST_JITTER_MAX_MS)
    return random.uniform(low, high) / 1000.0


class DoubaoAccount:
    """豆包账号，以 sessionid 为核心标识。"""

    def __init__(
        self,
        sessionid: str = "",
        name: str = "",
        status_code: str = "",
        last_error: str = "",
        **kwargs,
    ):
        self.sessionid = sessionid
        self.name = name or (sessionid[:8] + "..." if sessionid else "unknown")
        self.valid = bool(sessionid)  # 有 sessionid 即视为有效
        self.last_used = 0.0
        self.inflight = 0
        self.rate_limited_until = 0.0
        self.verification_required = False
        self.verification_required_at = 0.0
        self.status_code = status_code or ("valid" if self.valid else "invalid")
        self.last_error = last_error or ""
        self.last_request_started = float(
            kwargs.get("last_request_started", 0.0) or 0.0
        )
        self.last_request_finished = float(
            kwargs.get("last_request_finished", 0.0) or 0.0
        )
        self.consecutive_failures = int(kwargs.get("consecutive_failures", 0) or 0)
        self.rate_limit_strikes = int(kwargs.get("rate_limit_strikes", 0) or 0)

    def is_rate_limited(self) -> bool:
        return self.rate_limited_until > time.time()

    def is_available(self) -> bool:
        return (
            self.valid and not self.verification_required and not self.is_rate_limited()
        )

    def next_available_at(self) -> float:
        min_interval = max(0, DOUBAO_ACCOUNT_MIN_INTERVAL_MS) / 1000.0
        return max(self.rate_limited_until, self.last_request_started + min_interval)

    def get_status_code(self) -> str:
        if self.is_rate_limited():
            return "rate_limited"
        if self.valid:
            return "valid"
        if self.status_code == "banned":
            return "banned"
        if self.status_code == "auth_error":
            return "auth_error"
        return self.status_code or "invalid"

    def get_status_text(self) -> str:
        status_map = {
            "valid": "正常",
            "rate_limited": "限流",
            "banned": "封禁",
            "auth_error": "鉴权失败",
            "invalid": "失效",
            "session_expired": "Session 过期",
            "unknown": "未知",
        }
        return status_map.get(self.get_status_code(), "未知")

    def to_dict(self) -> dict:
        return {
            "sessionid": self.sessionid,
            "name": self.name,
            "status_code": self.status_code,
            "last_error": self.last_error,
            "last_request_started": self.last_request_started,
            "last_request_finished": self.last_request_finished,
            "consecutive_failures": self.consecutive_failures,
            "rate_limit_strikes": self.rate_limit_strikes,
        }


class DoubaoAccountPool:
    """豆包账号池，管理 sessionid 的获取、释放、限流等。"""

    def __init__(self, db: DoubaoMemoryDB, max_inflight: int = DOUBAO_MAX_INFLIGHT):
        self.db = db
        self.max_inflight = max_inflight
        self.accounts: list[DoubaoAccount] = []
        self._lock = asyncio.Lock()
        self._waiters: list[asyncio.Event] = []
        self._sticky_sessionid: Optional[str] = None

    async def load(self):
        data = await self.db.load()
        self.accounts = (
            [DoubaoAccount(**d) for d in data] if isinstance(data, list) else []
        )
        _doubao_log.debug(f"Loaded {len(self.accounts)} upstream account(s)")

    async def save(self):
        await self.db.save([a.to_dict() for a in self.accounts])

    async def add(self, account: DoubaoAccount):
        async with self._lock:
            # 用 sessionid 去重
            self.accounts = [
                a for a in self.accounts if a.sessionid != account.sessionid
            ]
            self.accounts.append(account)
        await self.save()

    async def remove(self, sessionid: str):
        async with self._lock:
            self.accounts = [a for a in self.accounts if a.sessionid != sessionid]
        await self.save()

    def set_max_inflight(self, value: int):
        self.max_inflight = max(1, int(value))

    async def acquire(self, exclude: set | None = None) -> Optional[DoubaoAccount]:
        """获取一个可用账号，优先选择 inflight 最少、最早就绪的。"""
        async with self._lock:
            now = time.time()
            available = [
                a
                for a in self.accounts
                if a.is_available() and (not exclude or a.sessionid not in exclude)
            ]
            if not available:
                return None

            ready = [
                a
                for a in available
                if a.inflight < self.max_inflight and a.next_available_at() <= now
            ]
            if not ready:
                return None

            ready.sort(
                key=lambda a: (
                    a.inflight,
                    a.last_request_started or 0.0,
                    a.last_used or 0.0,
                )
            )
            best = ready[0]
            best.inflight += 1
            best.last_used = now
            best.last_request_started = now
            self._sticky_sessionid = best.sessionid if len(ready) == 1 else None
            return best

    async def acquire_wait(
        self, wait_seconds: float = 60, exclude: set | None = None
    ) -> Optional[DoubaoAccount]:
        """等待获取可用账号，超时返回 None。"""
        deadline = time.time() + wait_seconds
        while True:
            acc = await self.acquire(exclude)
            if acc:
                return acc

            async with self._lock:
                candidates = [
                    a
                    for a in self.accounts
                    if a.valid
                    and not a.verification_required
                    and (not exclude or a.sessionid not in exclude)
                ]
                if not candidates:
                    return None
                next_ready_at = min(
                    (a.next_available_at() for a in candidates),
                    default=time.time(),
                )

            remaining = deadline - time.time()
            if remaining <= 0:
                return None

            evt = asyncio.Event()
            self._waiters.append(evt)
            wait_timeout = min(remaining, max(0.05, next_ready_at - time.time() + 0.05))
            try:
                await asyncio.wait_for(evt.wait(), timeout=wait_timeout)
            except asyncio.TimeoutError:
                pass
            finally:
                if evt in self._waiters:
                    self._waiters.remove(evt)

    async def acquire_wait_for_sessionid(
        self, sessionid: str, wait_seconds: float = 60
    ):
        deadline = time.time() + wait_seconds
        while True:
            async with self._lock:
                now = time.time()
                account = next(
                    (a for a in self.accounts if a.sessionid == sessionid), None
                )
                if account is None or not account.is_available():
                    return None
                if (
                    account.inflight < self.max_inflight
                    and account.next_available_at() <= now
                ):
                    account.inflight += 1
                    account.last_used = now
                    account.last_request_started = now
                    return account
                next_ready_at = account.next_available_at()
            remaining = deadline - time.time()
            if remaining <= 0:
                return None
            await asyncio.sleep(
                min(remaining, max(0.05, next_ready_at - time.time() + 0.05))
            )

    async def pace_request(self, acc: DoubaoAccount) -> float:
        """Apply one request jitter and record the actual send-ready time.

        Account acquisition enforces the minimum inter-request interval. This
        method owns the only randomized delay, so browser and account clocks
        cannot drift because of independent jitter values.
        """
        delay = _request_jitter_seconds()
        if delay > 0:
            await asyncio.sleep(delay)
        async with self._lock:
            acc.last_request_started = time.time()
        return delay

    def release(self, acc: DoubaoAccount):
        """释放账号，减少 inflight 计数。"""
        acc.inflight = max(0, acc.inflight - 1)
        acc.last_request_finished = time.time()
        if self._waiters:
            evt = self._waiters.pop(0)
            evt.set()

    def mark_invalid(
        self, acc: DoubaoAccount, reason: str = "invalid", error_message: str = ""
    ):
        """标记账号为不可用。"""
        acc.valid = False
        acc.status_code = reason or "invalid"
        acc.last_error = error_message or acc.last_error
        acc.consecutive_failures += 1
        if self._sticky_sessionid == acc.sessionid:
            self._sticky_sessionid = None
        _doubao_log.warning(f"[账号] {acc.name} 已标记为不可用，状态={acc.status_code}")

    def mark_verification_required(self, acc: DoubaoAccount, error_message: str = ""):
        acc.verification_required = True
        acc.verification_required_at = time.time()
        acc.rate_limited_until = max(
            acc.rate_limited_until, time.time() + DOUBAO_VERIFICATION_COOLDOWN
        )
        acc.last_error = str(error_message or "verification required")[:500]
        _doubao_log.warning(
            "[账号] %s requires Doubao web verification; automatic requests paused",
            acc.name,
        )
        _notify_doubao_auth_required(710022004)

    def mark_success(self, acc: DoubaoAccount):
        """标记账号请求成功，重置失败计数。"""
        acc.consecutive_failures = 0
        acc.rate_limit_strikes = 0
        acc.last_error = ""
        if acc.status_code == "rate_limited":
            acc.status_code = "valid"
        acc.valid = True

    def mark_rate_limited(
        self, acc: DoubaoAccount, cooldown: int | None = None, error_message: str = ""
    ):
        """标记账号被限流，设置冷却时间。"""
        acc.rate_limit_strikes += 1
        base = cooldown if cooldown is not None else DOUBAO_RATE_LIMIT_BASE_COOLDOWN
        dynamic = min(
            DOUBAO_RATE_LIMIT_MAX_COOLDOWN,
            int(base * (2 ** max(0, acc.rate_limit_strikes - 1))),
        )
        dynamic += int(_jitter_seconds())
        acc.rate_limited_until = time.time() + dynamic
        acc.status_code = "rate_limited"
        acc.last_error = error_message or acc.last_error
        if self._sticky_sessionid == acc.sessionid:
            self._sticky_sessionid = None
        _doubao_log.warning(f"[账号] {acc.name} 已限流冷却 {dynamic} 秒")

    def status(self) -> dict:
        """返回账号池状态概览。"""
        available = [a for a in self.accounts if a.is_available()]
        rate_limited = [
            a for a in self.accounts if a.get_status_code() == "rate_limited"
        ]
        invalid = [
            a
            for a in self.accounts
            if a.get_status_code() not in ("valid", "rate_limited")
        ]
        banned = [a for a in self.accounts if a.get_status_code() == "banned"]
        session_expired = [
            a for a in self.accounts if a.get_status_code() == "session_expired"
        ]
        in_use = sum(a.inflight for a in self.accounts)
        return {
            "total": len(self.accounts),
            "valid": len(available),
            "rate_limited": len(rate_limited),
            "invalid": len(invalid),
            "banned": len(banned),
            "session_expired": len(session_expired),
            "in_use": in_use,
            "max_inflight": self.max_inflight,
            "waiting": len(self._waiters),
            "account_min_interval_ms": DOUBAO_ACCOUNT_MIN_INTERVAL_MS,
        }


def _request_jitter_seconds() -> float:
    low = max(0, DOUBAO_REQUEST_JITTER_MIN_MS)
    high = max(low, DOUBAO_REQUEST_JITTER_MAX_MS)
    return random.uniform(low, high) / 1000.0


def _generate_trace_id() -> str:
    """Return the trace-parent shape used by the Doubao web client."""
    trace_id = uuid.uuid4().hex
    span_id = secrets.token_hex(8)
    return f"04-{trace_id}-{span_id}-01"


JS_STREAM_DOUBAO = (
    "async (args) => {"
    # 检测 fetch 是否被字节 JS 劫持
    "const fetchStr=window.fetch.toString().substring(0,80);"
    # 构造请求 Headers
    "const headers={"
    "'Content-Type':'application/json',"
    "'Agw-Js-Conv':'str, str',"
    "'x-flow-trace':args.trace_id"
    "};"
    # 构造 fetch 选项
    "const opts={"
    "method:'POST',"
    "headers:headers,"
    "body:args.body,"
    "credentials:'include',"
    "signal:AbortSignal.timeout(1800000)"
    "};"
    "try{"
    "const res=await fetch(args.url,opts);"
    "if(!res.ok){"
    "const t=await res.text();"
    "return{status:res.status,body:t.substring(0,2000),fetch_hook:fetchStr};}"
    # 读取完整 SSE body
    "const rdr=res.body.getReader();"
    "const dec=new TextDecoder();"
    "let body='';"
    "while(true){"
    "const{done,value}=await rdr.read();"
    "if(done)break;"
    "body+=dec.decode(value,{stream:true});}"
    "return{status:res.status,body:body,fetch_hook:fetchStr,body_len:body.length,response_meta:{x_ms_token:res.headers.has('x-ms-token'),agw_login:res.headers.get('x-tt-agw-login')||'',content_type:res.headers.get('content-type')||''},page_path:location.pathname};"
    "}catch(e){"
    "return{status:0,body:'JS error: '+e.message,fetch_hook:fetchStr};"
    "}}"
)

JS_STREAM_DOUBAO_LIVE = (
    "async (args) => {"
    "const emit=window[args.emit_name];"
    "const headers={'Content-Type':'application/json','Agw-Js-Conv':'str, str',"
    "'x-flow-trace':args.trace_id};"
    "try{"
    "const res=await fetch(args.url,{method:'POST',headers:headers,body:args.body,"
    "credentials:'include',signal:AbortSignal.timeout(1800000)});"
    "await emit({type:'meta',status:res.status,response_meta:{x_ms_token:res.headers.has('x-ms-token'),agw_login:res.headers.get('x-tt-agw-login')||'',content_type:res.headers.get('content-type')||''},page_path:location.pathname});"
    "if(!res.ok){const text=await res.text();"
    "await emit({type:'error',status:res.status,data:text.substring(0,2000)});return;}"
    "const reader=res.body.getReader();const decoder=new TextDecoder();"
    "while(true){const item=await reader.read();"
    "if(item.done)break;"
    "const text=decoder.decode(item.value,{stream:true});"
    "if(text)await emit({type:'chunk',data:text});}"
    "const tail=decoder.decode();if(tail)await emit({type:'chunk',data:tail});"
    "await emit({type:'done'});"
    "}catch(error){await emit({type:'error',status:0,data:String(error)});}"
    "}"
)


class DoubaoBrowserEngine:
    """Playwright Chromium 浏览器引擎，管理页面池并执行豆包 SSE 请求。"""

    def __init__(
        self,
        pool_size: int | None = None,
        base_url: str | None = None,
    ):
        self.pool_size = pool_size or DOUBAO_BROWSER_POOL_SIZE
        self.base_url = base_url or DOUBAO_BASE_URL
        self._browser = None
        self._playwright = None
        self._camoufox = None
        self._pages: asyncio.Queue[tuple[Any, Any]] = asyncio.Queue()
        self._started = False
        self._ready = asyncio.Event()
        # 跟踪每个 context 的 sessionid，用于检测 Cookie 变化
        self._context_sessionid: dict[int, str] = {}  # context id → sessionid
        self._injected_cookie_digests = {}
        self._stream_queues: dict[int, asyncio.Queue] = {}
        self._stream_binding_names: dict[int, str] = {}
        # Keep strong references to fire-and-forget page recovery tasks.
        # Tasks remove themselves when complete and surface unexpected errors.
        self._background_tasks: set[asyncio.Task] = set()

    # ── 生命周期 ──────────────────────────────────────────

    async def start(self):
        """Start the configured official Playwright browser engine."""
        if self._started:
            return
        try:
            await self._start_browser_backend()
        except Exception as exc:
            _doubao_log.error(
                "[Browser] backend startup failed: engine=%s error=%s",
                DOUBAO_BROWSER_ENGINE,
                exc,
            )
            if DOUBAO_BROWSER_ENGINE in {"chromium", "firefox"}:
                _doubao_log.error(
                    "[Browser] please install it with: python -m playwright install %s",
                    DOUBAO_BROWSER_ENGINE,
                )
            elif DOUBAO_BROWSER_ENGINE == "camoufox":
                _doubao_log.error(
                    "[Browser] please install it with: "
                    "pip install camoufox[geoip] && python -m camoufox fetch"
                )
            # 清理部分初始化的资源（如 __aenter__ 成功但 _init_pages 失败）
            try:
                await self.stop()
            except Exception:
                pass
        finally:
            self._ready.set()

    async def _start_browser_backend(self):
        engine = DOUBAO_BROWSER_ENGINE
        if engine == "camoufox":
            await self._start_camoufox()
            return
        if engine not in {"chromium", "firefox"}:
            raise ValueError(
                f"Unsupported DOUBAO_BROWSER_ENGINE={engine!r}; "
                "expected chromium, firefox, or camoufox"
            )
        await self._start_playwright(engine)

    async def _start_camoufox(self):
        """启动 Camoufox（反检测 Firefox）作为豆包后端。

        Camoufox 内部管理自己的 Playwright + Firefox 实例并完成指纹补丁，
        因此这里不需要单独持有 Playwright 对象。返回的 browser 是标准
        Playwright Browser，可直接复用 _init_pages 流程。
        """
        try:
            from camoufox.async_api import AsyncCamoufox
        except ImportError as exc:
            raise RuntimeError(
                "Camoufox is not installed; run: "
                "pip install camoufox[geoip] && python -m camoufox fetch"
            ) from exc

        humanize = os.getenv("DOUBAO_CAMOUFOX_HUMANIZE", "1").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        # 默认匹配当前宿主系统，避免 macOS 上伪装成 Windows 等明显矛盾
        os_fingerprint = tuple(
            v.strip()
            for v in os.getenv("DOUBAO_CAMOUFOX_OS", "macos").split(",")
            if v.strip()
        ) or ("macos",)

        _doubao_log.debug(
            "Starting browser engine (Camoufox, headless=%s, humanize=%s, os=%s)...",
            DOUBAO_BROWSER_HEADLESS,
            humanize,
            ",".join(os_fingerprint),
        )

        self._camoufox = AsyncCamoufox(
            headless=DOUBAO_BROWSER_HEADLESS,
            humanize=humanize,
            locale=["zh-CN"],
            os=os_fingerprint,
            geoip=False,
            block_images=False,
            block_webrtc=False,
            i_know_what_im_doing=True,
        )
        # AsyncCamoufox 的 __aenter__ 启动 Firefox 并返回 Playwright Browser
        self._browser = await self._camoufox.__aenter__()
        await self._init_pages("camoufox")
        self._started = True
        _doubao_log.debug(
            "Browser engine started: engine=camoufox pool_size=%d",
            self.pool_size,
        )

    async def _start_playwright(self, engine: str):
        from playwright.async_api import async_playwright

        _doubao_log.debug(
            "Starting browser engine (Playwright %s, headless=%s)...",
            engine,
            DOUBAO_BROWSER_HEADLESS,
        )
        self._playwright = await async_playwright().start()
        browser_type = getattr(self._playwright, engine)
        launch_options: dict[str, Any] = {"headless": DOUBAO_BROWSER_HEADLESS}
        if engine == "chromium":
            launch_options["args"] = [
                "--disable-dev-shm-usage",
                "--no-sandbox",
                "--disable-gpu",
                "--lang=zh-CN",
            ]
        self._browser = await browser_type.launch(**launch_options)
        await self._init_pages(engine)
        self._started = True
        _doubao_log.debug(
            "Browser engine started: engine=%s pool_size=%d",
            engine,
            self.pool_size,
        )

    async def _init_pages(self, engine: str):
        """创建页面池：每个 page 绑定独立的 BrowserContext（Cookie 隔离）。

        只创建空的 context+page，不导航。Cookie 注入和页面导航在
        fetch_chat 中按需执行，确保页面以登录态加载。
        """
        _doubao_log.debug(f"[Browser] 正在初始化 {self.pool_size} 个并发页面...")
        browser = self._browser
        if browser is None:
            raise RuntimeError("Doubao browser is not initialized")
        for i in range(self.pool_size):
            context = await self._browser.new_context(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                viewport={"width": 1920, "height": 1080},
                locale="zh-CN",
            )
            page = await context.new_page()
            stream_queue = asyncio.Queue(maxsize=256)
            binding_name = f"__voice_edge_doubao_stream_{i}_{id(page)}"

            async def _stream_callback(_source, value, queue=stream_queue):
                await queue.put(value)

            await page.expose_binding(binding_name, _stream_callback)
            self._stream_queues[id(page)] = stream_queue
            self._stream_binding_names[id(page)] = binding_name
            # 队列元素：(page, context) 元组，context 用于 Cookie 注入
            await self._pages.put((page, context))
            _doubao_log.debug(
                f"  [Browser] Page {i + 1}/{self.pool_size} ready (idle, no navigation yet)"
            )

    async def acquire_page(self, wait_seconds: float = 60.0) -> tuple[Any, Any]:
        """Acquire one typed (page, context) pair within a bounded wait."""
        return await asyncio.wait_for(
            self._pages.get(),
            timeout=wait_seconds,
        )

    async def release_page(self, page: Any, context: Any) -> None:
        """Return one typed (page, context) pair to the browser pool."""
        await self._pages.put((page, context))

    async def stop(self):
        """关闭浏览器引擎。"""
        self._started = False

        # Page recovery may still be navigating or returning a page to the
        # pool. Cancel and reap those tasks before closing browser contexts.
        background_tasks = list(self._background_tasks)
        for task in background_tasks:
            task.cancel()
        if background_tasks:
            await asyncio.gather(*background_tasks, return_exceptions=True)
        self._background_tasks.clear()
        # 关闭所有 context 和 page
        while not self._pages.empty():
            try:
                page, context = self._pages.get_nowait()
                await context.close()
            except Exception:
                pass
        # Camoufox 自管理 browser + playwright：通过 __aexit__ 一次性释放，
        # 不能先手动 close browser，否则 __aexit__ 内部清理会异常
        if self._camoufox is not None:
            try:
                await self._camoufox.__aexit__(None, None, None)
            except Exception:
                pass
            self._camoufox = None
            self._browser = None
        else:
            if self._browser:
                try:
                    await self._browser.close()
                except Exception:
                    pass
                self._browser = None
            if self._playwright:
                try:
                    await self._playwright.stop()
                except Exception:
                    pass
                self._playwright = None

    # ── Cookie 注入 ──────────────────────────────────────

    async def inject_session(self, context, sessionid: str):
        """Inject structured Firefox cookies, with environment fallback."""
        live_cookies = _doubao_live_cookie_snapshot()
        if live_cookies:
            await context.add_cookies(live_cookies)
            self._injected_cookie_digests[id(context)] = {
                str(item.get("name") or ""): _doubao_cookie_digest(
                    item.get("value", "")
                )
                for item in live_cookies
                if item.get("name") and item.get("value") != ""
            }
            _doubao_log.debug(
                "[Debug] injected structured Firefox cookies count=%d names=%s",
                len(live_cookies),
                sorted({str(item.get("name") or "") for item in live_cookies}),
            )
            return

        header_values = _load_doubao_cookie_header()
        values = dict(header_values)
        source = "DOUBAO_COOKIE_HEADER" if header_values else "legacy-environment"

        # Backward compatibility: individual optional variables fill only names
        # not already supplied by the complete Cookie header.
        for cookie_name, env_name in DOUBAO_OPTIONAL_COOKIE_ENV.items():
            value = os.getenv(env_name, "").strip()
            if value:
                values.setdefault(cookie_name, value)

        effective_sessionid = values.get("sessionid") or sessionid
        if not effective_sessionid:
            raise RuntimeError(
                "Doubao sessionid is missing: provide DOUBAO_COOKIE_HEADER "
                "or DOUBAO_SESSION_ID"
            )
        values.setdefault("sessionid", effective_sessionid)
        values.setdefault(
            "sessionid_ss",
            os.getenv("DOUBAO_SESSION_ID_SS", "").strip() or effective_sessionid,
        )
        values.setdefault(
            "sid_tt", os.getenv("DOUBAO_SID_TT", "").strip() or effective_sessionid
        )

        cookies = [
            {
                "name": name,
                "value": value,
                "domain": ".doubao.com",
                "path": "/",
                "secure": True,
            }
            for name, value in values.items()
            if name and value != ""
        ]
        await context.add_cookies(cookies)
        self._injected_cookie_digests[id(context)] = {
            name: _doubao_cookie_digest(value)
            for name, value in values.items()
            if value != ""
        }
        _doubao_log.debug(
            "[Debug] injected Doubao cookie names=%s source=%s count=%d",
            sorted(values),
            source,
            len(cookies),
        )

    async def _force_override_ttwid(self, context) -> None:
        """把 Firefox 插件快照中的 ttwid 强制覆盖回 Camoufox 上下文。

        页面导航后服务端可能通过 Set-Cookie 写入新的 ttwid，与 Firefox
        登录态不一致从而触发豆包风控。在导航完成后调用本方法，用 Firefox
        的 ttwid 覆盖 Camoufox 中的同名 Cookie（同 name+domain+path 的
        Cookie 会被 Playwright add_cookies 原子替换）。
        """
        ttwid = _doubao_forced_ttwid()
        if not ttwid:
            return
        await context.add_cookies(
            [
                {
                    "name": "ttwid",
                    "value": ttwid,
                    "domain": ".doubao.com",
                    "path": "/",
                    "secure": True,
                }
            ]
        )
        _doubao_log.debug(
            "[Debug] force-overrode ttwid in Camoufox context=%s digest=%s",
            id(context),
            _doubao_cookie_digest(ttwid),
        )

    # ── SSE 流式请求 ─────────────────────────────────────

    async def _set_doubao_spa_path(
        self,
        page,
        conversation_id: str,
    ) -> str:
        """Update the Doubao SPA URL without loading a new document.

        This is used only when the current page is already an initialized
        /chat document for the same account.  A fresh/restored context still
        performs a real navigation so its application state can be loaded.
        """
        conversation_id = str(conversation_id or "").strip()
        target_path = (
            f"/chat/{urllib.parse.quote(conversation_id, safe='')}"
            if conversation_id
            else "/chat"
        )
        actual_path = str(
            await page.evaluate(
                """(targetPath) => {
                    const target = new URL(targetPath, window.location.origin);
                    if (window.location.pathname !== target.pathname) {
                        window.history.replaceState(
                            window.history.state,
                            '',
                            target.pathname + target.search + target.hash
                        );
                    }
                    return window.location.pathname;
                }""",
                target_path,
            )
            or ""
        ).rstrip("/")
        expected_path = target_path.rstrip("/")
        if actual_path != expected_path:
            raise RuntimeError(
                "Doubao SPA route did not reach the expected path: "
                f"expected={expected_path!r} actual={actual_path!r}"
            )
        _doubao_log.debug(
            "[Debug] Doubao SPA route updated without navigation path=%s",
            actual_path,
        )
        return actual_path

    async def _prepare_chat_page(
        self,
        page,
        context,
        sessionid: str,
        conversation_id: str = "",
    ) -> None:
        ctx_id = id(context)
        conversation_id = str(conversation_id or "").strip()
        chat_root_url = f"{self.base_url.rstrip('/')}/chat/"
        target_url = chat_root_url
        if conversation_id:
            target_url = (
                f"{chat_root_url}{urllib.parse.quote(conversation_id, safe='')}"
            )
        target_path = urllib.parse.urlparse(target_url).path.rstrip("/")
        current_path = urllib.parse.urlparse(str(page.url or "")).path.rstrip("/")
        previous = self._context_sessionid.get(ctx_id, "")

        if previous == sessionid and current_path == target_path:
            _doubao_log.debug(
                "[Debug] reusing prepared page context=%s path=%s",
                ctx_id,
                current_path or "/",
            )
            return

        # Same account + an already initialized Doubao chat document: only
        # update the SPA route.  This preserves the fetch wrapper, page runtime,
        # browser identity, dynamic cookies, and loaded application state.
        if (
            previous == sessionid
            and conversation_id
            and (current_path == "/chat" or current_path.startswith("/chat/"))
        ):
            await self._set_doubao_spa_path(page, conversation_id)
            return

        _doubao_log.debug(
            "[Debug] preparing browser page context=%s cookie=%s "
            "target_path=%s direct_conversation=%s",
            ctx_id,
            _mask_doubao_session_id(sessionid),
            target_path or "/",
            bool(conversation_id),
        )

        if previous != sessionid:
            await self.inject_session(context, sessionid)
            self._context_sessionid[ctx_id] = sessionid

        # A fresh context or a page outside the initialized /chat SPA needs a
        # real document load.  Auth-sync restoration therefore still opens the
        # captured /chat/<conversation_id> directly.
        response = await page.goto(
            target_url,
            wait_until="domcontentloaded",
            timeout=30000,
        )
        identity = await self._wait_for_browser_identity(page, context)
        await self._force_override_ttwid(context)
        if VE_DOUBAO_LOG_DEBUG:
            _doubao_log.debug(
                "[Debug] browser identity ready=%s wait_ms=%d fp=%s "
                "device_keys=%s missing=%s",
                identity["ready"],
                identity["wait_ms"],
                self._mask_browser_identity(identity["fp"]),
                sorted(identity["device_context"]),
                identity["missing"],
            )
            cookies = await context.cookies(self.base_url)
            cookie_names = {cookie.get("name", "") for cookie in cookies}
            important = (
                "sessionid",
                "sessionid_ss",
                "sid_tt",
                "sid_guard",
                "session_tlb_tag",
                "uid_tt",
                "uid_tt_ss",
                "x-tt-multi-sids",
                "sid_ucp_v1",
                "ssid_ucp_v1",
                "passport_auth_status",
                "passport_auth_status_ss",
                "passport_csrf_token",
                "passport_csrf_token_default",
                "passport_mfa_token",
                "flow_multi_user_sec_info",
                "is_staff_user",
                "has_biz_token",
            )
            _doubao_log.debug(
                "[Debug] page prepared url=%s status=%s cookie_names=%s title=%r",
                page.url,
                response.status if response else None,
                sorted(cookie_names),
                await page.title(),
            )
            _doubao_log.debug(
                "[Debug] Doubao auth cookie presence=%s",
                {name: name in cookie_names for name in important},
            )
            injected_digests = self._injected_cookie_digests.get(ctx_id, {})
            current_values = {
                cookie.get("name", ""): str(cookie.get("value") or "")
                for cookie in cookies
            }
            tracked = (
                "sessionid",
                "sid_guard",
                "session_tlb_tag",
                "s_v_web_id",
                "uid_tt",
                "uid_tt_ss",
                "ttwid",
            )
            _doubao_log.debug(
                "[Debug] injected cookie state=%s",
                {
                    name: (
                        "not_injected"
                        if name not in injected_digests
                        else "missing_after_navigation"
                        if name not in current_values
                        else "preserved"
                        if _doubao_cookie_digest(current_values[name])
                        == injected_digests[name]
                        else "replaced"
                    )
                    for name in tracked
                },
            )

    async def _ensure_conversation_page(
        self,
        page,
        conversation_id: str,
    ) -> None:
        """Ensure requests use /chat/<id> without reloading an initialized SPA."""
        conversation_id = str(conversation_id or "").strip()
        if not conversation_id:
            return
        expected_path = f"/chat/{conversation_id}".rstrip("/")
        try:
            current_path = str(
                await page.evaluate("() => window.location.pathname") or ""
            ).rstrip("/")
        except Exception:
            current_path = urllib.parse.urlparse(str(page.url or "")).path.rstrip("/")
        if current_path == expected_path:
            _doubao_log.debug(
                "[Debug] conversation SPA route already active conv=%s path=%s",
                conversation_id[:16],
                current_path,
            )
            return
        if current_path == "/chat" or current_path.startswith("/chat/"):
            await self._set_doubao_spa_path(page, conversation_id)
            return
        # This helper is retained as a defensive recovery path.  Normal live
        # turns reach it only from an initialized /chat document.
        target_url = (
            f"{self.base_url}/chat/{urllib.parse.quote(conversation_id, safe='')}"
        )
        response = await page.goto(
            target_url,
            wait_until="domcontentloaded",
            timeout=30000,
        )
        actual_path = str(
            await page.evaluate("() => window.location.pathname") or ""
        ).rstrip("/")
        if actual_path != expected_path:
            raise RuntimeError(
                "Doubao conversation recovery did not reach expected path: "
                f"expected={expected_path!r} actual={actual_path!r} "
                f"status={response.status if response else None}"
            )

    @staticmethod
    def _mask_browser_identity(value: str) -> str:
        value = str(value or "")
        if len(value) <= 16:
            return "***" if value else ""
        return f"{value[:10]}...{value[-6:]}"

    async def _wait_for_browser_identity(self, page, context) -> dict:
        """Wait for page-generated fingerprint and device identity after DOM load."""
        started = time.monotonic()
        deadline = started + DOUBAO_BROWSER_IDENTITY_WAIT_SECONDS
        fp = ""
        device_context = {}
        required = ("device_id", "tea_uuid", "web_id", "web_tab_id")
        while True:
            fp = await self._browser_fingerprint(page, context)
            device_context = await self._browser_device_context(page)
            missing = [key for key in required if not device_context.get(key)]
            if fp and not missing:
                return {
                    "ready": True,
                    "fp": fp,
                    "device_context": device_context,
                    "missing": [],
                    "wait_ms": int((time.monotonic() - started) * 1000),
                }
            if time.monotonic() >= deadline:
                return {
                    "ready": False,
                    "fp": fp,
                    "device_context": device_context,
                    "missing": missing,
                    "wait_ms": int((time.monotonic() - started) * 1000),
                }
            await asyncio.sleep(0.25)

    async def _browser_fingerprint(self, page, context) -> str:
        """Return the fingerprint generated by the currently loaded Doubao page."""
        cookies = await context.cookies(self.base_url)
        for cookie in cookies:
            if cookie.get("name") == "s_v_web_id":
                value = str(cookie.get("value") or "").strip()
                if value:
                    return value
        try:
            value = await page.evaluate(
                "() => (document.cookie.match(/(?:^|;\\s*)s_v_web_id=([^;]+)/)||[])[1]||''"
            )
            return str(value or "").strip()
        except Exception:
            return ""

    async def _prepare_browser_request(
        self, page, context, request_body: str
    ) -> tuple[str, str]:
        """Synchronize payload.ext.fp with the active browser identity."""
        try:
            payload = json.loads(request_body)
        except json.JSONDecodeError as exc:
            raise RuntimeError(f"Invalid Doubao request JSON: {exc}") from exc
        if not isinstance(payload, dict):
            raise RuntimeError("Doubao request payload must be a JSON object")

        cookie_fp = await self._browser_fingerprint(page, context)
        configured_fp = str(DOUBAO_DEFAULT_FP or "").strip()
        payload_ext = payload.setdefault("ext", {})
        if not isinstance(payload_ext, dict):
            raise RuntimeError("Doubao payload.ext must be an object")
        previous_fp = str(payload_ext.get("fp") or "").strip()

        # The page-generated s_v_web_id is authoritative because the same
        # browser context signs this request. A configured value is only a
        # fallback for pages that have not yielded the cookie.
        effective_fp = cookie_fp or configured_fp
        if not effective_fp:
            raise RuntimeError(
                "Doubao browser identity unavailable: s_v_web_id cookie was not generated "
                "and DOUBAO_FP is empty"
            )
        payload_ext["fp"] = effective_fp

        if VE_DOUBAO_LOG_DEBUG:
            _doubao_log.debug(
                "[Debug] Doubao identity cookie_fp=%s payload_fp=%s configured_fp=%s matched=%s source=%s",
                self._mask_browser_identity(cookie_fp),
                self._mask_browser_identity(effective_fp),
                self._mask_browser_identity(configured_fp),
                bool(cookie_fp and cookie_fp == effective_fp),
                "s_v_web_id" if cookie_fp else "DOUBAO_FP",
            )
            if cookie_fp and previous_fp and previous_fp != cookie_fp:
                _doubao_log.debug(
                    "[Debug] replaced mismatched Doubao payload fp old=%s new=%s",
                    self._mask_browser_identity(previous_fp),
                    self._mask_browser_identity(cookie_fp),
                )

        compact_body = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
        )
        return compact_body, effective_fp

    async def _wait_for_fetch_interceptor(self, page) -> tuple[bool, str]:
        """Wait briefly for the page-level fetch interceptor used by Doubao."""
        deadline = time.monotonic() + DOUBAO_FETCH_HOOK_WAIT_SECONDS
        last_preview = ""
        while True:
            try:
                last_preview = str(
                    await page.evaluate(
                        "() => window.fetch.toString().substring(0,160)"
                    )
                )
            except Exception as exc:
                last_preview = f"unavailable:{type(exc).__name__}"
            if last_preview and "native code" not in last_preview:
                return True, last_preview
            if time.monotonic() >= deadline:
                return False, last_preview
            await asyncio.sleep(0.25)

    async def _browser_device_context(self, page) -> dict:
        """Recover the current Doubao web-client identity from loaded resources/storage."""
        script = """() => {
          const wanted = new Set([
            'aid','real_aid','device_id','tea_uuid','web_id','web_tab_id',
            'device_platform','doubao_device_platform','web_platform',
            'doubao_pc_version','pc_version','version_code','pkg_type',
            'region','sys_region','language','tz_name','samantha_web',
            'use-olympus-account'
          ]);
          const out = {};
          const consume = (raw) => {
            try {
              const u = new URL(raw, location.href);
              for (const [k, v] of u.searchParams.entries()) {
                if (wanted.has(k) && v && !(k in out)) out[k] = v;
              }
            } catch (_) {}
          };
          consume(location.href);
          for (const entry of performance.getEntriesByType('resource')) consume(entry.name);
          for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            let value = '';
            try { value = localStorage.getItem(key) || ''; } catch (_) {}
            if (wanted.has(key) && value && !(key in out)) out[key] = value;
            if (value && value.length < 4096) consume(value);
          }
          for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            let value = '';
            try { value = sessionStorage.getItem(key) || ''; } catch (_) {}
            if (wanted.has(key) && value && !(key in out)) out[key] = value;
            if (value && value.length < 4096) consume(value);
          }
          return out;
        }"""
        try:
            value = await page.evaluate(script)
        except Exception as exc:
            _doubao_log.warning("Failed reading Doubao browser device context: %s", exc)
            value = {}
        context = dict(value) if isinstance(value, dict) else {}
        # Stable public web-client fields are safe fallbacks. Device-bound values
        # must come from this exact browser page and are never fabricated.
        defaults = {
            "aid": DOUBAO_WEB_AID,
            "real_aid": DOUBAO_WEB_AID,
            "device_platform": "web",
            "doubao_device_platform": "web",
            "web_platform": "browser",
            "region": DOUBAO_WEB_REGION,
            "sys_region": DOUBAO_WEB_REGION,
            "language": DOUBAO_WEB_LANGUAGE,
            "tz_name": DOUBAO_WEB_TIMEZONE,
            "samantha_web": "1",
            "use-olympus-account": "1",
            "pkg_type": "release_version",
        }
        for key, value in defaults.items():
            if value and not context.get(key):
                context[key] = value
        return {str(k): str(v) for k, v in context.items() if str(v)}

    async def _build_completion_endpoint(
        self, page, browser_fp: str
    ) -> tuple[str, dict]:
        params = await self._browser_device_context(page)
        required = ("device_id", "tea_uuid", "web_id", "web_tab_id")
        if not browser_fp or any(not params.get(key) for key in required):
            identity = await self._wait_for_browser_identity(page, page.context)
            browser_fp = identity["fp"] or browser_fp
            params = identity["device_context"] or params
        params["fp"] = browser_fp
        missing = [
            key
            for key in ("fp", "device_id", "tea_uuid", "web_id", "web_tab_id")
            if not params.get(key)
        ]
        if missing:
            raise RuntimeError(
                "Doubao browser device context incomplete after page load; missing="
                + ",".join(missing)
                + ". The frontend did not expose a usable signed web identity."
            )
        endpoint = f"{self.base_url}/chat/completion?" + urllib.parse.urlencode(params)
        return endpoint, params

    @staticmethod
    def _completion_request_shape(
        url: str,
        headers: Optional[dict] = None,
    ) -> Optional[dict]:
        """Return non-sensitive request-shape diagnostics; never include values."""
        try:
            parsed = urllib.parse.urlsplit(str(url or ""))
        except Exception:
            return None
        if not parsed.path.rstrip("/").endswith("/chat/completion"):
            return None
        query = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        keys = sorted(query)
        header_map = {str(k).lower(): str(v) for k, v in (headers or {}).items()}
        device_id = (query.get("device_id") or [""])[0]
        tea_uuid = (query.get("tea_uuid") or [""])[0]
        web_id = (query.get("web_id") or [""])[0]
        trace_value = header_map.get("x-flow-trace", "")
        referer = header_map.get("referer", "")
        try:
            referer_path = urllib.parse.urlsplit(referer).path
        except Exception:
            referer_path = ""
        return {
            "host": parsed.hostname or "",
            "path": parsed.path,
            "query_keys": keys,
            "has_a_bogus": "a_bogus" in query,
            "has_ms_token": any(k.lower() == "mstoken" for k in query),
            "device_context": all(
                key in query
                for key in ("device_id", "tea_uuid", "web_id", "web_tab_id")
            ),
            "tea_uuid_eq_web_id": bool(tea_uuid and tea_uuid == web_id),
            "device_id_eq_tea_uuid": bool(device_id and device_id == tea_uuid),
            "agw_js_conv": header_map.get("agw-js-conv", ""),
            "trace_format_web": bool(
                re.fullmatch(r"04-[0-9a-fA-F]{32}-[0-9a-fA-F]{16}-01", trace_value)
            ),
            "referer_local_chat": bool(
                re.fullmatch(r"/chat/local_[^/]+/?", referer_path)
            ),
            "referer_path_kind": (
                "local_chat"
                if re.fullmatch(r"/chat/local_[^/]+/?", referer_path)
                else "conversation_chat"
                if re.fullmatch(r"/chat/[^/]+/?", referer_path)
                else "chat_root"
                if referer_path.rstrip("/") == "/chat"
                else "other"
            ),
        }

    def _log_completion_request_shape(
        self, trace_id: str, shape: Optional[dict]
    ) -> None:
        if shape is None:
            _llm_log.debug(
                "[Debug] no final /chat/completion network request was observed trace=%s",
                trace_id[:12],
            )
            return

        _llm_log.debug(
            "[Debug] actual completion request trace=%s host=%s path=%s "
            "query_keys=%s a_bogus=%s query_msToken=%s device_context=%s "
            "tea_uuid_eq_web_id=%s device_id_eq_tea_uuid=%s agw_js_conv=%r "
            "trace_format_web=%s referer_path_kind=%s",
            trace_id[:12],
            shape.get("host"),
            shape.get("path"),
            shape.get("query_keys"),
            shape.get("has_a_bogus"),
            shape.get("has_ms_token"),
            shape.get("device_context"),
            shape.get("tea_uuid_eq_web_id"),
            shape.get("device_id_eq_tea_uuid"),
            shape.get("agw_js_conv"),
            shape.get("trace_format_web"),
            shape.get("referer_path_kind"),
        )

    async def fetch_chat_stream(
        self, sessionid: str, request_body: str, conversation_id: str = ""
    ):
        """Yield upstream SSE data using the verified buffered path by default."""
        await asyncio.wait_for(self._ready.wait(), timeout=300)
        if not self._started:
            yield {"type": "error", "status": 0, "data": "Browser engine not started"}
            return
        try:
            page, context = await asyncio.wait_for(self._pages.get(), timeout=60)
        except asyncio.TimeoutError:
            yield {"type": "error", "status": 429, "data": "Browser page queue full"}
            return

        refresh = False
        task = None
        request_handler = None
        observed_shape = None
        stream_queue = self._stream_queues[id(page)]
        while not stream_queue.empty():
            try:
                stream_queue.get_nowait()
            except asyncio.QueueEmpty:
                break

        try:
            await self._prepare_chat_page(
                page,
                context,
                sessionid,
                conversation_id=conversation_id,
            )
            if conversation_id:
                expected_path = f"/chat/{conversation_id}".rstrip("/")
                actual_path = str(
                    await page.evaluate("() => window.location.pathname") or ""
                ).rstrip("/")
                if actual_path != expected_path:
                    # The Doubao SPA may still be settling its client-side
                    # route. Give it one short grace period and re-read once
                    # before deciding, so a transient routing race is not
                    # mistaken for a deleted conversation.
                    await asyncio.sleep(0.5)
                    actual_path = str(
                        await page.evaluate("() => window.location.pathname") or ""
                    ).rstrip("/")
                if actual_path != expected_path:
                    # A deleted/invalid conversation is bounced to the bare
                    # /chat root. That specific redirect is the stale signal
                    # and the HTTP layer may start a fresh conversation.
                    # Landing on a *different* specific conversation is a real
                    # navigation bug and must fail closed.
                    if actual_path in {"/chat", "", "/"}:
                        raise DoubaoStaleConversationError(
                            conversation_id, actual_path, expected_path
                        )
                    raise RuntimeError(
                        "Doubao page/payload conversation mismatch: "
                        f"path={actual_path!r} expected={expected_path!r}"
                    )
            hook_ready, hook_preview = await self._wait_for_fetch_interceptor(page)

            if VE_DOUBAO_LOG_DEBUG:
                _doubao_log.debug(
                    "[Debug] fetch interceptor ready=%s preview=%r mode=%s",
                    hook_ready,
                    hook_preview[:120],
                    "live" if DOUBAO_LIVE_STREAM_ENABLED else "buffered-upstream",
                )

                if not hook_ready:
                    _doubao_log.debug(
                        "[Debug] window.fetch still appears native after %.1fs; "
                        "continuing with final network-request inspection",
                        DOUBAO_FETCH_HOOK_WAIT_SECONDS,
                    )

            request_body, browser_fp = await self._prepare_browser_request(
                page, context, request_body
            )
            # 发起 fetch 前的最后防线：无论本次是首次导航还是复用页面，
            # 都用 Firefox 的 ttwid 强制覆盖一次，防止页面后台请求或
            # _prepare_chat_page 之后的 Set-Cookie 让 ttwid 漂移。
            await self._force_override_ttwid(context)
            trace_id = _generate_trace_id()
            endpoint, request_context = await self._build_completion_endpoint(
                page, browser_fp
            )
            _doubao_log.debug(
                "[Debug] browser device context keys=%s",
                sorted(request_context),
            )

            def _observe_request(request):
                nonlocal observed_shape
                shape = self._completion_request_shape(request.url, request.headers)
                if shape is not None:
                    observed_shape = shape

            request_handler = _observe_request
            page.on("request", request_handler)

            _doubao_log.debug(
                "[Debug] starting Doubao fetch trace=%s conv=%s body_bytes=%d "
                "endpoint_path=/chat/completion mode=%s",
                trace_id[:12],
                str(conversation_id or "")[:16] or "new",
                len(request_body.encode("utf-8")),
                "live" if DOUBAO_LIVE_STREAM_ENABLED else "buffered-upstream",
            )

            if not DOUBAO_LIVE_STREAM_ENABLED:
                # Match doubao2API upstream exactly: let Chromium read the full
                # EventSource body inside page.evaluate, then parse it in Python.
                result = await asyncio.wait_for(
                    page.evaluate(
                        JS_STREAM_DOUBAO,
                        {
                            "url": endpoint,
                            "body": request_body,
                            "trace_id": trace_id,
                        },
                    ),
                    timeout=DOUBAO_REQUEST_TIMEOUT,
                )
                await asyncio.sleep(0)
                self._log_completion_request_shape(trace_id, observed_shape)
                if not isinstance(result, dict):
                    result = {"status": 0, "body": str(result)}
                status = int(result.get("status", 0) or 0)
                body = str(result.get("body", "") or "")
                response_meta = result.get("response_meta", {})
                response_meta = response_meta if isinstance(response_meta, dict) else {}

                _doubao_log.debug(
                    "[Debug] buffered Doubao fetch finished trace=%s status=%s bytes=%d "
                    "response_x_ms_token_present=%s response_agw_login=%r "
                    "response_content_type=%r page_path_kind=%s",
                    trace_id[:12],
                    status,
                    len(body.encode("utf-8")),
                    bool(response_meta.get("x_ms_token")),
                    str(response_meta.get("agw_login", ""))[:16],
                    str(response_meta.get("content_type", ""))[:80],
                    (
                        "local_chat"
                        if re.fullmatch(
                            r"/chat/local_[^/]+/?", str(result.get("page_path", ""))
                        )
                        else "conversation_chat"
                        if re.fullmatch(
                            r"/chat/[^/]+/?", str(result.get("page_path", ""))
                        )
                        else "chat_root"
                        if str(result.get("page_path", "")).rstrip("/") == "/chat"
                        else "other"
                    ),
                )

                yield {"type": "meta", "status": status}
                if status != 200:
                    yield {"type": "error", "status": status, "data": body[:2000]}
                else:
                    if body:
                        yield {"type": "chunk", "data": body}
                    yield {"type": "done"}
                return

            task = asyncio.create_task(
                page.evaluate(
                    JS_STREAM_DOUBAO_LIVE,
                    {
                        "url": endpoint,
                        "body": request_body,
                        "trace_id": trace_id,
                        "emit_name": self._stream_binding_names[id(page)],
                    },
                )
            )
            event_count = 0
            chunk_bytes = 0
            shape_logged = False
            while True:
                timeout = (
                    DOUBAO_STREAM_FIRST_EVENT_TIMEOUT
                    if event_count == 0
                    else DOUBAO_STREAM_IDLE_TIMEOUT
                )
                try:
                    item = await asyncio.wait_for(stream_queue.get(), timeout=timeout)
                except asyncio.TimeoutError as exc:
                    eval_state = "done" if task.done() else "pending"
                    raise TimeoutError(
                        f"Doubao stream timeout after {timeout:.0f}s: "
                        f"first_event={event_count == 0} evaluate={eval_state} "
                        f"trace={trace_id[:12]} page={page.url}"
                    ) from exc
                event_count += 1
                kind = item.get("type")
                if observed_shape is not None and not shape_logged:
                    self._log_completion_request_shape(trace_id, observed_shape)
                    shape_logged = True
                if kind == "chunk":
                    chunk_bytes += len(str(item.get("data", "")).encode("utf-8"))

                _doubao_log.debug(
                    "[Debug] browser event trace=%s n=%d type=%s status=%s "
                    "chunk_bytes=%d total_bytes=%d",
                    trace_id[:12],
                    event_count,
                    kind,
                    item.get("status"),
                    len(str(item.get("data", "")).encode("utf-8"))
                    if kind == "chunk"
                    else 0,
                    chunk_bytes,
                )

                yield item
                if kind in {"done", "error"}:
                    break
            if not shape_logged:
                self._log_completion_request_shape(trace_id, observed_shape)
            await asyncio.wait_for(task, timeout=5)

            _doubao_log.debug(
                "[Debug] Doubao live fetch finished trace=%s events=%d bytes=%d",
                trace_id[:12],
                event_count,
                chunk_bytes,
            )
        except Exception as exc:
            refresh = True
            if task is not None and not task.done():
                task.cancel()
            if isinstance(exc, DoubaoStaleConversationError):
                # A stale conversation is an expected, recoverable control-flow
                # signal, not a fault. Log a single clean line WITHOUT a stack
                # trace; a traceback here is misleading noise.
                _doubao_log.debug(
                    "[Debug] Doubao conversation is stale; triggering recovery: %s",
                    exc,
                )
                # Preserve the typed stale signal end-to-end. Flattening it
                # into a generic error dict here (which raw_chunks then
                # re-raises as a status=0 DoubaoHTTPError) erased the type, so
                # chat_stream never tagged stale_conversation and the HTTP
                # recovery gate could not start a fresh conversation. Re-raise
                # so the typed exception reaches chat_stream's handler; the
                # finally block below still refreshes this stale page.
                raise
            _doubao_log.debug(
                "[Debug] Doubao browser stream failed: %s",
                exc,
                exc_info=True,
            )
            yield {"type": "error", "status": 0, "data": str(exc)}
        finally:
            if request_handler is not None:
                try:
                    page.remove_listener("request", request_handler)
                except Exception:
                    pass
            if refresh:
                self._create_background_task(
                    self._refresh_page_and_return(page, context)
                )
            else:
                await self._pages.put((page, context))

    async def fetch_chat(
        self,
        sessionid: str,
        request_body: str,
        conversation_id: str = "",
    ):
        """执行豆包 SSE 流式请求，异步生成器返回完整 SSE body。

        流程：
        1. 从页面池获取 (page, context)
        2. 检查是否需要重新导航（Cookie 变化或首次请求）
        3. 先注入 Cookie → 再导航页面（确保以登录态加载）
        4. 执行 JS_STREAM_DOUBAO 在浏览器内 fetch
        5. 返回 {status, body} 字典

        Args:
            sessionid: 豆包账号的 sessionid
            request_body: JSON 字符串形式的请求体
            conversation_id: 会话 ID（用于日志）
        """
        await asyncio.wait_for(self._ready.wait(), timeout=300)
        if not self._started:
            yield {
                "status": 0,
                "body": "Browser engine not started. Run: python -m playwright install chromium",
            }
            return

        try:
            page, context = await asyncio.wait_for(self._pages.get(), timeout=60)
        except asyncio.TimeoutError:
            yield {"status": 429, "body": "Too Many Requests (Queue full)"}
            return

        needs_refresh = False
        trace_id = _generate_trace_id()

        try:
            ctx_id = id(context)
            prev_sessionid = self._context_sessionid.get(ctx_id, "")

            # 判断是否需要（重新）导航页面
            # 1. 首次请求（prev_sessionid 为空）
            # 2. Cookie 变化（不同账号）
            need_navigate = prev_sessionid != sessionid

            if need_navigate:
                # 先注入 Cookie，再导航页面
                # 这样页面加载时字节 JS 拦截器在登录态下正确初始化
                await self.inject_session(context, sessionid)
                self._context_sessionid[ctx_id] = sessionid

                _doubao_log.debug(
                    f"[Browser] {'首次' if not prev_sessionid else 'Cookie 变化，'}导航页面 (sessionid={sessionid[:8]}...)"
                )
                try:
                    await page.goto(
                        self.base_url, wait_until="networkidle", timeout=30000
                    )
                    # 额外等待，确保字节 JS 拦截器完全加载
                    await asyncio.sleep(2)
                except Exception:
                    _doubao_log.warning(
                        "[Browser] networkidle 超时，尝试 domcontentloaded"
                    )
                    try:
                        await page.goto(
                            self.base_url, wait_until="domcontentloaded", timeout=15000
                        )
                        await asyncio.sleep(1.5)
                    except Exception:
                        _doubao_log.warning("[Browser] 页面导航超时")

                # 导航完成后强制用 Firefox 的 ttwid 覆盖回 Camoufox，
                # 防止服务端 Set-Cookie 写入的新 ttwid 与登录态不一致。
                await self._force_override_ttwid(context)

                # 验证 fetch 是否被劫持
                try:
                    fetch_str = await page.evaluate(
                        "() => window.fetch.toString().substring(0, 80)"
                    )
                    is_hooked = "native code" not in fetch_str
                    _doubao_log.debug(
                        f"[Browser] fetch hooked={is_hooked}, fetch={fetch_str[:60]}"
                    )
                except Exception:
                    pass
            else:
                # 同一账号，Cookie 已存在，无需重新导航
                _doubao_log.debug(
                    f"[Browser] 复用已有页面 (sessionid={sessionid[:8]}...)"
                )

            request_body, browser_fp = await self._prepare_browser_request(
                page, context, request_body
            )

            # 抖动延迟

            # 发起 fetch 前的最后防线：无论本次是首次导航还是复用页面，
            # 都用 Firefox 的 ttwid 强制覆盖一次，防止页面后台请求或
            # _prepare_chat_page 之后的 Set-Cookie 让 ttwid 漂移。
            await self._force_override_ttwid(context)

            # 在浏览器内执行 fetch（字节 JS 拦截器自动注入 a_bogus / msToken）
            url, request_context = await self._build_completion_endpoint(
                page, browser_fp
            )
            _doubao_log.debug(
                "[Debug] browser device context keys=%s",
                sorted(request_context),
            )
            # 诊断：打印请求体的关键字段
            try:
                import json as _json

                body_obj = _json.loads(request_body)
                cm = body_obj.get("client_meta", {})
                _doubao_log.debug(
                    f"[Browser] 请求体诊断: conversation_id={cm.get('conversation_id', 'N/A')!r}, "
                    f"local_conversation_id={cm.get('local_conversation_id', 'N/A')}, "
                    f"bot_id={cm.get('bot_id', 'N/A')}, "
                    f"need_create_conversation={body_obj.get('option', {}).get('need_create_conversation', 'N/A')}"
                )
            except Exception:
                pass
            res = await asyncio.wait_for(
                page.evaluate(
                    JS_STREAM_DOUBAO,
                    {
                        "url": url,
                        "body": request_body,
                        "trace_id": trace_id,
                    },
                ),
                timeout=1800,
            )

            if isinstance(res, dict) and res.get("status") == 0:
                needs_refresh = True

            # 诊断日志
            if isinstance(res, dict):
                hook = res.get("fetch_hook", "unknown")
                body_len = res.get("body_len", len(res.get("body", "")))
                _doubao_log.debug(
                    f"[Browser] fetch result: status={res.get('status')}, "
                    f"body_len={body_len}, fetch_hook={hook[:60]}"
                )

            yield res if isinstance(res, dict) else {"status": 0, "body": str(res)}

        except asyncio.TimeoutError:
            needs_refresh = True
            yield {"status": 0, "body": "Timeout"}
        except Exception as e:
            needs_refresh = True
            _doubao_log.error(f"[Browser] fetch_chat 异常: {e}")
            yield {"status": 0, "body": str(e)}
        finally:
            if needs_refresh:
                self._create_background_task(
                    self._refresh_page_and_return(page, context)
                )
            else:
                await self._pages.put((page, context))

    # ── 页面刷新与回收 ───────────────────────────────────

    def _create_background_task(self, coroutine) -> asyncio.Task:
        """Create and track a browser-maintenance task until completion."""
        task = asyncio.create_task(coroutine)
        self._background_tasks.add(task)
        task.add_done_callback(self._background_task_done)
        return task

    def _background_task_done(self, task: asyncio.Task) -> None:
        """Release a completed task reference and retrieve its exception."""
        self._background_tasks.discard(task)
        if task.cancelled():
            return
        try:
            task.result()
        except Exception:
            _doubao_log.exception("[Browser] background page recovery failed")

    async def _refresh_page(self, page, context):
        """刷新页面，恢复字节 JS 拦截器上下文。"""
        try:
            await asyncio.wait_for(
                page.goto(self.base_url, wait_until="domcontentloaded"),
                timeout=20000,
            )
        except Exception:
            _doubao_log.warning("[Browser] 页面刷新超时")

    async def _refresh_page_and_return(self, page, context):
        """刷新页面并放回页面池。"""
        await self._refresh_page(page, context)
        await self._pages.put((page, context))


@dataclass(slots=True)
class DoubaoSession:
    """豆包会话状态"""

    session_id: str = ""  # 本地会话标识
    conversation_id: str = ""  # 豆包 conversation_id
    local_conversation_id: str = ""  # 本地会话ID（local_xxx）
    section_id: str = ""  # section_id
    last_message_index: int = 0  # 消息序号
    bot_id: str = ""  # 当前 bot_id
    account_sessionid: str = ""  # 创建远端会话的豆包账号
    turn_count: int = 0  # 当前会话已轮次
    created_at: float = 0.0


class DoubaoConversationStore:
    """会话状态管理器"""

    def __init__(self):
        self._sessions: dict[str, DoubaoSession] = {}  # session_id → DoubaoSession
        self._conversation_index: dict[str, str] = {}  # conversation_id → session_id

    def create_session(self, bot_id: str, conversation_id: str = "") -> DoubaoSession:
        session = DoubaoSession(
            session_id=str(uuid.uuid4()),
            conversation_id=conversation_id,
            local_conversation_id=f"local_{int(time.time() * 1000)}{uuid.uuid4().hex[:6]}",
            bot_id=bot_id,
            created_at=time.time(),
        )
        self._sessions[session.session_id] = session
        if conversation_id:
            self._conversation_index[conversation_id] = session.session_id
        return session

    def get_or_create_session(
        self, bot_id: str, conversation_id: str = ""
    ) -> DoubaoSession:
        if conversation_id:
            runtime_id = self._conversation_index.get(conversation_id, "")
            session = self._sessions.get(runtime_id)
            if session is not None:
                if session.bot_id != bot_id:
                    raise RuntimeError(
                        "Conversation bot_id does not match existing session"
                    )
                return session
        return self.create_session(bot_id, conversation_id)

    def get_session(self, session_id: str) -> Optional[DoubaoSession]:
        return self._sessions.get(session_id)

    def update_from_sse(
        self,
        session_id: str,
        conversation_id: str | None = None,
        section_id: str | None = None,
        message_index: int | None = None,
    ):
        """从 SSE 响应更新会话状态"""
        session = self._sessions.get(session_id)
        if not session:
            return

        if conversation_id:
            old_id = session.conversation_id
            session.conversation_id = conversation_id
            if old_id and old_id != conversation_id:
                self._conversation_index.pop(old_id, None)
            self._conversation_index[conversation_id] = session.session_id
        if section_id:
            session.section_id = section_id
        if message_index is not None:
            try:
                session.last_message_index = max(
                    session.last_message_index, int(message_index)
                )
            except (TypeError, ValueError):
                pass

    def build_client_meta(self, session_id: str) -> dict:
        """构建请求的 client_meta"""
        session = self._sessions.get(session_id)
        if not session:
            return {}

        is_new = not session.conversation_id

        if is_new:
            return {
                "local_conversation_id": session.local_conversation_id,
                "conversation_id": "",
                "bot_id": session.bot_id,
                "last_section_id": "",
                "last_message_index": None,
            }
        else:
            return {
                "conversation_id": session.conversation_id,
                "bot_id": session.bot_id,
                "last_section_id": session.section_id,
                "last_message_index": session.last_message_index,
            }

    def build_option(self, session_id: str) -> dict:
        session = self._sessions.get(session_id)
        is_new = not session.conversation_id if session else True
        option = {
            "send_message_scene": "",
            "create_time_ms": int(time.time() * 1000),
            "collect_id": "",
            "is_audio": False,
            "answer_with_suggest": False,
            "agent_mode": 2,
            "tts_switch": False,
            "need_deep_think": 0,
            "click_clear_context": False,
            "from_suggest": False,
            "is_regen": False,
            "is_replace": False,
            "is_from_click_option": False,
            "is_from_click_softlink": False,
            "disable_sse_cache": False,
            "select_text_action": "",
            "is_select_text": False,
            "resend_for_regen": False,
            "scene_type": 0,
            "unique_key": str(uuid.uuid4()),
            "start_seq": 0,
            "need_create_conversation": is_new,
            "regen_query_id": [],
            "edit_query_id": [],
            "regen_instruction": "",
            "no_replace_for_regen": False,
            "message_from": 0,
            "shared_app_name": "",
            "shared_app_id": "",
            "sse_recv_event_options": {"support_chunk_delta": True},
            "is_ai_playground": False,
            "is_old_user": True,
            "recovery_option": {
                "is_recovery": False,
                "req_create_time_sec": int(time.time()),
                "append_sse_event_scene": 0,
            },
            "message_storage_type": 0,
        }
        if is_new:
            option["conversation_init_option"] = {"need_ack_conversation": True}
        return option

    def build_message(self, text: str) -> dict:
        """构建消息体"""
        return {
            "local_message_id": str(uuid.uuid4()),
            "content_block": [
                {
                    "block_type": 10000,
                    "content": {
                        "text_block": {
                            "text": text,
                            "icon_url": "",
                            "icon_url_dark": "",
                            "summary": "",
                        },
                        "pc_event_block": "",
                    },
                    "block_id": str(uuid.uuid4()),
                    "parent_id": "",
                    "meta_info": [],
                    "append_fields": [],
                }
            ],
            "message_status": 0,
        }

    def build_ext(self, session_id: str) -> dict:
        session = self._sessions.get(session_id)
        is_new = not session.conversation_id if session else True
        ext = {
            "use_deep_think": "0",
            "fp": DOUBAO_DEFAULT_FP,
            "collection_id": "",
            "commerce_credit_config_enable": "0",
        }
        if is_new:
            ext["sub_conv_firstmet_type"] = "1"
            ext["conversation_init_option"] = json.dumps(
                {"need_ack_conversation": True}, separators=(",", ":")
            )
        return ext

    def build_full_payload(self, session_id: str, text: str) -> dict:
        """构建完整的请求 payload"""
        return {
            "client_meta": self.build_client_meta(session_id),
            "messages": [self.build_message(text)],
            "option": self.build_option(session_id),
            "user_context": [],
            "ext": self.build_ext(session_id),
        }

    def increment_turn(self, session_id: str):
        """增加轮次计数"""
        session = self._sessions.get(session_id)
        if session:
            session.turn_count += 1

    def remove_session(self, session_id: str):
        session = self._sessions.pop(session_id, None)
        if session and session.conversation_id:
            self._conversation_index.pop(session.conversation_id, None)

    def status(self) -> dict:
        return {
            "active_sessions": len(self._sessions),
        }


@dataclass(slots=True)
class DoubaoSSEEvent:
    """解析后的 SSE 事件。"""

    event_type: str  # SSE_HEARTBEAT/SSE_ACK/FULL_MSG_NOTIFY/STREAM_MSG_NOTIFY/CHUNK_DELTA/STREAM_CHUNK/SSE_REPLY_END
    id: str = ""
    data: dict = field(default_factory=dict)


@dataclass(slots=True)
class DoubaoSessionMeta:
    """从 SSE 流中提取的会话元数据"""

    conversation_id: str = ""
    local_conversation_id: str = ""
    section_id: str = ""
    message_id: str = ""
    last_message_index: int = 0
    conversation_type: int = 0
    timeout_conf: dict = field(default_factory=dict)


@dataclass(slots=True)
class DoubaoStreamResult:
    """SSE 流解析最终结果"""

    text: str = ""  # 完整文本内容
    session_meta: DoubaoSessionMeta = field(default_factory=DoubaoSessionMeta)
    suggestions: list = field(default_factory=list)  # 推荐问题
    brief: str = ""  # 消息摘要
    error: Optional[str] = None  # 错误信息
    image_urls: list = field(default_factory=list)


def _merge_doubao_text(
    current: str,
    incoming: str,
    *,
    mode: str = "delta",
) -> tuple[str, str]:
    """Merge Doubao text without deleting legitimate repeated characters.

    ``delta`` is append-only and is used for STREAM_MSG_NOTIFY,
    CHUNK_DELTA, and STREAM_CHUNK text patches.  ``snapshot`` is reserved
    for fields explicitly documented as cumulative full-text snapshots.
    Arbitrary suffix/prefix overlap removal is intentionally forbidden:
    a boundary such as ``"2" + "2:54"`` must remain ``"22:54"``.
    """
    current = str(current or "")
    incoming = str(incoming or "")
    if not incoming:
        return current, ""
    if mode == "delta":
        return current + incoming, incoming
    if mode == "snapshot":
        if incoming == current:
            return current, ""
        if incoming.startswith(current):
            delta = incoming[len(current) :]
            return incoming, delta
        return incoming, incoming
    raise ValueError(f"Unknown Doubao text merge mode: {mode!r}")


class DoubaoSSEParser:
    """豆包 SSE 流解析器"""

    def __init__(self):
        self.result = DoubaoStreamResult()
        self._full_text = ""
        self._latest_tts_content = ""
        self._session_meta = DoubaoSessionMeta()
        self._text_sources_seen: set[str] = set()

    def _append_text(self, text: str, source: str):
        """Append one protocol-defined text delta without overlap guessing."""
        if not text:
            return
        self._text_sources_seen.add(str(source or "unknown"))
        self._full_text, _delta = _merge_doubao_text(
            self._full_text, text, mode="delta"
        )

    def parse_raw_sse(self, raw_body: str) -> DoubaoStreamResult:
        """解析完整的 SSE 响应文本"""
        events = self._split_sse_events(raw_body)

        _http_log.info(f"[SSE] Parsed {len(events)} events from {len(raw_body)} chars")
        if not events:
            # 诊断：raw_body 不像 SSE 格式
            if raw_body.strip().startswith("{"):
                _http_log.warning(
                    f"[SSE] raw_body 是 JSON 而非 SSE！preview: {raw_body[:300]}"
                )
            elif raw_body.strip().startswith("<"):
                _http_log.warning(
                    f"[SSE] raw_body 是 HTML 而非 SSE！preview: {raw_body[:300]}"
                )
            elif not raw_body.strip():
                _http_log.warning("[SSE] raw_body 为空！")
            else:
                _http_log.warning(f"[SSE] raw_body 格式异常！preview: {raw_body[:300]}")
        # # 打印事件类型摘要
        # evt_types = [e.event_type for e in events]
        # if evt_types:
        #     _doubao_log.debug(f"[SSE] Event types: {evt_types}")
        for evt in events:
            self._process_event(evt)

        # 兜底：当 content_block 路径只投递了部分文本时，依次尝试
        # SSE_REPLY_END 的 brief 和 patch_object=111 的 tts_content 快照
        best = self._full_text
        if self.result.brief and len(self.result.brief) > len(best):
            best = self.result.brief
        if self._latest_tts_content and len(self._latest_tts_content) > len(best):
            best = self._latest_tts_content
        self.result.text = best
        self.result.session_meta = self._session_meta
        return self.result

    def _split_sse_events(self, raw: str) -> list[DoubaoSSEEvent]:
        """将原始 SSE 文本拆分为事件列表"""
        events = []
        current_id = ""
        current_event = ""
        current_data = ""

        for line in raw.splitlines():
            line = line.strip()
            if not line:
                # 空行表示事件结束
                if current_event and current_data:
                    try:
                        data = (
                            json.loads(current_data)
                            if current_data and current_data != "{}"
                            else {}
                        )
                    except json.JSONDecodeError as exc:
                        data = {
                            "error_msg": "Invalid SSE JSON",
                            "raw_data": current_data[:2000],
                            "json_error": str(exc),
                        }
                        _doubao_log.error(
                            "[SSE] invalid JSON event=%s id=%s error=%s raw=%r",
                            current_event,
                            current_id,
                            exc,
                            current_data[:500],
                        )
                    events.append(
                        DoubaoSSEEvent(
                            event_type=current_event,
                            id=current_id,
                            data=data,
                        )
                    )
                current_id = ""
                current_event = ""
                current_data = ""
                continue

            if line.startswith("id:"):
                current_id = line[3:].strip()
            elif line.startswith("event:"):
                current_event = line[6:].strip()
            elif line.startswith("data:"):
                data_str = line[5:].strip()
                if current_data:
                    current_data += "\n" + data_str
                else:
                    current_data = data_str

        if current_event and current_data:
            try:
                data = json.loads(current_data) if current_data != "{}" else {}
            except json.JSONDecodeError as exc:
                data = {
                    "error_msg": "Invalid SSE JSON",
                    "raw_data": current_data[:2000],
                    "json_error": str(exc),
                }
                _doubao_log.error(
                    "[SSE] invalid trailing JSON event=%s id=%s error=%s raw=%r",
                    current_event,
                    current_id,
                    exc,
                    current_data[:500],
                )
            events.append(
                DoubaoSSEEvent(
                    event_type=current_event,
                    id=current_id,
                    data=data,
                )
            )
        return events

    def _process_event(self, evt: DoubaoSSEEvent):
        """处理单个 SSE 事件"""
        if evt.event_type == "SSE_HEARTBEAT":
            pass  # 心跳，忽略

        elif evt.event_type == "SSE_ACK":
            self._process_ack(evt.data)

        elif evt.event_type == "FULL_MSG_NOTIFY":
            self._process_full_msg(evt.data)

        elif evt.event_type == "STREAM_MSG_NOTIFY":
            self._process_stream_msg(evt.data)

        elif evt.event_type == "CHUNK_DELTA":
            self._process_chunk_delta(evt.data)

        elif evt.event_type == "STREAM_CHUNK":
            self._process_stream_chunk(evt.data)

        elif evt.event_type == "SSE_REPLY_END":
            self._process_reply_end(evt.data)

        elif evt.event_type == "STREAM_ERROR":
            error_msg = evt.data.get("error_msg", "Unknown error")
            self.result.error = error_msg
            _doubao_log.error(f"[SSE] STREAM_ERROR: {error_msg}")

    def _process_full_msg(self, data: dict):
        """Use the echoed user message as a conversation-cursor fallback."""
        message = data.get("message", {}) if isinstance(data, dict) else {}
        conv_id = str(message.get("conversation_id", "") or "")
        section_id = str(message.get("section_id", "") or "")
        if conv_id:
            self._session_meta.conversation_id = conv_id
        if section_id:
            self._session_meta.section_id = section_id
        index = message.get("index_in_conv")
        if index is not None:
            try:
                self._session_meta.last_message_index = max(
                    self._session_meta.last_message_index, int(index)
                )
            except (TypeError, ValueError):
                pass

    def _process_ack(self, data: dict):
        """处理 SSE_ACK 事件 - 提取会话元数据"""
        meta = data.get("ack_client_meta", {})
        conv_id = meta.get("conversation_id", "")
        if conv_id == "0":
            _http_log.warning(
                f"[SSE] ⚠️ conversation_id='0' — 会话创建可能失败！ack_client_meta={json.dumps(meta, ensure_ascii=False)[:500]}"
            )
        if not self._session_meta.conversation_id:
            self._session_meta.conversation_id = conv_id
        if not self._session_meta.section_id:
            self._session_meta.section_id = meta.get("section_id", "")
        self._session_meta.conversation_type = meta.get("conversation_type", 0)
        self._session_meta.local_conversation_id = meta.get("local_conversation_id", "")

        timeout = data.get("timeout_conf", {})
        if timeout:
            self._session_meta.timeout_conf = timeout

        # 提取用户消息 message_index
        query_list = data.get("query_list", [])
        if query_list:
            indexes = [
                q.get("message_index") for q in query_list if isinstance(q, dict)
            ]
            indexes = [
                int(v)
                for v in indexes
                if v is not None and (isinstance(v, int) or str(v).isdigit())
            ]
            if indexes:
                self._session_meta.last_message_index = max(
                    self._session_meta.last_message_index, max(indexes)
                )

    def _process_stream_msg(self, data: dict):
        """处理 STREAM_MSG_NOTIFY 事件 - 首个文本块 + 元数据"""
        meta = data.get("meta", {})
        if not self._session_meta.message_id:
            self._session_meta.message_id = meta.get("message_id", "")
        if not self._session_meta.section_id:
            self._session_meta.section_id = meta.get("section_id", "")

        # 提取机器人回复的 index_in_conv
        idx = meta.get("index_in_conv")
        if idx is not None:
            try:
                self._session_meta.last_message_index = max(
                    self._session_meta.last_message_index, int(idx)
                )
            except (TypeError, ValueError):
                pass

        # 提取首个文本块
        content = data.get("content", {})
        blocks = content.get("content_block", [])

        # 诊断：打印首个 STREAM_MSG_NOTIFY 的完整 content 结构
        if not DoubaoSSEParser._stream_msg_logged:
            DoubaoSSEParser._stream_msg_logged = True
            _http_log.info(
                f"[SSE] 首个 STREAM_MSG_NOTIFY content keys={list(content.keys())}"
            )
            _http_log.info(f"[SSE]   content_block 数量={len(blocks)}")
            for i, block in enumerate(blocks[:3]):
                block_type = block.get("block_type", 0)
                block_content = block.get("content", {})
                block_content_json = json.dumps(block_content, ensure_ascii=False)[:800]
                _http_log.info(
                    f"[SSE]   block[{i}]: block_type={block_type}, content={block_content_json}"
                )

        for block in blocks:
            if block.get("block_type") == 10000:
                text = block.get("content", {}).get("text_block", {}).get("text", "")
                if text:
                    self._full_text, _delta = _merge_doubao_text(
                        self._full_text, text, mode="delta"
                    )
                break

        # 检测文生图 Agent
        ext = content.get("ext", {})
        bot_state = ext.get("bot_state", "")
        if "Agent-Text2Image" in str(bot_state):
            _http_log.info("[SSE] Image generation agent detected")

    def _process_chunk_delta(self, data: dict):
        """处理 CHUNK_DELTA 事件 - 增量文本（最简洁路径）"""
        self._append_text(data.get("text", ""), "chunk_delta")

    _first_stream_chunk_logged = 0  # 类变量，控制诊断打印前N个
    _stream_msg_logged = False

    def _process_stream_chunk(self, data: dict):
        """处理 STREAM_CHUNK 事件 - 补丁更新"""
        patch_ops = data.get("patch_op", [])

        # 诊断：打印前3个 STREAM_CHUNK 的完整结构
        if DoubaoSSEParser._first_stream_chunk_logged < 3:
            DoubaoSSEParser._first_stream_chunk_logged += 1
            _http_log.info(
                f"[SSE] STREAM_CHUNK #{DoubaoSSEParser._first_stream_chunk_logged} data keys={list(data.keys())}"
            )
            for i, op in enumerate(patch_ops):
                po = op.get("patch_object", 0)
                pv = op.get("patch_value", {})
                pv_json = (
                    json.dumps(pv, ensure_ascii=False)
                    if isinstance(pv, dict)
                    else str(pv)[:500]
                )
                _http_log.info(
                    f"[SSE]   patch_op[{i}]: patch_object={po}, patch_value={pv_json[:1000]}"
                )

        for op in patch_ops:
            patch_object = op.get("patch_object", 0)

            if patch_object == 1:
                # content_block 更新（可能包含文本 block_type=10000 或文生图 block_type=2074）
                patches = op.get("patch_value", {}).get("content_block", [])
                for block in patches:
                    block_type = block.get("block_type", 0)
                    if block_type == 2074:
                        # 文生图 creation_block
                        self._extract_image_urls(block)
                    elif block_type == 10000:
                        # 文本块 — 提取增量文本
                        text = (
                            block.get("content", {})
                            .get("text_block", {})
                            .get("text", "")
                        )
                        self._append_text(text, "stream_chunk")
                    elif block_type == 10101:
                        # loading_block — 忽略
                        pass
                    else:
                        # 未知 block_type — 记录一次
                        _http_log.debug(
                            f"[SSE] 未知 block_type={block_type} in STREAM_CHUNK"
                        )

            elif patch_object == 3:
                # 完成标记
                pv = op.get("patch_value", {})
                # 可能包含 msg_finish_attr / answer_finish_attr
                msg_attr = pv.get("msg_finish_attr", {})
                if msg_attr and msg_attr.get("brief") and not self.result.brief:
                    self.result.brief = msg_attr["brief"]
                answer_attr = pv.get("answer_finish_attr", {})
                if answer_attr:
                    pass  # has_suggest 等信息

            elif patch_object == 102:
                # 增量文本（游客模式 / 部分场景的文本路径）
                # content 是 JSON 字符串：{"text": "你好", "text_tags": []}
                pv = op.get("patch_value", {})
                content_str = pv.get("content", "")
                if content_str:
                    try:
                        content_obj = (
                            json.loads(content_str)
                            if isinstance(content_str, str)
                            else content_str
                        )
                        self._append_text(content_obj.get("text", ""), "stream_chunk")
                    except (json.JSONDecodeError, AttributeError):
                        # 非标准 JSON，尝试直接取文本
                        if isinstance(content_str, str) and content_str:
                            self._append_text(content_str, "stream_chunk")

            elif patch_object == 50:
                # ext 元数据更新 - 可能包含建议
                ext = op.get("patch_value", {}).get("ext", {})
                sp_v2 = ext.get("sp_v2", "")
                if sp_v2:
                    try:
                        suggestions = json.loads(sp_v2)
                        if isinstance(suggestions, list):
                            self.result.suggestions = suggestions
                    except json.JSONDecodeError:
                        pass

            elif patch_object == 111:
                # tts_content：TTS 专用文本快照（渐进式替换，非增量）
                # 当 content_block 路径只投递了首字、后续文本走 tts_content 时，
                # 保留最长快照作为兜底文本来源
                tts = op.get("patch_value", {}).get("tts_content", "")
                if tts and len(tts) > len(self._latest_tts_content):
                    self._latest_tts_content = tts

    def _extract_image_urls(self, block: dict):
        """从 creation_block 提取图片 URL"""
        content = block.get("content", {})
        creation_block = content.get("creation_block", {})
        creations = creation_block.get("creations", [])
        for creation in creations:
            image = creation.get("image", {})
            # 优先取无水印原图
            url = image.get("image_ori_raw", {}).get("url", "")
            if not url:
                url = image.get("image_ori", {}).get("url", "")
            if not url:
                url = image.get("image_url", "")
            if url and url not in self.result.image_urls:
                self.result.image_urls.append(url)

    def _process_reply_end(self, data: dict):
        """处理 SSE_REPLY_END 事件"""
        end_type = data.get("end_type", 0)

        if end_type == 1:
            # 消息完成 - 提取 brief
            msg_attr = data.get("msg_finish_attr", {})
            self.result.brief = msg_attr.get("brief", "")

        elif end_type == 2:
            # 回答完成；当前无需额外提取字段。
            pass


class DoubaoHTTPError(RuntimeError):
    def __init__(self, status: int, body: str = ""):
        self.status = int(status or 0)
        self.body = str(body or "")[:2000]
        super().__init__(f"Doubao returned HTTP {self.status}")


class DoubaoStaleConversationError(RuntimeError):
    """A specific Doubao conversation URL was redirected to the bare /chat
    root, i.e. the conversation no longer exists on the server.

    This is the client-side stale signal (there is no server SSE error for
    it). The HTTP layer clears the stored conversation id and starts a fresh
    conversation exactly once, before any visible output. Landing on a
    *different* specific conversation is a real navigation bug, not stale,
    and must fail closed instead of raising this.
    """

    def __init__(
        self,
        conversation_id: str,
        actual_path: str = "",
        expected_path: str = "",
    ):
        self.conversation_id = str(conversation_id or "")
        self.actual_path = str(actual_path or "")
        self.expected_path = str(expected_path or "")
        super().__init__(
            "Doubao conversation is stale: "
            f"path={self.actual_path!r} expected={self.expected_path!r}"
        )


class DoubaoClient:
    """豆包聊天客户端，串联引擎+账号池+会话管理+SSE 解析。"""

    def __init__(self, engine: DoubaoBrowserEngine, account_pool: DoubaoAccountPool):
        self.engine = engine
        self.account_pool = account_pool
        self.session_store = DoubaoConversationStore()

    async def chat(
        self,
        text: str,
        bot_id: str = "",
        conversation_id: str = "",
        exclude_accounts: set | None = None,
    ) -> tuple[DoubaoStreamResult, Optional[DoubaoAccount], str]:
        """非流式聊天，返回 (DoubaoStreamResult, DoubaoAccount, session_id)。

        内部会自动管理会话状态：新会话创建、SSE 解析后更新。
        """
        bot_id = bot_id or DOUBAO_DEFAULT_BOT_ID
        session = self.session_store.get_or_create_session(bot_id, conversation_id)
        if session.account_sessionid:
            acc = await self.account_pool.acquire_wait_for_sessionid(
                session.account_sessionid, 60
            )
        else:
            acc = await self.account_pool.acquire_wait(
                wait_seconds=60, exclude=exclude_accounts
            )
        if not acc:
            return (
                DoubaoStreamResult(error="No available account for this conversation"),
                None,
                session.session_id,
            )
        if not session.account_sessionid:
            session.account_sessionid = acc.sessionid

        await self.account_pool.pace_request(acc)

        try:
            # 构建请求 payload
            payload = self.session_store.build_full_payload(session.session_id, text)
            body_str = json.dumps(payload, ensure_ascii=False)

            _doubao_log.debug(
                f"[Client] chat request: session={session.session_id[:8]}... "
                f"bot_id={bot_id} is_new={not conversation_id} "
                f"account={acc.name}"
            )

            # 通过浏览器引擎执行请求
            result = None
            async for res in self.engine.fetch_chat(
                sessionid=acc.sessionid,
                request_body=body_str,
                conversation_id=conversation_id,
            ):
                result = res
                break  # fetch_chat yield 一次

            if not result:
                self.account_pool.release(acc)
                return (
                    DoubaoStreamResult(error="Empty response from engine"),
                    acc,
                    session.session_id,
                )

            if result.get("status", 0) != 200:
                error_body = result.get("body", "Unknown error")
                # 检测账号失效
                if (
                    "session" in str(error_body).lower()
                    and "expired" in str(error_body).lower()
                ):
                    self.account_pool.mark_invalid(
                        acc, reason="session_expired", error_message=error_body[:200]
                    )
                elif (
                    "rate" in str(error_body).lower()
                    or "limit" in str(error_body).lower()
                ):
                    self.account_pool.mark_rate_limited(
                        acc, error_message=error_body[:200]
                    )
                else:
                    # 非账号问题的上游错误（如浏览器引擎未启动），不标记 invalid
                    _doubao_log.warning(
                        f"[Client] upstream error (not marking invalid): {error_body[:200]}"
                    )
                self.account_pool.release(acc)
                return (
                    DoubaoStreamResult(
                        error=str(
                            DoubaoHTTPError(int(result.get("status") or 0), error_body)
                        )
                    ),
                    acc,
                    session.session_id,
                )

            # 解析 SSE 响应
            raw_body = result.get("body", "")
            _doubao_log.debug(
                f"[Client] raw_body length={len(raw_body)}, preview={raw_body[:300]!r}"
            )
            parser = DoubaoSSEParser()
            stream_result = parser.parse_raw_sse(raw_body)
            _http_log.info(
                f"[Client] SSE parsed: text_len={len(stream_result.text)}, "
                f"error={stream_result.error}, "
                f"conv_id={stream_result.session_meta.conversation_id[:12] if stream_result.session_meta.conversation_id else 'N/A'}"
            )

            if not stream_result.text and not stream_result.error:
                _http_log.warning(
                    f"[Client] ⚠️ SSE 解析成功但文本为空！raw_body 前 500 字符:\n{raw_body[:500]}"
                )

            if stream_result.error:
                # 检测常见错误码
                err = stream_result.error
                if "conversation id is 0" in err:
                    _doubao_log.error(
                        "[Client] conversation id is 0 — 可能缺少 local_conversation_id"
                    )
                elif "invalid param" in err:
                    _doubao_log.error("[Client] invalid param — 请求体格式可能有误")
                # SSE 解析错误可能是请求格式问题，不一定是账号问题
                _http_log.warning(
                    f"[Client] SSE parse error (not marking invalid): {err[:200]}"
                )
                self.account_pool.release(acc)
                return stream_result, acc, session.session_id

            # 更新会话状态
            meta = stream_result.session_meta
            self.session_store.update_from_sse(
                session.session_id,
                conversation_id=meta.conversation_id or None,
                section_id=meta.section_id or None,
                message_index=meta.last_message_index
                if meta.last_message_index
                else None,
            )
            self.session_store.increment_turn(session.session_id)

            # 标记账号成功 + 释放
            self.account_pool.mark_success(acc)
            self.account_pool.release(acc)

            _doubao_log.debug(
                f"[Client] chat complete: conv_id={meta.conversation_id[:12] if meta.conversation_id else 'N/A'}... "
                f"text_len={len(stream_result.text)} session={session.session_id[:8]}..."
            )

            return stream_result, acc, session.session_id

        except Exception as e:
            _doubao_log.error(f"[Client] chat exception: {e}")
            self.account_pool.release(acc)
            return DoubaoStreamResult(error=str(e)), acc, session.session_id

    @staticmethod
    def _classify_stream_exception(exc: Exception) -> tuple[str, bool]:
        message = str(exc).lower()
        if isinstance(exc, (asyncio.TimeoutError, TimeoutError)):
            return "doubao_timeout", True
        if isinstance(exc, DoubaoStaleConversationError):
            # Non-retryable at this layer on purpose: recovery is performed
            # by the HTTP adapter (clear stored id + fresh conversation),
            # not by blindly replaying against the same stale id.
            return "doubao_stale_conversation", False
        if isinstance(exc, DoubaoHTTPError):
            if exc.status in {408, 425, 429}:
                return "doubao_retryable_http", True
            if exc.status in {500, 502, 503, 504}:
                return "doubao_upstream_error", True
            if exc.status in {401, 403}:
                return "doubao_auth_error", False
            return "doubao_http_error", False
        if "sessionid" in message or "cookie" in message:
            return "doubao_configuration_error", False
        if "browser device context incomplete" in message:
            return "doubao_browser_identity_error", False
        if "browser backend" in message or "failed to start" in message:
            return "doubao_browser_startup_error", False
        return "doubao_internal_error", False

    async def chat_stream(
        self,
        text: str,
        bot_id: str = "",
        conversation_id: str = "",
        exclude_accounts: set | None = None,
    ) -> AsyncGenerator[dict, None]:
        bot_id = bot_id or DOUBAO_DEFAULT_BOT_ID
        session = self.session_store.get_or_create_session(bot_id, conversation_id)
        if session.account_sessionid:
            acc = await self.account_pool.acquire_wait_for_sessionid(
                session.account_sessionid, 60
            )
        else:
            acc = await self.account_pool.acquire_wait(
                wait_seconds=60, exclude=exclude_accounts
            )
        if not acc:
            bound_acc = None
            if session.account_sessionid:
                bound_acc = next(
                    (
                        item
                        for item in self.account_pool.accounts
                        if item.sessionid == session.account_sessionid
                    ),
                    None,
                )
            if bound_acc is not None and bound_acc.verification_required:
                yield {
                    "type": "error",
                    "message": (
                        "The account bound to this Doubao conversation requires "
                        "web verification; automatic retries are paused."
                    ),
                    "error_type": "doubao_verification_required",
                    "code": 710022004,
                    "retryable": False,
                }
            else:
                yield {
                    "type": "error",
                    "message": "No available account for this conversation",
                    "error_type": "doubao_account_unavailable",
                    "retryable": True,
                }
            return
        if not session.account_sessionid:
            session.account_sessionid = acc.sessionid
        await self.account_pool.pace_request(acc)

        _doubao_log.debug(
            "[Debug] chat_stream acquired account=%s session=%s "
            "requested_conv=%s effective_conv=%s text_chars=%d",
            _mask_doubao_session_id(acc.sessionid),
            session.session_id[:12],
            str(conversation_id or "")[:16] or "new",
            str(session.conversation_id or "")[:16] or "new",
            len(text),
        )

        yield {"type": "meta", "session_id": session.session_id, "acc": acc}
        payload = self.session_store.build_full_payload(session.session_id, text)
        payload_meta = payload.get("client_meta", {})
        payload_index = payload_meta.get("last_message_index")
        if session.conversation_id and payload_index != session.last_message_index:
            raise RuntimeError(
                "Doubao cursor payload invariant failed: "
                f"payload={payload_index!r} stored={session.last_message_index!r}"
            )

        _doubao_log.debug(
            "[Debug] payload keys=%s local_conv=%s section=%s "
            "message_index=%s stored_message_index=%s cursor_match=%s",
            sorted(payload.keys()),
            payload_meta.get("local_conversation_id"),
            payload_meta.get("last_section_id"),
            payload_index,
            session.last_message_index,
            (not session.conversation_id)
            or payload_index == session.last_message_index,
        )

        status = None

        async def raw_chunks():
            nonlocal status
            async for item in self.engine.fetch_chat_stream(
                sessionid=acc.sessionid,
                request_body=json.dumps(payload, ensure_ascii=False),
                conversation_id=session.conversation_id,
            ):
                kind = item.get("type")
                if kind == "meta":
                    status = int(item.get("status", 0))
                elif kind == "chunk":
                    yield str(item.get("data", ""))
                elif kind == "error":
                    raise DoubaoHTTPError(
                        int(item.get("status", status or 0)),
                        str(item.get("data", "Doubao stream error")),
                    )

        try:
            async for event in self._stream_sse(raw_chunks(), session.session_id, acc):
                yield event
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            error_type, retryable = self._classify_stream_exception(exc)
            error_event = {
                "type": "error",
                "message": str(exc),
                "error_type": error_type,
                "retryable": retryable,
            }
            if isinstance(exc, DoubaoStaleConversationError):
                # Deterministic signal for the HTTP recovery gate, so it does
                # not depend on fragile message/marker string matching.
                error_event["stale_conversation"] = True
            yield error_event
        finally:
            # Account inflight ownership lives here and nowhere else in the
            # streaming stack.  This guarantees exactly one release on normal
            # completion, upstream error, consumer cancellation, or generator close.
            self.account_pool.release(acc)

    async def _stream_sse(
        self,
        raw_body: str | AsyncGenerator[str, Any],
        session_id: str,
        acc: DoubaoAccount,
    ):
        """逐事件解析 SSE 并 yield 增量文本。"""
        parser = DoubaoSSEParser()

        async def iter_events():
            if isinstance(raw_body, str):
                for parsed in parser._split_sse_events(raw_body):
                    yield parsed
                return

            pending = ""
            async for raw_chunk in raw_body:
                pending += raw_chunk
                while "\n\n" in pending:
                    packet, pending = pending.split("\n\n", 1)
                    for parsed in parser._split_sse_events(packet + "\n\n"):
                        yield parsed
            if pending.strip():
                for parsed in parser._split_sse_events(pending):
                    yield parsed

        full_text = ""
        final_brief = ""
        latest_tts_content = ""
        saw_terminal_end = False
        stored_session = self.session_store.get_session(session_id)
        cursor_previous = (
            stored_session.last_message_index if stored_session is not None else 0
        )
        cursor_ack_query_max = None
        cursor_full_msg_max = None
        cursor_stream_msg_max = None
        text_sources_seen: set[str] = set()

        def normalized_index(value):
            try:
                return int(value) if value is not None else None
            except (TypeError, ValueError):
                return None

        async def emit_text(text: str, source: str):
            nonlocal full_text
            text = str(text or "")
            if not text:
                return
            text_sources_seen.add(source)
            full_text, delta = _merge_doubao_text(full_text, text, mode="delta")
            if delta:
                yield {"type": "delta", "content": delta}

        # 显式持有 generator 引用，确保 break/return 时能通过 finally 关闭整条链，
        # 否则 fetch_chat_stream 的 finally（归还 page 到池）不会执行。
        events_gen = iter_events()
        try:
            async for evt in events_gen:
                if evt.event_type == "SSE_HEARTBEAT":
                    continue

                if evt.event_type == "SSE_ACK":
                    meta = evt.data.get("ack_client_meta", {})
                    conv_id = meta.get("conversation_id", "")
                    section_id = meta.get("section_id", "")
                    query_list = evt.data.get("query_list", []) or []
                    query_indexes = [
                        q.get("message_index")
                        for q in query_list
                        if isinstance(q, dict)
                    ]
                    query_indexes = [
                        int(v)
                        for v in query_indexes
                        if v is not None and (isinstance(v, int) or str(v).isdigit())
                    ]
                    ack_index = max(query_indexes) if query_indexes else None
                    if ack_index is not None:
                        cursor_ack_query_max = (
                            ack_index
                            if cursor_ack_query_max is None
                            else max(cursor_ack_query_max, ack_index)
                        )
                    self.session_store.update_from_sse(
                        session_id,
                        conversation_id=conv_id or None,
                        section_id=section_id or None,
                        message_index=ack_index,
                    )
                    if conv_id:
                        yield {"type": "conversation", "conversation_id": conv_id}
                    continue

                if evt.event_type == "FULL_MSG_NOTIFY":
                    message = evt.data.get("message", {})
                    full_index = normalized_index(message.get("index_in_conv"))
                    if full_index is not None:
                        cursor_full_msg_max = (
                            full_index
                            if cursor_full_msg_max is None
                            else max(cursor_full_msg_max, full_index)
                        )
                    self.session_store.update_from_sse(
                        session_id,
                        conversation_id=message.get("conversation_id") or None,
                        section_id=message.get("section_id") or None,
                        message_index=full_index,
                    )
                    continue

                if evt.event_type == "STREAM_MSG_NOTIFY":
                    meta = evt.data.get("meta", {})
                    stream_index = normalized_index(meta.get("index_in_conv"))
                    if stream_index is not None:
                        cursor_stream_msg_max = (
                            stream_index
                            if cursor_stream_msg_max is None
                            else max(cursor_stream_msg_max, stream_index)
                        )
                    self.session_store.update_from_sse(
                        session_id,
                        conversation_id=meta.get("conversation_id") or None,
                        section_id=meta.get("section_id") or None,
                        message_index=stream_index,
                    )
                    content = evt.data.get("content", {})
                    for block in content.get("content_block", []):
                        if block.get("block_type") == 10000:
                            text = (
                                block.get("content", {})
                                .get("text_block", {})
                                .get("text", "")
                            )
                            async for output in emit_text(text, "stream_msg_notify"):
                                yield output
                            break
                    continue

                if evt.event_type == "CHUNK_DELTA":
                    async for output in emit_text(
                        evt.data.get("text", ""), "chunk_delta"
                    ):
                        yield output
                    continue

                if evt.event_type == "STREAM_CHUNK":
                    for op in evt.data.get("patch_op", []):
                        patch_object = op.get("patch_object", 0)
                        if patch_object == 1:
                            for block in op.get("patch_value", {}).get(
                                "content_block", []
                            ):
                                block_type = block.get("block_type", 0)
                                if block_type == 2074:
                                    for url in self._extract_image_urls(block):
                                        yield {"type": "image", "url": url}
                                elif block_type == 10000:
                                    text = (
                                        block.get("content", {})
                                        .get("text_block", {})
                                        .get("text", "")
                                    )
                                    async for output in emit_text(
                                        text, "stream_chunk_content"
                                    ):
                                        yield output
                        elif patch_object == 102:
                            content_value = op.get("patch_value", {}).get("content", "")
                            try:
                                obj = (
                                    json.loads(content_value)
                                    if isinstance(content_value, str)
                                    else content_value
                                )
                                text = (
                                    obj.get("text", "") if isinstance(obj, dict) else ""
                                )
                            except json.JSONDecodeError:
                                text = ""
                            async for output in emit_text(text, "stream_chunk_102"):
                                yield output
                        elif patch_object == 50:
                            sp_v2 = (
                                op.get("patch_value", {})
                                .get("ext", {})
                                .get("sp_v2", "")
                            )
                            if sp_v2:
                                try:
                                    items = json.loads(sp_v2)
                                    if isinstance(items, list):
                                        yield {"type": "suggestion", "items": items}
                                except json.JSONDecodeError:
                                    pass
                        elif patch_object == 111:
                            # tts_content：TTS 专用文本快照（渐进式替换）
                            # content_block 路径可能只投递首字，保留最长快照作兜底
                            tts = op.get("patch_value", {}).get("tts_content", "")
                            if tts and len(tts) > len(latest_tts_content):
                                latest_tts_content = tts
                    continue

                if evt.event_type == "SSE_REPLY_END":
                    end_type = int(evt.data.get("end_type", 0) or 0)
                    if end_type == 1:
                        final_brief = str(
                            evt.data.get("msg_finish_attr", {}).get("brief", "") or ""
                        )
                        if (
                            VE_DOUBAO_LOG_DEBUG
                            and final_brief
                            and full_text
                            and final_brief.replace("\n", "")
                            != full_text.replace("\n", "")
                        ):
                            _http_log.debug(
                                "[SSE] streamed text differs from final brief: stream=%r brief=%r",
                                full_text,
                                final_brief,
                            )
                    elif end_type == 3:
                        saw_terminal_end = True
                        cursor_session = self.session_store.get_session(session_id)
                        stored_index = (
                            cursor_session.last_message_index
                            if cursor_session is not None
                            else None
                        )
                        observed_values = [
                            value
                            for value in (
                                cursor_ack_query_max,
                                cursor_full_msg_max,
                                cursor_stream_msg_max,
                            )
                            if value is not None
                        ]
                        observed_max = max(observed_values) if observed_values else None

                        _doubao_log.debug(
                            "[Debug] Doubao cursor update session=%s previous=%s "
                            "ack_query_max=%s full_msg_max=%s stream_msg_max=%s "
                            "observed_max=%s stored=%s text_sources=%s",
                            session_id[:12],
                            cursor_previous,
                            cursor_ack_query_max,
                            cursor_full_msg_max,
                            cursor_stream_msg_max,
                            observed_max,
                            stored_index,
                            sorted(text_sources_seen),
                        )

                        if (
                            observed_max is not None
                            and stored_index is not None
                            and stored_index < observed_max
                        ):
                            raise RuntimeError(
                                "Doubao cursor invariant failed: "
                                f"observed_max={observed_max} stored={stored_index}"
                            )
                        break
                    continue

                if evt.event_type == "STREAM_ERROR":
                    error_msg = str(
                        evt.data.get("error_msg")
                        or evt.data.get("message")
                        or evt.data.get("msg")
                        or "Unknown SSE error"
                    )
                    error_code = evt.data.get("error_code")
                    extra = (
                        evt.data.get("extra", {}) if isinstance(evt.data, dict) else {}
                    )
                    decision_raw = (
                        extra.get("decision", "") if isinstance(extra, dict) else ""
                    )
                    try:
                        decision = (
                            json.loads(decision_raw)
                            if isinstance(decision_raw, str)
                            else decision_raw
                        )
                    except json.JSONDecodeError:
                        decision = {}
                    decision = decision if isinstance(decision, dict) else {}
                    # Never log or return the opaque verification challenge detail.
                    # Keep only bounded, non-secret routing metadata useful for diagnosis.
                    safe_error = {
                        "error_code": error_code,
                        "error_msg": error_msg,
                        "extra": {
                            "ack": extra.get("ack")
                            if isinstance(extra, dict)
                            else None,
                            "decision": {
                                key: decision.get(key)
                                for key in (
                                    "code",
                                    "from",
                                    "type",
                                    "region",
                                    "subtype",
                                    "verify_scene",
                                    "log_id",
                                )
                                if decision.get(key) is not None
                            },
                        },
                    }
                    safe_details = json.dumps(
                        safe_error, ensure_ascii=False, default=str
                    )[:2000]
                    verification_required = bool(
                        int(error_code or 0) == 710022004
                        and isinstance(decision, dict)
                        and decision.get("type") == "verify"
                    )
                    log_method = (
                        _doubao_log.warning
                        if verification_required
                        else _doubao_log.error
                    )
                    log_method(
                        "[SSE] STREAM_ERROR id=%s code=%s message=%s details=%s",
                        evt.id,
                        error_code,
                        error_msg,
                        safe_details,
                    )
                    if verification_required:
                        self.account_pool.mark_verification_required(acc, error_msg)
                        public_message = (
                            "Doubao web verification is required for this automated browser "
                            "session. Automatic retries are paused; use the normal Doubao web "
                            "flow or an official API before retrying."
                        )
                        error_type = "doubao_verification_required"
                    else:
                        acc.last_error = error_msg[:200]
                        acc.consecutive_failures += 1
                        public_message = error_msg
                        error_type = "doubao_error"
                    yield {
                        "type": "error",
                        "message": public_message,
                        "error_type": error_type,
                        "code": error_code,
                        "retryable": False if verification_required else None,
                        "details": safe_details if VE_DOUBAO_LOG_DEBUG else None,
                    }
                    return
        finally:
            # 关闭 iter_events → raw_chunks → fetch_chat_stream 整条链，
            # 确保 fetch_chat_stream 的 finally 块执行（归还 page 到池）。
            # aclose() 对已耗尽的 generator 是 no-op，安全调用。
            # 用嵌套 finally 隔离异常：events_gen.aclose() 失败不能阻止 raw_body.aclose()
            try:
                await events_gen.aclose()
            finally:
                if not isinstance(raw_body, str):
                    await raw_body.aclose()

        # 兜底：content_block 路径可能只投递了部分文本，依次尝试 brief 和 tts_content。
        # 仅当兜底文本以已流式文本为前缀时补发剩余部分，避免内容重复。
        for fallback in (final_brief, latest_tts_content):
            if fallback and len(fallback) > len(full_text):
                if not full_text or fallback.startswith(full_text):
                    delta = fallback[len(full_text) :]
                    full_text = fallback
                    yield {"type": "delta", "content": delta}
                    break
        if not saw_terminal_end:
            error_type = (
                "doubao_partial_stream_end" if full_text else "doubao_truncated_stream"
            )
            yield {
                "type": "error",
                "error_type": error_type,
                "retryable": not bool(full_text),
                "partial": bool(full_text),
                "message": "Doubao stream ended without a terminal provider event",
            }
            return
        self.session_store.increment_turn(session_id)
        self.account_pool.mark_success(acc)
        # Note: account release is handled by chat_stream's finally block (single owner)
        yield {"type": "done"}

    @staticmethod
    def _extract_image_urls(block: dict) -> list[str]:
        """从 creation_block 提取图片 URL"""
        urls = []
        content = block.get("content", {})
        creation_block = content.get("creation_block", {})
        creations = creation_block.get("creations", [])
        for creation in creations:
            image = creation.get("image", {})
            url = image.get("image_ori_raw", {}).get("url", "")
            if not url:
                url = image.get("image_ori", {}).get("url", "")
            if not url:
                url = image.get("image_url", "")
            if url and url not in urls:
                urls.append(url)
        return urls

    async def chat_with_retry(
        self,
        text: str,
        bot_id: str = "",
        conversation_id: str = "",
        max_retries: int | None = None,
    ) -> tuple[DoubaoStreamResult, Optional[DoubaoAccount], str]:
        """带重试的聊天（非流式）。"""
        max_retries = max(1, int(max_retries or DOUBAO_STREAM_MAX_RETRIES))
        exclude = set()

        for attempt in range(max_retries):
            result, acc, session_id = await self.chat(
                text=text,
                bot_id=bot_id,
                conversation_id=conversation_id,
                exclude_accounts=exclude,
            )

            if not result.error:
                return result, acc, session_id

            if acc:
                exclude.add(acc.sessionid)

            _doubao_log.warning(
                f"[Client] retry {attempt + 1}/{max_retries}: "
                f"error={result.error[:100]}"
            )
            await asyncio.sleep(0.5)

        return result, acc, session_id

    async def stream_with_retry(
        self,
        text: str,
        bot_id: str = "",
        conversation_id: str = "",
        max_retries: int | None = None,
    ) -> AsyncGenerator[dict, None]:
        """Retry only before the server has committed the request.

        Any conversation/delta/image/suggestion event proves that the upstream
        accepted the turn.  Replaying after that point risks duplicate messages.
        Explicit retryable=False always fails closed.
        """
        attempts = max(1, int(max_retries or DOUBAO_STREAM_MAX_RETRIES))
        last_error = None

        for attempt in range(1, attempts + 1):
            request_committed = False
            retry_requested = False
            stream = self.chat_stream(
                text=text,
                bot_id=bot_id,
                conversation_id=conversation_id,
                exclude_accounts=None,
            )
            try:
                async for event in stream:
                    kind = event.get("type")
                    if kind == "meta":
                        continue
                    if kind in {"conversation", "delta", "image", "suggestion"}:
                        request_committed = True
                        yield event
                        continue
                    if kind == "done":
                        yield event
                        return
                    if kind != "error":
                        continue

                    last_error = dict(event)
                    explicitly_non_retryable = event.get("retryable") is False
                    # INVARIANT (do not weaken): request_committed is the sole
                    # authoritative dedup gate. It is set on the first
                    # conversation/delta/image/suggestion event (the server has
                    # accepted the turn). Never replace this gate with the
                    # per-event `retryable` flag; replaying a committed turn would
                    # duplicate the Doubao message. `retryable` only refines
                    # behavior BEFORE commit.
                    if (
                        request_committed
                        or explicitly_non_retryable
                        or attempt >= attempts
                    ):
                        yield event
                        return

                    retry_requested = True
                    delay = min(
                        DOUBAO_STREAM_RETRY_MAX_DELAY,
                        DOUBAO_STREAM_RETRY_BASE_DELAY * (2 ** (attempt - 1)),
                    )
                    delay += random.uniform(0.0, min(0.25, delay * 0.2))
                    _doubao_log.warning(
                        "[Client] stream retry %d/%d in %.2fs: type=%s code=%s error=%s",
                        attempt,
                        attempts,
                        delay,
                        event.get("error_type", "doubao_error"),
                        event.get("code"),
                        str(event.get("message", ""))[:160],
                    )
                    await asyncio.sleep(delay)
                    break
            finally:
                await stream.aclose()

            if retry_requested:
                continue
            if request_committed:
                yield {
                    "type": "error",
                    "message": "Doubao stream ended after the request was committed",
                    "error_type": "doubao_partial_stream_end",
                    "retryable": False,
                }
                return

        yield last_error or {
            "type": "error",
            "message": "Doubao stream retries exhausted",
            "error_type": "doubao_retries_exhausted",
            "retryable": False,
        }


def _local_model_residency_snapshot() -> dict:
    """Return local MLX model object identities without loading or releasing anything."""
    return {
        "mlx_lm_model": id(mlx_llm_model) if mlx_llm_model is not None else None,
        "mlx_lm_tokenizer": id(mlx_llm_tokenizer)
        if mlx_llm_tokenizer is not None
        else None,
        "mlx_lm_model_id": LLM_CURRENT_MODEL_ID,
        "mlx_vlm_model": id(mlx_vlm_model) if mlx_vlm_model is not None else None,
        "mlx_vlm_processor": id(mlx_vlm_processor)
        if mlx_vlm_processor is not None
        else None,
        "mlx_vlm_model_id": MLX_VLM_CURRENT_MODEL_ID,
    }


class DoubaoRuntime:
    """Directly owns the Playwright browser client; no nested HTTP gateway."""

    def __init__(self):
        self._start_lock = threading.Lock()
        self._ready = threading.Event()
        self._thread = None
        self._loop = None
        self._engine: Optional[DoubaoBrowserEngine] = None
        self._pool = None
        self._client = None
        self._configured_ids = ()
        self._shutdown_requested = threading.Event()
        self._activity_lock = threading.Lock()
        self._active_futures: set[concurrent.futures.Future] = set()
        self._active_queues: set[queue.Queue] = set()
        self._initialize_lock: Optional[asyncio.Lock] = None

    def _loop_worker(self):
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        self._loop = loop
        self._ready.set()
        try:
            loop.run_forever()
        finally:
            pending = {task for task in asyncio.all_tasks(loop) if not task.done()}
            for task in pending:
                task.cancel("Doubao runtime loop is shutting down")
            if pending:
                try:
                    done, still_pending = loop.run_until_complete(
                        asyncio.wait(pending, timeout=1.5)
                    )
                    for task in done:
                        try:
                            task.result()
                        except (asyncio.CancelledError, Exception):
                            pass
                    if still_pending:
                        _doubao_log.warning(
                            "Detaching %d non-cooperative Doubao task(s) during loop shutdown",
                            len(still_pending),
                        )
                except Exception:
                    _doubao_log.warning(
                        "Bounded Doubao task drain failed", exc_info=True
                    )
            loop.close()

    def _ensure_loop(self):
        if self._shutdown_requested.is_set() or SERVER_SHUTTING_DOWN.is_set():
            raise RuntimeError("Doubao runtime is shutting down")
        with self._start_lock:
            if self._thread and self._thread.is_alive() and self._loop:
                return
            self._ready.clear()
            self._thread = threading.Thread(
                target=self._loop_worker, name="DoubaoBrowserLoop", daemon=True
            )
            self._thread.start()
        if not self._ready.wait(5.0):
            raise RuntimeError("Doubao browser event loop did not start")

    async def _initialize(self):
        if self._shutdown_requested.is_set() or SERVER_SHUTTING_DOWN.is_set():
            raise RuntimeError("Doubao runtime is shutting down")
        if self._initialize_lock is None:
            self._initialize_lock = asyncio.Lock()
        async with self._initialize_lock:
            if self._shutdown_requested.is_set() or SERVER_SHUTTING_DOWN.is_set():
                raise RuntimeError("Doubao runtime is shutting down")
            if (
                self._client is not None
                and self._engine is not None
                and self._engine._started
            ):
                return

            local_models_before = _local_model_residency_snapshot()
            session_ids = _load_doubao_session_ids()
            if not session_ids:
                raise RuntimeError(
                    "Set DOUBAO_SESSION_ID, DOUBAO_SESSION_IDS, or "
                    "DOUBAO_COOKIE_HEADER before using LLM:doubao"
                )
            accounts = [
                DoubaoAccount(sessionid=sid, name=f"env-account-{index}")
                for index, sid in enumerate(session_ids, 1)
            ]
            pool = DoubaoAccountPool(
                DoubaoMemoryDB([account.to_dict() for account in accounts]),
                max_inflight=DOUBAO_MAX_INFLIGHT,
            )
            await pool.load()
            engine = DoubaoBrowserEngine(
                pool_size=DOUBAO_BROWSER_POOL_SIZE,
                base_url=DOUBAO_BASE_URL,
            )
            try:
                await engine.start()
                if not engine._started:
                    if DOUBAO_BROWSER_ENGINE in {"chromium", "firefox"}:
                        hint = (
                            "pip install playwright && python -m playwright install "
                            f"{DOUBAO_BROWSER_ENGINE}"
                        )
                    else:
                        hint = "install and configure the selected browser backend"
                    raise RuntimeError(
                        f"Doubao browser backend {DOUBAO_BROWSER_ENGINE!r} failed to start; "
                        f"{hint}"
                    )
                local_models_after = _local_model_residency_snapshot()
                if local_models_after != local_models_before:
                    raise RuntimeError(
                        "Browser backend startup unexpectedly changed local MLX model residency"
                    )
            except BaseException:
                try:
                    await engine.stop()
                except Exception:
                    _doubao_log.debug(
                        "Failed to clean up partially initialized Doubao browser",
                        exc_info=True,
                    )
                raise

            self._configured_ids = session_ids
            self._pool = pool
            self._engine = engine
            self._client = DoubaoClient(engine, pool)
            _doubao_log.debug(
                "Doubao browser backend ready alongside local models: "
                "engine=%s accounts=%s local=%s debug=%s "
                "first_event_timeout=%.0fs idle_timeout=%.0fs",
                DOUBAO_BROWSER_ENGINE,
                [_mask_doubao_session_id(v) for v in session_ids],
                local_models_after,
                VE_DOUBAO_LOG_DEBUG,
                DOUBAO_STREAM_FIRST_EVENT_TIMEOUT,
                DOUBAO_STREAM_IDLE_TIMEOUT,
            )

    async def _chat(self, text: str, conversation_id: str):
        await self._initialize()
        client = self._client
        if client is None:
            raise RuntimeError("Doubao client is not initialized")
        result, _account, local_session_id = await client.chat(
            text=text, bot_id=DOUBAO_DEFAULT_BOT_ID, conversation_id=conversation_id
        )
        return result, local_session_id

    def _track_future(self, future: concurrent.futures.Future):
        with self._activity_lock:
            self._active_futures.add(future)

        def _done(done_future):
            with self._activity_lock:
                self._active_futures.discard(done_future)

        future.add_done_callback(_done)
        return future

    @staticmethod
    def _put_terminal_nowait(output_queue, event: dict) -> None:
        try:
            output_queue.put_nowait(event)
            return
        except queue.Full:
            pass
        try:
            output_queue.get_nowait()
        except queue.Empty:
            pass
        try:
            output_queue.put_nowait(event)
        except queue.Full:
            _doubao_log.warning(
                "Unable to publish Doubao terminal event: queue remains full"
            )

    def submit_chat(self, text: str, conversation_id: str = ""):
        self._ensure_loop()
        loop = self._loop
        if loop is None:
            raise RuntimeError("Doubao event loop is not initialized")
        future = asyncio.run_coroutine_threadsafe(
            self._chat(text, conversation_id), loop
        )
        return self._track_future(future)

    async def _chat_stream(self, text: str, conversation_id: str, output_queue):
        started = time.monotonic()

        _doubao_log.debug(
            "[Debug] runtime stream entered conv=%s text_chars=%d",
            str(conversation_id or "")[:16] or "new",
            len(text),
        )

        terminal_forwarded = False
        try:
            await self._initialize()

            _doubao_log.debug(
                "[Debug] runtime initialized; entering client.chat_stream"
            )

            client = self._client
            if client is None:
                raise RuntimeError("Doubao client is not initialized")
            async for event in client.stream_with_retry(
                text=text,
                bot_id=DOUBAO_DEFAULT_BOT_ID,
                conversation_id=conversation_id,
                max_retries=DOUBAO_STREAM_MAX_RETRIES,
            ):
                kind = event.get("type")

                _doubao_log.debug("[Debug] runtime forwarding event type=%s", kind)

                if self._shutdown_requested.is_set() or SERVER_SHUTTING_DOWN.is_set():
                    break
                while True:
                    if (
                        self._shutdown_requested.is_set()
                        or SERVER_SHUTTING_DOWN.is_set()
                    ):
                        break
                    try:
                        await asyncio.to_thread(output_queue.put, event, True, 0.25)
                        break
                    except queue.Full:
                        _doubao_log.debug(
                            "[Debug] runtime output queue backpressure kind=%s size=%d",
                            kind,
                            output_queue.qsize(),
                        )
                        continue
                if self._shutdown_requested.is_set() or SERVER_SHUTTING_DOWN.is_set():
                    break
                if kind in {"done", "error", "shutdown"}:
                    terminal_forwarded = True
        except asyncio.CancelledError:
            _doubao_log.debug(
                "[Debug] runtime stream cancelled after %.2fs",
                time.monotonic() - started,
            )
            raise
        except Exception as exc:
            _doubao_log.debug(
                "[Debug] runtime stream exception after %.2fs: %s",
                time.monotonic() - started,
                exc,
                exc_info=True,
            )
            self._put_terminal_nowait(
                output_queue,
                {"type": "error", "message": str(exc), "source": "runtime"},
            )
            terminal_forwarded = True
        finally:
            if not terminal_forwarded:
                self._put_terminal_nowait(
                    output_queue,
                    {"type": "bridge_done"},
                )
            with self._activity_lock:
                self._active_queues.discard(output_queue)

            _doubao_log.debug(
                "[Debug] runtime stream exited after %.2fs",
                time.monotonic() - started,
            )

    def submit_chat_stream(self, text: str, conversation_id: str = ""):
        self._ensure_loop()
        output_queue = queue.Queue(maxsize=1024)
        with self._activity_lock:
            self._active_queues.add(output_queue)
        try:
            loop = self._loop
            if loop is None:
                raise RuntimeError("Doubao event loop is not initialized")
            future = asyncio.run_coroutine_threadsafe(
                self._chat_stream(text, conversation_id, output_queue), loop
            )
        except Exception:
            with self._activity_lock:
                self._active_queues.discard(output_queue)
            raise
        return self._track_future(future), output_queue

    async def _apply_auth_snapshot(self, snapshot: dict) -> dict:
        cookies = snapshot.get("cookies") if isinstance(snapshot, dict) else None
        sessionid = _set_doubao_live_cookie_snapshot(cookies or [])

        # Firefox 插件在 AUTH_SNAPSHOT 顶层显式带上 ttwid（cookies API
        # 缺失时会从 document.cookie 兜底）。优先使用该字段，缺失时回退到
        # live cookie 快照中的 ttwid。该值会在页面导航后强制覆盖回 Camoufox。
        forced_ttwid = (
            str(snapshot.get("ttwid") or "").strip()
            if isinstance(snapshot, dict)
            else ""
        )
        if not forced_ttwid:
            for cookie in _doubao_live_cookie_snapshot():
                if cookie.get("name") == "ttwid":
                    forced_ttwid = str(cookie.get("value") or "")
                    if forced_ttwid:
                        break
        _set_doubao_forced_ttwid(forced_ttwid)

        conversation = (
            snapshot.get("conversation") if isinstance(snapshot, dict) else None
        )
        if not isinstance(conversation, dict):
            raise ValueError(
                "Firefox did not provide Doubao conversation state. "
                "Open the target conversation, send one successful message, "
                "wait for the answer to finish, then click Sync."
            )
        conversation_id = str(conversation.get("conversation_id") or "").strip()
        section_id = str(conversation.get("section_id") or "").strip()
        try:
            raw_last_message_index = conversation.get("last_message_index")
            if raw_last_message_index is None:
                raise ValueError("last_message_index is missing")
            last_message_index = int(raw_last_message_index)
        except (TypeError, ValueError):
            last_message_index = 0
        if not conversation_id or not section_id or last_message_index <= 0:
            raise ValueError(
                "Incomplete Doubao conversation snapshot: conversation_id, "
                "section_id, and a positive last_message_index are required."
            )

        page_url_from_extension = str(snapshot.get("page_url") or "").strip()
        expected_path = f"/chat/{conversation_id}"
        captured_path = urllib.parse.urlparse(page_url_from_extension).path.rstrip("/")
        if captured_path != expected_path.rstrip("/"):
            raise ValueError(
                "Firefox tab does not match the captured Doubao conversation: "
                f"page={captured_path!r} expected={expected_path!r}"
            )

        # Cancel old requests and rebuild only the Doubao browser runtime.
        with self._activity_lock:
            active = list(self._active_futures)
        for future in active:
            future.cancel()
        await asyncio.sleep(0)

        engine = self._engine
        if engine is not None:
            await asyncio.wait_for(engine.stop(), timeout=10.0)
        self._client = None
        self._pool = None
        self._engine = None
        self._configured_ids = ()

        os.environ["DOUBAO_SESSION_ID"] = sessionid
        os.environ.pop("DOUBAO_SESSION_IDS", None)
        await self._initialize()

        # Restore the exact Firefox conversation cursor before any XiaoAI turn.
        client = self._client
        engine_value = self._engine
        if client is None or engine_value is None:
            raise RuntimeError("Doubao runtime failed to initialize")
        # _initialize() mutates self._engine; cast prevents stale literal-None
        # narrowing across that async method call.
        engine = cast(DoubaoBrowserEngine, engine_value)
        restored_session = client.session_store.get_or_create_session(
            DOUBAO_DEFAULT_BOT_ID,
            conversation_id,
        )
        restored_session.account_sessionid = sessionid
        client.session_store.update_from_sse(
            restored_session.session_id,
            conversation_id=conversation_id,
            section_id=section_id,
            message_index=last_message_index,
        )

        # Inject cookies, load /chat, then navigate to the captured conversation.
        page = context = None
        try:
            page, context = await engine.acquire_page(wait_seconds=10.0)
            await engine._prepare_chat_page(
                page,
                context,
                sessionid,
                conversation_id=conversation_id,
            )
            title = await page.title()
            actual_path = str(
                await page.evaluate("() => window.location.pathname")
            ).rstrip("/")
            if actual_path != expected_path.rstrip("/"):
                raise RuntimeError(
                    "Restored Doubao page path mismatch: "
                    f"actual={actual_path!r} expected={expected_path!r}"
                )
            actual_cookies = await context.cookies(f"{DOUBAO_BASE_URL}{expected_path}")
            cookie_names = {str(item.get("name") or "") for item in actual_cookies}
            missing = sorted(
                name
                for name in ("sessionid", "sessionid_ss", "sid_tt")
                if name not in cookie_names
            )
            if missing:
                raise RuntimeError(
                    "Restored Doubao page is missing required cookies: "
                    + ",".join(missing)
                )
        finally:
            if page is not None and context is not None:
                await engine.release_page(page, context)

        xiaoai_result = {
            "notified": False,
            "replayed": False,
            "query_chars": 0,
        }
        bridge_thread = globals().get("XIAOAI_BRIDGE_THREAD")
        if bridge_thread is not None:
            xiaoai_result = bridge_thread.notify_doubao_auth_refreshed(
                conversation_id,
            )
        xiaoai_resumed = bool(xiaoai_result.get("notified"))
        question_replayed = bool(xiaoai_result.get("replayed"))

        # HTTP browser callers also resume the same captured conversation.
        _doubao_http_set_last_conversation_id(conversation_id)
        cookie_count = len(_doubao_live_cookie_snapshot())
        _doubao_log.debug(
            "Applied Firefox Doubao snapshot and restored conversation: "
            "cookies=%d session=%s conversation=%s section=%s "
            "last_message_index=%d page=%s title=%r "
            "xiaoai_resumed=%s question_replayed=%s replay_chars=%s",
            cookie_count,
            _mask_doubao_session_id(sessionid),
            conversation_id[:18],
            section_id[:18],
            last_message_index,
            expected_path,
            title[:80],
            xiaoai_resumed,
            question_replayed,
            int(xiaoai_result.get("query_chars") or 0),
        )
        return {
            "type": "AUTH_APPLIED",
            "provider": "doubao",
            "success": True,
            "validated": True,
            "restored": True,
            "cookie_count": cookie_count,
            "conversation_id": conversation_id,
            "last_message_index": last_message_index,
            "xiaoai_resumed": xiaoai_resumed,
            "question_replayed": question_replayed,
            "replay_query_chars": int(xiaoai_result.get("query_chars") or 0),
        }

    def apply_auth_snapshot(self, snapshot: dict, timeout: float = 30.0) -> dict:
        self._ensure_loop()
        loop = self._loop
        if loop is None:
            raise RuntimeError("Doubao event loop is not initialized")
        future = asyncio.run_coroutine_threadsafe(
            self._apply_auth_snapshot(snapshot),
            loop,
        )
        return future.result(timeout=max(5.0, float(timeout)))

    def begin_shutdown(self) -> None:
        first = not self._shutdown_requested.is_set()
        self._shutdown_requested.set()
        with self._activity_lock:
            queues = list(self._active_queues)
            futures = list(self._active_futures)
        if first or queues or futures:
            _doubao_log.debug(
                "Stopping Doubao runtime: active_futures=%d active_streams=%d",
                len(futures),
                len(queues),
            )
        for output_queue in queues:
            self._put_terminal_nowait(
                output_queue, {"type": "shutdown", "message": "Server is shutting down"}
            )
        for future in futures:
            future.cancel()

    async def _shutdown(self):
        # begin_shutdown() already cancels every Future submitted by this
        # runtime. Do not mass-cancel asyncio.all_tasks() here: Playwright owns
        # internal tasks that must remain alive long enough to close contexts
        # and reap Chromium cleanly.
        await asyncio.sleep(0)
        engine = self._engine
        if engine is not None:
            _doubao_log.debug(
                "Closing Doubao browser backend: engine=%s", DOUBAO_BROWSER_ENGINE
            )
            try:
                await asyncio.wait_for(engine.stop(), timeout=1.5)
                _doubao_log.debug("Doubao browser engine stopped")
            except asyncio.TimeoutError:
                _doubao_log.warning("Doubao browser engine shutdown timed out")
            except Exception:
                _doubao_log.warning(
                    "Doubao browser engine shutdown failed", exc_info=True
                )
        self._client = self._pool = self._engine = None

    def stop(self, timeout: float = 10.0) -> bool:
        self.begin_shutdown()
        loop, thread = self._loop, self._thread
        if not loop or not thread:
            _doubao_log.debug("Doubao runtime was not started")
            return True
        if thread is threading.current_thread():
            _doubao_log.warning("Doubao runtime cannot join its own loop thread")
            return False
        if thread.is_alive() and not loop.is_closed():
            shutdown_future = None
            try:
                shutdown_future = asyncio.run_coroutine_threadsafe(
                    self._shutdown(), loop
                )
                shutdown_future.result(timeout=max(1.0, float(timeout) - 1.0))
            except concurrent.futures.TimeoutError:
                _doubao_log.warning("Doubao runtime coroutine shutdown timed out")
                if shutdown_future is not None:
                    shutdown_future.cancel()
            except Exception:
                _doubao_log.warning(
                    "Doubao runtime coroutine shutdown failed", exc_info=True
                )
            try:
                loop.call_soon_threadsafe(loop.stop)
            except Exception:
                _doubao_log.warning("Failed requesting Doubao loop stop", exc_info=True)
            thread.join(timeout=3.0)
        stopped = not thread.is_alive()
        if stopped:
            _doubao_log.debug("Doubao runtime thread stopped")
            self._loop = self._thread = None
            with self._activity_lock:
                self._active_futures.clear()
                self._active_queues.clear()
        else:
            _doubao_log.error(
                "Doubao runtime thread remains alive after shutdown timeout: name=%s ident=%s",
                thread.name,
                thread.ident,
            )
        return stopped


DOUBAO_RUNTIME = DoubaoRuntime()


def _browser_state_report() -> dict:
    """Secret-free summary of persisted + in-memory browser state for the
    extension panel. Never includes cookie values or Authorization tokens.
    """
    state = _browser_state_read()
    providers = state.get("providers", {}) if isinstance(state, dict) else {}

    def _auth_summary(provider: str) -> dict:
        raw = providers.get(provider, {}) if isinstance(providers, dict) else {}
        auth = raw.get("auth", {}) if isinstance(raw, dict) else {}
        cookies = auth.get("cookies") if isinstance(auth, dict) else None
        # DeepSeek does not keep a flat auth.cookies list; its cookies live
        # inside the Playwright storage_state blob (auth.storage_state.cookies).
        # Fall back to that so the panel does not report 0 cookies for DeepSeek.
        if not (isinstance(cookies, list) and cookies):
            storage_state = (
                auth.get("storage_state") if isinstance(auth, dict) else None
            )
            if isinstance(storage_state, dict):
                nested = storage_state.get("cookies")
                if isinstance(nested, list):
                    cookies = nested
        cookie_list = cookies if isinstance(cookies, list) else []
        names = sorted(
            {
                str(item.get("name") or "")
                for item in cookie_list
                if isinstance(item, dict) and item.get("name")
            }
        )
        return {
            # Raw stored-cookie count (DeepSeek keeps same-name cookies for
            # multiple domains, so this can exceed the number of unique names).
            "cookie_count": len(cookie_list),
            "cookie_names": names,
            "has_authorization": bool(
                str((auth or {}).get("authorization") or "").strip()
            ),
            "account_id": str((auth or {}).get("account_id") or ""),
            "has_sessionid": "sessionid" in names,
        }

    with _DEEPSEEK_HTTP_LOCK:
        ds_runtime = dict(_DEEPSEEK_HTTP_LAST_SESSION_BY_MODEL_TYPE)
    ds_conv = _browser_persisted_conversation("deepseek")
    ds_last_ids = ds_conv.get("last_conversation_ids", {})
    ds_last_ids = ds_last_ids if isinstance(ds_last_ids, dict) else {}
    ds_sessions = {}
    for mode in ("default", "expert", "vision"):
        ds_sessions[mode] = (
            str(ds_runtime.get(mode) or "").strip()
            or str(ds_last_ids.get(mode) or "").strip()
        )
    ds_modes = ds_conv.get("model_types", {})
    ds_mode_count = len(ds_modes) if isinstance(ds_modes, dict) else 0

    with _QWEN_HTTP_CHAT_LOCK:
        qwen_runtime_id = _QWEN_HTTP_LAST_CHAT_ID
    qwen_conv = _browser_persisted_conversation("qwen")
    qwen_id = (
        str(qwen_runtime_id or "").strip()
        or str(qwen_conv.get("conversation_id") or "").strip()
    )

    with _DOUBAO_HTTP_CONVERSATION_LOCK:
        db_runtime_id = _DOUBAO_HTTP_LAST_CONVERSATION_ID
    db_conv = _browser_persisted_conversation("doubao")
    db_id = (
        str(db_runtime_id or "").strip()
        or str(db_conv.get("conversation_id") or "").strip()
    )

    with _M365_HTTP_CONVERSATION_LOCK:
        m365_runtime_ids = dict(_M365_HTTP_LAST_BY_TONE)
    m365_conv = _browser_persisted_conversation("m365")
    m365_saved_ids = m365_conv.get("last_conversation_ids", {})
    m365_saved_ids = m365_saved_ids if isinstance(m365_saved_ids, dict) else {}
    m365_ids = {
        tone: str(m365_runtime_ids.get(tone) or m365_saved_ids.get(tone) or "").strip()
        for tone in M365_BROWSER_MODEL_TONES.values()
    }

    return {
        "type": "STATE_REPORT",
        "generated_at": int(time.time() * 1000),
        "state_path": str(VOICE_EDGE_BROWSER_STATE_PATH),
        "updated_at": float(state.get("updated_at") or 0.0)
        if isinstance(state, dict)
        else 0.0,
        "restore_last_conversation": bool(VOICE_EDGE_RESTORE_LAST_CONVERSATION),
        "conversation_persistence_disabled": bool(
            VOICE_EDGE_DISABLE_CONVERSATION_PERSISTENCE
        ),
        "providers": {
            "deepseek": {
                "sessions_by_mode": ds_sessions,
                "known_conversation_count": ds_mode_count,
                "auth": _auth_summary("deepseek"),
            },
            "qwen": {
                "conversation_id": qwen_id,
                "auth": _auth_summary("qwen"),
            },
            "doubao": {
                "conversation_id": db_id,
                "auth": _auth_summary("doubao"),
            },
            "m365": {
                "conversations_by_tone": m365_ids,
                "auth": _auth_summary("m365"),
            },
        },
    }


# Routine, high-frequency sync messages are logged at DEBUG so they do not
# flood the log (e.g. STATE_QUERY polling and DeepSeek CONVERSATION_SNAPSHOTs
# emitted while browsing). Credential-bearing messages remain at INFO.
_QUIET_SYNC_TYPES = frozenset(
    {
        "PING",
        "PONG",
        "STATE_QUERY",
        "STATE_REPORT",
        "STATE_MUTATE",
        "CONVERSATION_SNAPSHOT",
        "CONVERSATION_APPLIED",
    }
)


def _browser_state_mutate(message: dict) -> dict:
    """Clear a stored conversation so the next request starts a fresh one.

    This reuses the exact clear helpers the stale-recovery path already uses.
    It never touches auth/cookies, never deletes a server-side conversation,
    and does not affect the XiaoAI bridge (which keeps its own in-process
    conversation id). Both "clear" and "new" map to the same safe action.
    """
    action = str(message.get("action") or "").strip().lower()
    provider = str(message.get("provider") or "").strip().lower()
    if action not in {"clear", "new"}:
        raise ValueError("unsupported state mutate action")
    if provider == "qwen":
        _qwen_http_clear_chat_id()
    elif provider == "doubao":
        _doubao_http_clear_last_conversation_id()
    elif provider == "deepseek":
        model_type = str(message.get("model_type") or "").strip().lower()
        modes = (
            (model_type,)
            if model_type in {"default", "expert", "vision"}
            else ("default", "expert", "vision")
        )
        for mode in modes:
            _deepseek_http_clear_last_session("", mode)
    elif provider == "m365":
        requested_tone = str(message.get("model_type") or "").strip()
        tones = (
            (M365_BROWSER_MODEL_TONES[requested_tone],)
            if requested_tone in M365_BROWSER_MODEL_TONES
            else tuple(M365_BROWSER_MODEL_TONES.values())
        )
        with _M365_HTTP_CONVERSATION_LOCK:
            for tone in tones:
                _M365_HTTP_LAST_BY_TONE[tone] = ""
        if not VOICE_EDGE_DISABLE_CONVERSATION_PERSISTENCE:
            with _BROWSER_STATE_LOCK:
                state = _browser_state_read_unlocked()
                conv = state["providers"]["m365"].setdefault("conversation", {})
                ids = conv.get("last_conversation_ids", {})
                if not isinstance(ids, dict):
                    ids = {}
                    conv["last_conversation_ids"] = ids
                for tone in tones:
                    ids.pop(tone, None)
                conv["tones"] = {
                    str(conversation_id): str(mapped_tone)
                    for mapped_tone, conversation_id in ids.items()
                    if str(mapped_tone) in M365_BROWSER_MODEL_TONES.values()
                    and str(conversation_id).strip()
                }
                _browser_state_write_unlocked(state)
    else:
        raise ValueError("unsupported state mutate provider")
    report = _browser_state_report()
    report["mutated"] = {
        "provider": provider,
        "action": action,
        "model_type": str(message.get("model_type") or ""),
    }
    return report


class AuthSyncServer:
    """Local Unix-socket bridge for Firefox Native Messaging."""

    def __init__(self, path: str):
        self.path = path
        self._sock = None
        self._thread = None
        self._stop = threading.Event()
        self._clients_lock = threading.RLock()
        self._clients: set[socket.socket] = set()
        self._client_threads: set[threading.Thread] = set()

    def start(self) -> None:
        if not AUTH_SYNC_ENABLED or self._thread is not None:
            return
        parent = os.path.dirname(self.path)
        os.makedirs(parent, mode=0o700, exist_ok=True)
        try:
            os.chmod(parent, 0o700)
        except OSError:
            pass
        try:
            os.unlink(self.path)
        except FileNotFoundError:
            pass
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        sock.bind(self.path)
        os.chmod(self.path, 0o600)
        sock.listen(4)
        sock.settimeout(0.5)
        self._sock = sock
        self._thread = threading.Thread(
            target=self._serve,
            name="voice-edge-auth-sync",
            daemon=True,
        )
        self._thread.start()
        _auth_log.info("Auth sync listening on %s", self.path)

    def _serve(self) -> None:
        sock = self._sock
        if sock is None:
            _auth_log.error("Auth sync socket is not initialized")
            return
        while not self._stop.is_set():
            try:
                client, _ = sock.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            client.settimeout(1.0)
            with self._clients_lock:
                self._clients.add(client)
                client_count = len(self._clients)
            _auth_log.info("Auth sync client connected clients=%d", client_count)
            client_thread = threading.Thread(
                target=self._handle_client,
                args=(client,),
                name="voice-edge-auth-client",
                daemon=True,
            )
            with self._clients_lock:
                self._client_threads.add(client_thread)
            client_thread.start()

    def _send(self, client: socket.socket, message: dict) -> bool:
        try:
            payload = json.dumps(message, ensure_ascii=False, separators=(",", ":"))
            client.sendall(payload.encode("utf-8") + b"\n")
            return True
        except OSError:
            return False

    def _handle_client(self, client: socket.socket) -> None:
        buffer = b""
        try:
            self._send(
                client,
                {
                    "type": "BRIDGE_READY",
                    "providers": ["doubao", "qwen", "deepseek", "m365"],
                },
            )
            while not self._stop.is_set():
                try:
                    data = client.recv(65536)
                except socket.timeout:
                    continue
                if not data:
                    break
                buffer += data
                if len(buffer) > FIREFOX_AUTH_SYNC_MAX_MESSAGE_BYTES:
                    self._send(
                        client, {"type": "AUTH_ERROR", "message": "message too large"}
                    )
                    break
                while b"\n" in buffer:
                    line, buffer = buffer.split(b"\n", 1)
                    if not line.strip():
                        continue
                    try:
                        message = json.loads(line.decode("utf-8"))
                        _recv_type = str(message.get("type") or "")
                        _recv_log = (
                            _auth_log.debug
                            if _recv_type in _QUIET_SYNC_TYPES
                            else _auth_log.info
                        )
                        _recv_log(
                            "Auth sync recv type=%s provider=%s cookies=%d",
                            message.get("type"),
                            message.get("provider"),
                            len(message.get("cookies") or []),
                        )
                        response = self._dispatch(message)
                        _reply_type = str(response.get("type") or "")
                        _reply_log = (
                            _auth_log.debug
                            if _reply_type in _QUIET_SYNC_TYPES
                            else _auth_log.info
                        )
                        _reply_log(
                            "Auth sync reply type=%s provider=%s success=%s validated=%s",
                            response.get("type"),
                            response.get("provider"),
                            response.get("success"),
                            response.get("validated"),
                        )
                    except Exception as exc:
                        response = {
                            "type": "AUTH_ERROR",
                            "provider": str(message.get("provider") or "doubao"),
                            "message": re.sub(r"\s+", " ", str(exc)).strip()[:500],
                        }
                    self._send(client, response)
        finally:
            with self._clients_lock:
                self._clients.discard(client)
                self._client_threads.discard(threading.current_thread())
            try:
                client.close()
            except OSError:
                pass

    def _dispatch(self, message: dict) -> dict:
        if not isinstance(message, dict):
            raise ValueError("message must be an object")
        kind = str(message.get("type") or "")
        provider = str(message.get("provider") or "").lower()
        if kind == "PING":
            return {"type": "PONG"}
        if kind == "STATE_QUERY":
            return _browser_state_report()
        if kind == "STATE_MUTATE":
            return _browser_state_mutate(message)
        if kind == "CONVERSATION_SNAPSHOT" and provider == "deepseek":
            return DEEPSEEK_BROWSER_RUNTIME.apply_conversation_snapshot(message)
        if kind != "AUTH_SNAPSHOT":
            raise ValueError("unsupported auth sync message")
        if provider == "doubao":
            return DOUBAO_RUNTIME.apply_auth_snapshot(message)
        if provider == "qwen":
            return QWEN_BROWSER_RUNTIME.apply_auth_snapshot(message)
        if provider == "deepseek":
            return DEEPSEEK_BROWSER_RUNTIME.apply_auth_snapshot(message)
        raise ValueError("unsupported auth sync provider")

    def broadcast(self, message: dict) -> None:
        with self._clients_lock:
            clients = list(self._clients)
        _bcast_type = str(message.get("type") or "")
        _bcast_log = (
            _auth_log.debug if _bcast_type in _QUIET_SYNC_TYPES else _auth_log.info
        )
        _bcast_log(
            "Auth sync broadcast type=%s provider=%s clients=%d",
            message.get("type"),
            message.get("provider"),
            len(clients),
        )
        for client in clients:
            if not self._send(client, message):
                with self._clients_lock:
                    self._clients.discard(client)

    def notify_auth_required(self, provider: str, code: int) -> None:
        message = {
            "type": "AUTH_REQUIRED",
            "provider": provider,
            "code": int(code),
            "message": "Open Doubao in Firefox and send one message; the extension will synchronize automatically after the full reply.",
        }
        self.broadcast(message)
        osascript = "/usr/bin/osascript"
        if os.path.isfile(osascript) and os.access(osascript, os.X_OK):
            script = (
                'display notification "请在 Firefox 网页版豆包发送一条消息，'
                '完整回复后扩展会自动同步，无需点击。" '
                'with title "Voice Edge：豆包状态需要刷新" sound name "Basso"'
            )
            try:
                subprocess.run(
                    [osascript, "-e", script],
                    check=False,
                    timeout=5.0,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
            except Exception:
                _doubao_log.debug(
                    "Failed sending Doubao auth notification", exc_info=True
                )

    def notify_qwen_auth_required(
        self,
        account_id: str,
        verification_url: str,
        status: int,
    ) -> None:
        message = {
            "type": "AUTH_REQUIRED",
            "provider": "qwen",
            "account_id": str(account_id or ""),
            "verification_url": str(verification_url or ""),
            "code": int(status or 0),
            "message": "Click the Firefox notification, complete Qwen verification, and the updated cookies will synchronize automatically.",
        }
        self.broadcast(message)
        osascript = "/usr/bin/osascript"
        if os.path.isfile(osascript) and os.access(osascript, os.X_OK):
            script = (
                'display notification "请点击 Firefox 通知打开 Qwen 验证页面。'
                '验证完成后 Cookie 将自动同步。" '
                'with title "Voice Edge：Qwen 需要验证" sound name "Basso"'
            )
            try:
                subprocess.run(
                    [osascript, "-e", script],
                    check=False,
                    timeout=5.0,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
            except Exception:
                _qwen_log.debug("Failed sending Qwen auth notification", exc_info=True)

    def notify_deepseek_auth_required(self, status: int = 401) -> None:
        self.broadcast(
            {
                "type": "AUTH_REQUIRED",
                "provider": "deepseek",
                "code": int(status or 401),
                "login_url": DEEPSEEK_SIGN_IN_URL,
                "message": "Open DeepSeek in Firefox and complete login; cookies will synchronize automatically.",
            }
        )
        osascript = "/usr/bin/osascript"
        if os.path.isfile(osascript) and os.access(osascript, os.X_OK):
            script = (
                'display notification "请点击 Firefox 扩展通知打开 DeepSeek，完成登录后 Cookie 将自动同步。" '
                'with title "Voice Edge：DeepSeek 需要登录" sound name "Basso"'
            )
            try:
                subprocess.run(
                    [osascript, "-e", script],
                    check=False,
                    timeout=5.0,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
            except Exception:
                _deepseek_log.debug(
                    "Failed sending DeepSeek auth notification", exc_info=True
                )

    def request_stop(self) -> None:
        """Non-blocking shutdown signal safe for the main teardown path."""
        self._stop.set()
        sock = self._sock
        self._sock = None
        if sock is not None:
            try:
                sock.close()
            except OSError:
                pass

    def stop(self) -> None:
        self.request_stop()
        with self._clients_lock:
            clients = list(self._clients)
            self._clients.clear()
        for client in clients:
            try:
                client.close()
            except OSError:
                pass
        if self._thread is not None:
            self._thread.join(timeout=2.0)
            self._thread = None
        with self._clients_lock:
            client_threads = list(self._client_threads)
        deadline = time.monotonic() + 2.0
        for client_thread in client_threads:
            remaining = max(0.0, deadline - time.monotonic())
            if client_thread is not threading.current_thread():
                client_thread.join(timeout=remaining)
        with self._clients_lock:
            alive = [thread for thread in self._client_threads if thread.is_alive()]
        if alive:
            _auth_log.warning(
                "Auth sync shutdown left %d client thread(s) alive",
                len(alive),
            )
        try:
            os.unlink(self.path)
        except FileNotFoundError:
            pass


AUTH_SYNC_SERVER = AuthSyncServer(FIREFOX_AUTH_SYNC_SOCKET)


_DOUBAO_HTTP_CONVERSATION_LOCK = threading.Lock()
_DOUBAO_HTTP_LAST_CONVERSATION_ID = ""


def _doubao_http_get_last_conversation_id() -> str:
    with _DOUBAO_HTTP_CONVERSATION_LOCK:
        current = _DOUBAO_HTTP_LAST_CONVERSATION_ID
    if current:
        return current
    return str(_browser_stored_conversation("doubao").get("conversation_id") or "")


def _doubao_http_clear_last_conversation_id(expected: str = "") -> None:
    global _DOUBAO_HTTP_LAST_CONVERSATION_ID
    with _DOUBAO_HTTP_CONVERSATION_LOCK:
        if expected and _DOUBAO_HTTP_LAST_CONVERSATION_ID not in {"", expected}:
            return
        _DOUBAO_HTTP_LAST_CONVERSATION_ID = ""
    _browser_state_remove_conversation_values("doubao", ("conversation_id",))


def _doubao_http_set_last_conversation_id(conversation_id: str) -> None:
    global _DOUBAO_HTTP_LAST_CONVERSATION_ID
    value = str(conversation_id or "").strip()
    if not value:
        return
    with _DOUBAO_HTTP_CONVERSATION_LOCK:
        _DOUBAO_HTTP_LAST_CONVERSATION_ID = value
    _browser_state_update("doubao", "conversation", {"conversation_id": value})


def _doubao_http_resolve_conversation(body: dict) -> tuple[str, str]:
    """Resolve an HTTP request conversation under the configured guard policy.

    Returns ``(conversation_id, decision)``.  ``decision`` is one of explicit,
    bootstrap, new, reuse, or reject.  XiaoAI does not use this path and keeps
    its own server-side conversation state.
    """
    explicit = str(body.get("conversation_id", "") or "").strip()
    if explicit:
        return explicit, "explicit"

    explicit_new = bool(body.get("new_conversation") is True)
    remembered = _doubao_http_get_last_conversation_id()
    policy = DOUBAO_HTTP_MISSING_CONVERSATION_POLICY

    if explicit_new:
        return "", "new"
    if policy == "allow":
        return "", "new"
    if policy == "reuse":
        # The first request has nothing to reuse yet, so bootstrap one
        # conversation.  Once its SSE ACK supplies a conversation_id,
        # subsequent requests without an explicit ID reuse that value.
        if remembered:
            return remembered, "reuse"
        return "", "bootstrap"
    if policy == "bootstrap_then_reject" and not remembered:
        return "", "bootstrap"
    return "", "reject"


async def _direct_doubao_chat_response(body: dict, messages: list, stream_mode: bool):
    conversation_id, conversation_decision = _doubao_http_resolve_conversation(body)
    # Seam #1: unified relay. Doubao metadata is relay_prompt=False /
    # supports_tools=False, so this preserves the current behavior (latest user
    # turn only). XiaoAI drives this path (source=='xiaoai') and bypasses
    # explicitly here — it must never receive an injected system prompt or
    # tools, matching the smart-speaker's current contract.
    _doubao_prepared = BROWSER_RELAY.prepare(
        "LLM:doubao", body, messages, bypass=BrowserRelay.should_bypass(body)
    )
    text = _doubao_prepared.text
    # Attachment egress hook (upload not yet implemented for Doubao). Relay has
    # already parsed + stripped inline files from `text`; this makes any drop
    # explicit and marks where the Doubao upload path will slot in. XiaoAI sends
    # plain text with no attachments, so the stub stays silent for it.
    _browser_attachments_egress_stub("LLM:doubao", messages)
    # Doubao has no upload egress; keep inline file text in the prompt.
    # (XiaoAI bypass sends plain text -> helper returns "" -> no double-send.)
    # oversize/unreadable inline files raise ValueError -> family 400.
    try:
        text = _browser_append_inline_files(text, messages)
    except ValueError as exc:
        return JSONResponse(
            {"error": {"message": str(exc), "type": "doubao_file_error"}},
            status_code=400,
        )
    if not text:
        return JSONResponse(
            {"error": "No user text provided for LLM:doubao"}, status_code=400
        )

    request_id = f"dbreq-{uuid.uuid4().hex[:12]}"
    text_hash = hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]
    roles = [
        str(message.get("role", ""))
        for message in messages
        if isinstance(message, dict)
    ]

    _doubao_log.debug(
        "[Debug] incoming Doubao HTTP request request_id=%s source=%s "
        "stream=%s conversation=%s decision=%s message_count=%d roles=%s "
        "text_chars=%d text_sha256=%s",
        request_id,
        str(body.get("source", "unknown") or "unknown")[:40],
        stream_mode,
        conversation_id[:16] if conversation_id else "new",
        conversation_decision,
        len(messages),
        roles,
        len(text),
        text_hash,
    )

    if conversation_decision == "reject":
        remembered = _doubao_http_get_last_conversation_id()
        _doubao_log.warning(
            "Rejected Doubao HTTP request without conversation_id: "
            "request_id=%s policy=%s remembered=%s text_chars=%d text_sha256=%s",
            request_id,
            DOUBAO_HTTP_MISSING_CONVERSATION_POLICY,
            bool(remembered),
            len(text),
            text_hash,
        )
        return JSONResponse(
            {
                "error": {
                    "message": (
                        "conversation_id is required for this Doubao HTTP request. "
                        "Pass the conversation_id returned by the first response, "
                        "or set new_conversation=true to explicitly start a new chat."
                    ),
                    "type": "doubao_missing_conversation_id",
                    "code": "missing_conversation_id",
                    "retryable": False,
                }
            },
            status_code=409,
        )

    model_name = "LLM:doubao"
    completion_id = f"chatcmpl-doubao-{time.monotonic_ns()}"
    created = int(time.time())

    if stream_mode:
        _doubao_log.debug(
            "[Debug] submitting Doubao HTTP stream request_id=%s conversation=%s",
            request_id,
            conversation_id[:16] if conversation_id else "new",
        )

        future, event_queue = DOUBAO_RUNTIME.submit_chat_stream(text, conversation_id)

        async def generate():
            nonlocal future, event_queue, conversation_id
            sent_role = False
            visible_output = False
            # Seam #2 (tool interception). DORMANT while doubao supports_tools is
            # False (its current default, and the format XiaoAI relies on):
            # new_transpiler() returns None and every `is not None` guard below is
            # skipped, so this path is byte-identical to before. Flip doubao's
            # metadata (supports_tools + tool_format) to activate for IDE clients.
            _doubao_tool_tp = _doubao_prepared.new_transpiler()
            # Shared Cline attempt_completion envelope (no-op unless client_kind
            # == "cline"); same helper every browser family uses.
            _doubao_env = ClineEnvelope(_doubao_prepared.client_kind == "cline")
            stale_recovery_allowed = bool(
                conversation_id and conversation_decision == "reuse"
            )
            stale_recovery_attempted = False
            try:
                event_count = 0
                deadline = time.monotonic() + DOUBAO_STREAM_FIRST_EVENT_TIMEOUT
                while True:
                    if SERVER_SHUTTING_DOWN.is_set():
                        break
                    try:
                        event = await asyncio.to_thread(event_queue.get, True, 1.0)
                    except queue.Empty:
                        if future.done():
                            try:
                                future.result()
                            except concurrent.futures.CancelledError:
                                pass
                            except Exception as exc:
                                yield _chat_sse_data(
                                    {
                                        "error": {
                                            "message": str(exc),
                                            "type": "doubao_error",
                                        }
                                    }
                                )
                            break
                        if time.monotonic() >= deadline:
                            timeout = (
                                DOUBAO_STREAM_FIRST_EVENT_TIMEOUT
                                if event_count == 0
                                else DOUBAO_STREAM_IDLE_TIMEOUT
                            )
                            message = f"Doubao HTTP stream timeout after {timeout:.0f}s: first_event={event_count == 0} runtime_future=pending"
                            _doubao_log.error("%s", message)
                            yield _chat_sse_data(
                                {
                                    "error": {
                                        "message": message,
                                        "type": "doubao_timeout",
                                    }
                                }
                            )
                            break
                        continue
                    event_count += 1
                    deadline = time.monotonic() + DOUBAO_STREAM_IDLE_TIMEOUT
                    kind = event.get("type")

                    _http_log.debug(
                        "[Debug] HTTP stream received event n=%d type=%s",
                        event_count,
                        kind,
                    )

                    if kind == "meta":
                        continue
                    if kind == "conversation":
                        returned_conversation_id = str(
                            event.get("conversation_id", "") or ""
                        ).strip()
                        if returned_conversation_id:
                            _doubao_http_set_last_conversation_id(
                                returned_conversation_id
                            )

                            _doubao_log.debug(
                                "[Debug] remembered Doubao HTTP conversation request_id=%s conversation=%s",
                                request_id,
                                returned_conversation_id[:16],
                            )
                        yield _chat_sse_data(
                            {
                                "id": completion_id,
                                "object": "chat.completion.chunk",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {"index": 0, "delta": {}, "finish_reason": None}
                                ],
                                "conversation_id": event.get("conversation_id", ""),
                            }
                        )
                        continue
                    if kind == "delta":
                        _content = str(event.get("content") or "")
                        if _doubao_tool_tp is not None:
                            _content = "".join(_doubao_tool_tp.push(_content))
                            if not _content:
                                continue
                        # A (defense-in-depth, symmetric with m365): strip any
                        # model-emitted attempt_completion/result tags before the
                        # transport adds its own envelope. Byte-exact passthrough
                        # when not cline. (The image branch below emits our OWN
                        # generated markdown, which cannot contain these tags, so
                        # it is not stripped.)
                        _content = _doubao_env.strip_envelope_tags(_content)
                        if not _content:
                            continue
                        _content = _doubao_env.open_prefix() + _content
                        visible_output = True
                        delta = {"content": _content}
                        if not sent_role:
                            delta["role"] = "assistant"
                            sent_role = True
                        yield _chat_sse_data(
                            {
                                "id": completion_id,
                                "object": "chat.completion.chunk",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {"index": 0, "delta": delta, "finish_reason": None}
                                ],
                            }
                        )
                    elif kind == "image":
                        visible_output = True
                        yield _chat_sse_data(
                            {
                                "id": completion_id,
                                "object": "chat.completion.chunk",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {
                                        "index": 0,
                                        "delta": {
                                            # route the image markdown
                                            # through the Cline envelope too, so
                                            # a leading image opens <result> and
                                            # is not emitted outside the envelope.
                                            "content": _doubao_env.open_prefix()
                                            + f"![generated]({event.get('url', '')})"
                                        },
                                        "finish_reason": None,
                                    }
                                ],
                            }
                        )
                    elif kind == "error":
                        message = str(event.get("message", "Doubao error"))
                        status = int(event.get("status") or event.get("code") or 0)
                        if (
                            stale_recovery_allowed
                            and not stale_recovery_attempted
                            and not visible_output
                            and (
                                event.get("stale_conversation") is True
                                or _browser_error_is_stale_conversation(
                                    "doubao", status, message
                                )
                            )
                        ):
                            stale_recovery_attempted = True
                            _doubao_http_clear_last_conversation_id(conversation_id)
                            conversation_id = ""
                            future, event_queue = DOUBAO_RUNTIME.submit_chat_stream(
                                text, ""
                            )
                            event_count = 0
                            deadline = (
                                time.monotonic() + DOUBAO_STREAM_FIRST_EVENT_TIMEOUT
                            )
                            continue
                        error_payload = {
                            "message": event.get("message", "Doubao error"),
                            "type": event.get("error_type", "doubao_error"),
                        }
                        if event.get("code") is not None:
                            error_payload["code"] = event.get("code")
                        if event.get("retryable") is not None:
                            error_payload["retryable"] = event.get("retryable")
                        if VE_DOUBAO_LOG_DEBUG and event.get("details"):
                            error_payload["details"] = event.get("details")
                        yield _chat_sse_data({"error": error_payload})
                        break
                    elif kind == "shutdown":
                        break
                    elif kind == "bridge_done":
                        yield _chat_sse_data(
                            {
                                "error": {
                                    "message": "Doubao bridge ended without a terminal provider event",
                                    "type": "doubao_bridge_terminated",
                                    "retryable": False,
                                }
                            }
                        )
                        break
                    elif kind == "done":
                        if _doubao_tool_tp is not None:
                            # Seam #2 terminal (dormant while tp is None). Parsed
                            # tool block -> OpenAI tool_calls; else flush any
                            # held-back tail as a final content delta.
                            _db_calls = _doubao_tool_tp.finish_tool_calls()
                            if _db_calls:
                                # tool_call turn: no Cline envelope.
                                _db_close = _doubao_env.suppress()
                                if _db_close:
                                    yield _chat_sse_data(
                                        {
                                            "id": completion_id,
                                            "object": "chat.completion.chunk",
                                            "created": created,
                                            "model": model_name,
                                            "choices": [
                                                {
                                                    "index": 0,
                                                    "delta": (
                                                        {
                                                            "role": "assistant",
                                                            "content": _db_close,
                                                        }
                                                        if not sent_role
                                                        else {"content": _db_close}
                                                    ),
                                                    "finish_reason": None,
                                                }
                                            ],
                                        }
                                    )
                                    sent_role = True
                                _tc = [
                                    {
                                        "index": _i,
                                        "id": _c["id"],
                                        "type": "function",
                                        "function": _c["function"],
                                    }
                                    for _i, _c in enumerate(_db_calls)
                                ]
                                yield _chat_sse_data(
                                    {
                                        "id": completion_id,
                                        "object": "chat.completion.chunk",
                                        "created": created,
                                        "model": model_name,
                                        "choices": [
                                            {
                                                "index": 0,
                                                "delta": (
                                                    {
                                                        "role": "assistant",
                                                        "tool_calls": _tc,
                                                    }
                                                    if not sent_role
                                                    else {"tool_calls": _tc}
                                                ),
                                                "finish_reason": None,
                                            }
                                        ],
                                    }
                                )
                                yield _chat_sse_data(
                                    {
                                        "id": completion_id,
                                        "object": "chat.completion.chunk",
                                        "created": created,
                                        "model": model_name,
                                        "choices": [
                                            {
                                                "index": 0,
                                                "delta": {},
                                                "finish_reason": "tool_calls",
                                            }
                                        ],
                                    }
                                )
                                if not SERVER_SHUTTING_DOWN.is_set():
                                    yield _SSE_DONE_FRAME
                                break
                            _resid = _doubao_tool_tp.flush_pending()
                            # strip model envelope tags from the residual
                            # (symmetric with deepseek/delta path). Unreachable
                            # while doubao supports_tools=False; future-proofing.
                            _resid = _doubao_env.strip_envelope_tags(_resid)
                            if _resid:
                                yield _chat_sse_data(
                                    {
                                        "id": completion_id,
                                        "object": "chat.completion.chunk",
                                        "created": created,
                                        "model": model_name,
                                        "choices": [
                                            {
                                                "index": 0,
                                                "delta": (
                                                    {
                                                        "role": "assistant",
                                                        "content": _resid,
                                                    }
                                                    if not sent_role
                                                    else {"content": _resid}
                                                ),
                                                "finish_reason": None,
                                            }
                                        ],
                                    }
                                )
                                sent_role = True
                        _doubao_closing = _doubao_env.closing()
                        if _doubao_closing:
                            yield _chat_sse_data(
                                {
                                    "id": completion_id,
                                    "object": "chat.completion.chunk",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "index": 0,
                                            "delta": (
                                                {
                                                    "role": "assistant",
                                                    "content": _doubao_closing,
                                                }
                                                if not sent_role
                                                else {"content": _doubao_closing}
                                            ),
                                            "finish_reason": None,
                                        }
                                    ],
                                }
                            )
                            sent_role = True
                        yield _chat_sse_data(
                            {
                                "id": completion_id,
                                "object": "chat.completion.chunk",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {"index": 0, "delta": {}, "finish_reason": "stop"}
                                ],
                            }
                        )
                        break
                if not SERVER_SHUTTING_DOWN.is_set():
                    yield _SSE_DONE_FRAME
            finally:
                if not future.done():
                    # A terminal queue event can arrive just before the runtime
                    # coroutine finishes its own generator/page/account cleanup.
                    # Give that normal cleanup a short bounded grace period;
                    # cancel immediately only when the HTTP consumer vanished
                    # before receiving a terminal event.
                    terminal_received = "kind" in locals() and kind in {
                        "done",
                        "error",
                        "shutdown",
                        "bridge_done",
                    }
                    if terminal_received:
                        try:
                            await asyncio.wait_for(
                                asyncio.wrap_future(future),
                                timeout=2.0,
                            )
                        except (
                            asyncio.TimeoutError,
                            concurrent.futures.CancelledError,
                        ):
                            future.cancel()
                        except Exception:
                            # The structured queue event is authoritative. The
                            # runtime already reported any request-level error.
                            pass
                    else:
                        future.cancel()

        return StreamingResponse(
            generate(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    future = DOUBAO_RUNTIME.submit_chat(text, conversation_id)
    try:
        result, local_session_id = await asyncio.wait_for(
            asyncio.wrap_future(future), timeout=DOUBAO_REQUEST_TIMEOUT
        )
    except Exception as exc:
        future.cancel()
        return JSONResponse(
            {"error": {"message": str(exc), "type": "doubao_error"}}, status_code=502
        )
    if result.error:
        return JSONResponse(
            {"error": {"message": result.error, "type": "doubao_error"}},
            status_code=502,
        )
    effective_id = result.session_meta.conversation_id or conversation_id
    if effective_id:
        _doubao_http_set_last_conversation_id(effective_id)
        _doubao_log.debug(
            "[Debug] remembered Doubao HTTP conversation request_id=%s conversation=%s",
            request_id,
            effective_id[:16],
        )
    content = result.text or ""
    if result.image_urls:
        content += ("\\n" if content else "") + "\\n".join(
            f"![generated]({url})" for url in result.image_urls
        )
    # Non-stream: wrap the full answer in the Cline envelope when active.
    _doubao_ns_env = ClineEnvelope(_doubao_prepared.client_kind == "cline")
    return JSONResponse(
        {
            "id": completion_id,
            "object": "chat.completion",
            "created": created,
            "model": model_name,
            "choices": [
                {
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": _doubao_ns_env.wrap(content),
                    },
                    "finish_reason": "stop",
                }
            ],
            "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0},
            "conversation_id": effective_id,
            "doubao_session_id": local_session_id,
            "images": result.image_urls,
        }
    )


def _sanitize_browser_chat_request(body: dict, messages: list) -> tuple[dict, list]:
    """Remove OpenAI tool-call protocol fields for plain browser chat models."""
    clean_body = dict(body or {})
    for key in (
        "tools",
        "tool_choice",
        "parallel_tool_calls",
        "functions",
        "function_call",
    ):
        clean_body.pop(key, None)

    clean_messages = []
    for message in messages or []:
        if not isinstance(message, dict):
            continue
        role = str(message.get("role", "") or "")
        # Tool result messages have no meaningful plain-chat equivalent.
        if role in {"tool", "function"}:
            continue
        clean = dict(message)
        clean.pop("tool_calls", None)
        clean.pop("function_call", None)
        clean.pop("tool_call_id", None)
        clean.pop("name", None)
        clean_messages.append(clean)
    return clean_body, clean_messages


async def dispatch_browser_chat_model(
    model_name: str,
    body: dict,
    messages: list,
    stream_mode: bool,
):
    if model_name == "LLM:doubao":
        return await _direct_doubao_chat_response(body, messages, stream_mode)
    if model_name == "LLM:qwen":
        return await _direct_qwen_chat_response(body, messages, stream_mode)
    if model_name in DEEPSEEK_BROWSER_MODEL_TYPES:
        return await _direct_deepseek_chat_response(
            model_name, body, messages, stream_mode
        )
    if model_name in M365_BROWSER_MODEL_TONES:
        return await _direct_m365_chat_response(model_name, body, messages, stream_mode)
    raise ValueError(f"No browser provider registered for model: {model_name}")


# ==================== M365 Copilot Browser Backend ====================


M365_ENTRY_URL = os.getenv("M365_ENTRY_URL", "").strip()
SHAREPOINT_HOME_URL = os.getenv("SHAREPOINT_HOME_URL", "").strip().rstrip("/")
SHAREPOINT_UPLOAD_FOLDER = os.getenv("SHAREPOINT_UPLOAD_FOLDER", "").strip().strip("/")
SHAREPOINT_DOWNLOAD_FOLDER = os.getenv("SHAREPOINT_DOWNLOAD_FOLDER", "").strip()


def _validate_sharepoint_settings() -> None:
    if SHAREPOINT_HOME_URL:
        parsed = urllib.parse.urlparse(SHAREPOINT_HOME_URL)
        host = str(parsed.hostname or "").lower()
        if (
            parsed.scheme != "https"
            or not host.endswith(".sharepoint.com")
            or not re.fullmatch(
                r"/sites/[^/?#]+", parsed.path.rstrip("/"), re.IGNORECASE
            )
            or parsed.params
            or parsed.query
            or parsed.fragment
        ):
            raise ValueError(
                "SHAREPOINT_HOME_URL must look like "
                "https://tenant.sharepoint.com/sites/site_name"
            )
    if ".." in SHAREPOINT_UPLOAD_FOLDER.split("/"):
        raise ValueError(
            "SHAREPOINT_UPLOAD_FOLDER must be a safe document-library-relative folder"
        )


M365_BRIDGE_HOST = os.getenv("M365_BRIDGE_HOST", "127.0.0.1").strip()
M365_BRIDGE_PORT = int(os.getenv("M365_BRIDGE_PORT", "5003"))
M365_FIRST_EVENT_TIMEOUT = max(5.0, float(os.getenv("M365_FIRST_EVENT_TIMEOUT", "60")))
M365_IDLE_BASE_SECONDS = max(5.0, float(os.getenv("M365_IDLE_BASE_SECONDS", "180")))
M365_IDLE_SECONDS_PER_FILE = max(
    0.0, float(os.getenv("M365_IDLE_SECONDS_PER_FILE", "15"))
)
M365_IDLE_SECONDS_PER_MIB = max(
    0.0, float(os.getenv("M365_IDLE_SECONDS_PER_MIB", "12"))
)
M365_IDLE_MAX_SECONDS = max(
    M365_IDLE_BASE_SECONDS, float(os.getenv("M365_IDLE_MAX_SECONDS", "900"))
)
# Code Interpreter may legitimately emit no Chathub frames for longer than the
# normal request idle budget. Apply this separate absolute ceiling only after an
# explicit codeExecuting signal; ordinary stalled requests keep the short idle
# timeout above.
M365_CODE_EXECUTION_MAX_SECONDS = max(
    M365_IDLE_BASE_SECONDS,
    float(os.getenv("M365_CODE_EXECUTION_MAX_SECONDS", "1800")),
)
M365_GETCHATS_TIMEOUT = max(3.0, float(os.getenv("M365_GETCHATS_TIMEOUT", "20")))


def _m365_request_idle_seconds(attachments: Optional[Sequence[dict]]) -> float:
    """Return this request's idle budget from attachment count and total bytes."""
    items = list(attachments or [])
    total_bytes = sum(max(0, int(item.get("size") or 0)) for item in items)
    return min(
        M365_IDLE_MAX_SECONDS,
        M365_IDLE_BASE_SECONDS
        + len(items) * M365_IDLE_SECONDS_PER_FILE
        + total_bytes / (1024 * 1024) * M365_IDLE_SECONDS_PER_MIB,
    )


# A browser hook may observe weak UI completion signals (for example
# isLastUpdate or ReferencesListComplete) several seconds before SignalR sends
# the authoritative type=3 Completion frame. Keep the relay alive for a bounded
# drain window so late snapshots/deltas can repair the final answer.
M365_TERMINAL_DRAIN_SECONDS = max(
    0.0, float(os.getenv("M365_TERMINAL_DRAIN_SECONDS", "6.0"))
)
# 模型产出的图片现在会以 base64 data-URI 内联进答案（随 M365_DONE.appendText，
# 方向为 extension→Python）。aiohttp 的 WSResponse 默认 max_msg_size 是 4 MiB，
# 单张大图 + 答案正文就可能超限 → 桥会丢掉整个 DONE 帧，图片和链接一起消失。
# 抬高上限；扩展端已对单图内联做了 M365_INLINE_IMAGE_MAX_B64(~3MB) 上限并对超限回退为链接。
M365_BRIDGE_MAX_MSG_SIZE = int(
    os.getenv("M365_BRIDGE_MAX_MSG_SIZE", str(32 * 1024 * 1024))
)
# Observation-only relay tracing. When enabled, the M365 pipeline accounts for
# every answer character at two points and logs a per-request summary:
#   [producer] the driver() coroutine that converts the extension's cumulative
#              M365_DELTA snapshots into incremental "delta" events (emit()).
#   [consumer] the events() SSE generator that yields those deltas to Continue.
# Comparing len(best) vs producer-emitted vs consumer-yielded isolates whether
# any text loss happens inside Python (relay/queue) or downstream (SSE transport
# / Continue rendering). It never alters the reconstruction logic; it only
# counts and hashes what already flows. Gated so production stays silent.


def _m365_trace_digest(text: str) -> str:
    """Short, non-sensitive fingerprint of accumulated answer text for tracing.

    Returns "<char_count>:<sha8>:<head>…<tail>" so two trace points can be
    compared for exact equality (via sha) and eyeballed (via head/tail) without
    dumping the whole answer into logs.
    """
    raw = text or ""
    sha8 = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:8]
    head = raw[:24].replace("\n", "\\n")
    tail = raw[-24:].replace("\n", "\\n")
    return f"{len(raw)}chars:{sha8}:{head!r}…{tail!r}"


def _m365_trace_inbound_key(mtype: str, msg: dict) -> str:
    """Bucket key for [relay-producer] inbound_types accounting.

    A Progress frame carries the model's REAL chain-of-thought only when the
    extension forwards addToChainOfThought:true (content-m365.js sets this at
    the top level of the M365_PROGRESS message); frames without the flag are
    mere status placeholders ("正在思考...", EarlyProgress). Splitting the count
    into "M365_PROGRESS(CoT)" vs "M365_PROGRESS" makes the trace state, per
    request, whether the M365 backend actually emitted a reasoning stream this
    turn — independently of whether the M365_REASONING extraction path exists or
    works. This resolves the ambiguity where "no reasoning shown" could mean
    either "backend sent none" or "extraction dropped it". Pure classification;
    no side effects.
    """
    base = mtype or "<empty>"
    if base == "M365_PROGRESS" and msg.get("addToChainOfThought") is True:
        return "M365_PROGRESS(CoT)"
    return base


def _m365_attachment_debug(event: str, **fields) -> None:
    if not VE_M365_LOG_ATTACHMENT:
        return
    safe = {}
    for key, value in fields.items():
        if key in {"data", "content", "raw", "token", "authorization"}:
            continue
        safe[key] = value
    _m365_log.info(
        "attachment-debug %s %s",
        event,
        json.dumps(safe, ensure_ascii=False, default=str),
    )


def _validate_m365_entry_url(value: str) -> str:
    value = str(value or "").strip()
    if not value:
        return ""
    parsed = urllib.parse.urlparse(value)
    if parsed.scheme != "https" or parsed.hostname != "outlook.cloud.microsoft":
        raise ValueError("M365_ENTRY_URL must use https://outlook.cloud.microsoft")
    if not re.fullmatch(
        r"/host/[0-9a-f-]{36}/entity1-[0-9a-f-]{36}/?",
        parsed.path,
        re.IGNORECASE,
    ):
        raise ValueError("M365_ENTRY_URL must match /host/{uuid}/entity1-{uuid}")
    if parsed.params or parsed.query or parsed.fragment:
        raise ValueError("M365_ENTRY_URL must not contain params, query, or fragment")
    return urllib.parse.urlunparse(
        (parsed.scheme, parsed.netloc, parsed.path.rstrip("/"), "", "", "")
    )


# ---- conversation-id persistence (mirrors _qwen_http_* / _doubao_http_*) --------
_M365_HTTP_CONVERSATION_LOCK = threading.RLock()
_M365_HTTP_LAST_BY_TONE = {tone: "" for tone in M365_BROWSER_MODEL_TONES.values()}


def _m365_http_get_conversation_id(tone: str) -> str:
    with _M365_HTTP_CONVERSATION_LOCK:
        current = _M365_HTTP_LAST_BY_TONE.get(tone, "")
    if current or not VOICE_EDGE_RESTORE_LAST_CONVERSATION:
        return current
    ids = _browser_persisted_conversation("m365").get("last_conversation_ids", {})
    return str(ids.get(tone) or "") if isinstance(ids, dict) else ""


def _m365_http_set_conversation_id(cid: str, tone: str) -> None:
    cid = str(cid or "").strip()
    tone = str(tone or "").strip()
    if not cid or tone not in M365_BROWSER_MODEL_TONES.values():
        return
    with _M365_HTTP_CONVERSATION_LOCK:
        _M365_HTTP_LAST_BY_TONE[tone] = cid
    conv = _browser_persisted_conversation("m365")
    ids = dict(conv.get("last_conversation_ids", {}))
    ids[tone] = cid

    # `tones` is a reverse index of the current per-tone conversations, not
    # conversation history. Rebuild it from last_conversation_ids so replacing
    # one tone cannot leave stale IDs mapped to the same tone. This also repairs
    # state written by older builds on the next snapshot/response.
    tones = {
        str(conversation_id): str(mapped_tone)
        for mapped_tone, conversation_id in ids.items()
        if str(mapped_tone) in M365_BROWSER_MODEL_TONES.values()
        and str(conversation_id).strip()
    }
    _browser_state_update(
        "m365", "conversation", {"last_conversation_ids": ids, "tones": tones}
    )


def _m365_ingest_chats_snapshot(chats: list) -> dict:
    newest = {}
    for x in chats or []:
        if not isinstance(x, dict):
            continue
        tone = str(x.get("tone") or "")
        cid = str(x.get("conversationId") or "")
        if tone not in M365_BROWSER_MODEL_TONES.values() or not cid:
            continue
        if str(x.get("turnState") or "Completed") != "Completed":
            continue
        raw_time = x.get("updateTimeUtc")
        try:
            t = float(raw_time or 0)
        except (TypeError, ValueError):
            try:
                t = datetime.fromisoformat(
                    str(raw_time).replace("Z", "+00:00")
                ).timestamp()
            except (TypeError, ValueError):
                t = 0.0
        if tone not in newest or t >= newest[tone][1]:
            newest[tone] = (cid, t)
    for tone, (cid, _) in newest.items():
        _m365_http_set_conversation_id(cid, tone)
    return {k: v[0] for k, v in newest.items()}


# ---- per-client-chat conversation identity (Continue/OpenAI clients) ---------
# OpenAI-compatible clients (Continue, Cline) never send a conversation_id and
# replay the FULL message history every request. Keying the remembered M365
# ConversationId by model tone alone (the legacy _M365_HTTP_LAST_BY_TONE slot)
# collapsed every chat for one model onto ONE server conversation: a brand-new
# client chat silently continued the previous thread.
# We instead key by a hash of the FROZEN head of the transcript, which is
# byte-identical across every turn of one client chat and differs between chats.
#
# Two keys per chat:
#   boot_key = H(tone | first_user_turn)                    — stable ALL turns
#   full_key = H(tone | first_user_turn | first_assistant)  — from turn 2 on
# boot_key bridges the first→second turn (before any assistant reply exists);
# full_key is the strong, collision-resistant identity used thereafter. The
# first assistant reply is model output the client never rewrites, so two
# independent chats sharing a first user line still get distinct full_keys.
#
# Memory is bounded by an LRU cap; a dropped mapping degrades to a fresh M365
# conversation on that chat's next turn (never an error, never cross-talk).
M365_CONV_MAP_MAX = max(16, int(os.getenv("M365_CONV_MAP_MAX", "1024")))
_M365_CONV_BY_KEY: "OrderedDict[str, str]" = OrderedDict()


# Marker used inside the conversation-identity text to stand in for a stripped
# inline <file_content> block. It carries ONLY the attachment path (never the
# body) and uses control characters that cannot appear in normal prose so a
# placeholder can never collide with user-authored text. \x1e separates the
# tag from the path.
def _m365_inline_file_identity_placeholder(path: str) -> str:
    return "\x00m365-file\x1e" + str(path or "") + "\x00"


# A client may replay an earlier attachment either as the full <file_content>
# block OR as its own short placeholder like "[file: /abs/path/a.js]". Both are
# canonicalized to the SAME identity placeholder so turn 1 (full block) and a
# later replay (bracket form) hash to one conversation. Path must not contain
# ']' or a newline; the body is never present in this form so nothing to strip.
_M365_IDENTITY_FILE_PLACEHOLDER_RE = re.compile(
    r"\[\s*file\s*:\s*(?P<path>[^\]\r\n]+?)\s*\]",
    re.IGNORECASE,
)


def _m365_strip_inline_files_for_identity(text: str) -> str:
    """Replace every inline attachment reference with a stable, path-only
    placeholder, whether it arrives as a full <file_content> block or as a
    client-rendered "[file: /path]" replay placeholder.

    The file BODY is intentionally discarded from the identity so a later turn
    that resends the same attachment with different bytes (the file changed) or
    different surrounding whitespace still hashes to the same conversation.
    Keeping a per-path placeholder (rather than deleting the block outright)
    preserves the fact that a file WAS attached and WHICH one, so two otherwise
    identical prompts that attach different files stay distinct chats. Both the
    full-block path and the bracket path are normalized identically
    (strip + rstrip("\\")) so equivalent paths collapse to one identity.
    """
    value = str(text or "")
    # Mirror the opening-tag escape normalization used when the attachment is
    # actually consumed (_client_collect_inline_files), so identity spans
    # line up 1:1 with the blocks that were uploaded.
    scan_text = re.sub(
        r'(?m)^([ \t]*<file_content\b[^>\r\n]*?\bpath\s*=\s*)\\(["\'])',
        r"\1\2",
        value,
        flags=re.IGNORECASE,
    )
    spans = _client_inline_file_spans(scan_text)
    if spans:
        pieces = []
        cursor = 0
        for span in spans:
            pieces.append(scan_text[cursor : span["start"]])
            pieces.append(_m365_inline_file_identity_placeholder(span["path"]))
            cursor = span["end"]
        pieces.append(scan_text[cursor:])
        scan_text = "".join(pieces)

    # Fold client-rendered "[file: /path]" replay placeholders into the same
    # canonical form. Runs after the block pass; the control-character
    # placeholders emitted above contain no brackets, so they are untouched.
    def _fold_bracket(match: "re.Match") -> str:
        raw_path = str(match.group("path") or "").strip().rstrip("\\")
        return _m365_inline_file_identity_placeholder(raw_path)

    return _M365_IDENTITY_FILE_PLACEHOLDER_RE.sub(_fold_bracket, scan_text)


# Mirror of the client's stripInlineImageBase64 history normalization
# (continue messageContent.ts): from the second turn onward the client replays
# history with every inline-image data-URI "![alt](data:...)" collapsed to a
# bare "![alt]" marker — for BOTH user and assistant messages. The identity
# must be computed on the same normalized text, or the turn that GENERATED the
# image (full base64 in history) and every later turn (stripped marker) hash
# to different keys and the M365 conversation silently forks. Only "data:"
# URLs are stripped; ordinary link images stay identity-bearing.
_M365_INLINE_DATA_IMAGE_RE = re.compile(
    r"(?P<head>!\[[^\]\n]*\])\([ \t]*data:",
    re.IGNORECASE,
)


def _m365_strip_inline_data_images(text: str) -> str:
    """Collapse every "![alt](data:...)" to "![alt]", mirroring the client.

    The data-URI payload may itself contain "(" / ")" (e.g. non-base64
    "data:...;utf8," payloads), so the closing paren is found by bracket-depth
    tracking from the opening "(" exactly like the client — a regex that stops
    at the first ")" would truncate early and leave a drifting payload tail in
    the identity. An unterminated image is left untouched.
    """
    value = str(text or "")
    pieces: list[str] = []
    cursor = 0
    for match in _M365_INLINE_DATA_IMAGE_RE.finditer(value):
        if match.start() < cursor:
            continue  # inside an already-consumed image payload
        depth = 0
        end = -1
        for index in range(match.end("head"), len(value)):
            char = value[index]
            if char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
                if depth == 0:
                    end = index + 1
                    break
        if end < 0:
            continue  # unterminated: leave the text as-is
        pieces.append(value[cursor : match.start()])
        pieces.append(match.group("head"))
        cursor = end
    if not pieces:
        return value
    pieces.append(value[cursor:])
    return "".join(pieces)


def _m365_identity_normalize(text: str) -> str:
    """Whitespace-tolerant identity text for conversation keying.

    Collapses inline <file_content> blocks (and client "[file: /path]" replay
    placeholders) to path-only placeholders, collapses inline-image data-URIs
    to bare "![alt]" markers (mirroring the client's history normalization),
    then folds whitespace so blank lines and trailing/duplicated spaces cannot
    change the key across turns (a client may re-emit the frozen head with
    cosmetically different whitespace).

    A dedicated step folds whitespace *immediately adjacent* to the \\x00
    placeholder sentinels. Without it, the number of blank lines a client puts
    BETWEEN two consecutive <file_content> blocks would leak into the identity
    (adjacent placeholders "{A}\\n{B}" vs "{A}{B}"), because the per-line fold
    below never touches the boundary between two control-character tokens. A
    path can never contain \\x00, so every \\x00 is a true placeholder boundary
    and stripping whitespace around it is always safe.
    """
    stripped = _m365_strip_inline_data_images(
        _m365_strip_inline_files_for_identity(text)
    )
    # Canonicalize whitespace hugging placeholder sentinels so inter-file and
    # prose-to-file spacing (spaces, tabs, or any number of newlines) cannot
    # alter the identity. Placeholder count, order, and paths are preserved.
    stripped = re.sub(r"[ \t\r\n\f\v]*\x00[ \t\r\n\f\v]*", "\x00", stripped)
    lines = []
    for raw_line in stripped.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        collapsed = re.sub(r"[ \t]+", " ", raw_line).strip()
        if collapsed:
            lines.append(collapsed)
    return "\n".join(lines)


def _m365_first_user_and_assistant(messages: list) -> tuple[str, str]:
    """Whitespace-tolerant first user turn and first assistant reply, used only
    to derive a per-client-chat conversation identity.

    A client replays history verbatim, so a hash of the frozen head is a stable
    per-chat identity - EXCEPT that an uploaded file's <file_content> body may
    be resent with different bytes (the file changed) or different whitespace on
    a later turn. Both turns therefore strip inline file blocks down to a
    path-only placeholder and fold whitespace via _m365_identity_normalize, so
    the identity depends on the user-authored text and WHICH files were
    attached, never on the (possibly re-read/reformatted) file body. Inline
    data-URI images are likewise collapsed to bare "![alt]" markers, mirroring
    the client's stripInlineImageBase64 history normalization.
    """
    first_user = ""
    first_assistant = ""
    for message in messages or []:
        if not isinstance(message, dict):
            continue
        role = str(message.get("role") or "").strip().lower()
        if role == "user" and not first_user:
            first_user = _m365_identity_normalize(_client_user_text(message))
        elif role == "assistant" and not first_assistant:
            first_assistant = _m365_identity_normalize(_client_user_text(message))
        if first_user and first_assistant:
            break
    return first_user, first_assistant


def _m365_conversation_key(tone: str, messages: list) -> tuple[str, str]:
    """Return (full_key, boot_key). full_key is "" until an assistant reply
    exists (i.e. before the second turn). \\x1e separates fields so distinct
    (user, assistant) splits cannot collide by concatenation."""
    first_user, first_assistant = _m365_first_user_and_assistant(messages)
    boot = hashlib.sha256(f"{tone}\x1e{first_user}".encode("utf-8")).hexdigest()[:16]
    full = (
        hashlib.sha256(
            f"{tone}\x1e{first_user}\x1e{first_assistant}".encode("utf-8")
        ).hexdigest()[:16]
        if first_assistant
        else ""
    )
    return full, boot


def _m365_has_prior_assistant_turn(messages: list) -> bool:
    """True when the client is CONTINUING an existing chat (has ≥1 assistant
    turn). A first turn carries only system/user messages, so a missing mapping
    then means "start fresh" rather than "reuse an unrelated conversation"."""
    for message in messages or []:
        if (
            isinstance(message, dict)
            and str(message.get("role") or "").strip().lower() == "assistant"
        ):
            return True
    return False


def _m365_lru_get(key: str) -> str:
    if not key:
        return ""
    with _M365_HTTP_CONVERSATION_LOCK:
        cid = _M365_CONV_BY_KEY.get(key, "")
        if cid:
            _M365_CONV_BY_KEY.move_to_end(key)
    return cid


def _m365_lru_put(key: str, cid: str) -> None:
    cid = str(cid or "").strip()
    if not key or not cid:
        return
    with _M365_HTTP_CONVERSATION_LOCK:
        _M365_CONV_BY_KEY[key] = cid
        _M365_CONV_BY_KEY.move_to_end(key)
        while len(_M365_CONV_BY_KEY) > M365_CONV_MAP_MAX:
            _M365_CONV_BY_KEY.popitem(last=False)


def _m365_persisted_keyed() -> dict:
    ids = _browser_persisted_conversation("m365").get("keyed_conversation_ids", {})
    return ids if isinstance(ids, dict) else {}


def _m365_persist_keyed(key: str, cid: str) -> None:
    # Persistence is opt-in via the existing restore switch; in-memory keying
    # works regardless. Stored map is bounded the same way as memory so it
    # cannot grow unbounded across restarts.
    if not (VOICE_EDGE_RESTORE_LAST_CONVERSATION and key and cid):
        return
    ids = dict(_m365_persisted_keyed())
    if ids.get(key) == cid:
        return
    ids[key] = cid
    if len(ids) > M365_CONV_MAP_MAX:
        for stale in list(ids.keys())[: len(ids) - M365_CONV_MAP_MAX]:
            ids.pop(stale, None)
    _browser_state_update("m365", "conversation", {"keyed_conversation_ids": ids})


def _m365_resolve_conversation(full_key: str, boot_key: str) -> str:
    """ConversationId for a CONTINUING client chat, or "" to start fresh.

    Order: in-memory full → in-memory boot → (if restore enabled) persisted
    full → persisted boot. Persisted hits are warmed back into memory. Only
    called when the request already contains an assistant turn, so restoring a
    persisted id here means resuming a chat whose earlier turn completed."""
    for key in (full_key, boot_key):
        cid = _m365_lru_get(key)
        if cid:
            return cid
    if VOICE_EDGE_RESTORE_LAST_CONVERSATION:
        persisted = _m365_persisted_keyed()
        for key in (full_key, boot_key):
            cid = str(persisted.get(key) or "") if key else ""
            if cid:
                _m365_lru_put(key, cid)  # warm memory
                return cid
    return ""


def _m365_remember_conversation(
    cid: str, full_key: str, boot_key: str, tone: str, has_history: bool
) -> None:
    cid = str(cid or "").strip()
    if not cid:
        return
    # Collision guard (debug-only): if the weak boot alias already points at a
    # DIFFERENT ConversationId, two client chats share an identical first user
    # turn. full_key separates them from turn 2 on; the residual window is the
    # first↔second-turn boundary. Surface it rather than crossing talk silently.
    if VE_M365_LOG_DEBUG and boot_key:
        prior = _m365_lru_get(boot_key)
        if prior and prior != cid:
            _m365_log.debug(
                "[conv-collision] boot_key=%s already=%s… incoming=%s… tone=%s "
                "has_history=%s — two chats share the same first user turn",
                boot_key,
                prior[:16],
                cid[:16],
                tone,
                has_history,
            )
    # Always bind the boot alias (bridges turn 1→2, incl. across a restart).
    # Bind the strong full key only when the client is replaying an assistant
    # turn, so persist(full) and restore(full) both hash the CLIENT's copy of
    # the first assistant reply and therefore agree byte-for-byte.
    _m365_lru_put(boot_key, cid)
    _m365_persist_keyed(boot_key, cid)
    if has_history and full_key:
        _m365_lru_put(full_key, cid)
        _m365_persist_keyed(full_key, cid)
    # Keep the legacy per-tone slot fresh for the restore/telemetry UI only; it
    # is no longer consulted when choosing a conversation.
    _m365_http_set_conversation_id(cid, tone)


# ==================== DeepSeek Harness bridge (M365 models) ====================
# When a model opts in via BROWSER_MODEL_METADATA["deepseek_harness"] and the
# plugin endpoint is configured, each request is bound to a Harness session
# through the conversation identity (_m365_conversation_key) and model steps
# are mirrored into the session log. Tool schemas are merged into the relayed
# tool set (and Harness tool calls are executed by the plugin instead of being
# returned to Continue) ONLY when the per-model "deepseek_harness_tools"
# switch is True — it defaults to False, so the default bridge is a passive
# session logger. The bridge boundary is strict: the plugin never returns
# model context, and this file never asks for any — the model request, the
# tool loop, and the Continue-visible output stay owned here.
VOICE_EDGE_HARNESS_URL = os.getenv("VOICE_EDGE_HARNESS_URL", "").strip().rstrip("/")
VOICE_EDGE_HARNESS_TOKEN = os.getenv("VOICE_EDGE_HARNESS_TOKEN", "").strip()
VOICE_EDGE_HARNESS_TIMEOUT = max(
    3.0, float(os.getenv("VOICE_EDGE_HARNESS_TIMEOUT", "30"))
)
VOICE_EDGE_HARNESS_MAX_STEPS = max(
    1, int(os.getenv("VOICE_EDGE_HARNESS_MAX_STEPS", "8"))
)
# Tool executions outlive the sync budget (the plugin's own default tool
# timeout is 120s), so the execute call gets its own floor.
VOICE_EDGE_HARNESS_TOOL_TIMEOUT = max(
    VOICE_EDGE_HARNESS_TIMEOUT,
    float(os.getenv("VOICE_EDGE_HARNESS_TOOL_TIMEOUT", "150")),
)
# The user-message mirror sends the final prompt verbatim; the plugin's
# maxBodyBytes request-body cap is the single size bound.


def _harness_enabled(model_name: str) -> bool:
    """True only for metadata-opted-in models with a configured endpoint.
    Everything else takes the historical direct path byte-for-byte."""
    if not (VOICE_EDGE_HARNESS_URL and VOICE_EDGE_HARNESS_TOKEN):
        return False
    return bool((BROWSER_MODEL_METADATA.get(model_name) or {}).get("deepseek_harness"))


def _harness_tools_enabled(model_name: str) -> bool:
    """deepseek_harness_tools metadata switch (default False). When off, the
    bridge still binds the session and mirrors turns, but NO Harness tool
    schemas are injected into the relayed prompt: the model is never told
    about the tools, and the ownership name set stays empty so no parsed
    tool call can ever be classified as harness-owned (hence never executed
    by the plugin)."""
    return bool(
        (BROWSER_MODEL_METADATA.get(model_name) or {}).get("deepseek_harness_tools")
    )


async def _harness_post(path: str, payload: dict, timeout_seconds: float = 0.0) -> dict:
    """One JSON round-trip to the Harness voice-edge plugin. Raises on
    transport or HTTP error; each caller picks its own failure stance."""
    if not VOICE_EDGE_HARNESS_URL:
        raise RuntimeError("harness bridge is not configured")
    effective = timeout_seconds if timeout_seconds > 0 else VOICE_EDGE_HARNESS_TIMEOUT
    async with aiohttp.ClientSession(
        timeout=aiohttp.ClientTimeout(total=effective),
        headers={
            "authorization": f"Bearer {VOICE_EDGE_HARNESS_TOKEN}",
            "content-type": "application/json",
        },
    ) as session:
        async with session.post(
            f"{VOICE_EDGE_HARNESS_URL}{path}", json=payload
        ) as response:
            data = await response.json(content_type=None)
            if response.status >= 400:
                message = (
                    data.get("error", {}).get("message")
                    if isinstance(data, dict)
                    else None
                )
                raise RuntimeError(
                    f"harness {path} -> HTTP {response.status}: {message or data}"
                )
            if not isinstance(data, dict):
                raise RuntimeError(f"harness {path} -> non-object response")
            return data


async def _harness_user_message(bridge: dict, model_name: str, prompt: str) -> None:
    """Record the user's fresh turn text as the turn's user message, verbatim
    — no truncation. The text is the relay-extracted prompt body (the FIRST
    extractor's output, not a second parser), minus transport framing, so
    the mirror shows the conversation the model saw. Fail-open like every
    mirror tap."""
    bridge["sequence"] += 1
    payload: dict = {
        "conversation_key": bridge["key"],
        "type": "voice-edge/sync",
        "request_id": uuid.uuid4().hex,
        "model": model_name,
        "messages": [
            {
                "role": "user",
                "text": prompt,
            }
        ],
    }
    if bridge.get("boot_key"):
        payload["boot_key"] = bridge["boot_key"]
    if bridge.get("full_key"):
        payload["full_key"] = bridge["full_key"]
    try:
        await _harness_post("/event", payload)
    except Exception as exc:
        _m365_log.warning("[harness] user message mirror failed: %s", exc)


def _harness_tools_to_openai(tools: list, client_names: set) -> tuple[list, set]:
    """Convert Harness tool schemas into OpenAI function tools for relay
    injection. A name colliding with a client-provided tool stays CLIENT-owned
    (client wins), so the bridge can never hijack an MCP/IDE tool."""
    converted: list = []
    names: set = set()
    for tool in tools or []:
        if not isinstance(tool, dict):
            continue
        name = str(tool.get("name") or "").strip()
        if not name or name in client_names:
            continue
        parameters = tool.get("parameters")
        converted.append(
            {
                "type": "function",
                "function": {
                    "name": name,
                    "description": str(tool.get("description") or ""),
                    "parameters": (
                        parameters
                        if isinstance(parameters, dict)
                        else {"type": "object", "properties": {}}
                    ),
                },
            }
        )
        names.add(name)
    return converted, names


def _harness_client_tool_names(body: dict) -> set:
    names: set = set()
    for tool in (body or {}).get("tools") or []:
        if not isinstance(tool, dict):
            continue
        fn = tool.get("function")
        if isinstance(fn, dict):
            name = str(fn.get("name") or "").strip()
            if name:
                names.add(name)
    return names


async def _harness_begin(
    model_name: str, body: dict, messages: list, tone: str
) -> Optional[dict]:
    """Bind this client conversation to a Harness session and fetch the
    agent-scoped Harness tool schemas. Bind records nothing — every mirror
    append is a separate explicit tap by the caller. Fail-open: any error
    logs and returns None, and the request then runs exactly as it did
    before the bridge."""
    full_key, boot_key = _m365_conversation_key(tone, messages)
    conversation_key = full_key or boot_key
    if not conversation_key:
        return None
    try:
        response = await _harness_post(
            "/session/bind",
            {
                "conversation_key": conversation_key,
                "boot_key": boot_key,
                "full_key": full_key,
                "model": model_name,
            },
        )
    except Exception as exc:
        _m365_log.warning(
            "[harness] session bind failed; continuing without bridge: %s", exc
        )
        return None
    raw_tools = response.get("tools")
    if _harness_tools_enabled(model_name):
        openai_tools, names = _harness_tools_to_openai(
            raw_tools if isinstance(raw_tools, list) else [],
            _harness_client_tool_names(body),
        )
    else:
        # deepseek_harness_tools switch (default False): bind and mirror
        # only. Empty injection set AND empty ownership names — no schema
        # reaches the prompt and no parsed call is harness-executed.
        openai_tools, names = [], set()
    try:
        sequence = int(response.get("sequence") or 0)
    except (TypeError, ValueError):
        # A malformed optional sequence must not violate the bridge's
        # fail-open contract or take down the M365 request path.
        sequence = 0
    return {
        "key": str(response.get("conversation_key") or conversation_key),
        "session_id": str(response.get("harness_session_id") or ""),
        "sequence": sequence,
        "openai_tools": openai_tools,
        "names": names,
        "boot_key": boot_key or "",
        "full_key": full_key or "",
    }


async def _harness_mirror_event(
    bridge: dict,
    *,
    kind: str,
    text: str = "",
    reasoning: str = "",
    tool_calls: Optional[list] = None,
    finish_reason: str = "",
) -> None:
    """Mirror one model step into the Harness session log. Mirror failures are
    logged and dropped — the client-visible stream is never hostage to the
    bridge."""
    bridge["sequence"] += 1
    payload: dict = {
        "conversation_key": bridge["key"],
        "type": "voice-edge/model-event",
        "sequence": bridge["sequence"],
        "kind": kind,
    }
    if text:
        payload["text"] = text
    if reasoning:
        payload["reasoning"] = reasoning
    if tool_calls:
        payload["tool_calls"] = [
            {
                "id": str(call.get("id") or ""),
                "name": str((call.get("function") or {}).get("name") or ""),
                "arguments": str((call.get("function") or {}).get("arguments") or ""),
            }
            for call in tool_calls
        ]
    if finish_reason:
        payload["finish_reason"] = finish_reason
    try:
        await _harness_post("/event", payload)
    except Exception as exc:
        _m365_log.warning("[harness] model event mirror failed: %s", exc)


def _harness_split_calls(calls: list, harness_names: set) -> tuple[list, list]:
    """Split parsed tool calls into (harness-owned, client-owned)."""
    harness_calls = [
        c
        for c in calls
        if str((c.get("function") or {}).get("name") or "") in harness_names
    ]
    client_calls = [
        c
        for c in calls
        if str((c.get("function") or {}).get("name") or "") not in harness_names
    ]
    return harness_calls, client_calls


async def _harness_execute_tool(bridge: dict, call: dict) -> "ToolResult":
    """Execute one Harness tool call through the plugin and shape the outcome
    as the ToolResult the relay's tool-results block expects. Transport and
    tool errors both become error result TEXT so the model can react."""
    fn = call.get("function") or {}
    name = str(fn.get("name") or "")
    call_id = str(call.get("id") or "")
    raw_arguments = fn.get("arguments")
    arguments: object = {}
    if isinstance(raw_arguments, str) and raw_arguments.strip():
        try:
            arguments = json.loads(raw_arguments)
        except ValueError:
            arguments = {"_raw": raw_arguments}
    elif isinstance(raw_arguments, (dict, list)):
        arguments = raw_arguments
    try:
        response = await _harness_post(
            "/tool/execute",
            {
                "conversation_key": bridge["key"],
                "call_id": call_id,
                "name": name,
                "arguments": arguments,
            },
            timeout_seconds=VOICE_EDGE_HARNESS_TOOL_TIMEOUT,
        )
        result = response.get("tool_result") or {}
        text = str(result.get("text") or "")
        if result.get("isError"):
            text = f"[harness tool error] {text}"
    except Exception as exc:
        text = f"[harness tool transport error] {exc}"
    return ToolResult(name=name, call_id=call_id, content=text)


def _harness_client_refusal(call: dict) -> "ToolResult":
    """Synthetic error result for a CLIENT-owned tool call that arrived in the
    same batch as Harness calls: the client executes its own tools on the next
    OpenAI turn, so co-hosted calls are asked to retry separately."""
    fn = call.get("function") or {}
    return ToolResult(
        name=str(fn.get("name") or ""),
        call_id=str(call.get("id") or ""),
        content=(
            "[voice-edge] this tool is executed by the client, but it was "
            "called in the same step as Harness-hosted tools, which are "
            "handled internally. Call it again in a separate step."
        ),
    )


async def _harness_finish(bridge: Optional[dict], status: str = "completed") -> None:
    """Close the turn in the Harness session (finish marker + durability
    checkpoint). Fire-and-log like the mirror."""
    if not bridge:
        return
    bridge["sequence"] += 1
    try:
        await _harness_post(
            "/event",
            {
                "conversation_key": bridge["key"],
                "type": "voice-edge/finish",
                "sequence": bridge["sequence"],
                "status": status,
            },
        )
    except Exception as exc:
        _m365_log.warning("[harness] turn finish failed: %s", exc)


M365_UPLOAD_MAX_BYTES = max(
    1024 * 1024,
    int(os.getenv("M365_UPLOAD_MAX_BYTES", str(50 * 1024 * 1024))),
)


# A client tool result (the output of an MCP / IDE tool call — e.g. a large
# read_file) is normally inlined verbatim into this turn's prompt via
# compose_turn_text -> build_tool_results_block. Those bytes then count against
# M365 Copilot's context window; two big results (a few thousand tokens each)
# crowd out the user's actual request and Copilot "forgets" what was asked.
# Above this many UTF-8 bytes a single tool result is OFFLOADED: its body is
# uploaded to SharePoint as a text attachment (the same FileUrl document-link
# egress inline files already use) and only a short pointer stays inline, so the
# model pulls the full result from the attachment on demand instead of paying
# for it in-context every turn. 0 disables offloading (always inline). Only the
# m365 family has a SharePoint upload egress, so only _direct_m365_chat_response
# applies this; qwen/doubao/deepseek keep inlining.
M365_TOOL_RESULT_INLINE_MAX_BYTES = max(
    0,
    int(os.getenv("M365_TOOL_RESULT_INLINE_MAX_BYTES", str(6 * 1024))),
)


# A Cline/Continue client may emit an empty <file_content> wrapper while still
# including the absolute path selected by the user. In that case, read the
# selected local file directly. The normal size and regular-file checks remain.
def _client_read_local_attachment_fallback(raw_path: str) -> tuple[bytes, Path]:
    candidate = Path(str(raw_path or "")).expanduser()
    if not candidate.is_absolute():
        raise ValueError("empty inline attachment path is not absolute")
    try:
        resolved = candidate.resolve(strict=True)
    except (FileNotFoundError, OSError) as exc:
        raise ValueError("empty inline attachment file was not found") from exc
    if not resolved.is_file():
        raise ValueError("empty inline attachment path is not a regular file")
    try:
        size = resolved.stat().st_size
    except OSError as exc:
        raise ValueError("empty inline attachment file cannot be inspected") from exc
    if size > M365_UPLOAD_MAX_BYTES:
        raise ValueError("inline attachment exceeds upload limit")
    try:
        data = resolved.read_bytes()
    except OSError as exc:
        raise ValueError("empty inline attachment file cannot be read") from exc
    if len(data) != size:
        raise ValueError("local attachment changed while being read")
    return data, resolved


def _client_safe_filename(value: str, fallback: str) -> str:
    name = Path(str(value or "")).name.strip()
    name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name)
    return name[:180] or fallback


def _client_latest_user_message(messages: list) -> dict:
    for message in reversed(messages or []):
        if (
            isinstance(message, dict)
            and str(message.get("role") or "").strip().lower() == "user"
        ):
            return message
    return {}


# The opening AND closing protocol markers must EACH occupy their own line
# (the documented contract of _client_inline_file_spans). Previously only the
# closing marker was line-anchored, so a bare "<file_content path=...>" mention
# appearing MID-LINE in ordinary prose (a user quoting/discussing the marker, or
# a pasted report containing the text "file_content") started a span that
# swallowed everything up to the next standalone "</file_content>" line.
# Anchoring the opening tag to a standalone line makes a real IDE-injected
# attachment match while an inline prose mention never starts a span. Limiting
# attrs to [^>\r\n]* stops the opening tag from spanning lines. As a bonus the
# content group now begins AFTER the opening line's newline, so the extracted
# payload is byte-exact (no stray leading "\n").
_CLIENT_FILE_CONTENT_RE = re.compile(
    r"^[ \t]*<file_content\b(?P<attrs>[^>\r\n]*)>[ \t]*\r?\n"
    r"(?P<content>.*?)"
    r"^[ \t]*</file_content\s*>[ \t]*(?:\r?\n|\Z)",
    re.IGNORECASE | re.MULTILINE | re.DOTALL,
)

_CLIENT_FILE_PATH_RE = re.compile(
    r"\bpath\s*=\s*(?:"
    r'"(?P<double>[^"]+)"|'
    r"'(?P<single>[^']+)'|"
    r"(?P<bare>[^\s>]+)"
    r")",
    re.IGNORECASE | re.DOTALL,
)

_CLINE_TASK_RE = re.compile(
    r"<task\s*>(?P<task>.*?)</task>",
    re.IGNORECASE | re.DOTALL,
)

_CLINE_ENVIRONMENT_RE = re.compile(
    r"<environment_details\s*>.*?</environment_details>",
    re.IGNORECASE | re.DOTALL,
)

_CLINE_TASK_PROGRESS_RE = re.compile(
    r"(?:^|\n)\s*#\s*task_progress\s+List.*?(?=\n\s*<environment_details\s*>|\Z)",
    re.IGNORECASE | re.DOTALL,
)


def _client_user_text_parts(message: dict) -> list[str]:
    content = message.get("content")
    if isinstance(content, list):
        return [
            str(part.get("text") or "")
            for part in content
            if isinstance(part, dict)
            and str(part.get("type") or "").strip().lower() in {"text", "input_text"}
        ]
    return [str(content or "")]


def _client_user_text(message: dict) -> str:
    """Reassemble one logical user text stream before parsing wrappers.

    OpenAI/Continue clients may split a single Cline wrapper, its payload, and
    its closing marker across multiple text/input_text parts. Joining with an
    empty separator preserves the original byte-for-byte character stream;
    parsing each part independently can create empty or missing attachments.
    """
    return "".join(_client_user_text_parts(message))


def _client_inline_file_spans(text: str) -> list[dict]:
    """Return every complete, line-delimited Cline inline-file span.

    Opening and closing protocol markers must each occupy their own line.
    Consecutive attachment blocks are matched independently by finditer().
    Marker-like text embedded within a source line remains attachment payload.
    """
    value = str(text or "")
    spans: list[dict] = []

    for match in _CLIENT_FILE_CONTENT_RE.finditer(value):
        attrs = match.group("attrs") or ""
        path_match = _CLIENT_FILE_PATH_RE.search(attrs)
        if path_match is None:
            _m365_attachment_debug(
                "cline-file-skip",
                reason="standalone file block has no valid path attribute",
                attrs_preview=attrs[:160],
            )
            continue

        raw_path = (
            next(item for item in path_match.group("double", "single", "bare") if item)
            .strip()
            .rstrip("\\")
        )
        spans.append(
            {
                "start": match.start(),
                "end": match.end(),
                "content_start": match.start("content"),
                "content_end": match.end("content"),
                "path": raw_path,
            }
        )

    return spans


def _client_collect_inline_files(message: dict) -> list[dict]:
    attachments: list[dict] = []
    text_parts = _client_user_text_parts(message)
    logical_text = "".join(text_parts)
    # Some Cline builds JSON-escape quotes inside the already decoded opening
    # tag (path=\"...\"). Normalize only protocol opening-tag syntax after
    # all text fragments have been reassembled.
    scan_text = re.sub(
        r'(?m)^([ \t]*<file_content\b[^>\r\n]*?\bpath\s*=\s*)\\(["\'])',
        r"\1\2",
        logical_text,
        flags=re.IGNORECASE,
    )
    spans = _client_inline_file_spans(scan_text)

    _m365_attachment_debug(
        "cline-scan",
        content_type=type(message.get("content")).__name__,
        part_count=len(text_parts),
        part_lengths=[len(text) for text in text_parts],
        logical_length=len(logical_text),
        normalized_length=len(scan_text),
        file_tag_count=len(spans),
        task_tag_count=len(_CLINE_TASK_RE.findall(logical_text)),
    )
    attachment_index = 0
    for span in spans:
        attachment_index += 1
        extracted_text = scan_text[span["content_start"] : span["content_end"]]
        data = extracted_text.encode("utf-8")
        source = "inline"
        resolved_path = ""
        if not extracted_text.strip():
            data, local_path = _client_read_local_attachment_fallback(span["path"])
            source = "local-path-fallback"
            resolved_path = str(local_path)
        _m365_attachment_debug(
            "inline-extracted",
            attachment_index=attachment_index,
            raw_path=span["path"],
            source=source,
            resolved_path=resolved_path,
            content_start=span["content_start"],
            content_end=span["content_end"],
            scan_length=len(scan_text),
            extracted_chars=len(extracted_text),
            extracted_bytes=len(data),
            extracted_sha256=hashlib.sha256(data).hexdigest(),
            prefix_hex=data[:32].hex(),
            suffix_hex=data[-32:].hex() if data else "",
            newline_count=extracted_text.count("\n"),
        )
        if len(data) > M365_UPLOAD_MAX_BYTES:
            raise ValueError("inline attachment exceeds upload limit")
        fallback = f"attachment-{attachment_index}.txt"
        name = _client_safe_filename(span["path"], fallback)
        suffix = Path(name).suffix.lower()
        mime = {
            ".py": "text/x-python",
            ".js": "text/javascript",
            ".json": "application/json",
            ".md": "text/markdown",
            ".txt": "text/plain",
            ".html": "text/html",
            ".css": "text/css",
            ".xml": "application/xml",
            ".yaml": "application/yaml",
            ".yml": "application/yaml",
        }.get(suffix, "text/plain")
        attachments.append(
            {
                "name": name,
                "mimeType": mime,
                "size": len(data),
                "data": base64.b64encode(data).decode("ascii"),
            }
        )
        _m365_attachment_debug("cline-file", name=name, mime_type=mime, size=len(data))
    _m365_attachment_debug(
        "cline-scan-result",
        attachment_count=len(attachments),
        names=[item["name"] for item in attachments],
    )
    return attachments


def _client_text_outside_inline_files(text: str) -> str:
    """Return user-authored text while removing only parsed attachment spans."""
    value = str(text or "")
    spans = _client_inline_file_spans(value)
    if not spans:
        return value
    pieces = []
    cursor = 0
    for span in spans:
        pieces.append(value[cursor : span["start"]])
        cursor = span["end"]
    pieces.append(value[cursor:])
    return "".join(pieces)


# Continue 专属：Continue（streamResponse.ts 的 buildAttachedFilesText）在附件
# 前注入一行 "Files attached by the user:"，与 <file_content> 块一同作为【独立
# text part】发送。_client_user_text 用空串合并多 part 时，这行可能【紧贴用户正文
# 末尾且不换行】。这行对模型没有信息量（真正的文件上下文由 m365 的 ConversationId
# 承载，见 _m365_first_user_and_assistant 的跨轮 identity 归一），故整段【干净删除】、
# 不留占位符。剥离不做行首锚定（否则粘连时漏剥）；但要求 marker 后紧跟换行或字符串
# 结尾，避免误删用户正文里句中随口提到的同名文字。这是 Continue 客户端格式的一部分
# （Cline 不发此行），故独立成 _continue_ 函数。
_CONTINUE_ATTACHMENT_NOTICE_RE = re.compile(
    r"[ \t]*Files attached by the user:[ \t]*(?:\r?\n+|\Z)",
    re.IGNORECASE,
)


def _continue_strip_attachment_notice(text: str) -> str:
    """Delete Continue's injected "Files attached by the user:" notice line.

    The notice carries no signal for the model (attachment context is owned by
    m365's ConversationId across turns), so it is removed outright rather than
    replaced with a placeholder. Stripping is position-tolerant (no line anchor,
    since _client_user_text may glue the notice mid-line) but still requires a
    newline/EOF after the marker so a literal same-text mention the user typed in
    prose is never over-stripped.
    """
    return _CONTINUE_ATTACHMENT_NOTICE_RE.sub("", text)


def _client_prompt_from_message(message: dict) -> str:
    logical_text = _client_user_text(message)
    parts = [_client_text_outside_inline_files(logical_text)]
    explicit_tasks = []
    for text in parts:
        explicit_tasks.extend(
            match.group("task").strip()
            for match in _CLINE_TASK_RE.finditer(text)
            if match.group("task").strip()
        )
    if explicit_tasks:
        return "\n\n".join(explicit_tasks).strip()

    cleaned = []
    for text in parts:
        text = _CLINE_ENVIRONMENT_RE.sub("", text)
        text = _CLINE_TASK_PROGRESS_RE.sub("", text)
        text = _continue_strip_attachment_notice(text)
        text = text.strip()
        if text:
            cleaned.append(text)
    return "\n\n".join(cleaned).strip()


async def _client_collect_attachments(messages: list) -> list[dict]:
    message = _client_latest_user_message(messages)
    content = message.get("content")
    attachments: list[dict] = _client_collect_inline_files(message)
    _m365_attachment_debug(
        "collect-start",
        message_count=len(messages or []),
        latest_content_type=type(content).__name__,
        inline_count=len(attachments),
    )
    if not isinstance(content, list):
        _m365_attachment_debug(
            "collect-done",
            total_count=len(attachments),
            names=[x["name"] for x in attachments],
        )
        return attachments
    file_kinds = {"file", "input_file"}
    image_kinds = {"image_url", "input_image", "imageurl", "image"}
    for index, part in enumerate(content):
        if not isinstance(part, dict):
            continue
        kind = str(part.get("type") or "").strip().lower()
        if kind not in file_kinds | image_kinds:
            continue
        is_image = kind in image_kinds
        source = (
            part.get("file")
            if kind in file_kinds
            else part.get("image_url") or part.get("imageUrl")
        )
        if isinstance(source, dict):
            raw = source.get("file_data") or source.get("data") or source.get("url")
            filename = source.get("filename") or source.get("name")
            mime = source.get("mime_type") or source.get("content_type")
        else:
            raw = source or part.get("file_data") or part.get("data") or part.get("url")
            filename = part.get("filename") or part.get("name")
            mime = part.get("mime_type") or part.get("content_type")
        if not isinstance(raw, str) or not raw.strip():
            continue
        raw = raw.strip()
        decoded = _deepseek_decode_data_uri(raw)
        if decoded is not None:
            data, detected_mime = decoded
        elif raw.startswith(("https://", "http://")):
            data, detected_mime = await _deepseek_download_attachment(raw)
        else:
            try:
                data = base64.b64decode(raw, validate=True)
                detected_mime = "application/octet-stream"
            except (ValueError, binascii.Error):
                continue
        if len(data) > M365_UPLOAD_MAX_BYTES:
            raise ValueError("inline attachment exceeds upload limit")
        effective_mime = str(mime or detected_mime or "application/octet-stream")
        if not is_image and effective_mime.startswith("image/"):
            is_image = True
        # Continue never supplies a filename for pasted images. Derive a real
        # extension from the MIME type so SharePoint stores a proper image file
        # (both SharePoint and the model key off the extension); non-image
        # attachments keep the existing generic fallback.
        if is_image:
            ext = (
                effective_mime.split("/", 1)[-1].split("+", 1)[0].replace("jpeg", "jpg")
                or "png"
            )
            fallback = f"image-{index + 1}.{ext}"
        else:
            fallback = f"attachment-{index + 1}.bin"
        attachments.append(
            {
                # Preserve the image/file distinction end-to-end. The extension
                # routes kind=="image" through the inline owahub UploadFile path
                # (ImageFile annotation, vision model sees the pixels); anything
                # else takes the SharePoint upload / FileUrl document-link path.
                # Without this tag the extension cannot tell a pasted image from
                # a document and silently sends it as a FileUrl link.
                "kind": "image" if is_image else "file",
                "name": _client_safe_filename(str(filename or ""), fallback),
                "mimeType": effective_mime,
                "size": len(data),
                "data": base64.b64encode(data).decode("ascii"),
                # Preserve the originating multimodal content slot so Harness
                # can mirror text and images in the exact order the user sent.
                "content_index": index,
            }
        )
    _m365_attachment_debug(
        "collect-done",
        total_count=len(attachments),
        names=[x["name"] for x in attachments],
    )
    return attachments


_CLINE_PROTOCOL_MARKERS = (
    "# reminder: instructions for tool use",
    "<attempt_completion>",
    "[attempt_completion] result:",
    "# task_progress list",
)


def _cline_is_request(messages: list) -> bool:
    """Detect the Cline response protocol without misclassifying Continue.

    Continue reuses only <file_content> for inline file uploads. That tag is
    attachment syntax, not a Cline protocol signal. Inspect only the latest user
    message and require Cline-specific control structure before enabling the
    attempt_completion response envelope.
    """
    message = _client_latest_user_message(messages)
    texts = (
        _client_text_outside_inline_files(text)
        for text in _client_user_text_parts(message)
    )
    lowered = "\n".join(texts).lower()
    if "<environment_details>" not in lowered:
        return False
    return "<task>" in lowered or any(
        marker in lowered for marker in _CLINE_PROTOCOL_MARKERS
    )


def _cline_result_open() -> str:
    return "<attempt_completion>\n<result>\n"


def _cline_result_close() -> str:
    return "\n</result>\n</attempt_completion>"


# a MODEL under the relayed classic-Cline system prompt may emit the
# envelope tags itself. These primitives strip those TAGS (keeping all inner +
# surrounding text) so the transport can add exactly one envelope. The tag regex
# is whitespace-tolerant; the marker list drives streaming holdback so a tag
# split across two chunks is never leaked as content.
_CLINE_ENVELOPE_TAG_RE = re.compile(
    r"<\s*/?\s*(?:attempt_completion|result)\s*>",
    re.IGNORECASE,
)
_CLINE_ENVELOPE_TAG_MARKERS = (
    "<attempt_completion>",
    "</attempt_completion>",
    "<result>",
    "</result>",
)


def _cline_env_tag_holdback(buf: str) -> int:
    """Longest suffix of buf that could BEGIN one of the envelope tags (so it is
    held back across a chunk boundary). Complete tags are handled by the regex,
    so this only inspects proper prefixes."""
    lo = buf.lower()
    best = 0
    for marker in _CLINE_ENVELOPE_TAG_MARKERS:
        ml = marker.lower()
        for k in range(min(len(lo), len(ml) - 1), 0, -1):
            if lo.endswith(ml[:k]):
                best = max(best, k)
                break
    return best


def _cline_wrap_result(text: str) -> str:
    value = str(text or "").strip()
    # The transport owns the Cline envelope. Remove ANY model-emitted envelope
    # TAGS (keeping all surrounding + inner text) so re-wrapping cannot nest
    # attempt_completion. Tag-removal (not extracting only <result>…</result>)
    # is used deliberately: it never DROPS prose the model placed outside its
    # own envelope, which extraction would.
    value = _CLINE_ENVELOPE_TAG_RE.sub("", value).strip()
    return _cline_result_open() + value + _cline_result_close()


class ClineEnvelope:
    """Cline attempt_completion response envelope, shared by ALL browser handlers.

    The Cline client expects a plain-text final answer wrapped as
    <attempt_completion><result>…</result></attempt_completion>. That framing is
    a CLIENT format (not model-specific), so the wrapping lives here and every
    family (m365 / deepseek / qwen / doubao) applies it identically when
    prepared.client_kind == "cline".

    Semantics (the agreed default):
      * plain-text answer -> wrapped (streaming: open tag on the FIRST content
        chunk, close tag at done; non-stream: wrap the whole text).
      * tool_calls        -> NOT wrapped: a tool call is a request, not the final
        result. Call suppress() before emitting tool_calls; the envelope then
        opens/closes nothing.
      * reasoning_content -> NEVER wrapped (handlers must not feed reasoning
        through open_prefix()/wrap()).

    Usage (streaming):
        env = ClineEnvelope(prepared.client_kind == "cline")
        # for each answer content piece (m365 also strips model-emitted tags):
        piece = env.strip_envelope_tags(content)                 # A: drop model envelope tags
        if not piece:                              #    (held-back partial tag)
            continue
        content = env.open_prefix() + piece        # open tag once, else ""
        # if a tool_call is produced instead (emit any returned close tag first):
        closing = env.suppress()   # non-"" only if content already opened it
        # if closing: emit_content(closing)   then emit tool_calls
        # at stream end, before finish_reason=stop:
        closing = env.closing()                    # close tag / empty env / ""
    Usage (non-stream):
        message_content = env.wrap(full_text)
    """

    def __init__(self, active: bool) -> None:
        self.active = bool(active)
        self._opened = False
        self._suppressed = False
        self._strip_buf = ""  # A: streaming model-envelope-tag holdback

    def open_prefix(self) -> str:
        """Opening tag to prepend to the FIRST content chunk (once). "" after
        that, or when inactive/suppressed."""
        if not self.active or self._opened or self._suppressed:
            return ""
        self._opened = True
        return _cline_result_open()

    def strip_envelope_tags(self, text: str) -> str:
        """A (defense-in-depth): remove MODEL-emitted envelope tags
        (<attempt_completion>/<result> + closers) from one streamed content
        chunk, keeping all surrounding + inner text. Holds back a partial tag
        that spans the chunk boundary (returns it once the next chunk completes
        or discards it at stream end as protocol noise). Returns "" when the
        whole chunk was tag(s)/held. No-op byte-passthrough when inactive
        (non-cline), so callers stay identical for plain clients.

        Call BEFORE open_prefix(): strip_envelope_tags() yields the raw answer
        open_prefix() adds the transport\'s single opening tag on the first
        non-empty piece.
        """
        text = str(text or "")
        if not self.active:
            return text
        self._strip_buf += text
        self._strip_buf = _CLINE_ENVELOPE_TAG_RE.sub("", self._strip_buf)
        hb = _cline_env_tag_holdback(self._strip_buf)
        safe = self._strip_buf[: len(self._strip_buf) - hb]
        self._strip_buf = self._strip_buf[len(safe) :]
        return safe

    def suppress(self) -> str:
        """Mark this turn as a tool-call turn (a tool call is a request, not the
        final result): no further envelope opens and closing() stays silent.

        Returns the closing tag ONLY when the streaming envelope was ALREADY
        opened — i.e. the transpiler streamed pre-fence content (open_prefix
        fired) before the tool block was detected. REQUIRED / AUTO+fence json
        modes emit pre-fence text as content, so they can open the envelope
        before a tool call is seen; AUTO+sentinel buffers until decided and
        never opens. The handler MUST emit this returned tag BEFORE the
        tool_calls delta, otherwise the client receives an unclosed <result>
        followed by tool_calls. Returns "" when nothing was opened (the normal
        tool-only turn) or when inactive / already suppressed.
        """
        if self._suppressed:
            return ""
        self._suppressed = True
        if self.active and self._opened:
            return _cline_result_close()
        return ""

    def closing(self) -> str:
        """Closing text at stream end: close tag if content opened the envelope,
        an empty <result></result> envelope if cline is active but nothing was
        streamed, or "" when inactive/suppressed."""
        if not self.active or self._suppressed:
            return ""
        if self._opened:
            return _cline_result_close()
        return _cline_wrap_result("")

    def wrap(self, text: str) -> str:
        """Non-stream: wrap the whole final text, or pass it through."""
        if not self.active or self._suppressed:
            return str(text or "")
        return _cline_wrap_result(text)


def _harness_inline_image_markdown(attachments: list[dict]) -> str:
    """Rebuild the user's inline images as markdown data URIs for the mirror.

    The m365 egress uploads them for the vision model (attachment channel),
    so the extracted turn text carries no trace; the Harness mirror records
    what the user actually sent. kind=="file" attachments (documents) stay
    out — no faithful chat rendering exists for them.
    """
    return "".join(
        f"\n\n![{a['name']}](data:{a['mimeType']};base64,{a['data']})"
        for a in attachments
        if a.get("kind") == "image"
    )


def _harness_ordered_user_content(message: dict, attachments: list[dict]) -> str:
    """Mirror a fresh multimodal user turn without moving its inline images.

    Text is cleaned by the same prompt extractor used for the model-facing user
    body. Successfully collected image parts are replaced in their original
    content-list slots with markdown data URIs; documents remain attachment-only.
    """
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, list):
        return _client_prompt_from_message(message) + _harness_inline_image_markdown(
            attachments
        )

    images_by_index = {
        a.get("content_index"): a
        for a in attachments
        if a.get("kind") == "image" and isinstance(a.get("content_index"), int)
    }
    logical_parts: list[str] = []
    for index, part in enumerate(content):
        if not isinstance(part, dict):
            continue
        kind = str(part.get("type") or "").strip().lower()
        if kind in {"text", "input_text"}:
            logical_parts.append(str(part.get("text") or ""))
            continue
        image = images_by_index.get(index)
        if image is not None:
            logical_parts.append(
                f"\n\n![{image['name']}]"
                f"(data:{image['mimeType']};base64,{image['data']})\n\n"
            )
    return _client_prompt_from_message(
        {"role": "user", "content": "".join(logical_parts)}
    )


def _client_extract_prompt(messages: list) -> str:
    """Envelope-aware user-text extraction for ALL browser models.

    Takes ONLY the newest user turn (Copilot owns history per ConversationId;
    replaying the transcript would duplicate context and leak IDE system prompts
    into the visible chat — mirrors the Qwen/DeepSeek browser backends), unwraps
    <task>…</task> and strips inline <file_content>/<environment_details>/
    task_progress plus Continue's "Files attached by the user:" notice, so
    (a) the raw IDE envelope is never sent as the prompt and (b) inline files are
    not duplicated once as prose and again as each family's attachment egress.
    A no-op for plain chat with no envelope markers.
    """
    for message in reversed(messages or []):
        if not isinstance(message, dict):
            continue
        if str(message.get("role") or "").strip().lower() != "user":
            continue
        text = _client_prompt_from_message(message)
        if text:
            return text
    return ""


# Normalize the three M365 citation encodings plus host-protocol inline images.
# Ordinary Markdown (links, brackets, code samples) must never enter this path.
_M365_CITE_REFID = r"[A-Za-z0-9][A-Za-z0-9_:\-]*"
# —— 完整跨度：位置稳定、可安全整体删除。全部限定单行：引用编码是服务器下发的
#    原子 token，永不跨行；不这么限，散文里一个孤零零的 "【1-" 会和几百字符之后
#    真正的 【N-x】 拼成巨型跨度被整体删除（= 吞正文）。——
_M365_CITE_COMPLETE_RES = (
    re.compile(r"<cite\b[^\n>]*>" + _M365_CITE_REFID + r"</cite>", re.IGNORECASE),  # ③
    re.compile("\ue200[^\ue201\n]*\ue201"),  # ① 私有区已解析（单行原子 token）
    re.compile(
        r"【\d+-[^】\n]*】"
    ),  # ② 未解析占位符 【N-xxx】（要求“数字-”，不误伤中文【重要】等）
    # ④ 宿主协议内联图 markdown：![alt](attachment://…) / ![alt](sandbox:…)。
    # attachment:// 是 Copilot 宿主内部协议，Continue 加载不了（坏图占位）；真图走
    # appendText 的 data-URI，正文里这类图 markdown 冗余且坏，删掉。只删 attachment:/
    # sandbox: 协议，普通 http(s)/data: 图片一律保留。URL 用宽字符集（除 ) 和换行）：
    # 尾部扣留（④ 在途分支）本就是宽字符集，CJK 路径的宿主图会被 JS/Python 扣到闭合，
    # 这里必须同宽删除——否则扣完不删，坏图占位泄漏进正文（内联图"中断"的现形之一）。
    re.compile(
        r"!\[[^\]\n]*\]\([ \t]*(?:attachment:|sandbox:)[^)\n]*\)",
        re.IGNORECASE,
    ),
)
# —— 结尾“在途”跨度（锚定文末 \Z）：删完整跨度后可能剩半个引用，扣住一帧等下一帧
#    补全，避免先发半个再回收（破坏 relay 前缀单调、触发丢弃）。单条正则、取最左
#    匹配即扣留点；②③ 各分支不跨换行（引用编码恒为单行，换行即证明是字面文本，
#    立即放行，杜绝旧版 “<cite\n\n… 被永久扣留” 的死角）。——
_M365_CITE_TAIL_RE = re.compile(
    r"(?:"
    "\ue200[^\ue201\n]*"  # ① \ue200… 尚未见到 \ue201
    r"|【\d+-?[^】\n]*"  # ② 【N / 【N- / 【N-x 尚未见到 】
    r"|【"  # ② 裸 【 正在成形（仅当它就是最后一个字符；【中文 不匹配）
    r"|<cite\b[^\n>]*(?:>(?:"
    + _M365_CITE_REFID
    + r")?(?:</?[a-z]*)?)?"  # ③ <cite 开标签/REFID/半闭标签各阶段
    r"|<(?:c(?:i(?:t(?:e)?)?)?)?"  # ③ 字面 "<"…"<cit" 正在成形（裸 "<" 也扣：若下一帧补成完整 <cite> 被整体删除，先发出的 "<" 会造成前缀回退）
    r"|!\[[^\]\n]*(?:\](?:\([^)\n]*)?)?"  # ④ ![alt / ![alt] / ![alt](… 扣到 ) 闭合或换行（届时若是 attachment:/sandbox: 被 ④ 删除，普通图片原样补发）
    r"|!"  # ④ 裸 ! 是 ![ 的前缀，扣一帧（否则先发出的 ! 会在图片被删时回退；终态不扣）
    r")\Z",
    re.IGNORECASE,
)


# 终态(final=True)专用:删除文末【带 REFID 的未闭合】引用跨度——
#   <cite …>REFID(</… 半个闭标签，可无)  且锚定 \Z。
# 语义边界:REFID 为【必需】,故裸 <cite>(用户可能字面写的)不被误删,维持既有
# “字面 <cite> 不误伤”承诺;而 <cite>turn69file21</c 这类明确是被切断的坏引用
# (流式永不会再补全,因为已是终态),原样泄漏严格劣于删除,故仅在 final 删它。
# 中间帧(final=False)仍由 _M365_CITE_TAIL_RE 扣住等待补全,不走这里。
_M365_CITE_FINAL_UNCLOSED_RE = re.compile(
    r"<cite\b[^\n>]*>" + _M365_CITE_REFID + r"(?:</?[a-z]*)?\Z",
    re.IGNORECASE,
)


def _m365_code_intervals(text: str) -> list[tuple[int, int]]:
    """Find Markdown backtick spans, including an unterminated final span.

    注意：文末未闭合跨度【必须】始终算代码——这是删除作用域的单调性要求，
    与 JS 稳定器的扣留放行是两层不同职责。若未闭合时按散文删除其中的
    引用/图片形状，闭合符到达那一帧该跨度变成真代码、内容恢复，清洗结果
    会变长回去 = 前缀回退 → relay 丢弃。JS 侧扣留
    放行（孤立反引号不当代码扣留）只是发布时机决策、只增不删，不受影响。
    """
    intervals: list[tuple[int, int]] = []
    opener: Optional[re.Match[str]] = None
    for match in re.finditer(r"`+", text):
        if opener is None:
            opener = match
        elif len(match.group()) == len(opener.group()):
            intervals.append((opener.start(), match.end()))
            opener = None
    if opener is not None:
        intervals.append((opener.start(), len(text)))
    return intervals


def _m365_sub_outside_code(text: str, transform) -> str:
    """Apply a citation transform to prose, preserving code literally."""
    pieces: list[str] = []
    cursor = 0
    for start, end in _m365_code_intervals(text):
        pieces.append(transform(text[cursor:start]))
        pieces.append(text[start:end])
        cursor = end
    pieces.append(transform(text[cursor:]))
    return "".join(pieces)


def _m365_strip_cite(cumulative: str, final: bool = False) -> str:
    """从累积答案快照中一致剥离【三种引用编码 + 宿主协议内联图】，返回“稳定”前缀。

    M365_DELTA/DONE 携带累积全文（delta = text[len(best):]），故本函数必须保持前缀单调：
    清洗结果永远是上次清洗结果的前缀扩展，否则触发 relay 的 non-prefix 丢弃、把正文吞掉。
    关键：流式帧(②)与权威 type2-final(①)必须归一到【同一】结果，才能前缀相容、不丢正文。

    参数 final：
      False（流式中间帧）：
        删除完整引用跨度，并暂存结尾处确定属于引用协议的未完成前缀，等待下一帧补全。
        不暂存普通 Markdown 链接、图片、方括号、圆括号或其他通用文本字符。
      True（权威终态帧 DONE）：
        删除完整引用跨度，并清理结尾处带 REFID 的截断 <cite> 引用。
        不暂存任何可能属于正常正文的尾部字符。

    删除对象：
      ① \ue200…\ue201（私有区已解析）
      ② 【N-xxx】（未解析占位符）
      ③ <cite>REFID</cite>
      ④ ![alt](attachment://…) / ![alt](sandbox:…)（宿主协议内联图；真图走 appendText
         的 data-URI，正文里的 attachment:// 是坏图占位，删掉；普通 http(s)/data:
         图片一律保留）

    普通 Markdown 链接、方括号、代码范围、字面 `<cite>`、中文【重要】和数学表达式均
    不参与清理；反引号代码范围中的引用/图片形状也按原文保留。流式态额外扣住文末
    半个引用/内联图构造（含裸 "<" 与裸 "!"——它们是 <cite / ![ 的前缀，不扣会在
    下一帧整体删除时造成前缀回退）。
    """
    if not cumulative:
        return cumulative

    # Markdown is not a citation protocol.  Normalizing or holding ordinary
    # ``[...](...)`` links here made them look like mutable citations and stalled
    # the relay at the first '['.  Only the four encodings above are stripped, and
    # only outside code spans.
    def strip_complete(prose: str) -> str:
        for rgx in _M365_CITE_COMPLETE_RES:
            prose = rgx.sub("", prose)
        return prose

    text = _m365_sub_outside_code(cumulative, strip_complete)
    code_intervals = _m365_code_intervals(cumulative)
    tail_is_code = bool(code_intervals and code_intervals[-1][1] == len(cumulative))
    if final:
        return _m365_sub_outside_code(
            text, lambda prose: _M365_CITE_FINAL_UNCLOSED_RE.sub("", prose)
        )
    if tail_is_code:
        return text
    # 扣住文末半个引用/内联图构造（单条正则的最左匹配即扣留点）；普通 Markdown
    # 链接 […](…)、方括号、圆括号等字符从不参与扣留（见 tests/ 的逐字符回归）。
    match = _M365_CITE_TAIL_RE.search(text)
    return text[: match.start()] if match is not None else text


def _m365_done_is_authoritative(message: dict) -> bool:
    """Return whether an extension terminal event is backed by Hub completion.

    Weak page signals such as ``isLastUpdate`` and ``ReferencesListComplete``
    are intentionally excluded. Updated extensions should send one of the
    accepted markers only after observing SignalR type=3, or a type=2 item with
    ``turnState=Completed``.
    """
    signal = (
        str(
            message.get("completionSignal")
            or message.get("terminalSignal")
            or message.get("doneReason")
            or ""
        )
        .strip()
        .lower()
    )
    if signal in {
        "signalr_completion",
        "signalr-type-3",
        "type3",
        "hub_completion",
        "turn_completed",
        "type2_completed",
        "type2-completed",
    }:
        return True
    return bool(message.get("authoritative") is True)


class M365BrowserRuntime:
    """Bridge server for M365 ASK/DELTA/DONE/ERROR and passive chat snapshots.

    Python owns conversation selection and persistence; the extension owns the
    browser page, token refresh, frame routing, and page-world Chathub socket.
    """

    def __init__(self):
        self._thread: Optional[threading.Thread] = None
        self._loop: Optional[asyncio.AbstractEventLoop] = None
        self._serve_task: Optional[asyncio.Task] = None
        self._async_shutdown: Optional[asyncio.Event] = None
        self._start_lock = threading.Lock()
        self._ext_ws: Any = None
        self._pending: dict[str, queue.Queue] = {}
        self._pending_lock = threading.Lock()
        self._active_lock = threading.Lock()
        self._active_futures: set = set()
        self._shutdown = threading.Event()
        self._shutdown_lock = threading.Lock()
        self._stopped = threading.Event()
        self._server_started = threading.Event()
        self._ready = threading.Event()
        self._server_error = ""

    def _run_loop(self):
        loop = asyncio.new_event_loop()
        self._loop = loop
        self._ready.set()
        asyncio.set_event_loop(loop)
        self._async_shutdown = asyncio.Event()
        self._serve_task = loop.create_task(self._serve())

        def _serve_done(task):
            if task.cancelled():
                return
            try:
                error = task.exception()
            except asyncio.CancelledError:
                return
            if error is not None:
                self._server_error = str(error)
                _m365_log.exception(
                    "M365 bridge server failed",
                    exc_info=(type(error), error, error.__traceback__),
                )
            self._server_started.set()
            if loop.is_running():
                loop.stop()

        self._serve_task.add_done_callback(_serve_done)
        try:
            loop.run_forever()
        finally:
            task = self._serve_task
            if task is not None and not task.done():
                task.cancel("M365 bridge loop is stopping")
                try:
                    loop.run_until_complete(asyncio.wait({task}, timeout=1.0))
                except Exception:
                    _m365_log.warning(
                        "M365 serve task bounded drain failed", exc_info=True
                    )
            pending = {task for task in asyncio.all_tasks(loop) if not task.done()}
            for pending_task in pending:
                pending_task.cancel("M365 bridge loop is closing")
            if pending:
                try:
                    _done, still_pending = loop.run_until_complete(
                        asyncio.wait(pending, timeout=1.0)
                    )
                    if still_pending:
                        _m365_log.warning(
                            "Detaching %d non-cooperative M365 task(s)",
                            len(still_pending),
                        )
                except Exception:
                    _m365_log.warning("M365 pending-task drain failed", exc_info=True)
            self._serve_task = None
            self._async_shutdown = None
            self._loop = None
            self._ready.clear()
            loop.close()
            self._stopped.set()

    def _ensure_loop(self):
        with self._start_lock:
            if not (self._thread and self._thread.is_alive()):
                self._shutdown.clear()
                self._stopped.clear()
                self._server_started.clear()
                self._ready.clear()
                self._server_error = ""
                self._thread = threading.Thread(
                    target=self._run_loop, name="voice-edge-m365", daemon=True
                )
                self._thread.start()
        if not self._ready.wait(timeout=3.0):
            raise RuntimeError("M365 bridge event loop did not become ready")

    def start(self, timeout: float = 5.0) -> None:
        """Start the local WebSocket bridge during service initialization."""
        global M365_ENTRY_URL
        _validate_sharepoint_settings()
        M365_ENTRY_URL = _validate_m365_entry_url(M365_ENTRY_URL)
        self._ensure_loop()
        if not self._server_started.wait(timeout=max(0.1, float(timeout))):
            raise RuntimeError(
                "M365 bridge did not start within "
                f"{timeout:.1f}s on ws://{M365_BRIDGE_HOST}:{M365_BRIDGE_PORT}/ws"
            )
        if self._server_error:
            raise RuntimeError(
                "M365 bridge failed to start on "
                f"ws://{M365_BRIDGE_HOST}:{M365_BRIDGE_PORT}/ws: "
                f"{self._server_error}"
            )
        if not self._thread or not self._thread.is_alive():
            raise RuntimeError("M365 bridge thread exited during startup")

    async def _serve(self):
        try:
            from aiohttp import WSMsgType, web
        except ImportError:
            _m365_log.error("M365 bridge requires aiohttp")
            self._server_started.set()
            return

        async def ws_handler(request):
            ws: Any = web.WebSocketResponse(
                heartbeat=30, max_msg_size=M365_BRIDGE_MAX_MSG_SIZE
            )
            await ws.prepare(request)
            self._ext_ws = ws
            _m365_log.info("M365 extension connected to bridge")
            await ws.send_str(
                json.dumps(
                    {
                        "type": "M365_CONFIG",
                        "entryUrl": M365_ENTRY_URL,
                        "sharePointHomeUrl": SHAREPOINT_HOME_URL,
                        "sharePointUploadFolder": SHAREPOINT_UPLOAD_FOLDER,
                        "sharePointDownloadFolder": SHAREPOINT_DOWNLOAD_FOLDER,
                        # Propagate backend verbose tracing so VE_M365_LOG_DEBUG=1 lights
                        # up the extension's dlog end-to-end.
                        "debug": VE_M365_LOG_DEBUG,
                    },
                    ensure_ascii=False,
                )
            )
            try:
                async for msg in ws:
                    if msg.type == WSMsgType.TEXT:
                        try:
                            self._on_ext_message(json.loads(msg.data))
                        except Exception:
                            _m365_log.exception("bad M365 extension message")
                    elif msg.type == WSMsgType.ERROR:
                        break
            finally:
                if self._ext_ws is ws:
                    self._ext_ws = None
                _m365_log.info("M365 extension disconnected")
            return ws

        app = web.Application()
        app.router.add_get("/ws", ws_handler)
        runner = web.AppRunner(app, shutdown_timeout=0.5)
        site = None
        try:
            await runner.setup()
            site = web.TCPSite(runner, M365_BRIDGE_HOST, M365_BRIDGE_PORT)
            await site.start()
            self._server_started.set()
            _m365_log.info(
                "M365 bridge: extension WS ws://%s:%d/ws",
                M365_BRIDGE_HOST,
                M365_BRIDGE_PORT,
            )
            shutdown = self._async_shutdown
            if shutdown is None:
                raise RuntimeError("M365 async shutdown event was not initialized")
            await shutdown.wait()
        finally:
            # Stop accepting first, then explicitly close the persistent
            # extension WebSocket. aiohttp runner.cleanup() otherwise waits for
            # ws_handler's async-for loop and can keep this thread alive.
            if site is not None:
                try:
                    await asyncio.wait_for(site.stop(), timeout=0.5)
                except Exception:
                    _m365_log.warning("M365 bridge site stop failed", exc_info=True)
            ws = self._ext_ws
            if ws is not None and not ws.closed:
                try:
                    await asyncio.wait_for(
                        ws.close(code=1001, message=b"server shutdown"), timeout=1.0
                    )
                except Exception:
                    _m365_log.warning(
                        "M365 extension WebSocket close failed", exc_info=True
                    )
            self._ext_ws = None
            try:
                await asyncio.wait_for(runner.cleanup(), timeout=1.5)
            except asyncio.TimeoutError:
                _m365_log.warning("M365 aiohttp runner cleanup timed out")
            except Exception:
                _m365_log.warning("M365 aiohttp runner cleanup failed", exc_info=True)

    def _on_ext_message(self, msg: dict) -> None:
        mtype = str(msg.get("type") or "")
        rid = str(msg.get("id") or "")
        if mtype == "M365_READY":
            # M365_READY has two distinct sources that previously shared one
            # misleading log line. The extension sends a bare M365_READY the
            # moment its background page connects to this bridge WebSocket (on
            # extension (re)load, before any M365 tab exists) — a transport
            # handshake, NOT a page hook. It sends a second M365_READY carrying
            # frameOrigin/frameUrl only when a content-script page hook actually
            # becomes ready in an M365 tab. Distinguish them by the presence of
            # frameUrl so "loaded the extension" is no longer reported as
            # "page hook ready", and so a real hook shows which origin it came
            # from (useful when diagnosing duplicate/stale frames).
            frame_url = str(msg.get("frameUrl") or "")
            frame_origin = str(msg.get("frameOrigin") or "")
            if frame_url or frame_origin:
                _m365_log.info(
                    "M365 page hook ready (origin=%s)",
                    frame_origin or "unknown",
                )
            else:
                _m365_log.info("M365 bridge connected")
            return
        if mtype == "M365_CHATS_SNAPSHOT":
            raw_chats = msg.get("chats")
            chats: list = raw_chats if isinstance(raw_chats, list) else []
            _m365_ingest_chats_snapshot(chats)
            return
        with self._pending_lock:
            out = self._pending.get(rid)
            known = set(self._pending.keys())
        if out is not None:
            try:
                out.put_nowait(msg)
            except queue.Full:
                _m365_log.warning("M365 relay full; dropping id=%s type=%s", rid, mtype)
        else:
            # [inbound trace] An answer-bearing frame arrived from the extension
            # but there is NO pending relay queue for its request id, so it is
            # dropped here. This is the definitive signature of an id-routing
            # failure (failure mode "b"): the browser produced output but Python
            # cannot attribute it to a live request. Distinguishes "wrong/unknown
            # id" from "request already finished" so a routing bug is not
            # mistaken for a normal late frame. Observation-only; gated.
            _m365_log.debug(
                "[relay-inbound-drop] no pending queue for id=%s type=%s "
                "text_len=%s known_ids=%s",
                rid or "<empty>",
                mtype or "<empty>",
                len(str(msg.get("text") or "")) if "text" in msg else "n/a",
                sorted(known) if known else "[]",
            )

    async def _send_to_ext(self, obj: dict) -> None:
        ws = self._ext_ws
        if ws is None:
            raise RuntimeError("M365 extension not connected (open the Copilot tab)")
        await ws.send_str(json.dumps(obj, ensure_ascii=False))

    async def _safe_send_to_ext(self, obj: dict) -> None:
        """Best-effort send that never raises.

        Used for the fire-and-forget M365_STOP abort, which runs while a request
        is being torn down (client disconnect / cancellation): a failed or racing
        send there must never surface as an unhandled task exception.
        """
        try:
            await self._send_to_ext(obj)
        except Exception:
            _m365_log.debug(
                "M365 best-effort send failed type=%s id=%s",
                obj.get("type"),
                obj.get("id"),
                exc_info=True,
            )

    def _schedule_ext_stop(self, rid: str, reason: str = "client-abort") -> None:
        """Fire-and-forget: ask the extension to abort the in-flight browser turn.

        When an OpenAI client (e.g. Continue) interrupts a request, the SSE
        consumer's finally sets consumer_stopped and cancels the driver, but
        nothing tells the browser to stop generating. The extension then keeps
        streaming frames for a request id whose relay queue has already been
        removed (surfaced as [relay-inbound-drop] no pending queue for id=...)
        and, worse, the browser silently completes a turn the user never saw — so
        the NEXT message is out of sync with the model. Emitting an M365_STOP lets
        the extension cancel that turn's Chathub/SignalR generation so the browser
        conversation reflects the interruption.

        Safe to call from any thread and from the driver's finally (including while
        the driver task itself is being cancelled): it only schedules work on the
        bridge loop and never awaits, so cancellation of the caller cannot abort
        the send.
        """
        if not rid:
            return
        loop = self._loop
        if loop is None or not loop.is_running():
            return

        def _dispatch() -> None:
            ws = self._ext_ws
            if ws is None or getattr(ws, "closed", True):
                _m365_log.warning(
                    "M365_STOP not sent because extension websocket is unavailable: id=%s reason=%s",
                    rid,
                    reason,
                )
                return
            self._track(
                loop.create_task(
                    self._safe_send_to_ext(
                        {"type": "M365_STOP", "id": rid, "reason": reason}
                    )
                )
            )

        try:
            loop.call_soon_threadsafe(_dispatch)
        except RuntimeError:
            # The loop stopped between the is_running() check and scheduling.
            pass

    def _track(self, future):
        with self._active_lock:
            self._active_futures.add(future)

        def _done(f):
            with self._active_lock:
                self._active_futures.discard(f)

        future.add_done_callback(_done)
        return future

    def submit_chat_stream(
        self,
        prompt: str,
        conversation_id: str = "",
        tone: str = "",
        attachments: Optional[list[dict]] = None,
        agent_config: Optional[dict] = None,
    ):
        if self._shutdown.is_set() or SERVER_SHUTTING_DOWN.is_set():
            raise RuntimeError("M365 bridge is shutting down")
        self._ensure_loop()
        relay_queue: "queue.Queue" = queue.Queue(maxsize=2048)
        output_queue: "queue.Queue" = queue.Queue(maxsize=2048)
        consumer_stopped = threading.Event()
        output_overflowed = threading.Event()

        def emit(item: dict, *, terminal: bool = False) -> bool:
            if consumer_stopped.is_set():
                return False
            try:
                output_queue.put_nowait(item)
                return True
            except queue.Full:
                output_overflowed.set()
                consumer_stopped.set()
                if terminal:
                    try:
                        output_queue.get_nowait()
                        output_queue.put_nowait(item)
                    except queue.Empty:
                        pass
                return False

        rid = "ve-" + uuid.uuid4().hex
        with self._pending_lock:
            self._pending[rid] = relay_queue

        async def driver():
            # Tracks whether the browser reached its OWN terminal for this turn
            # (an authoritative or weak M365_DONE, or an M365_ERROR). When this is
            # still False in the finally below, the turn ended abnormally (client
            # disconnect, first-event/idle timeout, shutdown, or an internal
            # error) and the extension is told to abort the in-flight browser
            # generation. Initialized before the try so the finally can always
            # read it even if the very first M365_ASK send raises.
            browser_terminated = False
            try:
                outbound_attachments = list(attachments or [])
                _m365_attachment_debug(
                    "ask-outbound",
                    request_id=rid,
                    attachment_count=len(outbound_attachments),
                    attachments=[
                        {
                            "name": item.get("name"),
                            "size": item.get("size"),
                            "mimeType": item.get("mimeType"),
                            "base64_chars": len(str(item.get("data") or "")),
                            "decoded_sha256": hashlib.sha256(
                                base64.b64decode(
                                    str(item.get("data") or ""), validate=True
                                )
                            ).hexdigest(),
                        }
                        for item in outbound_attachments
                    ],
                )
                request_idle_seconds = _m365_request_idle_seconds(outbound_attachments)
                await self._send_to_ext(
                    {
                        "type": "M365_ASK",
                        "id": rid,
                        "text": prompt,
                        "tone": tone,
                        "agentConfig": dict(agent_config or {}),
                        "conversationId": conversation_id or "",
                        "entryUrl": M365_ENTRY_URL,
                        "attachments": outbound_attachments,
                        "idleTimeoutMs": round(request_idle_seconds * 1000),
                    }
                )
                best = ""
                best_reasoning = ""
                got_any = False
                # 带外尾块 appendText 只应下发一次（先弱后强可能收到两次 DONE）。
                append_emitted = False
                pending_done: Optional[dict] = None
                pending_done_deadline = 0.0
                first_deadline = time.monotonic() + M365_FIRST_EVENT_TIMEOUT
                idle_deadline = time.monotonic() + request_idle_seconds
                loop = asyncio.get_running_loop()
                # [producer trace] running total of answer characters actually
                # handed to Continue via emit({"type":"delta"}). By construction
                # this must equal len(best) at the end; a mismatch means a delta
                # was computed but its emit() was refused (queue closed/full).
                trace_emitted_chars = 0
                trace_emitted_frames = 0
                # [inbound trace] how many frames this driver actually pulled
                # from its relay_queue (i.e. frames the bridge attributed to THIS
                # request id). inbound==0 means the extension sent nothing to this
                # request (problem is browser/dispatch/socket or id-routing);
                # inbound>0 with emitted==0 means frames arrived but none were
                # answer deltas (all progress, or a non-prefix stall).
                trace_inbound_msgs = 0
                trace_inbound_types: dict = {}
                request_started_at = time.monotonic()
                last_liveness_at = request_started_at
                last_inbound_type = "request-start"
                last_liveness_source = "request-start"
                progress_frames = 0
                code_keepalive_frames = 0
                code_execution_active = False
                code_execution_hard_deadline: Optional[float] = None
                reasoning_frames = 0
                delta_frames = 0

                def _log_producer_summary(signal: str) -> None:
                    if not VE_M365_LOG_RELAY_TRACE:
                        return
                    # best == sum(emitted deltas) proves the relay itself is
                    # lossless; if they differ, loss is INSIDE Python (a delta
                    # was computed but emit() was refused). inbound_* shows
                    # whether the extension delivered anything at all for this id.
                    # The digest lets you diff this exact text against the
                    # consumer-side digest and against what Continue rendered.
                    _m365_log.debug(
                        "[relay-producer] id=%s signal=%s inbound_msgs=%d "
                        "inbound_types=%s best=%d emitted_chars=%d "
                        "emitted_frames=%d lossless_internal=%s best_digest=%s",
                        rid,
                        signal,
                        trace_inbound_msgs,
                        trace_inbound_types,
                        len(best),
                        trace_emitted_chars,
                        trace_emitted_frames,
                        len(best) == trace_emitted_chars,
                        _m365_trace_digest(best),
                    )

                while True:
                    if consumer_stopped.is_set():
                        return
                    if self._shutdown.is_set():
                        _log_producer_summary("shutdown")
                        emit({"type": "error", "message": "shutting down"})
                        return
                    try:
                        msg = await loop.run_in_executor(
                            None, lambda: relay_queue.get(True, 0.5)
                        )
                    except queue.Empty:
                        now = time.monotonic()
                        if pending_done is not None and now >= pending_done_deadline:
                            cid = (
                                str(pending_done.get("conversationId") or "")
                                or conversation_id
                            )
                            _log_producer_summary("weak-terminal-drain")
                            # OBSERVATION-ONLY (see the authoritative-terminal branch
                            # for the full rationale): same artifact/appendText
                            # classification for turns that finish via the WEAK
                            # terminal drain instead of an authoritative type-3 DONE
                            # (the "waited a long time for the download link, then the
                            # turn ended" case). appendText on this pending weak DONE
                            # was already consumed at the M365_DONE branch, so
                            # append_emitted tells whether the link tail went out this
                            # turn; artifact_count is what the extension detected.
                            try:
                                _artifact_count = int(
                                    pending_done.get("artifactCount") or 0
                                )
                            except (TypeError, ValueError):
                                _artifact_count = -1
                            # artScan summary from the weak DONE payload (same
                            # routing as the authoritative branch), so this path
                            # also surfaces the plugin counters in the PYTHON log.
                            _asum = pending_done.get("artScanSummary")
                            if not isinstance(_asum, dict):
                                _asum = {}
                            _m365_log.debug(
                                "[relay-artifact] id=%s signal=weak-terminal-drain "
                                "artifact_count=%s pending_append_len=%d "
                                "append_emitted=%s best_len=%d artscan_frames=%s "
                                "strict_urls=%s loose_asyncgw=%s loose_objects=%s "
                                "missed=%s",
                                rid,
                                _artifact_count,
                                len(str(pending_done.get("appendText") or "")),
                                append_emitted,
                                len(best),
                                _asum.get("frames", "?"),
                                _asum.get("strictUrls", "?"),
                                _asum.get("looseAsyncgw", "?"),
                                _asum.get("looseObjects", "?"),
                                _asum.get("missed", "?"),
                            )
                            _asnips = _asum.get("missedSnippets")
                            if isinstance(_asnips, list) and _asnips:
                                _m365_log.debug(
                                    "[relay-artifact] id=%s signal="
                                    "weak-terminal-drain missed_snippets=%s",
                                    rid,
                                    _asnips[:6],
                                )
                            browser_terminated = True
                            emit(
                                {"type": "done", "conversation_id": cid},
                                terminal=True,
                            )
                            return
                        if not got_any and now > first_deadline:
                            # inbound_msgs=0 here means the extension delivered
                            # nothing for this id (browser/dispatch/socket or
                            # id-routing); inbound>0 means frames arrived but none
                            # were answer content before the deadline.
                            _log_producer_summary("first-event-timeout")
                            emit(
                                {"type": "error", "message": "M365 first-event timeout"}
                            )
                            return
                        if now > idle_deadline:
                            # A confirmed Code Interpreter turn gets its own
                            # absolute ceiling. This prevents the ordinary idle
                            # watchdog from aborting a silent sandbox run, while
                            # still bounding a lost terminal event.
                            if (
                                code_execution_active
                                and code_execution_hard_deadline is not None
                                and now < code_execution_hard_deadline
                            ):
                                idle_deadline = min(
                                    now + request_idle_seconds,
                                    code_execution_hard_deadline,
                                )
                                # Keep the downstream SSE consumer alive too;
                                # otherwise its own idle watchdog can tear down
                                # the request while this producer is deliberately
                                # extending the silent Code Interpreter phase.
                                try:
                                    output_queue.put_nowait({"type": "keepalive"})
                                except queue.Full:
                                    pass
                                continue
                            idle_for = max(0.0, now - last_liveness_at)
                            elapsed = max(0.0, now - request_started_at)
                            deadline_overrun = max(0.0, now - idle_deadline)
                            _m365_log.warning(
                                "M365 idle timeout id=%s elapsed=%.1fs idle_for=%.1fs "
                                "budget=%.1fs deadline_overrun=%.1fs last_inbound=%s "
                                "last_liveness=%s inbound_msgs=%d progress=%d "
                                "code_keepalive=%d reasoning=%d delta=%d "
                                "attachments=%d attachment_bytes=%d queue_size=%d",
                                rid,
                                elapsed,
                                idle_for,
                                request_idle_seconds,
                                deadline_overrun,
                                last_inbound_type,
                                last_liveness_source,
                                trace_inbound_msgs,
                                progress_frames,
                                code_keepalive_frames,
                                reasoning_frames,
                                delta_frames,
                                len(outbound_attachments),
                                sum(
                                    max(0, int(item.get("size") or 0))
                                    for item in outbound_attachments
                                ),
                                relay_queue.qsize(),
                            )
                            _log_producer_summary("idle-timeout")
                            emit({"type": "error", "message": "M365 idle timeout"})
                            return
                        continue
                    mtype = str(msg.get("type") or "")
                    last_inbound_type = mtype or "<empty>"
                    if VE_M365_LOG_RELAY_TRACE:
                        trace_inbound_msgs += 1
                        _tk = _m365_trace_inbound_key(mtype, msg)
                        trace_inbound_types[_tk] = trace_inbound_types.get(_tk, 0) + 1
                    discriminator = (
                        str(
                            msg.get("channel")
                            or msg.get("phase")
                            or msg.get("kind")
                            or ""
                        )
                        .strip()
                        .lower()
                    )
                    is_reasoning = mtype == "M365_REASONING" or (
                        mtype == "M365_DELTA"
                        and discriminator
                        in {"analysis", "reasoning", "thinking", "thought"}
                    )
                    if mtype == "M365_PROGRESS":
                        # Progress is a typed M365 protocol event, not answer
                        # content. It refreshes liveness but never changes the
                        # append-only text already delivered to Continue.
                        progress_frames += 1
                        if msg.get("codeExecuting") is True:
                            code_keepalive_frames += 1
                            if not code_execution_active:
                                code_execution_active = True
                                code_execution_hard_deadline = (
                                    time.monotonic() + M365_CODE_EXECUTION_MAX_SECONDS
                                )
                            last_liveness_source = "M365_PROGRESS(code-executing)"
                        else:
                            content_type = str(msg.get("contentType") or "").strip()
                            last_liveness_source = (
                                "M365_PROGRESS(" + content_type + ")"
                                if content_type
                                else "M365_PROGRESS"
                            )
                        last_liveness_at = time.monotonic()
                        got_any = True
                        idle_deadline = last_liveness_at + request_idle_seconds
                        # Forward a liveness ping to the SSE consumer. A reasoning
                        # model can stream progress-only for a long "thinking"
                        # period before the first answer delta.
                        # Without a ping the consumer only refreshes its
                        # deadline on delta/reasoning, so its 60s first-event
                        # deadline fires first, the request is torn down, and the
                        # late answer is dropped as "no pending queue". A dropped
                        # keepalive is harmless, so this must never set the
                        # overflow flag or stop the consumer.
                        if not consumer_stopped.is_set():
                            try:
                                output_queue.put_nowait({"type": "keepalive"})
                            except queue.Full:
                                pass
                    elif mtype == "M365_DELTA" and not is_reasoning:
                        delta_frames += 1
                        # Visible answer output ends the silent sandbox phase;
                        # restore the normal per-request idle policy.
                        code_execution_active = False
                        code_execution_hard_deadline = None
                        last_liveness_at = time.monotonic()
                        last_liveness_source = "M365_DELTA"
                        got_any = True
                        # 归一化三种引用编码（<cite>/\ue200…\ue201/【N-xxx】），流式安全、
                        # 保持前缀单调（详见 _m365_strip_cite）。
                        text = _m365_strip_cite(
                            str(msg.get("text") or msg.get("content") or "")
                        )
                        if len(text) > len(best) and text.startswith(best):
                            _delta = text[len(best) :]
                            if not emit({"type": "delta", "content": _delta}):
                                return
                            best = text
                            if VE_M365_LOG_RELAY_TRACE:
                                trace_emitted_chars += len(_delta)
                                trace_emitted_frames += 1
                            idle_deadline = time.monotonic() + request_idle_seconds
                        elif text and text != best:
                            # A non-prefix cumulative snapshot means the upstream
                            # (content-m365.js) let a provisional writeAtCursor
                            # fragment diverge from the authoritative snapshot
                            # stream. We cannot append it without corrupting the
                            # already-delivered text, so it is dropped here — but
                            # this is a real content-loss signal and must never be
                            # silent, otherwise the "reply keeps losing text" bug
                            # is invisible in production.
                            _m365_log.warning(
                                "Dropping non-prefix M365 cumulative delta "
                                "(possible text loss): current=%d incoming=%d "
                                "source=%s id=%s",
                                len(best),
                                len(text),
                                str(msg.get("deltaSource") or "unknown"),
                                rid,
                            )
                    elif is_reasoning:
                        reasoning_frames += 1
                        last_liveness_at = time.monotonic()
                        last_liveness_source = "M365_REASONING"
                        got_any = True
                        text = str(
                            msg.get("reasoning")
                            or msg.get("text")
                            or msg.get("content")
                            or ""
                        )
                        if len(text) > len(best_reasoning) and text.startswith(
                            best_reasoning
                        ):
                            if not emit(
                                {
                                    "type": "reasoning",
                                    "content": text[len(best_reasoning) :],
                                }
                            ):
                                return
                            best_reasoning = text
                            idle_deadline = time.monotonic() + request_idle_seconds
                        elif text and text != best_reasoning:
                            # A non-prefix cumulative reasoning snapshot means the
                            # upstream CoT accumulator (content-m365's cotTotal())
                            # was not strictly append-only this turn. Slicing
                            # text[len(best_reasoning):] off a non-prefix snapshot
                            # would splice a misaligned fragment into the reasoning
                            # stream Continue renders. Mirror the answer path: drop
                            # it rather than corrupt the delivered reasoning, and
                            # never silently, so a real regression stays visible.
                            # This never touches the answer (best) channel.
                            _m365_log.warning(
                                "Dropping non-prefix M365 reasoning delta "
                                "(possible reasoning loss): current=%d incoming=%d "
                                "id=%s",
                                len(best_reasoning),
                                len(text),
                                rid,
                            )
                    elif mtype == "M365_DONE":
                        # 归一化引用编码 + 剥宿主图（详见 _m365_strip_cite）。终态帧用
                        # final=True：只删完整跨度、不扣在途尾巴，杜绝终态永久丢字。
                        text = _m365_strip_cite(str(msg.get("text") or ""), final=True)
                        if len(text) > len(best) and text.startswith(best):
                            _delta = text[len(best) :]
                            if not emit({"type": "delta", "content": _delta}):
                                return
                            best = text
                            if VE_M365_LOG_RELAY_TRACE:
                                trace_emitted_chars += len(_delta)
                                trace_emitted_frames += 1
                        elif text and text != best:
                            # Terminal authoritative snapshot diverged from what
                            # was already streamed to Continue. Surfacing this is
                            # essential: it is the last chance to notice that the
                            # final answer text was truncated or rewritten.
                            # 诊断安全网：打印首个分歧位置附近的 repr（两侧各 ~40 字），
                            # 若仍分歧即可从日志直接看清是何种编码/改写（repr 会显出
                            # \ue200 等私有区字符），无需再抓 WSS 帧盲猜。
                            _div = next(
                                (
                                    k
                                    for k in range(min(len(best), len(text)))
                                    if best[k] != text[k]
                                ),
                                min(len(best), len(text)),
                            )
                            _m365_log.debug(
                                "Dropping non-prefix M365 terminal snapshot "
                                "(possible tail loss): current=%d incoming=%d "
                                "id=%s diverge@=%d cur=%r inc=%r",
                                len(best),
                                len(text),
                                rid,
                                _div,
                                best[max(0, _div - 40) : _div + 40],
                                text[max(0, _div - 40) : _div + 40],
                            )
                        # 带外尾块：SharePoint 链接 / 内联图片 data-URI。扩展把它
                        # 单独放在 appendText（不拼进 DONE.text），正是为了在 DONE.text
                        # 与已流出正文不一致、被上面按 non-prefix 丢弃时，这段尾巴仍能
                        # 作为一条 final delta 补发。缺了这段，链接/内联图片会被静默丢掉，
                        # 正文就停在 “给你文件：[”。append_emitted 保证先弱后强两次 DONE
                        # 不会重复下发；弱终态 drain 路径只发 done 不带文本，也不会重复。
                        # appendText 走带外 done.appendText 专用字段，从不拼进
                        # done.text，故 best 正常不含它；append_emitted 已保证弱/强两次
                        # DONE 只下发一次。下载链接重复的真正来源是 appendText 内部就有
                        # 两条相同链接（同一产物被 harvest 两次 → 两个 descriptor），已在
                        # 扩展侧 background.js 按内容指纹去重根治。这里不得再按 best 尾部做
                        # overlap 削减：那既解决不了内部重复，又会在正文以换行结尾、
                        # appendText 以 \n\n 开头时吃掉分隔空行（详见 _merge_doubao_text
                        # 的原则：禁止任意 suffix/prefix overlap 移除）。
                        append_text = str(msg.get("appendText") or "")
                        if append_text and not append_emitted:
                            if not emit({"type": "delta", "content": append_text}):
                                return
                            append_emitted = True
                            best += append_text
                            if VE_M365_LOG_RELAY_TRACE:
                                trace_emitted_chars += len(append_text)
                                trace_emitted_frames += 1
                        if _m365_done_is_authoritative(msg):
                            cid = (
                                str(msg.get("conversationId") or "") or conversation_id
                            )
                            _log_producer_summary("authoritative-terminal")
                            # OBSERVATION-ONLY (zero behavior change): classify why a
                            # download/artifact link did or did not reach the client
                            # THIS turn. The out-of-band tail (SharePoint links /
                            # inline-image data-URIs) only arrives via appendText, and
                            # whether it is present is decided upstream (extension
                            # harvest + background hold), not here. Two extension-set
                            # fields survive onto this authoritative DONE:
                            #   * artifactCount — how many asyncgw/objects artifact
                            #     URLs content-m365.js DETECTED in this turn's frames.
                            #   * appendText    — the finalized links/images background
                            #     produced after its bounded artifact-hold, or "".
                            # The three cases this line lets you tell apart next time
                            # the link goes missing (no more guessing timeout vs bug):
                            #   artifact_count>0 & append_len==0
                            #       -> artifacts WERE detected but the hold/upload did
                            #          not settle in time (the "卡超时/harvest 未完成"
                            #          case) — upstream timing, not a relay bug.
                            #   artifact_count==0 & append_len==0
                            #       -> the artifact URL never appeared in any frame this
                            #          turn (upstream M365 did not emit it) — nothing to
                            #          harvest; also not a relay bug.
                            #   append_len>0
                            #       -> link delivered normally (the success case).
                            # append_emitted distinguishes "this DONE carried the tail"
                            # from "a weak DONE already emitted it earlier this turn".
                            try:
                                _artifact_count = int(msg.get("artifactCount") or 0)
                            except (TypeError, ValueError):
                                _artifact_count = -1  # present but non-numeric
                            # artScan summary rides on the M365_DONE payload
                            # (extension → background → here) so the plugin's
                            # per-turn artifact-detection counters land in the
                            # PYTHON log — no page console needed. Absent/old
                            # extension -> {} -> the fields simply read as "?".
                            _asum = msg.get("artScanSummary")
                            if not isinstance(_asum, dict):
                                _asum = {}
                            _m365_log.debug(
                                "[relay-artifact] id=%s signal=authoritative-terminal "
                                "artifact_count=%s append_len=%d append_emitted=%s "
                                "best_len=%d artscan_frames=%s strict_urls=%s "
                                "loose_asyncgw=%s loose_objects=%s missed=%s",
                                rid,
                                _artifact_count,
                                len(append_text),
                                append_emitted,
                                len(best),
                                _asum.get("frames", "?"),
                                _asum.get("strictUrls", "?"),
                                _asum.get("looseAsyncgw", "?"),
                                _asum.get("looseObjects", "?"),
                                _asum.get("missed", "?"),
                            )
                            # When strict detection missed a frame that carried
                            # an AMS marker, log the bounded, redacted URL-shape
                            # snippets the plugin captured so a real regex/
                            # cleanAmsUrl gap is diagnosable from the PYTHON log
                            # alone. Only logged when non-empty (no noise on the
                            # common missed==0 turn).
                            _asnips = _asum.get("missedSnippets")
                            if isinstance(_asnips, list) and _asnips:
                                _m365_log.debug(
                                    "[relay-artifact] id=%s signal="
                                    "authoritative-terminal missed_snippets=%s",
                                    rid,
                                    _asnips[:6],
                                )
                            browser_terminated = True
                            emit(
                                {"type": "done", "conversation_id": cid},
                                terminal=True,
                            )
                            return
                        pending_done = dict(msg)
                        pending_done_deadline = (
                            time.monotonic() + M365_TERMINAL_DRAIN_SECONDS
                        )
                        idle_deadline = max(idle_deadline, pending_done_deadline)
                        _m365_log.debug(
                            "Draining weak M365 terminal signal for %.1fs id=%s",
                            M365_TERMINAL_DRAIN_SECONDS,
                            rid,
                        )
                    elif mtype == "M365_ERROR":
                        # The browser reported its own error and has already
                        # stopped this turn, so no abort signal is needed.
                        browser_terminated = True
                        _log_producer_summary("extension-error")
                        emit(
                            {
                                "type": "error",
                                "message": str(msg.get("error") or "M365 error"),
                            }
                        )
                        return
            except Exception as exc:  # pragma: no cover
                emit({"type": "error", "message": str(exc)}, terminal=True)
            finally:
                with self._pending_lock:
                    self._pending.pop(rid, None)
                # The turn ended without the browser reaching its own terminal
                # (client disconnect, first-event/idle timeout, shutdown, or an
                # internal error): ask the extension to abort the in-flight
                # generation for this id. Without this the browser keeps emitting
                # frames for an id whose relay queue is already gone (logged as
                # [relay-inbound-drop] no pending queue for id=...) and silently
                # finishes an answer the user never saw, desyncing the model from
                # the next message. Fire-and-forget, so it is safe even while this
                # driver task is being cancelled.
                if not browser_terminated:
                    self._schedule_ext_stop(rid, reason="aborted")

        loop = self._loop
        if loop is None:
            with self._pending_lock:
                self._pending.pop(rid, None)
            raise RuntimeError("M365 bridge loop not started")
        future = asyncio.run_coroutine_threadsafe(driver(), loop)
        return (
            self._track(future),
            output_queue,
            consumer_stopped,
            output_overflowed,
        )

    def request_shutdown(self) -> None:
        """Signal M365 closure without waiting; safe in the main quiesce phase."""
        with self._shutdown_lock:
            first_request = not self._shutdown.is_set()
            self._shutdown.set()
            if not first_request:
                return
            with self._active_lock:
                futures = list(self._active_futures)
            for future in futures:
                future.cancel()
            loop = self._loop
            shutdown = self._async_shutdown
            if loop is not None and loop.is_running():

                def signal_shutdown():
                    if shutdown is not None:
                        shutdown.set()
                    ws = self._ext_ws
                    if ws is not None and not ws.closed:
                        loop.create_task(
                            ws.close(code=1001, message=b"server shutdown")
                        )

                loop.call_soon_threadsafe(signal_shutdown)

    def begin_shutdown(self, timeout: float = 5.0) -> bool:
        """Request M365 closure and wait only for the caller's deadline."""
        self.request_shutdown()
        timeout = max(0.1, float(timeout))
        thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=timeout)
        stopped = thread is None or not thread.is_alive()
        if not stopped:
            _m365_log.error("M365 bridge thread did not exit within %.1fs", timeout)
        return stopped


M365_BROWSER_RUNTIME = M365BrowserRuntime()


def _m365_offload_large_tool_results(messages: list) -> tuple[list, list[dict]]:
    """Move oversized client tool results out of the inline prompt.

    A client tool result (the output of an MCP / IDE tool call such as a large
    read_file) is normally inlined verbatim into this turn's prompt via
    compose_turn_text -> build_tool_results_block, so its bytes count against
    M365 Copilot's context window. A couple of big results crowd out the user's
    actual request. When a result's flattened text exceeds
    M365_TOOL_RESULT_INLINE_MAX_BYTES it is OFFLOADED: the body becomes a text
    attachment (uploaded to SharePoint by the browser egress — the same FileUrl
    document-link path inline files use) and the tool message keeps only a short
    pointer telling Copilot to open that attachment for the full result.

    Returns (messages, attachments):
      * messages    — a shallow copy with ONLY the offloaded tool messages
                      rewritten (the caller's list and dicts are never mutated);
                      pass it to BOTH prepare() and _client_collect_attachments
                      so the pointer — not the body — is what gets composed.
      * attachments — kind=="file" attachment dicts (same shape as
                      _client_collect_attachments) for every offloaded result.

    Disabled (returns the input unchanged, empty attachments) when the threshold
    is 0. Results larger than M365_UPLOAD_MAX_BYTES cannot be uploaded, so they
    are left inline rather than silently dropped.
    """
    threshold = M365_TOOL_RESULT_INLINE_MAX_BYTES
    if threshold <= 0 or not messages:
        return messages, []

    # Only results AFTER the last user turn are this turn's pending continuation
    # (mirrors ClientTurn.from_openai); earlier tool messages are history the
    # browser already owns and prepare() discards, so offloading them would
    # upload attachments no prompt ever references.
    last_user_idx = -1
    for i in range(len(messages) - 1, -1, -1):
        m = messages[i]
        if isinstance(m, dict) and str(m.get("role") or "").strip().lower() == "user":
            last_user_idx = i
            break

    # call_id -> function name, so a bare tool message (name omitted) can still
    # be labeled in the pointer / attachment filename.
    name_by_call_id: dict = {}
    for m in messages:
        if (
            isinstance(m, dict)
            and str(m.get("role") or "").strip().lower() == "assistant"
        ):
            for tc in m.get("tool_calls") or []:
                if isinstance(tc, dict):
                    cid = str(tc.get("id") or "").strip()
                    _tcfn = tc.get("function")
                    fn = _tcfn if isinstance(_tcfn, dict) else {}
                    nm = str(fn.get("name") or "").strip()
                    if cid and nm:
                        name_by_call_id[cid] = nm

    out = list(messages)
    attachments: list[dict] = []
    offloaded = 0
    for i in range(last_user_idx + 1, len(out)):
        m = out[i]
        if not isinstance(m, dict):
            continue
        if str(m.get("role") or "").strip().lower() not in ("tool", "function"):
            continue
        body = _content_to_text(m.get("content")).strip()
        if not body:
            continue
        size = len(body.encode("utf-8"))
        if size <= threshold:
            continue
        if size > M365_UPLOAD_MAX_BYTES:
            # Too big for the upload egress; keep it inline rather than drop it.
            _m365_attachment_debug(
                "tool-result-offload-skip",
                reason="exceeds_upload_limit",
                size=size,
            )
            continue
        cid = str(m.get("tool_call_id") or "").strip()
        name = str(m.get("name") or name_by_call_id.get(cid) or "").strip()
        offloaded += 1
        stub_id = (cid or uuid.uuid4().hex)[:12]
        base = _client_safe_filename(
            f"tool-result-{name or 'tool'}-{stub_id}",
            f"tool-result-{offloaded}",
        )
        filename = f"{base}.txt"
        data = body.encode("utf-8")
        attachments.append(
            {
                "kind": "file",
                "name": filename,
                "mimeType": "text/plain; charset=utf-8",
                "size": len(data),
                "data": base64.b64encode(data).decode("ascii"),
            }
        )
        pointer = (
            "[The full result of this tool call "
            + (f"({name}) " if name else "")
            + f"was {size} bytes — over the inline limit — so it was uploaded as "
            + f'the attachment "{filename}". Open that attached file to read the '
            + "complete result.]"
        )
        # Never mutate the caller's dict; rewrite only the copy held in `out`.
        rewritten = dict(m)
        rewritten["content"] = pointer
        out[i] = rewritten

    if not offloaded:
        return messages, []
    _m365_attachment_debug(
        "tool-result-offload",
        offloaded=offloaded,
        threshold=threshold,
        names=[a["name"] for a in attachments],
    )
    return out, attachments


async def _direct_m365_chat_response(
    model_name: str, body: dict, messages: list, stream_mode: bool
):
    if not M365_ENTRY_URL:
        return JSONResponse(
            {
                "error": {
                    "message": "M365 backend is not configured; set M365_ENTRY_URL",
                    "type": "m365_not_configured",
                }
            },
            status_code=503,
        )
    # Seam #1: compose this turn via the unified relay. The relay now performs
    # the client-envelope handling for ALL browser models: prepare() detects the
    # client format and _client_extract_prompt unwraps <task> / strips inline
    # <file_content>/<environment_details>, so `prompt` is already clean here
    # (no more per-handler Cline parsing) and inline files are not duplicated
    # (once as prose, once as the SharePoint egress below). For m365
    # relay_prompt is True, so the client system message rides along as
    # <client_system_prompt> XML each turn; history is still stripped (Copilot
    # owns it). XiaoAI (source=='xiaoai') bypasses entirely (no prompt/tools).
    # supports_tools is True for the tool-capable m365 models,
    # so <tool_use_instructions> ARE injected and Seam #2 (below) is live;
    _m365_bypass = BrowserRelay.should_bypass(body)
    # Seam #3 (Harness bridge): when the model opted in via metadata and the
    # plugin endpoint is configured, bind this conversation to a Harness
    # session and — only while the per-model deepseek_harness_tools switch
    # (default False) is on — merge the agent-scoped Harness tool schemas
    # into the body the relay composes, so tool instructions AND the
    # transpiler's allowed_names cover them. With the switch off the bridge
    # still binds and mirrors, but injects nothing and owns no tool names.
    # Bind is content-free; the user-message mirror taps the FINAL prompt
    # below, after prepare(). Uses the ORIGINAL messages (the conversation
    # identity pre-dates the offload rewrite below).
    # Fail-open: a bridge outage leaves body/messages untouched and the turn
    # runs exactly as it did before the bridge existed.
    _harness: Optional[dict] = None
    if not _m365_bypass and _harness_enabled(model_name):
        _harness = await _harness_begin(
            model_name, body, messages, M365_BROWSER_MODEL_TONES[model_name]
        )
        if _harness is not None and _harness["openai_tools"]:
            body = {
                **body,
                "tools": [*(body.get("tools") or []), *_harness["openai_tools"]],
            }
    # Offload oversized client tool results (big MCP read_file outputs, etc.) to
    # SharePoint attachments BEFORE composing the prompt, so a couple of large
    # results don't crowd the user's request out of Copilot's context window.
    # Runs on the same `messages` prepare() and _client_collect_attachments read,
    # so the inline prompt carries only a pointer while the body rides the
    # attachment egress. Skipped for bypass (XiaoAI) passthrough, which has no
    # tool results.
    _offloaded_tool_attachments: list[dict] = []
    if not _m365_bypass:
        messages, _offloaded_tool_attachments = _m365_offload_large_tool_results(
            messages
        )
    _m365_prepared = BROWSER_RELAY.prepare(
        model_name, body, messages, bypass=_m365_bypass
    )
    prompt = _m365_prepared.text
    _m365_attachment_debug(
        "prompt",
        source=str(body.get("source") or "unknown"),
        client_kind=_m365_prepared.client_kind,
        chars=len(prompt),
    )
    # cline_mode comes from the UNIFIED relay decision (prepared.client_kind),
    # not a second, m365-local detection pass. No prompt-side instruction is
    # appended here: _cline_wrap_result already strips any model-generated
    # attempt_completion envelope before re-wrapping, so telling the model not
    # to emit one was redundant defense. The shared ClineEnvelope below applies
    # the attempt_completion framing the SAME way every browser family does.
    cline_mode = _m365_prepared.client_kind == "cline"
    _m365_env = ClineEnvelope(cline_mode)
    try:
        attachments = await _client_collect_attachments(messages)
    except Exception as exc:
        return JSONResponse(
            {"error": {"message": str(exc), "type": "m365_file_error"}},
            status_code=400,
        )
    # Snapshot the fresh user turn before offloaded tool-result attachments join
    # this list. Multimodal content is rebuilt from the original content slots,
    # so images remain between the same surrounding text instead of moving to
    # the end of the mirrored message.
    _mirror_user_content = _harness_ordered_user_content(
        _client_latest_user_message(messages), attachments
    )
    # Append the offloaded tool-result attachments (built above from oversized
    # MCP results) so they upload alongside the user's inline files and the
    # longer request-idle allowance below accounts for their bytes too.
    if _offloaded_tool_attachments:
        attachments = attachments + _offloaded_tool_attachments
    if not prompt and attachments:
        prompt = "Please analyze the attached content."
    if not prompt:
        return JSONResponse(
            {"error": f"No text or file provided for {model_name}"}, status_code=400
        )
    # Mirror the user turn NOW: `user_text` is the relay-extracted turn body —
    # the same text `prompt` carries between its transport framing (relayed
    # system prose, <tool_use_instructions> XML). Mirroring the body, not the
    # composed prompt, keeps the user bubble readable while staying
    # extractor-identical to what the model received. The user's inline images
    # ride the m365 attachment egress instead of the text, so they are
    # re-embedded here as markdown data URIs — the mirror records the user's
    # actual turn, the model keeps its native channel. Continuations mirror
    # nothing (stale text and already-mirrored images must not re-appear).
    if _harness is not None and _m365_prepared.fresh_user_turn:
        if _mirror_user_content:
            await _harness_user_message(_harness, model_name, _mirror_user_content)
    tone = M365_BROWSER_MODEL_TONES[model_name]
    m365_agent_config = dict(
        (BROWSER_MODEL_METADATA.get(model_name) or {}).get("m365_agent") or {}
    )
    request_idle_seconds = _m365_request_idle_seconds(attachments)
    # Whether Continue asked for reasoning to be surfaced. Mirrors the request
    # shape already parsed by the DeepSeek/chat_api paths. When enabled, the
    # progress-driven keepalives render one visible "思考中…" reasoning block;
    # when disabled they stay a silent SSE heartbeat (liveness only). Either way
    # the keepalive keeps the SSE deadline fresh through a long thinking period.
    _m365_thinking_config = body.get("thinking")
    reasoning_enabled = bool(
        body.get("enable_thinking")
        or body.get("reasoning_effort")
        or (
            isinstance(_m365_thinking_config, dict)
            and _m365_thinking_config.get("type") == "enabled"
        )
    )
    # DEBUG: surface exactly what the client (Continue) sent for reasoning so it
    # is unambiguous whether the empty thinking block is because Continue never
    # asked for reasoning at all. Logs the raw presence/value of every reasoning
    # flag we honor, the resolved decision, and the full set of top-level body
    # keys (values omitted; only key names, so no prompt/content is leaked).
    # Unconditional INFO so it shows without flipping VE_M365_LOG_DEBUG; remove or gate
    # once the Continue-side reasoning toggle is confirmed working.
    _m365_log.debug(
        "[reasoning-req] model=%s enable_thinking=%r reasoning_effort=%r "
        "thinking=%r resolved_reasoning_enabled=%s body_keys=%s",
        model_name,
        body.get("enable_thinking"),
        body.get("reasoning_effort"),
        _m365_thinking_config,
        reasoning_enabled,
        sorted(body.keys()) if isinstance(body, dict) else type(body).__name__,
    )
    explicit_new = bool(body.get("new_conversation", False))
    requested = str(body.get("conversation_id") or "").strip()
    full_key, boot_key = _m365_conversation_key(tone, messages)
    has_history = _m365_has_prior_assistant_turn(messages)
    if explicit_new:
        # Brand-new client chat: drop any identity this chat's head may map to
        # so it cannot inherit an old ConversationId.
        with _M365_HTTP_CONVERSATION_LOCK:
            for _k in (full_key, boot_key):
                if _k:
                    _M365_CONV_BY_KEY.pop(_k, None)
        conversation_id = ""
    elif requested:
        conversation_id = requested
    elif has_history:
        # Continuation of an existing client chat: reuse the ConversationId
        # bound to this identity earlier (memory, then persisted if enabled).
        conversation_id = _m365_resolve_conversation(full_key, boot_key)
    else:
        # First turn of a client chat: always start a NEW M365 conversation
        # rather than reuse the last-used per-model id — the core fix for the
        # cross-chat reuse bug.
        conversation_id = ""

    def _remember_conversation(cid: str) -> None:
        _m365_remember_conversation(cid, full_key, boot_key, tone, has_history)

    _m365_log.debug(
        "[conv-resolve] tone=%s full=%s boot=%s explicit_new=%s requested=%s "
        "has_history=%s resolved=%s",
        tone,
        full_key or "-",
        boot_key,
        explicit_new,
        bool(requested),
        has_history,
        (conversation_id[:16] + "…") if conversation_id else "<new>",
    )

    completion_id = f"chatcmpl-m365-{uuid.uuid4().hex}"
    created = int(time.time())

    _m365_attachment_debug(
        "dispatch",
        model=model_name,
        tone=tone,
        prompt_length=len(prompt),
        prompt_preview=prompt[:160],
        attachment_count=len(attachments),
        attachments=[
            {
                "name": x.get("name"),
                "size": x.get("size"),
                "mimeType": x.get("mimeType"),
            }
            for x in attachments
        ],
        conversation_reused=bool(conversation_id),
    )
    (
        future,
        event_queue,
        consumer_stopped,
        output_overflowed,
    ) = M365_BROWSER_RUNTIME.submit_chat_stream(
        prompt, conversation_id, tone, attachments, m365_agent_config
    )

    async def events():
        # Harness tool steps resubmit a follow-up prompt into the SAME M365
        # conversation, replacing the stream resources below; the single
        # consume loop then reads the new queue unchanged. nonlocal because the
        # names live on the enclosing handler (shared with the non-stream path).
        nonlocal future, event_queue, consumer_stopped, output_overflowed
        role_sent = False
        thinking_hint_sent = False
        # Seam #2 (tool interception). ACTIVE for supports_tools=True models:
        # new_transpiler() returns a transpiler, so the `_m365_tool_tp is not None`
        # guards below engage — the transpiler holds back a trailing ```tool```
        # block and surfaces it as OpenAI tool_calls at done. For supports_tools=
        # False models new_transpiler() returns None and every guard is skipped,
        # so that path is byte-identical to a plain chat turn. NOTE: when active
        # alongside cline_mode the Cline result envelope and the tool block
        # interact — the tool_call branch below intentionally emits NO envelope.
        _m365_tool_tp = _m365_prepared.new_transpiler()
        deadline = time.monotonic() + M365_FIRST_EVENT_TIMEOUT
        # Harness bridge per-turn state (all inert when _harness is None):
        # the actual M365 ConversationId for follow-up submits, the internal
        # tool-step counter, and the current step's visible text / reasoning
        # accumulators for the model-event mirror.
        _harness_step = 0
        _stream_cid = ""
        _step_text: list = []
        _step_reasoning: list = []

        async def _harness_mirror_step(
            finish_reason: str, calls: Optional[list] = None
        ) -> None:
            if _harness is None:
                return
            await _harness_mirror_event(
                _harness,
                kind="step",
                text="".join(_step_text),
                reasoning="".join(_step_reasoning),
                tool_calls=calls,
                finish_reason=finish_reason,
            )
            _step_text.clear()
            _step_reasoning.clear()

        async def _harness_close(status: str) -> None:
            if _harness is not None:
                await _harness_finish(_harness, status)

        # [consumer trace] running total of answer characters actually yielded
        # into the SSE response toward Continue. Compare against the producer's
        # emitted_chars/best_digest: if they match, every byte left Python intact
        # and any loss is strictly downstream (SSE transport or Continue's
        # renderer). If the consumer total is short, loss happened between the
        # relay queue and this generator (e.g. output_queue overflow).
        trace_yielded_chars = 0
        trace_yielded_frames = 0
        trace_yielded_text = []

        def _log_consumer_summary(signal: str) -> None:
            if not VE_M365_LOG_RELAY_TRACE:
                return
            joined = "".join(trace_yielded_text)
            _m365_log.debug(
                "[relay-consumer] id=%s signal=%s yielded_chars=%d "
                "yielded_frames=%d yielded_digest=%s",
                completion_id,
                signal,
                trace_yielded_chars,
                trace_yielded_frames,
                _m365_trace_digest(joined),
            )

        try:
            while True:
                try:
                    event = await asyncio.to_thread(event_queue.get, True, 1.0)
                except queue.Empty:
                    if future.done():
                        terminal_error = ""
                        try:
                            future.result()
                        except concurrent.futures.CancelledError:
                            terminal_error = "M365 request was cancelled"
                        except Exception as exc:
                            terminal_error = str(exc)
                        if output_overflowed.is_set():
                            terminal_error = (
                                "M365 output buffer overflowed because the client "
                                "consumed the stream too slowly"
                            )
                        if terminal_error:
                            yield _chat_sse_data(
                                {
                                    "error": {
                                        "message": terminal_error,
                                        "type": "m365_error",
                                    }
                                }
                            )
                        await _harness_mirror_step(
                            "error" if terminal_error else "stop"
                        )
                        await _harness_close("error" if terminal_error else "completed")
                        yield _make_chat_finish_chunk(
                            prompt_id=completion_id,
                            created=created,
                            model_name=model_name,
                            finish_reason="stop",
                        )
                        yield _SSE_DONE_FRAME
                        return
                    if time.monotonic() >= deadline:
                        yield _chat_sse_data(
                            {
                                "error": {
                                    "message": "M365 stream timeout",
                                    "type": "m365_error",
                                }
                            }
                        )
                        future.cancel()
                        await _harness_close("error")
                        break
                    continue
                kind = event.get("type")
                if kind in {"delta", "reasoning", "conversation", "keepalive"}:
                    deadline = time.monotonic() + request_idle_seconds
                if kind == "keepalive":
                    # Liveness ping from a progress-only "thinking" period. The
                    # deadline was just refreshed above. Option A: surface one
                    # visible "思考中…" reasoning block when Continue asked for
                    # reasoning, then stay a silent SSE comment heartbeat; when
                    # reasoning is disabled, always a silent heartbeat. Never
                    # touches the answer (delta.content) channel.
                    if reasoning_enabled and not thinking_hint_sent:
                        thinking_hint_sent = True
                        yield _make_chat_reasoning_chunk(
                            prompt_id=completion_id,
                            created=created,
                            model_name=model_name,
                            text="思考中…",
                            include_role=not role_sent,
                        )
                        role_sent = True
                    else:
                        yield ": keepalive\n\n"
                    continue
                if kind == "conversation":
                    cid = str(event.get("conversation_id") or "")
                    if cid:
                        _stream_cid = cid
                        _remember_conversation(cid)
                    continue
                if kind == "reasoning":
                    content = str(event.get("content") or "")
                    if content:
                        if _harness is not None:
                            _step_reasoning.append(content)
                        yield _make_chat_reasoning_chunk(
                            prompt_id=completion_id,
                            created=created,
                            model_name=model_name,
                            text=content,
                            include_role=not role_sent,
                        )
                        role_sent = True
                    continue
                if kind == "delta":
                    content = str(event.get("content") or "")
                    if not content:
                        continue
                    if _m365_tool_tp is not None:
                        # Seam #2 (dormant unless supports_tools): only the text
                        # BEFORE a ```tool``` fence passes through as content; the
                        # fenced block is buffered and surfaced as tool_calls at
                        # done. No-op path is unreachable while tp is None.
                        content = "".join(_m365_tool_tp.push(content))
                        if not content:
                            continue
                    # defense-in-depth behind B. If the model ignores
                    # the no-wrap contract and emits its own attempt_completion/
                    # result tags, strip_envelope_tags() removes just those tags (holding back
                    # a tag split across chunks) so the transport still adds
                    # exactly one envelope. No-op passthrough when not cline.
                    content = _m365_env.strip_envelope_tags(content)
                    if not content:
                        # whole chunk was model envelope tag(s) or a held-back
                        # partial tag; nothing to yield this frame.
                        continue
                    if _harness is not None:
                        # Mirror accumulates the VISIBLE text only (transpiler
                        # passthrough, model envelope tags stripped) — exactly
                        # what Continue sees, before the transport's own
                        # envelope prefix is prepended below.
                        _step_text.append(content)
                    if VE_M365_LOG_RELAY_TRACE:
                        # Count the answer delta actually yielded (raw answer
                        # text, model envelope tags already stripped; the
                        # transport's own opening tag is added below and is not
                        # counted). Equals the producer's emitted_chars whenever
                        # the model did not self-wrap (the normal case).
                        trace_yielded_chars += len(content)
                        trace_yielded_frames += 1
                        trace_yielded_text.append(content)
                    content = _m365_env.open_prefix() + content
                    delta = {"content": content}
                    if not role_sent:
                        delta = {"role": "assistant", "content": content}
                        role_sent = True
                    yield _chat_sse_data(
                        {
                            "id": completion_id,
                            "object": "chat.completion.chunk",
                            "created": created,
                            "model": model_name,
                            "choices": [
                                {"index": 0, "delta": delta, "finish_reason": None}
                            ],
                        }
                    )
                elif kind == "done":
                    cid = str(event.get("conversation_id") or "")
                    if cid:
                        _stream_cid = cid
                        _remember_conversation(cid)
                    if _m365_tool_tp is not None:
                        # Seam #2 terminal (dormant while tp is None). A parsed
                        # ```tool``` block finishes the turn as OpenAI tool_calls
                        # instead of a normal stop; otherwise any held-back tail
                        # (no tool block) is flushed as a final content delta.
                        _m365_calls = _m365_tool_tp.finish_tool_calls()
                        if _m365_calls and _harness is not None:
                            # Seam #3 terminal: Harness-owned calls are executed
                            # by the plugin and NEVER reach Continue; the results
                            # go back into the same M365 conversation as a
                            # <tool_results> follow-up and the loop continues on
                            # the new stream. Client-owned calls in the same
                            # batch get a synthetic refusal result (the client
                            # executes its own tools on the next OpenAI turn, so
                            # a co-hosted call is asked to retry separately).
                            _h_calls, _c_calls = _harness_split_calls(
                                _m365_calls, _harness["names"]
                            )
                            if _h_calls:
                                await _harness_mirror_step(
                                    "tool_calls", calls=_m365_calls
                                )
                                if _harness_step >= VOICE_EDGE_HARNESS_MAX_STEPS:
                                    _m365_log.warning(
                                        "[harness] tool step limit %d reached; "
                                        "ending turn",
                                        VOICE_EDGE_HARNESS_MAX_STEPS,
                                    )
                                    _limit_note = (
                                        "\n[voice-edge] Harness tool step limit "
                                        f"({VOICE_EDGE_HARNESS_MAX_STEPS}) reached; "
                                        "stopping the internal tool loop."
                                    )
                                    yield _chat_sse_data(
                                        {
                                            "id": completion_id,
                                            "object": "chat.completion.chunk",
                                            "created": created,
                                            "model": model_name,
                                            "choices": [
                                                {
                                                    "index": 0,
                                                    "delta": (
                                                        {
                                                            "role": "assistant",
                                                            "content": _limit_note,
                                                        }
                                                        if not role_sent
                                                        else {"content": _limit_note}
                                                    ),
                                                    "finish_reason": None,
                                                }
                                            ],
                                        }
                                    )
                                    role_sent = True
                                    await _harness_close("max-steps")
                                    yield _chat_sse_data(
                                        {
                                            "id": completion_id,
                                            "object": "chat.completion.chunk",
                                            "created": created,
                                            "model": model_name,
                                            "choices": [
                                                {
                                                    "index": 0,
                                                    "delta": {},
                                                    "finish_reason": "stop",
                                                }
                                            ],
                                            "conversation_id": cid,
                                        }
                                    )
                                    yield _SSE_DONE_FRAME
                                    return
                                _harness_step += 1
                                _results = []
                                # Tool execution can legitimately run for up to
                                # VOICE_EDGE_HARNESS_TOOL_TIMEOUT. Keep the SSE
                                # connection active while preserving the existing
                                # serial execution and result ordering semantics.
                                for _c in _h_calls:
                                    _tool_task = asyncio.create_task(
                                        _harness_execute_tool(_harness, _c)
                                    )
                                    try:
                                        while not _tool_task.done():
                                            _done, _pending = await asyncio.wait(
                                                {_tool_task}, timeout=15.0
                                            )
                                            if not _done:
                                                yield ": keepalive\n\n"
                                        _results.append(await _tool_task)
                                    finally:
                                        if not _tool_task.done():
                                            _tool_task.cancel()
                                _results.extend(
                                    _harness_client_refusal(_c) for _c in _c_calls
                                )
                                _follow = build_tool_results_block(_results)
                                # Release the finished producer BEFORE swapping
                                # stream resources; its done event already
                                # arrived, so this never truncates output.
                                consumer_stopped.set()
                                (
                                    future,
                                    event_queue,
                                    consumer_stopped,
                                    output_overflowed,
                                ) = M365_BROWSER_RUNTIME.submit_chat_stream(
                                    _follow,
                                    _stream_cid or conversation_id,
                                    tone,
                                    [],
                                    m365_agent_config,
                                )
                                _m365_tool_tp = _m365_prepared.new_transpiler()
                                deadline = time.monotonic() + M365_FIRST_EVENT_TIMEOUT
                                continue
                        if _m365_calls:
                            # tool_call turn: no Cline envelope (future-proof for
                            # when m365 supports_tools is enabled).
                            _m365_close = _m365_env.suppress()
                            if _m365_close:
                                yield _chat_sse_data(
                                    {
                                        "id": completion_id,
                                        "object": "chat.completion.chunk",
                                        "created": created,
                                        "model": model_name,
                                        "choices": [
                                            {
                                                "index": 0,
                                                "delta": (
                                                    {
                                                        "role": "assistant",
                                                        "content": _m365_close,
                                                    }
                                                    if not role_sent
                                                    else {"content": _m365_close}
                                                ),
                                                "finish_reason": None,
                                            }
                                        ],
                                    }
                                )
                                role_sent = True
                            _tc = [
                                {
                                    "index": _i,
                                    "id": _c["id"],
                                    "type": "function",
                                    "function": {
                                        "name": _c["function"]["name"],
                                        "arguments": _c["function"]["arguments"],
                                    },
                                }
                                for _i, _c in enumerate(_m365_calls)
                            ]
                            yield _chat_sse_data(
                                {
                                    "id": completion_id,
                                    "object": "chat.completion.chunk",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "index": 0,
                                            "delta": (
                                                {"role": "assistant", "tool_calls": _tc}
                                                if not role_sent
                                                else {"tool_calls": _tc}
                                            ),
                                            "finish_reason": None,
                                        }
                                    ],
                                }
                            )
                            yield _chat_sse_data(
                                {
                                    "id": completion_id,
                                    "object": "chat.completion.chunk",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "index": 0,
                                            "delta": {},
                                            "finish_reason": "tool_calls",
                                        }
                                    ],
                                    "conversation_id": cid,
                                }
                            )
                            await _harness_mirror_step("tool_calls", calls=_m365_calls)
                            await _harness_close("tool_calls")
                            yield _SSE_DONE_FRAME
                            return
                        _resid = _m365_tool_tp.flush_pending()
                        # strip model envelope tags from the residual
                        # (symmetric with deepseek/delta path). Reachable now that
                        # supports_tools=True models run the transpiler.
                        _resid = _m365_env.strip_envelope_tags(_resid)
                        if _resid:
                            # The residual is client-visible output and belongs
                            # to the current mirrored model step as well.
                            _step_text.append(_resid)
                            yield _chat_sse_data(
                                {
                                    "id": completion_id,
                                    "object": "chat.completion.chunk",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "index": 0,
                                            "delta": (
                                                {"role": "assistant", "content": _resid}
                                                if not role_sent
                                                else {"content": _resid}
                                            ),
                                            "finish_reason": None,
                                        }
                                    ],
                                }
                            )
                            role_sent = True
                    closing = _m365_env.closing()
                    if closing:
                        yield _chat_sse_data(
                            {
                                "id": completion_id,
                                "object": "chat.completion.chunk",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {
                                        "index": 0,
                                        "delta": {
                                            "role": "assistant",
                                            "content": closing,
                                        }
                                        if not role_sent
                                        else {"content": closing},
                                        "finish_reason": None,
                                    }
                                ],
                            }
                        )
                        role_sent = True
                    await _harness_mirror_step("stop")
                    await _harness_close("completed")
                    yield _chat_sse_data(
                        {
                            "id": completion_id,
                            "object": "chat.completion.chunk",
                            "created": created,
                            "model": model_name,
                            "choices": [
                                {"index": 0, "delta": {}, "finish_reason": "stop"}
                            ],
                            "conversation_id": cid,
                        }
                    )
                    yield _SSE_DONE_FRAME
                    return
                elif kind == "error":
                    await _harness_mirror_step("error")
                    await _harness_close("error")
                    yield _chat_sse_data(
                        {
                            "error": {
                                "message": str(event.get("message") or "M365 error"),
                                "type": "m365_error",
                            }
                        }
                    )
                    return
        finally:
            # Single accounting point covering every exit path (done, error,
            # timeout, client disconnect). Emitting here guarantees the consumer
            # summary is always logged for comparison against the producer.
            _log_consumer_summary("stream-finally")
            consumer_stopped.set()
            if not future.done():
                future.cancel()

    if stream_mode:
        return StreamingResponse(
            events(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    best = ""
    reasoning = ""
    conv = ""
    # Harness bridge state for the non-streaming tool loop. The transpiler
    # runs ONLY when the bridge is active: legacy non-stream never parsed
    # tool blocks and returned the raw text (fence included), so when the
    # final step carries client-owned calls the RAW accumulation is returned
    # and that legacy shape survives byte-for-byte.
    _harness_step = 0
    _ns_tp = _m365_prepared.new_transpiler() if _harness is not None else None
    _visible_steps: list = []  # passthrough text of completed harness steps
    _step_visible: list = []  # passthrough text of the current step
    _step_reasoning: list = []  # current-step reasoning for the mirror
    _final_text: Optional[str] = None  # set when the bridge owns the content
    deadline = time.monotonic() + M365_FIRST_EVENT_TIMEOUT
    try:
        while True:
            try:
                event = await asyncio.to_thread(event_queue.get, True, 1.0)
            except queue.Empty:
                if future.done():
                    try:
                        future.result()
                    except concurrent.futures.CancelledError:
                        pass
                    except Exception as exc:
                        await _harness_finish(_harness, "error")
                        return JSONResponse(
                            {"error": {"message": str(exc), "type": "m365_error"}},
                            status_code=502,
                        )
                    await _harness_finish(_harness, "completed")
                    break
                if time.monotonic() >= deadline:
                    future.cancel()
                    await _harness_finish(_harness, "error")
                    return JSONResponse(
                        {
                            "error": {
                                "message": "M365 stream timeout",
                                "type": "m365_error",
                            }
                        },
                        status_code=504,
                    )
                continue
            kind = event.get("type")
            if kind in {"delta", "reasoning", "conversation", "keepalive"}:
                deadline = time.monotonic() + request_idle_seconds
            if kind == "keepalive":
                # Non-streaming accumulates then returns JSON; a keepalive has no
                # text and only refreshes the deadline (handled above) so a long
                # progress-only thinking period does not time out here either.
                continue
            if kind == "conversation":
                cid = str(event.get("conversation_id") or "")
                if cid:
                    conv = cid
                    _remember_conversation(cid)
            elif kind == "reasoning":
                _reason_piece = str(event.get("content") or "")
                reasoning += _reason_piece
                if _harness is not None:
                    _step_reasoning.append(_reason_piece)
            elif kind == "delta":
                _piece = str(event.get("content") or "")
                best += _piece
                if _ns_tp is not None:
                    _passed = "".join(_ns_tp.push(_piece))
                    if _passed:
                        _step_visible.append(_passed)
            elif kind == "done":
                cid = str(event.get("conversation_id") or "")
                if cid:
                    conv = cid
                    _remember_conversation(cid)
                if _ns_tp is not None and _harness is not None:
                    _ns_calls = _ns_tp.finish_tool_calls()
                    _h_calls, _c_calls = (
                        _harness_split_calls(_ns_calls, _harness["names"])
                        if _ns_calls
                        else ([], [])
                    )
                    if _h_calls:
                        # Same contract as the streaming loop: Harness calls
                        # execute internally, client co-hosted calls get a
                        # synthetic refusal, results re-enter the SAME M365
                        # conversation as a <tool_results> follow-up.
                        await _harness_mirror_event(
                            _harness,
                            kind="step",
                            text="".join(_step_visible),
                            reasoning="".join(_step_reasoning),
                            tool_calls=_ns_calls,
                            finish_reason="tool_calls",
                        )
                        _visible_steps.append("".join(_step_visible))
                        _step_visible.clear()
                        _step_reasoning.clear()
                        if _harness_step >= VOICE_EDGE_HARNESS_MAX_STEPS:
                            _m365_log.warning(
                                "[harness] tool step limit %d reached; ending turn",
                                VOICE_EDGE_HARNESS_MAX_STEPS,
                            )
                            _final_text = "".join(_visible_steps) + (
                                "\n[voice-edge] Harness tool step limit "
                                f"({VOICE_EDGE_HARNESS_MAX_STEPS}) reached; "
                                "stopping the internal tool loop."
                            )
                            await _harness_finish(_harness, "max-steps")
                            break
                        _harness_step += 1
                        _results = [
                            await _harness_execute_tool(_harness, _c) for _c in _h_calls
                        ]
                        _results.extend(_harness_client_refusal(_c) for _c in _c_calls)
                        _follow = build_tool_results_block(_results)
                        consumer_stopped.set()
                        (
                            future,
                            event_queue,
                            consumer_stopped,
                            output_overflowed,
                        ) = M365_BROWSER_RUNTIME.submit_chat_stream(
                            _follow,
                            conv or conversation_id,
                            tone,
                            [],
                            m365_agent_config,
                        )
                        _ns_tp = _m365_prepared.new_transpiler()
                        best = ""
                        deadline = time.monotonic() + M365_FIRST_EVENT_TIMEOUT
                        continue
                    if _c_calls:
                        # Client-owned calls only: keep the LEGACY non-stream
                        # shape — the raw text, tool fence included.
                        _final_text = "".join(_visible_steps) + best
                        await _harness_mirror_event(
                            _harness,
                            kind="step",
                            text=best,
                            reasoning="".join(_step_reasoning),
                            tool_calls=_ns_calls,
                            finish_reason="tool_calls",
                        )
                        await _harness_finish(_harness, "tool_calls")
                        break
                    _resid = _ns_tp.flush_pending()
                    if _resid:
                        _step_visible.append(_resid)
                    _final_text = "".join(_visible_steps) + "".join(_step_visible)
                    await _harness_mirror_event(
                        _harness,
                        kind="step",
                        text="".join(_step_visible),
                        reasoning="".join(_step_reasoning),
                        finish_reason="stop",
                    )
                    await _harness_finish(_harness, "completed")
                break
            elif kind == "error":
                await _harness_finish(_harness, "error")
                return JSONResponse(
                    {
                        "error": {
                            "message": str(event.get("message") or "M365 error"),
                            "type": "m365_error",
                        }
                    },
                    status_code=502,
                )

        return JSONResponse(
            {
                "id": completion_id,
                "object": "chat.completion",
                "created": created,
                "model": model_name,
                "choices": [
                    {
                        "index": 0,
                        "message": {
                            "role": "assistant",
                            "content": _m365_env.wrap(
                                _final_text if _final_text is not None else best
                            ),
                            **({"reasoning_content": reasoning} if reasoning else {}),
                        },
                        "finish_reason": "stop",
                    }
                ],
                "usage": {
                    "prompt_tokens": 0,
                    "completion_tokens": 0,
                    "total_tokens": 0,
                },
                "conversation_id": conv,
            }
        )
    finally:
        consumer_stopped.set()
        if not future.done():
            future.cancel()


