def normalize_stop_sequences(stop, fim_profile: Optional[dict] = None) -> list:
    if stop is None:
        stops = []
    elif isinstance(stop, str):
        stops = [stop]
    elif isinstance(stop, list):
        stops = [str(x) for x in stop if str(x)]
    else:
        stops = [str(stop)]

    normalized = []

    for s in stops:
        s2 = canonicalize_fim_special_tokens(s, fim_profile)

        for item in (s, s2):
            if item and item not in normalized:
                normalized.append(item)

    return normalized


def cut_at_stop_sequences(text: str, stop_sequences: list[str]) -> tuple[str, bool]:
    if not text or not stop_sequences:
        return text or "", False

    earliest = None

    for s in stop_sequences:
        if not s:
            continue

        idx = text.find(s)

        if idx != -1 and (earliest is None or idx < earliest):
            earliest = idx

    if earliest is None:
        return text, False

    return text[:earliest], True


def cut_at_suffix_overlap(
    text: str, suffix: Optional[str], min_overlap: int = 8
) -> tuple[str, bool]:
    """
    If generated text starts to reproduce the suffix, cut before the overlap.

    Example:
    suffix = "\\n\\nprint(add(1, 2))"
    text = "return a + b\\n\\nprint(add(1, 2))"
    -> "return a + b"
    """
    if not text or not suffix:
        return text or "", False

    suffix = str(suffix)

    # 1. Exact suffix occurrence.
    idx = text.find(suffix)
    if idx != -1:
        return text[:idx], True

    # 2. Try stripped suffix occurrence.
    suffix_stripped = suffix.strip()
    if suffix_stripped:
        idx = text.find(suffix_stripped)
        if idx != -1:
            # Also trim whitespace before repeated suffix.
            return text[:idx].rstrip(), True

    # 3. Suffix-prefix overlap at end of generated text.
    max_overlap = min(len(text), len(suffix))

    for n in range(max_overlap, min_overlap - 1, -1):
        if text[-n:] == suffix[:n]:
            return text[:-n].rstrip(), True

    # 4. Stripped suffix-prefix overlap.
    if suffix_stripped:
        max_overlap = min(len(text), len(suffix_stripped))
        for n in range(max_overlap, min_overlap - 1, -1):
            if text[-n:] == suffix_stripped[:n]:
                return text[:-n].rstrip(), True

    return text, False


def _release_llm_worker_models():
    """Fully unload worker models during normal runtime, including MLX cache cleanup."""
    _llm_log.info("Releasing LLM worker models...")

    _release_llm_model(reason="worker_release")
    _release_embed_model(reason="worker_release")
    _release_rerank_model(reason="worker_release")
    _release_vlm_model(reason="worker_release")

    _best_effort_memory_cleanup("worker_release")

    _llm_log.info("LLM worker models released")


def _detach_llm_worker_models_for_process_exit():
    """Detach worker model ownership without invoking native MLX teardown.

    The process is already exiting. Keep strong references in a process-lifetime retention
    container, clear all business-visible globals and identifiers, and return immediately.
    This deliberately skips model release helpers, APC close, gc.collect(), and MLX/Metal
    cache cleanup because those native paths can block indefinitely during shutdown.
    """
    global mlx_llm_model, mlx_llm_tokenizer, LLM_CURRENT_MODEL_ID
    global embed_model, embed_processor, embed_model_id_loaded
    global rerank_model, rerank_processor, rerank_model_id_loaded
    global mlx_vlm_model, mlx_vlm_processor, MLX_VLM_CURRENT_MODEL_ID
    global mlx_vlm_apc_manager, MLX_VLM_APC_MODEL_ID
    global MLX_VLM_DRAFT_MODEL, MLX_VLM_DRAFT_KIND
    global MLX_VLM_DRAFTER_ID, MLX_VLM_DRAFTER_TARGET_ID

    retained = (
        mlx_llm_model,
        mlx_llm_tokenizer,
        embed_model,
        embed_processor,
        rerank_model,
        rerank_processor,
        mlx_vlm_model,
        mlx_vlm_processor,
        mlx_vlm_apc_manager,
        MLX_VLM_DRAFT_MODEL,
    )
    _LLM_PROCESS_EXIT_MODEL_RETENTION.extend(
        value for value in retained if value is not None
    )

    mlx_llm_model = None
    mlx_llm_tokenizer = None
    LLM_CURRENT_MODEL_ID = None
    embed_model = None
    embed_processor = None
    embed_model_id_loaded = None
    rerank_model = None
    rerank_processor = None
    rerank_model_id_loaded = None
    mlx_vlm_model = None
    mlx_vlm_processor = None
    MLX_VLM_CURRENT_MODEL_ID = None
    mlx_vlm_apc_manager = None
    MLX_VLM_APC_MODEL_ID = None
    MLX_VLM_DRAFT_MODEL = None
    MLX_VLM_DRAFT_KIND = None
    MLX_VLM_DRAFTER_ID = None
    MLX_VLM_DRAFTER_TARGET_ID = None

    _llm_log.debug(
        "Detached LLM worker models for process exit: retained_objects=%d",
        len(_LLM_PROCESS_EXIT_MODEL_RETENTION),
    )


def _load_jina_official_mlx_reranker_in_worker(model_id: str):
    """
    Load official jinaai/jina-reranker-v3-mlx.

    This repo provides its own rerank.py / MLXReranker API.
    It expects config.json and projector.safetensors to be available
    relative to the model repo directory, so we load from the HF snapshot
    and temporarily chdir into that directory during construction.
    """
    _rerank_log.info(f"Loading official Jina MLX reranker: {model_id}")

    import importlib.util

    from huggingface_hub import snapshot_download

    try:
        local_dir = Path(
            snapshot_download(
                model_id,
                local_files_only=True,
            )
        ).resolve()

        _rerank_log.info(
            "Using cached Jina reranker snapshot: %s",
            local_dir,
        )

    except Exception:
        _rerank_log.info(
            "Cached Jina reranker unavailable; checking Hugging Face: %s",
            model_id,
        )

        local_dir = Path(
            snapshot_download(
                model_id,
                local_files_only=False,
            )
        ).resolve()

    rerank_py = local_dir / "rerank.py"
    config_json = local_dir / "config.json"
    projector_path = local_dir / "projector.safetensors"

    missing = []
    for p in (rerank_py, config_json, projector_path):
        if not p.exists():
            missing.append(str(p))

    if missing:
        raise FileNotFoundError(
            "Official Jina MLX reranker snapshot is missing required files:\n"
            + "\n".join(missing)
        )

    # Import rerank.py from this snapshot explicitly.
    # Avoid plain "import rerank", because another rerank.py may already
    # be cached in sys.modules or found earlier on sys.path.
    module_name = "jina_reranker_v3_mlx_rerank"
    spec = importlib.util.spec_from_file_location(module_name, str(rerank_py))

    if spec is None or spec.loader is None:
        raise RuntimeError(f"Failed to load rerank.py from {rerank_py}")

    rerank_module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(rerank_module)

    MLXReranker = rerank_module.MLXReranker

    cwd = os.getcwd()

    try:
        # Important:
        # rerank.py may use relative paths such as "projector.safetensors".
        # chdir makes MLXReranker() model-card style work.
        os.chdir(str(local_dir))

        sig = inspect.signature(MLXReranker)
        params = sig.parameters

        kwargs = {}

        if "model_path" in params:
            kwargs["model_path"] = str(local_dir)

        if "projector_path" in params:
            kwargs["projector_path"] = str(projector_path)

        try:
            reranker = MLXReranker(**kwargs)
        except TypeError as e:
            _rerank_log.debug(
                f"MLXReranker kwargs failed ({kwargs}), retrying no-arg init: {e}"
            )
            reranker = MLXReranker()

    finally:
        os.chdir(cwd)

    _rerank_log.info(f"Official Jina MLX reranker loaded from: {local_dir}")
    return reranker, None


def _load_mlx_embedding_model_in_worker(model_id: str):
    """
    Load an mlx-embeddings model inside the LLM worker thread.

    Works for:
    - standard text embedding models
    - Qwen3-VL Embedding / Reranker models that expose model.process(...)
    """
    if not model_id:
        return None, None

    _rerank_log.info(f"Loading MLX embedding/rerank model in LLM worker: {model_id}")

    try:
        from mlx_embeddings import load as mlx_embed_load
    except Exception:
        from mlx_embeddings.utils import load as mlx_embed_load

    model, processor = mlx_embed_load(model_id)

    _rerank_log.info(f"MLX embedding/rerank model loaded: {model_id}")
    return model, processor


def is_qwen3_vl_model(model_id: Optional[str]) -> bool:
    name = str(model_id or "").lower()
    return "qwen3-vl" in name


def _debug_embed(msg: str, **kwargs):
    if not VE_EMBEDDING_LOG_DEBUG:
        return

    try:
        details = " | ".join(f"{k}={v}" for k, v in kwargs.items())
        _embedding_log.info("[EMBED DEBUG] %s | %s", msg, details)
    except Exception:
        pass


def _debug_rerank(msg: str, **kwargs):
    if not VE_RERANK_LOG_DEBUG:
        return

    try:
        details = " | ".join(f"{k}={v}" for k, v in kwargs.items())
        _rerank_log.info("[RERANK DEBUG] %s | %s", msg, details)
    except Exception:
        pass


def _ensure_embed_model_loaded(model_id: Optional[str] = None):
    global embed_model, embed_processor, embed_model_id_loaded

    model_id = resolve_embed_model_name(model_id)

    if not model_id:
        return

    if embed_model is not None and embed_model_id_loaded == model_id:
        return

    # Model is changing: release old one first.
    if embed_model is not None or embed_processor is not None:
        _release_embed_model(reason=f"switch_embed_model_to:{model_id}")

    embed_model, embed_processor = _load_mlx_embedding_model_in_worker(model_id)
    embed_model_id_loaded = model_id

    _debug_embed(
        "model_loaded",
        model=model_id,
        is_qwen3_vl=is_qwen3_vl_model(model_id),
        model_type=type(embed_model),
        processor_type=type(embed_processor),
    )


def _ensure_rerank_model_loaded(model_id: Optional[str] = None):
    global rerank_model, rerank_processor, rerank_model_id_loaded

    model_id = resolve_rerank_model_name(model_id)

    if not model_id:
        return

    if rerank_model is not None and rerank_model_id_loaded == model_id:
        return

    # Model is changing: release old one first.
    if rerank_model is not None or rerank_processor is not None:
        _release_rerank_model(reason=f"switch_rerank_model_to:{model_id}")

    if is_jina_official_mlx_reranker(model_id):
        rerank_model, rerank_processor = _load_jina_official_mlx_reranker_in_worker(
            model_id
        )
    else:
        rerank_model, rerank_processor = _load_mlx_embedding_model_in_worker(model_id)

    rerank_model_id_loaded = model_id

    _debug_rerank(
        "model_loaded",
        model=model_id,
        jina_official=is_jina_official_mlx_reranker(model_id),
        is_qwen3_vl=is_qwen3_vl_model(model_id),
        model_type=type(rerank_model),
        processor_type=type(rerank_processor),
    )

    _debug_rerank_model_capabilities(rerank_model, rerank_processor)


def _mlx_to_list(x: Any) -> list[Any]:
    """Convert an MLX/NumPy-like value to a concrete Python list."""
    try:
        import mlx.core as mx

        mx.eval(x)
    except Exception:
        pass

    tolist = getattr(x, "tolist", None)
    if callable(tolist):
        converted = tolist()
        return converted if isinstance(converted, list) else [converted]

    if isinstance(x, (str, bytes, bytearray, dict)):
        raise TypeError(f"Cannot convert {type(x).__name__} to a numeric list")

    try:
        return list(x)
    except TypeError as exc:
        raise TypeError(
            f"Cannot convert non-iterable {type(x).__name__} to a list"
        ) from exc


def _embed_texts_standard_in_worker(
    model,
    tokenizer,
    texts: Union[str, list[str]],
    batch_size: int = DEFAULT_EMBED_BATCH_SIZE,
    max_length: int = DEFAULT_EMBED_MAX_LENGTH,
) -> list:
    """
    Standard text embedding path:

        tokenizer.batch_encode_plus(...)
        outputs = model(input_ids, attention_mask=...)
        embeddings = outputs.text_embeds

    Suitable for:
    - ModernBERT embedding models
    - voyage-4-nano converted via mlx_embeddings.convert
    - other standard text embedding models
    """
    if model is None or tokenizer is None:
        raise RuntimeError("Embed model/tokenizer is not loaded")

    if isinstance(texts, str):
        texts = [texts]

    texts = [str(t) for t in texts]

    if not texts:
        return []

    import mlx.core as mx

    all_vectors = []

    for i in range(0, len(texts), batch_size):
        batch = texts[i : i + batch_size]

        _debug_embed(
            "standard_batch",
            batch_size=len(batch),
            model=embed_model_id_loaded,
        )

        # Preferred HF tokenizer-style batch API.
        if hasattr(tokenizer, "batch_encode_plus"):
            inputs = tokenizer.batch_encode_plus(
                batch,
                return_tensors="mlx",
                padding=True,
                truncation=True,
                max_length=max_length,
            )
        else:
            # Fallback for tokenizer.__call__
            inputs = tokenizer(
                batch,
                return_tensors="mlx",
                padding=True,
                truncation=True,
                max_length=max_length,
            )

        input_ids = inputs["input_ids"]
        attention_mask = inputs.get("attention_mask", None)

        if attention_mask is not None:
            outputs = model(
                input_ids,
                attention_mask=attention_mask,
            )
        else:
            outputs = model(input_ids)

        embeddings = getattr(outputs, "text_embeds", None)

        if embeddings is None:
            _debug_mlx_embedding_output(outputs)
            raise RuntimeError(
                f"Embedding output has no text_embeds; output={type(outputs)}"
            )

        mx.eval(embeddings)

        _debug_embed(
            "standard_output",
            shape=getattr(embeddings, "shape", None),
        )

        all_vectors.extend(embeddings.tolist())

    return all_vectors


def _embed_qwen3_vl_in_worker(
    model,
    processor,
    items: Union[str, list, dict],
) -> list:
    """
    Qwen3-VL embedding path:

        embeddings = model.process(items, processor=processor)

    items can be:
    - "text"
    - ["text1", "text2"]
    - [{"text": "..."}, {"image": "..."}, {"text": "...", "image": "..."}]
    """
    if model is None or processor is None:
        raise RuntimeError("Qwen3-VL embed model/processor is not loaded")

    import mlx.core as mx

    if isinstance(items, str):
        inputs = [{"text": items}]
    elif isinstance(items, dict):
        inputs = [items]
    elif isinstance(items, list):
        inputs = []
        for item in items:
            if isinstance(item, dict):
                inputs.append(item)
            else:
                inputs.append({"text": str(item)})
    else:
        inputs = [{"text": str(items)}]

    if not inputs:
        return []

    _debug_embed(
        "qwen3_vl_process",
        count=len(inputs),
        model=embed_model_id_loaded,
    )

    embeddings = model.process(inputs, processor=processor)
    mx.eval(embeddings)

    _debug_embed(
        "qwen3_vl_output",
        shape=getattr(embeddings, "shape", None),
    )

    return embeddings.tolist()


def _embed_texts_in_worker(
    model,
    processor,
    texts: Union[str, list[str], list[dict], dict],
    batch_size: int = DEFAULT_EMBED_BATCH_SIZE,
) -> list:
    """
    Main embedding dispatcher.

    - Qwen3-VL models use model.process(...)
    - Standard text embedding models use batch_encode_plus -> model -> text_embeds
    """
    model_id = embed_model_id_loaded or EMBED_MODEL_ID

    if is_qwen3_vl_model(model_id):
        return _embed_qwen3_vl_in_worker(
            model,
            processor,
            texts,
        )

    if not isinstance(texts, str) and not all(isinstance(item, str) for item in texts):
        raise TypeError("Standard embedding backend requires text input")
    text_input = cast(Union[str, list[str]], texts)
    return _embed_texts_standard_in_worker(
        model,
        processor,
        text_input,
        batch_size=batch_size,
    )


def _debug_rerank_model_capabilities(model, processor):
    if not VE_RERANK_LOG_DEBUG:
        return

    try:
        _rerank_log.info("Rerank model type: %s", type(model))
        _rerank_log.info("Rerank processor type: %s", type(processor))

        public_methods = [name for name in dir(model) if not name.startswith("_")]

        interesting = [
            name
            for name in public_methods
            if any(
                k in name.lower()
                for k in [
                    "rank",
                    "rerank",
                    "score",
                    "process",
                    "predict",
                    "forward",
                    "generate",
                ]
            )
        ]

        _rerank_log.info("Rerank model interesting methods: %s", interesting)

        try:
            import inspect

            for name in interesting:
                obj = getattr(model, name, None)
                if callable(obj):
                    try:
                        _rerank_log.info(
                            "Method %s signature: %s",
                            name,
                            inspect.signature(obj),
                        )
                    except Exception:
                        pass
        except Exception:
            pass

    except Exception as e:
        _rerank_log.debug("Rerank model capability debug failed: %s", e)


def _debug_mlx_embedding_output(output):
    if not (VE_EMBEDDING_LOG_DEBUG or VE_RERANK_LOG_DEBUG):
        return

    try:
        _embedding_log.info("mlx-embeddings output type: %s", type(output))

        attrs = [name for name in dir(output) if not name.startswith("_")]

        interesting = [
            name
            for name in attrs
            if any(
                k in name.lower()
                for k in ["score", "logit", "embed", "hidden", "prob", "rank"]
            )
        ]

        _embedding_log.info("mlx-embeddings output interesting attrs: %s", interesting)

        for name in interesting:
            try:
                val = getattr(output, name)
                shape = getattr(val, "shape", None)
                _embedding_log.info(
                    "output.%s type=%s shape=%s",
                    name,
                    type(val),
                    shape,
                )
            except Exception:
                pass

    except Exception as e:
        _embedding_log.debug("mlx embedding output debug failed: %s", e)


def _try_extract_scores_from_output(
    output,
    expected_len: int,
):
    """
    Try extracting native rerank scores from model output.

    Supports:
    - raw MLX array with shape (num_docs,)
    - raw MLX array with shape (num_docs, 1)
    - object attrs: scores / relevance_scores / logits
    - dict keys: scores / relevance_scores / logits
    - flat Python lists / tuples returned through those fields

    Returns:
        list[float] or None
    """
    if output is None or expected_len < 0:
        return None

    import mlx.core as mx

    def normalize_scores(value):
        """
        Convert one candidate value to list[float].

        Returns None when:
        - the shape is unsupported;
        - the result is nested;
        - conversion fails;
        - the number of scores does not match expected_len.
        """
        if value is None:
            return None

        try:
            mx.eval(value)
        except Exception:
            # value may be a regular Python list/tuple rather
            # than an MLX array. Conversion below can still work.
            pass

        shape = getattr(value, "shape", None)

        if shape is not None:
            try:
                normalized_shape = tuple(int(dim) for dim in shape)
            except Exception:
                return None

            if normalized_shape == (expected_len, 1):
                try:
                    value = value[:, 0]
                except Exception:
                    return None

            elif normalized_shape != (expected_len,):
                # In particular, reject classification logits such as
                # (N, 2). They are not one native score per document.
                return None

        try:
            values = _mlx_to_list(value)
        except Exception:
            return None

        if not isinstance(values, (list, tuple)):
            return None

        if len(values) != expected_len:
            return None

        # Explicitly reject nested output. This also prevents accidentally
        # accepting shapes such as (N, 2) when shape metadata is unavailable.
        if any(isinstance(item, (list, tuple)) for item in values):
            return None

        try:
            return [float(item) for item in values]
        except (TypeError, ValueError, OverflowError):
            return None

    # Case 1: output itself is an array/list of scores.
    scores = normalize_scores(output)

    if scores is not None:
        return scores

    # Case 2: scores stored in an output-object attribute.
    for attr in (
        "scores",
        "relevance_scores",
        "logits",
    ):
        try:
            value = getattr(output, attr, None)
        except Exception:
            continue

        scores = normalize_scores(value)

        if scores is not None:
            return scores

    # Case 3: scores stored in a dictionary.
    if isinstance(output, dict):
        for key in (
            "scores",
            "relevance_scores",
            "logits",
        ):
            if key not in output:
                continue

            scores = normalize_scores(output[key])

            if scores is not None:
                return scores

    return None


def _parse_embedding_dimensions(value) -> Optional[int]:
    if value is None:
        return None

    try:
        dimensions = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("dimensions must be an integer") from exc

    if dimensions <= 0:
        raise ValueError("dimensions must be greater than 0")

    return dimensions


def _l2_normalize_vector(vec: list[float]) -> list:
    try:
        arr = np.asarray(vec, dtype=np.float32)
        norm = float(np.linalg.norm(arr))

        if norm > 0:
            arr = arr / norm

        return [float(x) for x in arr.tolist()]

    except Exception:
        # Fallback pure Python
        vals = [float(x) for x in vec]
        norm = math.sqrt(sum(x * x for x in vals))

        if norm > 0:
            vals = [x / norm for x in vals]

        return vals


def _apply_embedding_dimensions(
    vectors: list,
    dimensions: Optional[int],
    normalize_after_truncate: bool = True,
) -> list:
    if dimensions is None:
        return vectors

    out = []

    for vec in vectors:
        if len(vec) < dimensions:
            raise ValueError(
                f"Requested dimensions={dimensions}, but embedding has only {len(vec)} dimensions"
            )

        new_vec = [float(x) for x in vec[:dimensions]]

        if normalize_after_truncate:
            new_vec = _l2_normalize_vector(new_vec)

        out.append(new_vec)

    return out


def _encode_embedding_vector(vec: list[float], encoding_format: str):
    if encoding_format == "float":
        return [float(x) for x in vec]

    if encoding_format == "base64":
        arr = np.asarray(vec, dtype=np.float32)
        return base64.b64encode(arr.tobytes()).decode("ascii")

    raise ValueError("encoding_format must be 'float' or 'base64'")


def _embedding_similarity_rerank_in_worker(
    query: str,
    docs: list[str],
    batch_size: int = DEFAULT_EMBED_BATCH_SIZE,
) -> tuple[list[float], str]:
    """
    Fallback rerank by embedding similarity using configured embed model.

    This is not native cross-encoder reranking.
    """
    import mlx.core as mx

    embed_model_id = resolve_embed_model_name(EMBED_MODEL_ID)
    _ensure_embed_model_loaded(embed_model_id)

    texts = [f"Query: {query}"] + [f"Document: {doc}" for doc in docs]

    vectors = _embed_texts_in_worker(
        embed_model,
        embed_processor,
        texts,
        batch_size=batch_size,
    )

    if not vectors or len(vectors) < 2:
        return [], "embedding_dot_product_empty"

    q = mx.array(vectors[0])
    d = mx.array(vectors[1:])

    scores = mx.matmul(d, q)

    try:
        mx.eval(scores)
    except Exception:
        pass

    method = f"embedding_dot_product:{embed_model_id_loaded or EMBED_MODEL_ID}"

    _debug_rerank(
        "embedding_fallback",
        method=method,
        count=len(docs),
    )

    return [float(x) for x in scores.tolist()], method


def _rerank_qwen3_vl_in_worker(
    model,
    processor,
    query: str,
    docs: list,
    instruction: str = DEFAULT_RERANK_INSTRUCTION,
) -> tuple[list[float], str]:
    """
    Native Qwen3-VL Reranker path:

        scores = model.process(inputs, processor=processor)

    docs may be:
    - list[str]
    - list[dict], e.g. {"text": "..."}, {"image": "..."}, {"text": "...", "image": "..."}
    """
    if model is None or processor is None:
        raise RuntimeError("Qwen3-VL rerank model/processor is not loaded")

    query = str(query or "").strip()

    if not query:
        raise RuntimeError("Rerank query is empty")

    documents = []

    for d in docs:
        if isinstance(d, dict):
            documents.append(d)
        else:
            documents.append({"text": str(d)})

    if not documents:
        return [], "native_qwen3_vl_empty"

    inputs = {
        "instruction": instruction,
        "query": {"text": query},
        "documents": documents,
    }

    _debug_rerank(
        "qwen3_vl_process",
        docs=len(documents),
        model=rerank_model_id_loaded,
    )

    output = model.process(inputs, processor=processor)

    scores = _try_extract_scores_from_output(
        output,
        expected_len=len(documents),
    )

    if scores is None:
        _debug_mlx_embedding_output(output)
        raise RuntimeError(
            f"Qwen3-VL reranker did not return native scores; output={type(output)}"
        )

    _debug_rerank(
        "qwen3_vl_scores",
        scores=scores[:5],
        count=len(scores),
    )

    return (
        scores,
        f"native_qwen3_vl_process:{rerank_model_id_loaded or RERANK_MODEL_ID}",
    )


def _rerank_jina_official_mlx_in_worker(
    reranker,
    query: str,
    docs: list,
) -> tuple[list[float], str]:
    """
    Native Jina MLX rerank path.

    Official API:
        results = reranker.rerank(query, documents)

    Expected result item:
        {
            "document": ...,
            "relevance_score": float,
            "index": int,
            ...
        }
    """
    query = str(query or "").strip()

    if not query:
        raise RuntimeError("Rerank query is empty")

    documents = [
        d["text"] if isinstance(d, dict) and "text" in d else str(d) for d in docs
    ]

    if not documents:
        return [], "native_jina_mlx_empty"

    _debug_rerank(
        "jina_official_rerank",
        docs=len(documents),
        model=rerank_model_id_loaded,
    )

    results = reranker.rerank(
        query,
        documents,
        top_n=None,
        return_embeddings=False,
    )

    scores = [0.0 for _ in documents]

    for item in results:
        idx = item.get("index")
        score = item.get("relevance_score")

        if idx is None or score is None:
            continue

        if 0 <= int(idx) < len(scores):
            scores[int(idx)] = float(score)

    _debug_rerank(
        "jina_official_scores",
        scores=scores[:5],
        count=len(scores),
    )

    return scores, f"native_jina_mlx:{rerank_model_id_loaded}"


def _rerank_in_worker(
    model,
    processor,
    query: str,
    docs: list,
    batch_size: int = DEFAULT_RERANK_BATCH_SIZE,
) -> tuple[list[float], str]:
    """
    Rerank dispatcher.

    Routes:
    - jinaai/jina-reranker-v3-mlx -> MLXReranker.rerank(...)
    - Qwen3-VL Reranker -> model.process(...)
    - Other mlx-embeddings models -> native process/rank if available
    - Fallback -> embedding dot product
    """
    if model is None:
        raise RuntimeError("Rerank model is not loaded")

    query = str(query or "").strip()

    if not query:
        raise RuntimeError("Rerank query is empty")

    if not docs:
        return [], "rerank_empty"

    model_id = rerank_model_id_loaded or RERANK_MODEL_ID

    # 1. Official Jina MLX reranker
    if is_jina_official_mlx_reranker(model_id):
        return _rerank_jina_official_mlx_in_worker(
            model,
            query,
            docs,
        )

    # 2. Qwen3-VL native reranker
    if is_qwen3_vl_model(model_id):
        return _rerank_qwen3_vl_in_worker(
            model,
            processor,
            query,
            docs,
            instruction=DEFAULT_RERANK_INSTRUCTION,
        )

    # 3. Generic mlx-embeddings native process
    if hasattr(model, "process"):
        try:
            inputs = {
                "query": {"text": query},
                "documents": [
                    d if isinstance(d, dict) else {"text": str(d)} for d in docs
                ],
            }

            output = model.process(inputs, processor=processor)

            scores = _try_extract_scores_from_output(
                output,
                expected_len=len(docs),
            )

            if scores is not None:
                return scores, f"native_process:{model_id}"

            _debug_mlx_embedding_output(output)

        except Exception as e:
            _rerank_log.debug(f"Rerank model.process fallback: {e}")

    # 4. Other native methods
    for method_name in ("rerank", "rank"):
        method = getattr(model, method_name, None)

        if callable(method):
            try:
                output = method(
                    query=query,
                    documents=docs,
                    processor=processor,
                )

                scores = _try_extract_scores_from_output(
                    output,
                    expected_len=len(docs),
                )

                if scores is not None:
                    return scores, f"native_{method_name}:{model_id}"

                raw_scores = _mlx_to_list(output)
                return [
                    float(x) for x in raw_scores
                ], f"native_{method_name}:{model_id}"

            except Exception as e:
                _rerank_log.debug(f"Rerank {method_name} fallback: {e}")

    # 5. Fallback
    _rerank_log.warning(
        "Rerank model did not expose native scores; "
        "falling back to embedding similarity with embed model"
    )

    return _embedding_similarity_rerank_in_worker(
        query=query,
        docs=[
            str(d) if not isinstance(d, dict) else json.dumps(d, ensure_ascii=False)
            for d in docs
        ],
        batch_size=DEFAULT_EMBED_BATCH_SIZE,
    )


def _messages_to_vlm_plain_prompt(
    messages: list, allow_tool_calls: bool = False
) -> str:
    """
    Convert OpenAI chat messages into plain user prompt for mlx-vlm text-only backend.

    For Gemma4 agentic models, prepend a no-tool/no-channel guard.
    """
    messages = normalize_chat_messages_for_template(messages)

    system_parts = [] if allow_tool_calls else [VLM_NO_TOOL_SYSTEM_GUARD]
    convo_parts = []

    for msg in messages:
        role = msg.get("role", "user")
        content = msg.get("content", "")

        if content is None:
            content = ""

        if not isinstance(content, str):
            try:
                content = json.dumps(content, ensure_ascii=False)
            except Exception:
                content = str(content)

        content = content.strip()

        if not content:
            continue

        if role == "system":
            # Keep Continue's system prompt, but put our guard before it.
            system_parts.append(content)
        elif role == "assistant":
            convo_parts.append(f"Previous assistant response:\n{content}")
        else:
            convo_parts.append(content)

    parts = []

    if system_parts:
        parts.append("\n\n".join(system_parts))

    parts.extend(convo_parts)

    return "\n\n".join(parts).strip()


def _build_vlm_prompt_for_worker(
    prompt_text: str,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
) -> str:
    """
    Apply the mlx-vlm chat template for a text-only prompt.

    Rules:
    - Thinking disabled: pass enable_thinking=False and thinking_budget=0.
    - Thinking enabled without a budget: omit thinking_budget.
    - Thinking enabled with a positive budget: pass that budget.
    """
    prompt_text = "" if prompt_text is None else str(prompt_text)

    enable_thinking = bool(enable_thinking)

    if thinking_budget is not None:
        try:
            thinking_budget = int(thinking_budget)
        except (TypeError, ValueError):
            thinking_budget = None

    if enable_thinking and thinking_budget is not None and thinking_budget <= 0:
        thinking_budget = None

    try:
        from mlx_vlm.prompt_utils import (
            apply_chat_template,
        )

        if enable_thinking:
            template_kwargs = []

            if thinking_budget is not None:
                template_kwargs.append(
                    {
                        "num_images": 0,
                        "enable_thinking": True,
                        "thinking_budget": thinking_budget,
                    }
                )

            template_kwargs.extend(
                [
                    {
                        "num_images": 0,
                        "enable_thinking": True,
                    },
                    {
                        "num_images": 0,
                    },
                    {},
                ]
            )

        else:
            template_kwargs = [
                {
                    "num_images": 0,
                    "enable_thinking": False,
                    "thinking_budget": 0,
                },
                {
                    "num_images": 0,
                    "enable_thinking": False,
                },
                {
                    "num_images": 0,
                },
                {},
            ]

        model = mlx_vlm_model
        processor = mlx_vlm_processor
        if model is None or processor is None:
            raise RuntimeError("VLM model/processor not loaded")

        last_error = None

        for kwargs in template_kwargs:
            try:
                prompt = apply_chat_template(
                    processor,
                    model.config,
                    prompt_text,
                    **kwargs,
                )

                _vlm_log.debug(
                    "[VLM] apply_chat_template succeeded: kwargs=%s prompt_chars=%d",
                    kwargs,
                    len(prompt),
                )

                return prompt if isinstance(prompt, str) else str(prompt)

            except TypeError as exc:
                last_error = exc
                continue

        _vlm_log.warning(
            "[VLM] apply_chat_template rejected all "
            "thinking arguments; using raw prompt: %s",
            last_error,
        )

        return prompt_text

    except Exception as exc:
        _vlm_log.warning(
            "[VLM] apply_chat_template failed; using raw prompt: %s",
            exc,
        )

        return prompt_text


def _normalize_max_tokens(
    value,
    *,
    default: int,
) -> int:
    """
    Validate max_tokens without imposing a server-side cap.

    The caller-provided positive value is passed through unchanged.
    """
    if value is None:
        return default

    try:
        result = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("max_tokens must be a positive integer") from exc

    if result <= 0:
        raise ValueError("max_tokens must be greater than 0")

    return result


def _log_vlm_speculative_stats(
    draft_model,
    draft_kind: str,
):
    if draft_model is None:
        return

    try:
        from mlx_vlm.speculative.utils import (
            format_speculative_stats,
        )

        stats = format_speculative_stats(draft_model)

        if stats:
            _vlm_log.info(
                "[VLM %s] %s",
                str(draft_kind or "draft").upper(),
                stats,
            )

    except Exception:
        _vlm_log.debug(
            "Failed to collect VLM speculative stats",
            exc_info=True,
        )


def _vlm_stream_text(
    model_id: str,
    prompt_text: str,
    max_tokens: int = 500,
    temperature: float = 0.7,
    top_p: float = 1.0,
    stop_event: Optional[threading.Event] = None,
    allow_tool_calls: bool = False,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
):
    """
    Text-only streaming generation through mlx-vlm.

    Optional features:
    - Gemma 4 MTP speculative decoding
    - APC prefix caching
    - KV-cache TurboQuant
    """
    max_tokens = _normalize_max_tokens(
        max_tokens,
        default=500,
    )

    # Load/resolve the target model first.
    _ensure_vlm_model_loaded(model_id)

    # Use the logical ID for the MTP target-to-drafter mapping.
    resolved_model = MLX_VLM_CURRENT_MODEL_ID or str(model_id or "").strip()

    draft_model = None
    draft_kind = None

    if VLM_MTP_ENABLED:
        try:
            (
                draft_model,
                draft_kind,
            ) = _ensure_vlm_drafter_loaded(resolved_model)

        except Exception:
            _vlm_log.exception(
                "VLM MTP drafter initialization failed; using normal decoding"
            )

            draft_model = None
            draft_kind = None

    kwargs = {
        "max_tokens": max_tokens,
        "temperature": temperature,
        "top_p": top_p,
    }

    if draft_model is not None:
        kwargs.update(
            {
                "draft_model": draft_model,
                "draft_kind": draft_kind,
                "draft_block_size": VLM_MTP_DRAFT_BLOCK_SIZE,
            }
        )

    prompt = _build_vlm_prompt_for_worker(
        prompt_text,
        enable_thinking=enable_thinking,
        thinking_budget=thinking_budget,
    )

    apc_manager = _ensure_vlm_apc_manager(resolved_model)

    if apc_manager is not None:
        kwargs["apc_manager"] = apc_manager

    if VLM_KV_BITS is not None:
        kwargs["kv_bits"] = VLM_KV_BITS

    if VLM_KV_GROUP_SIZE is not None:
        kwargs["kv_group_size"] = VLM_KV_GROUP_SIZE

    if VLM_QUANTIZED_KV_START > 0:
        kwargs["quantized_kv_start"] = VLM_QUANTIZED_KV_START

    if VLM_KV_QUANT_SCHEME:
        kwargs["kv_quant_scheme"] = VLM_KV_QUANT_SCHEME

    _vlm_log.info(
        "[VLM] stream requested: "
        "model=%s mtp=%s draft_kind=%s "
        "draft_block_size=%s max_tokens=%s "
        "temperature=%s top_p=%s "
        "enable_thinking=%s thinking_budget=%s "
        "apc=%s kv_bits=%s kv_group_size=%s "
        "quantized_kv_start=%s kv_scheme=%s",
        resolved_model,
        draft_model is not None,
        draft_kind,
        (VLM_MTP_DRAFT_BLOCK_SIZE if draft_model is not None else None),
        max_tokens,
        temperature,
        top_p,
        enable_thinking,
        thinking_budget,
        apc_manager is not None,
        VLM_KV_BITS,
        VLM_KV_GROUP_SIZE,
        VLM_QUANTIZED_KV_START,
        VLM_KV_QUANT_SCHEME,
    )

    from mlx_vlm.generate import (
        stream_generate as vlm_stream_generate,
    )

    # Do not blindly remove kwargs only because stream_generate
    # exposes them through **kwargs.
    model = mlx_vlm_model
    processor = mlx_vlm_processor
    if model is None or processor is None:
        raise RuntimeError("VLM model/processor not loaded")
    processor_for_generate: Any = processor

    generation_kwargs = dict(kwargs)

    _vlm_log.info(
        "[VLM] stream_generate start: prompt_chars=%d kwargs=%s",
        len(prompt),
        sorted(generation_kwargs.keys()),
    )

    try:
        stream_iter = vlm_stream_generate(
            model,
            processor_for_generate,
            prompt,
            image=None,
            audio=None,
            video=None,
            **generation_kwargs,
        )

    except TypeError as exc:
        _vlm_log.warning(
            "[VLM] stream_generate rejected optional "
            "APC/KV arguments: %s; retrying while "
            "preserving MTP",
            exc,
        )

        # Remove only optional APC/KV arguments.
        # Keep the MTP parameters.
        fallback_kwargs = dict(generation_kwargs)

        fallback_kwargs.pop(
            "apc_manager",
            None,
        )
        fallback_kwargs.pop(
            "kv_bits",
            None,
        )
        fallback_kwargs.pop(
            "kv_group_size",
            None,
        )
        fallback_kwargs.pop(
            "quantized_kv_start",
            None,
        )
        fallback_kwargs.pop(
            "kv_quant_scheme",
            None,
        )

        stream_iter = vlm_stream_generate(
            model,
            processor_for_generate,
            prompt,
            image=None,
            audio=None,
            video=None,
            **fallback_kwargs,
        )

    pending_text = ""

    stop_sequences = list(VLM_STOP_SEQUENCES)

    if allow_tool_calls:
        stop_sequences = [
            sequence
            for sequence in VLM_STOP_SEQUENCES
            if ("tool_call" not in sequence and "channel" not in sequence)
        ]

    max_tail = (
        max(
            (len(sequence) for sequence in stop_sequences),
            default=0,
        )
        - 1
    )

    max_tail = max(
        0,
        max_tail,
    )

    try:
        # Some mlx-vlm versions may return a plain string.
        if isinstance(stream_iter, str):
            stream_iter = [stream_iter]

        for chunk in stream_iter:
            if stop_event is not None and stop_event.is_set():
                _vlm_log.info("[VLM] stream stopped by stop_event")
                break

            if isinstance(chunk, str):
                text = chunk
            else:
                text = getattr(
                    chunk,
                    "text",
                    None,
                )

                if text is None:
                    text = str(chunk)

            if not text:
                continue

            pending_text += text

            cut_text, hit_stop = cut_at_stop_sequences(
                pending_text,
                stop_sequences,
            )

            if hit_stop:
                _vlm_log.info(
                    "[VLM] stop marker emitted: cut_text_chars=%d pending_chars=%d",
                    len(cut_text),
                    len(pending_text),
                )

                if cut_text:
                    yield cut_text

                pending_text = ""
                break

            # Retain a short tail so a stop sequence split
            # across token chunks is not leaked.
            if max_tail and len(pending_text) > max_tail:
                emit = pending_text[:-max_tail]
                pending_text = pending_text[-max_tail:]
            else:
                emit = ""

            if emit:
                yield emit

        if pending_text:
            yield pending_text

    finally:
        if draft_model is not None:
            _log_vlm_speculative_stats(
                draft_model,
                draft_kind or "unknown",
            )

        if apc_manager is not None:
            try:
                _vlm_log.debug(
                    "[VLM APC] stats=%s",
                    apc_manager.stats_snapshot(),
                )
            except Exception:
                pass

        _vlm_log.info("[VLM] stream_generate done")


def _vlm_generate_text(
    model_id: str,
    prompt_text: str,
    max_tokens: int = 500,
    temperature: float = 0.7,
    top_p: float = 1.0,
    stop_event: Optional[threading.Event] = None,
    allow_tool_calls: bool = False,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
) -> str:
    """
    Non-streaming text generation through mlx-vlm.

    This intentionally wraps _vlm_stream_text() so VLM generation has one
    consistent path for:
    - APC
    - KV quantization
    - cancellation
    - stop-marker filtering
    - max-token capping
    """
    chunks = []

    for token_text in _vlm_stream_text(
        model_id=model_id,
        prompt_text=prompt_text,
        max_tokens=max_tokens,
        temperature=temperature,
        top_p=top_p,
        stop_event=stop_event,
        allow_tool_calls=allow_tool_calls,
        enable_thinking=enable_thinking,
        thinking_budget=thinking_budget,
    ):
        if stop_event is not None and stop_event.is_set():
            break

        chunks.append(token_text)

    raw = "".join(chunks)
    return raw if allow_tool_calls else strip_vlm_artifacts(raw)


def _is_local_model_path(model_id: str) -> bool:
    """
    Return True if model_id already points to a local file-system path.

    Supports:
    - absolute paths
    - relative paths beginning with ./ or ../
    - expanded home paths such as ~/Documents/models/model
    """
    raw = str(model_id or "").strip()

    if not raw:
        return False

    expanded = Path(raw).expanduser()

    return (
        expanded.is_absolute()
        or raw.startswith("./")
        or raw.startswith("../")
        or raw.startswith("~/")
        or expanded.exists()
    )


def resolve_local_hf_snapshot(
    model_id: str,
    *,
    revision: Optional[str] = None,
) -> str:
    """
    Resolve a model reference to an existing local directory.

    Rules:
    1. Existing local paths are returned directly.
    2. Hugging Face repo IDs are resolved from the local Hub cache only.
    3. No network download or remote metadata request is allowed.
    """
    raw = str(model_id or "").strip()

    if not raw:
        raise ValueError("Model id/path is empty")

    expanded = Path(raw).expanduser()

    # Existing local model directory.
    if _is_local_model_path(raw):
        resolved = expanded.resolve()

        if not resolved.exists():
            raise FileNotFoundError(f"Local model path does not exist: {resolved}")

        if not resolved.is_dir():
            raise NotADirectoryError(f"Local model path is not a directory: {resolved}")

        _app_log.info(
            "Using explicit local model path: %s",
            resolved,
        )

        return str(resolved)

    from huggingface_hub import snapshot_download
    from huggingface_hub.errors import LocalEntryNotFoundError

    try:
        local_path = snapshot_download(
            repo_id=raw,
            revision=revision,
            local_files_only=True,
        )
    except LocalEntryNotFoundError as exc:
        revision_text = revision or "cached main"

        raise FileNotFoundError(
            f"Model is not available in the local Hugging Face cache: "
            f"repo={raw}, revision={revision_text}. "
            f"Download it before starting the offline server."
        ) from exc

    resolved = Path(local_path).resolve()

    _app_log.info(
        "Resolved cached Hugging Face model: repo=%s revision=%s path=%s",
        raw,
        revision or "local refs/main",
        resolved,
    )

    return str(resolved)


def get_model_revision(model_id: str) -> Optional[str]:
    return MODEL_REVISIONS.get(str(model_id or "").strip())


def validate_llm_alias_backends() -> None:
    missing = sorted(set(LLM_MODEL_ALIASES) - set(LLM_MODEL_BACKENDS))
    if missing:
        raise RuntimeError(f"LLM aliases missing backend mappings: {missing}")


def validate_local_model_cache():
    validate_llm_alias_backends()

    groups = {
        "LLM": LLM_MODEL_ALIASES,
        "FIM": FIM_MODEL_ALIASES,
    }

    failures = []

    for group_name, aliases in groups.items():
        for alias, model_id in aliases.items():
            try:
                resolve_local_hf_snapshot(
                    model_id,
                    revision=get_model_revision(model_id),
                )

                # _app_log.info(
                #     "[LOCAL MODEL OK] group=%s alias=%s path=%s",
                #     group_name,
                #     alias,
                #     local_path,
                # )

            except Exception as exc:
                failures.append(f"{group_name} {alias} -> {model_id}: {exc}")

    if failures:
        _app_log.warning(
            "Some models are unavailable locally:\n%s",
            "\n".join(failures),
        )


def validate_default_local_models():
    defaults = [
        ("LLM", resolve_llm_model_name(DEFAULT_LLM_ALIAS)),
        ("FIM", resolve_fim_model_name(DEFAULT_FIM_ALIAS)),
    ]

    for kind, model_id in defaults:
        local_path = resolve_local_hf_snapshot(
            model_id,
            revision=get_model_revision(model_id),
        )

        _app_log.info(
            "Default %s model available locally: %s",
            kind,
            local_path,
        )


def _ensure_vlm_model_loaded(model_id: str):
    global mlx_vlm_model, mlx_vlm_processor, MLX_VLM_CURRENT_MODEL_ID

    model_id = str(model_id or "").strip()

    if not model_id:
        raise RuntimeError("Empty MLX-VLM model id")

    if (
        mlx_vlm_model is not None
        and mlx_vlm_processor is not None
        and MLX_VLM_CURRENT_MODEL_ID == model_id
    ):
        return

    # IMPORTANT:
    # If switching from mlx_lm backend to mlx_vlm backend,
    # release normal LLM first to avoid memory spike.
    if mlx_llm_model is not None or mlx_llm_tokenizer is not None:
        _release_llm_model(reason=f"switch_to_mlx_vlm:{model_id}")

    if mlx_vlm_model is not None or mlx_vlm_processor is not None:
        _release_vlm_model(reason=f"switch_vlm_model_to:{model_id}")

    if AGGRESSIVE_RELEASE_AUX_ON_VLM_LOAD:
        _vlm_log.info(
            "Aggressive auxiliary-model release: %s",
            AGGRESSIVE_RELEASE_AUX_ON_VLM_LOAD,
        )
        _release_embed_model(reason=f"before_loading_vlm:{model_id}")
        _release_rerank_model(reason=f"before_loading_vlm:{model_id}")

    _vlm_log.info(f"Loading MLX-VLM model in LLM worker: {model_id}")

    from mlx_vlm.utils import load as vlm_load

    local_model_path = resolve_local_hf_snapshot(
        model_id,
        revision=get_model_revision(model_id),
    )

    _vlm_log.info(
        "Loading MLX-VLM model locally: model=%s path=%s",
        model_id,
        local_model_path,
    )

    mlx_vlm_model, mlx_vlm_processor = vlm_load(
        local_model_path,
        strict=False,
    )

    MLX_VLM_CURRENT_MODEL_ID = model_id

    _vlm_log.info(f"MLX-VLM model loaded in LLM worker: {model_id}")


def _ensure_llm_model_loaded(model_id: str):
    global mlx_llm_model, mlx_llm_tokenizer, LLM_CURRENT_MODEL_ID

    requested_model = resolve_llm_model_name(model_id)

    if (
        mlx_llm_model is not None
        and mlx_llm_tokenizer is not None
        and LLM_CURRENT_MODEL_ID == requested_model
    ):
        return

    # IMPORTANT:
    # If switching from mlx_vlm backend to mlx_lm backend,
    # release VLM first or unified memory can spike badly.
    if mlx_vlm_model is not None or mlx_vlm_processor is not None:
        _release_vlm_model(reason=f"switch_to_mlx_lm:{requested_model}")

    _llm_log.info(
        f"Switching MLX LLM model: {LLM_CURRENT_MODEL_ID} -> {requested_model}"
    )

    mlx_llm_model = None
    mlx_llm_tokenizer = None
    LLM_CURRENT_MODEL_ID = None

    _best_effort_memory_cleanup(f"switch_llm_model_to:{requested_model}")

    _init_mlx_worker_stream()

    from mlx_lm import load as mlx_load

    local_model_path = resolve_local_hf_snapshot(
        requested_model,
        revision=get_model_revision(requested_model),
    )

    _llm_log.info(
        "Loading MLX LLM model from local path: model=%s path=%s",
        requested_model,
        local_model_path,
    )

    mlx_llm_model, mlx_llm_tokenizer, *_ = mlx_load(local_model_path)

    LLM_CURRENT_MODEL_ID = requested_model

    _llm_log.info(f"MLX LLM model loaded in LLM worker: {requested_model}")


def llm_control_fifo_worker():
    global LLM_FORCED_MODEL

    try:
        if not os.path.exists(LLM_CONTROL_FIFO):
            os.mkfifo(LLM_CONTROL_FIFO)
    except FileExistsError:
        pass
    except Exception as e:
        _llm_log.warning(f"Failed to create LLM control FIFO: {e}")
        return

    _llm_log.info(f"LLM control FIFO listening at {LLM_CONTROL_FIFO}")

    while not SERVER_SHUTTING_DOWN.is_set():
        try:
            # This blocks until someone writes to the FIFO.
            with open(LLM_CONTROL_FIFO, "r", encoding="utf-8") as f:
                for line in f:
                    if SERVER_SHUTTING_DOWN.is_set():
                        break

                    cmd = line.strip()
                    if not cmd:
                        continue

                    if cmd.startswith("switch "):
                        model = cmd[len("switch ") :].strip()

                        with LLM_FORCED_MODEL_LOCK:
                            LLM_FORCED_MODEL = model

                        _llm_log.info(
                            f"LLM forced model set to: {LLM_FORCED_MODEL} "
                            f"-> {resolve_llm_model_name(LLM_FORCED_MODEL)}"
                        )

                    elif cmd in ("clear", "default", "reset"):
                        with LLM_FORCED_MODEL_LOCK:
                            LLM_FORCED_MODEL = None

                        _llm_log.info(
                            "LLM forced model cleared; using request/default model"
                        )

                    elif cmd in ("status", "model"):
                        with LLM_FORCED_MODEL_LOCK:
                            forced = LLM_FORCED_MODEL

                        _llm_log.info(
                            f"LLM model status: forced={forced}, default={LLM_MODEL_ID}"
                        )

                    elif cmd == "shutdown":
                        if SERVER_SHUTTING_DOWN.is_set():
                            break

                    else:
                        _llm_log.warning(f"Unknown LLM FIFO command: {cmd}")

        except Exception as e:
            if not SERVER_SHUTTING_DOWN.is_set():
                _llm_log.debug(f"LLM control FIFO error: {e}")
                time.sleep(0.5)

    _llm_log.debug("LLM control FIFO worker stopped")


def start_llm_control_fifo_worker():
    global LLM_CONTROL_THREAD

    if LLM_CONTROL_THREAD and LLM_CONTROL_THREAD.is_alive():
        return

    LLM_CONTROL_THREAD = threading.Thread(
        target=llm_control_fifo_worker,
        daemon=True,
        name="LLMControlFIFO",
    )
    LLM_CONTROL_THREAD.start()

    _llm_log.info("LLM control FIFO worker started")


def _build_chat_prompt_for_worker(
    messages: list,
    enable_thinking: bool = False,
) -> str:
    """
    Build chat prompt inside the LLM worker thread.

    enable_thinking is passed to chat templates that support it.
    Templates that do not support the argument fall back automatically.
    """
    messages = normalize_chat_messages_for_template(messages)

    try:
        return mlx_llm_tokenizer.apply_chat_template(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            messages,
            tokenize=False,
            add_generation_prompt=True,
            enable_thinking=bool(enable_thinking),
        )

    except TypeError:
        return mlx_llm_tokenizer.apply_chat_template(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )


def apply_thinking_policy_to_messages(
    messages: list,
    enable_thinking: bool,
) -> list:
    if enable_thinking:
        return list(messages or [])

    instruction = (
        "Answer directly and provide only the final answer. "
        "Do not expose internal reasoning or analysis."
    )

    return _merge_instruction_into_system(
        list(messages or []),
        instruction,
    )


def _init_mlx_worker_stream():
    """
    Initialize MLX stream state in the current LLM worker thread.
    """
    import importlib

    import mlx.core as mx

    mlx_generate_mod = importlib.import_module("mlx_lm.generate")

    device = mx.default_device()

    # set_default_stream needs mlx.core.Stream
    default_stream = mx.default_stream(device)
    mx.set_default_stream(default_stream)

    # generation_stream can be ThreadLocalStream; do NOT pass it to set_default_stream
    if hasattr(mx, "new_thread_local_stream"):
        generation_stream = mx.new_thread_local_stream(device)
    else:
        generation_stream = mx.new_stream(device)

    if hasattr(mlx_generate_mod, "generation_stream"):
        mlx_generate_mod.generation_stream = generation_stream  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    _llm_log.info(f"LLM worker default stream: {default_stream!r}")
    _llm_log.info(f"LLM worker generation_stream rebound: {generation_stream!r}")

    try:
        mx.eval(mx.array([0]))
    except Exception as e:
        _llm_log.debug(f"LLM worker MLX warmup ignored error: {e}")

    return mlx_generate_mod


def _put_queue_interruptible(
    q: queue.Queue, item, stop_event: Optional[threading.Event] = None
):
    """
    Put item into a queue without blocking forever.
    """
    while True:
        if stop_event is not None and stop_event.is_set():
            return False

        try:
            q.put(item, timeout=0.1)
            return True
        except queue.Full:
            continue


def _get_job_thinking_options(
    job: dict,
) -> tuple[bool, Optional[int]]:
    enable_thinking = bool(job.get("enable_thinking", False))

    raw_budget = job.get("thinking_budget")

    if raw_budget is None:
        return enable_thinking, None

    try:
        thinking_budget = int(raw_budget)
    except (TypeError, ValueError):
        _app_log.warning(
            "Ignoring invalid thinking_budget: %r",
            raw_budget,
        )
        return enable_thinking, None

    if not enable_thinking:
        return False, 0

    if thinking_budget <= 0:
        return True, None

    return True, thinking_budget


def _llm_worker_loop():
    global LLM_WORKER_THREAD_ID
    global mlx_llm_model, mlx_llm_tokenizer
    global LLM_CURRENT_MODEL_ID

    LLM_WORKER_THREAD_ID = threading.get_ident()

    try:
        mlx_generate_mod = _init_mlx_worker_stream()

        mlx_llm_model = None
        mlx_llm_tokenizer = None
        LLM_CURRENT_MODEL_ID = None

        _llm_log.info("LLM worker initialized; model will be loaded lazily")

        if LOAD_EMBED_MODEL_ON_START and EMBED_MODEL_ID:
            _ensure_embed_model_loaded(EMBED_MODEL_ID)

        if LOAD_RERANK_MODEL_ON_START and RERANK_MODEL_ID:
            _ensure_rerank_model_loaded(RERANK_MODEL_ID)

    except Exception as e:
        _llm_log.exception(f"Failed to initialize LLM worker: {e}")
        LLM_WORKER_READY.set()
        LLM_WORKER_STOPPED.set()
        return

    LLM_WORKER_READY.set()
    _llm_log.info("LLM worker thread started")

    from mlx_lm.sample_utils import make_sampler

    while True:
        job = LLM_JOB_QUEUE.get()

        try:
            if job is None:
                _llm_log.debug("LLM worker received shutdown signal")
                _detach_llm_worker_models_for_process_exit()
                break

            job_type = job.get("type")
            out_q = job["out_q"]
            stop_event = job.get("stop_event")

            with LLM_FORCED_MODEL_LOCK:
                forced_model = LLM_FORCED_MODEL

            model_id = forced_model or resolve_llm_model_name(
                job.get("model") or DEFAULT_LLM_ALIAS
            )

            if SERVER_SHUTTING_DOWN.is_set():
                _put_queue_interruptible(
                    out_q,
                    ("error", "Server is shutting down"),
                    stop_event,
                )
                continue

            if job_type == "generate":
                try:
                    requested_model, resolved_model, backend, model_kind = (
                        resolve_generation_model_for_job(
                            job,
                            forced_model=forced_model,
                        )
                    )

                    enable_thinking, thinking_budget = _get_job_thinking_options(job)

                    if backend == "mlx_vlm":
                        allow_tool_calls = bool(job.get("allow_tool_calls"))
                        prompt_text = _messages_to_vlm_plain_prompt(
                            job["messages"], allow_tool_calls=allow_tool_calls
                        )

                        vlm_max_tokens = _normalize_max_tokens(
                            job.get("max_tokens"),
                            default=500,
                        )

                        chunks = []

                        for token_text in _vlm_stream_text(
                            resolved_model,
                            prompt_text=prompt_text,
                            max_tokens=vlm_max_tokens,
                            temperature=job.get("temperature", 0.7),
                            top_p=job.get("top_p", 1.0),
                            stop_event=stop_event,
                            allow_tool_calls=allow_tool_calls,
                            enable_thinking=enable_thinking,
                            thinking_budget=thinking_budget,
                        ):
                            if stop_event is not None and stop_event.is_set():
                                break

                            chunks.append(token_text)

                        raw = "".join(chunks)

                        if not allow_tool_calls:
                            raw = strip_vlm_artifacts(raw)

                    else:
                        sampler = make_sampler(
                            temp=job.get("temperature", 0.3),
                            top_p=job.get("top_p", 1.0),
                        )
                        _ensure_llm_model_loaded(resolved_model)

                        prompt = _build_chat_prompt_for_worker(
                            job["messages"],
                            enable_thinking=enable_thinking,
                        )

                        raw = mlx_generate_mod.generate(
                            mlx_llm_model,
                            mlx_llm_tokenizer,
                            prompt=prompt,
                            max_tokens=job.get("max_tokens", 500),
                            sampler=sampler,
                            verbose=False,
                        )

                    if job.get("clean_artifacts", True):
                        result = strip_llm_artifacts(
                            raw,
                            remove_reasoning=job.get("remove_reasoning", True),
                        )
                    else:
                        result = raw

                    _put_queue_interruptible(out_q, ("result", result), stop_event)

                except Exception as e:
                    _llm_log.exception("LLM generate job failed")
                    _put_queue_interruptible(out_q, ("error", str(e)), stop_event)

            elif job_type == "stream":
                try:
                    requested_model, resolved_model, backend, model_kind = (
                        resolve_generation_model_for_job(
                            job,
                            forced_model=forced_model,
                        )
                    )

                    enable_thinking, thinking_budget = _get_job_thinking_options(job)

                    if backend == "mlx_vlm":
                        allow_tool_calls = bool(job.get("allow_tool_calls"))
                        prompt_text = _messages_to_vlm_plain_prompt(
                            job["messages"], allow_tool_calls=allow_tool_calls
                        )

                        vlm_max_tokens = _normalize_max_tokens(
                            job.get("max_tokens"),
                            default=500,
                        )

                        for token_text in _vlm_stream_text(
                            resolved_model,
                            prompt_text=prompt_text,
                            max_tokens=vlm_max_tokens,
                            temperature=job.get("temperature", 0.7),
                            top_p=job.get("top_p", 1.0),
                            stop_event=stop_event,
                            allow_tool_calls=allow_tool_calls,
                            enable_thinking=enable_thinking,
                            thinking_budget=thinking_budget,
                        ):
                            if stop_event is not None and stop_event.is_set():
                                break

                            if not _put_queue_interruptible(
                                out_q,
                                ("token_text", token_text),
                                stop_event,
                            ):
                                break

                        _put_queue_interruptible(
                            out_q,
                            ("done", "stop"),
                            stop_event,
                        )

                        continue

                    # Existing mlx_lm streaming path
                    _ensure_llm_model_loaded(resolved_model)

                    sampler = make_sampler(
                        temp=job.get("temperature", 0.7),
                        top_p=job.get("top_p", 1.0),
                    )

                    prompt = _build_chat_prompt_for_worker(
                        job["messages"],
                        enable_thinking=enable_thinking,
                    )

                    if not _put_queue_interruptible(
                        out_q,
                        ("prompt", prompt),
                        stop_event,
                    ):
                        continue

                    last_finish_reason = None

                    for gen_resp in mlx_generate_mod.stream_generate(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                        mlx_llm_model,
                        mlx_llm_tokenizer,
                        prompt=prompt,
                        max_tokens=job.get("max_tokens", 500),
                        sampler=sampler,
                    ):
                        if stop_event is not None and stop_event.is_set():
                            break

                        fr = getattr(gen_resp, "finish_reason", None)
                        if fr is not None:
                            last_finish_reason = (
                                fr.value if hasattr(fr, "value") else str(fr).lower()
                            )

                        if not _put_queue_interruptible(
                            out_q,
                            ("token", gen_resp),
                            stop_event,
                        ):
                            break

                    _put_queue_interruptible(
                        out_q,
                        ("done", last_finish_reason),
                        stop_event,
                    )

                except FileNotFoundError as exc:
                    # Missing offline model snapshots are expected operational
                    # configuration errors. Keep the message actionable without
                    # emitting the chained Hugging Face traceback.
                    error_message = re.sub(r"\s+", " ", str(exc)).strip()
                    _llm_log.error("LLM model unavailable: %s", error_message)
                    _put_queue_interruptible(
                        out_q,
                        ("error", error_message),
                        stop_event,
                    )
                except Exception as exc:
                    _llm_log.exception("stream_generate failed")
                    _put_queue_interruptible(
                        out_q,
                        ("error", str(exc)),
                        stop_event,
                    )

            elif job_type == "embed":
                try:
                    model_id = resolve_embed_model_name(job.get("model"))
                    _ensure_embed_model_loaded(model_id)

                    texts = job.get("texts") or []
                    batch_size = int(job.get("batch_size") or DEFAULT_EMBED_BATCH_SIZE)

                    vectors = _embed_texts_in_worker(
                        embed_model,
                        embed_processor,
                        texts,
                        batch_size=batch_size,
                    )

                    _put_queue_interruptible(
                        out_q,
                        ("result", vectors),
                        stop_event,
                    )

                except Exception as e:
                    _embedding_log.exception("Embed job failed")
                    _put_queue_interruptible(
                        out_q,
                        ("error", str(e)),
                        stop_event,
                    )

            elif job_type == "rerank":
                try:
                    model_id = resolve_rerank_model_name(job.get("model"))
                    _ensure_rerank_model_loaded(model_id)

                    query = job.get("query") or ""
                    docs = job.get("docs") or []
                    batch_size = int(job.get("batch_size") or DEFAULT_RERANK_BATCH_SIZE)

                    scores, score_method = _rerank_in_worker(
                        rerank_model,
                        rerank_processor,
                        query,
                        docs,
                        batch_size=batch_size,
                    )

                    _put_queue_interruptible(
                        out_q,
                        (
                            "result",
                            {
                                "scores": scores,
                                "score_method": score_method,
                            },
                        ),
                        stop_event,
                    )

                except Exception as e:
                    _rerank_log.exception("Rerank job failed")
                    _put_queue_interruptible(
                        out_q,
                        ("error", str(e)),
                        stop_event,
                    )

            elif job_type == "completion":
                try:
                    requested_model, resolved_model, backend, model_kind = (
                        resolve_generation_model_for_job(
                            job,
                            forced_model=forced_model,
                        )
                    )

                    prompt = job.get("prompt") or ""

                    if backend == "mlx_vlm":
                        vlm_max_tokens = _normalize_max_tokens(
                            job.get("max_tokens"),
                            default=256,
                        )

                        raw = _vlm_generate_text(
                            resolved_model,
                            prompt_text=prompt,
                            max_tokens=vlm_max_tokens,
                            temperature=job.get("temperature", 0.7),
                            top_p=job.get("top_p", 1.0),
                            stop_event=stop_event,
                        )

                        _put_queue_interruptible(
                            out_q,
                            ("result", raw),
                            stop_event,
                        )

                        continue

                    else:
                        _ensure_llm_model_loaded(resolved_model)

                        sampler = make_sampler(
                            temp=job.get("temperature", 0.7),
                            top_p=job.get("top_p", 1.0),
                        )

                        raw = mlx_generate_mod.generate(
                            mlx_llm_model,
                            mlx_llm_tokenizer,
                            prompt=prompt,
                            max_tokens=job.get("max_tokens", 500),
                            sampler=sampler,
                            verbose=False,
                        )

                    _put_queue_interruptible(
                        out_q,
                        ("result", raw),
                        stop_event,
                    )

                except Exception as e:
                    _llm_log.exception("LLM completion job failed")
                    _put_queue_interruptible(
                        out_q,
                        ("error", str(e)),
                        stop_event,
                    )

            elif job_type == "completion_stream":
                try:
                    requested_model, resolved_model, backend, model_kind = (
                        resolve_generation_model_for_job(
                            job,
                            forced_model=forced_model,
                        )
                    )

                    prompt = job.get("prompt") or ""

                    if backend == "mlx_vlm":
                        vlm_max_tokens = _normalize_max_tokens(
                            job.get("max_tokens"),
                            default=256,
                        )

                        for token_text in _vlm_stream_text(
                            resolved_model,
                            prompt_text=prompt,
                            max_tokens=vlm_max_tokens,
                            temperature=job.get("temperature", 0.7),
                            top_p=job.get("top_p", 1.0),
                            stop_event=stop_event,
                        ):
                            if stop_event is not None and stop_event.is_set():
                                break

                            if not _put_queue_interruptible(
                                out_q,
                                ("token_text", token_text),
                                stop_event,
                            ):
                                break

                        _put_queue_interruptible(
                            out_q,
                            ("done", "stop"),
                            stop_event,
                        )

                        continue

                    # Existing mlx_lm completion_stream path
                    _ensure_llm_model_loaded(resolved_model)

                    sampler = make_sampler(
                        temp=job.get("temperature", 0.7),
                        top_p=job.get("top_p", 1.0),
                    )

                    last_finish_reason = None

                    for gen_resp in mlx_generate_mod.stream_generate(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                        mlx_llm_model,
                        mlx_llm_tokenizer,
                        prompt=prompt,
                        max_tokens=job.get("max_tokens", 500),
                        sampler=sampler,
                    ):
                        if stop_event is not None and stop_event.is_set():
                            break

                        fr = getattr(gen_resp, "finish_reason", None)

                        if fr is not None:
                            last_finish_reason = (
                                fr.value if hasattr(fr, "value") else str(fr).lower()
                            )

                        if not _put_queue_interruptible(
                            out_q,
                            ("token", gen_resp),
                            stop_event,
                        ):
                            break

                    _put_queue_interruptible(
                        out_q,
                        ("done", last_finish_reason),
                        stop_event,
                    )

                except FileNotFoundError as exc:
                    error_message = re.sub(r"\s+", " ", str(exc)).strip()
                    _llm_log.error("Completion model unavailable: %s", error_message)
                    _put_queue_interruptible(
                        out_q,
                        ("error", error_message),
                        stop_event,
                    )
                except Exception as exc:
                    _llm_log.exception("completion stream_generate failed")
                    _put_queue_interruptible(
                        out_q,
                        ("error", str(exc)),
                        stop_event,
                    )

            else:
                _put_queue_interruptible(
                    out_q,
                    ("error", f"Unknown LLM job type: {job_type}"),
                    stop_event,
                )

        finally:
            try:
                LLM_JOB_QUEUE.task_done()
            except Exception:
                pass

    LLM_WORKER_STOPPED.set()
    _llm_log.debug("LLM worker thread stopped")


def start_llm_worker():
    """
    Start the dedicated LLM worker thread once.
    """
    global LLM_WORKER_THREAD

    with LLM_WORKER_START_LOCK:
        if LLM_WORKER_THREAD is not None and LLM_WORKER_THREAD.is_alive():
            return

        if SERVER_SHUTTING_DOWN.is_set():
            raise RuntimeError("Cannot start LLM worker during shutdown")

        LLM_WORKER_READY.clear()
        LLM_WORKER_STOPPED.clear()

        thread = threading.Thread(
            target=_llm_worker_loop,
            daemon=True,
            name="LLMWorker",
        )

        LLM_WORKER_THREAD = thread
        thread.start()

    if not LLM_WORKER_READY.wait(timeout=10):
        _llm_log.warning("LLM worker did not become ready within timeout")


def wake_llm_control_fifo():
    try:
        if os.path.exists(LLM_CONTROL_FIFO):
            fd = os.open(
                LLM_CONTROL_FIFO,
                os.O_WRONLY | os.O_NONBLOCK,
            )

            try:
                os.write(fd, b"shutdown\n")
            finally:
                os.close(fd)

    except OSError:
        pass


def _cancel_pending_llm_jobs_for_shutdown() -> int:
    """
    Remove queued, not-yet-started LLM jobs during shutdown.

    Each removed job is notified through its stop_event and out_q.
    The currently executing job is not affected by this function.
    """
    cancelled = 0
    shutdown_sentinel_seen = False

    while True:
        try:
            job = LLM_JOB_QUEUE.get_nowait()

        except queue.Empty:
            break

        try:
            if job is None:
                shutdown_sentinel_seen = True
                continue

            cancelled += 1

            if isinstance(job, dict):
                stop_event = job.get("stop_event")

                if isinstance(
                    stop_event,
                    threading.Event,
                ):
                    stop_event.set()

                out_q = job.get("out_q")

                if out_q is not None:
                    try:
                        out_q.put_nowait(
                            (
                                "error",
                                "Server is shutting down",
                            )
                        )

                    except queue.Full:
                        pass

                    except Exception:
                        pass

        finally:
            try:
                LLM_JOB_QUEUE.task_done()
            except ValueError:
                pass

    # If a sentinel was already present, restore exactly one.
    if shutdown_sentinel_seen:
        try:
            LLM_JOB_QUEUE.put_nowait(None)
        except queue.Full:
            pass

    if cancelled:
        _llm_log.info(
            "Cancelled %d queued LLM job(s) during shutdown",
            cancelled,
        )

    return cancelled


def stop_llm_worker(
    timeout: float = 10.0,
):
    """
    Stop the dedicated LLM worker.

    Shutdown strategy:
    1. Try to enqueue a sentinel without disturbing queued jobs.
    2. If the queue remains full, cancel pending jobs.
    3. Enqueue the sentinel after space is available.
    4. Wait briefly; never block process exit on native MLX teardown or inference.
    """
    thread = LLM_WORKER_THREAD

    if thread is None or not thread.is_alive():
        _llm_log.info("LLM worker is already stopped")

        return

    try:
        timeout = max(
            0.1,
            float(timeout),
        )

    except (TypeError, ValueError):
        timeout = 10.0

    sentinel_queued = False

    gentle_deadline = time.monotonic() + min(
        timeout,
        2.0,
    )

    # First try to preserve queued jobs.
    while time.monotonic() < gentle_deadline:
        try:
            LLM_JOB_QUEUE.put(
                None,
                timeout=0.1,
            )

            sentinel_queued = True
            break

        except queue.Full:
            continue

    if not sentinel_queued:
        _llm_log.warning(
            "LLM job queue remained full during shutdown; cancelling queued jobs"
        )

        _cancel_pending_llm_jobs_for_shutdown()

        try:
            LLM_JOB_QUEUE.put(
                None,
                timeout=1.0,
            )

            sentinel_queued = True

        except queue.Full:
            _llm_log.error(
                "Unable to enqueue LLM worker "
                "shutdown sentinel even after "
                "clearing queued jobs"
            )

    join_started_at = time.monotonic()

    thread.join(timeout=timeout)

    if thread.is_alive():
        _llm_log.warning(
            "LLM worker is still alive after "
            "%.1fs shutdown timeout; "
            "sentinel_queued=%s "
            "elapsed=%.1fs",
            timeout,
            sentinel_queued,
            (time.monotonic() - join_started_at),
        )

    else:
        _llm_log.debug("LLM worker stopped cleanly")


def resolve_generation_model_for_job(
    job: dict,
    forced_model: Optional[str] = None,
) -> tuple[str, str, str, str]:
    """
    Returns:
        requested_model, resolved_model, backend, model_kind
    """
    model_kind = job.get("model_kind", "llm")

    if forced_model and model_kind == "llm":
        requested_model = forced_model
    else:
        requested_model = job.get("model")

    if model_kind == "fim":
        requested_model = requested_model or DEFAULT_FIM_ALIAS
        resolved_model = resolve_fim_model_name(requested_model)
        backend = resolve_fim_backend(requested_model, resolved_model)
        return requested_model, resolved_model, backend, model_kind

    requested_model = requested_model or DEFAULT_LLM_ALIAS
    resolved_model = resolve_llm_model_name(requested_model)
    backend = resolve_llm_backend(requested_model, resolved_model)
    return requested_model, resolved_model, backend, model_kind


class LLMQueueFullError(RuntimeError):
    pass


def _purge_pending_xiaoai_jobs() -> int:
    kept = []
    removed = 0
    while True:
        try:
            job = LLM_JOB_QUEUE.get_nowait()
        except queue.Empty:
            break
        try:
            if isinstance(job, dict) and job.get("source") == "xiaoai":
                removed += 1
                stop_event = job.get("stop_event")
                if isinstance(stop_event, threading.Event):
                    stop_event.set()
                out_q = job.get("out_q")
                if out_q is not None:
                    try:
                        out_q.put_nowait(("error", "Superseded by newer XiaoAI query"))
                    except Exception:
                        pass
            else:
                kept.append(job)
        finally:
            try:
                LLM_JOB_QUEUE.task_done()
            except ValueError:
                pass
    for job in kept:
        LLM_JOB_QUEUE.put_nowait(job)
    if removed:
        _llm_log.info("Compacted %d pending XiaoAI LLM job(s)", removed)
    return removed


def _submit_llm_job(
    job: dict,
    *,
    timeout: float = 0.5,
) -> None:
    if SERVER_SHUTTING_DOWN.is_set():
        raise RuntimeError("Server is shutting down")

    job["submitted_at"] = time.monotonic()

    if job.get("source") == "xiaoai":
        _purge_pending_xiaoai_jobs()

    try:
        LLM_JOB_QUEUE.put(
            job,
            timeout=timeout,
        )

    except queue.Full as exc:
        raise LLMQueueFullError("MLX inference queue is full") from exc


def _submit_completion_job(
    prompt: str,
    model: Optional[str] = None,
    model_kind: str = "llm",
    max_tokens: int = 256,
    temperature: float = 0.7,
    top_p: float = 1.0,
    timeout: float = 180.0,
) -> Optional[str]:
    if SERVER_SHUTTING_DOWN.is_set():
        return None

    start_llm_worker()

    out_q = queue.Queue(maxsize=4)
    stop_event = threading.Event()

    job = {
        "type": "completion",
        "model_kind": model_kind,
        "model": model or DEFAULT_LLM_ALIAS,
        "prompt": prompt,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "top_p": top_p,
        "out_q": out_q,
        "stop_event": stop_event,
    }

    _submit_llm_job(job)

    try:
        item = out_q.get(timeout=timeout)

    except queue.Empty as exc:
        stop_event.set()

        raise TimeoutError(
            f"Completion job timed out after {timeout:.1f} seconds"
        ) from exc

    if not isinstance(item, tuple):
        raise RuntimeError("Completion worker returned an invalid response")

    typ = item[0]

    payload = item[1] if len(item) > 1 else None

    if typ == "result":
        return payload

    if typ == "error":
        raise RuntimeError(str(payload))

    raise RuntimeError(
        f"Completion worker returned an unexpected response type: {typ!r}"
    )


def _submit_llm_generate_job(
    messages: list,
    model: Optional[str] = None,
    max_tokens: int = 500,
    temperature: float = 0.3,
    top_p: float = 1.0,
    clean_artifacts: bool = True,
    remove_reasoning: bool = True,
    allow_tool_calls: bool = False,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
    source: Optional[str] = None,
    timeout: float = 180.0,
) -> Optional[str]:
    """
    Submit a non-streaming generation job to the dedicated
    LLM worker and wait for its result.
    """
    if SERVER_SHUTTING_DOWN.is_set():
        raise RuntimeError("Server is shutting down")

    start_llm_worker()

    out_q = queue.Queue(maxsize=4)
    stop_event = threading.Event()

    job = {
        "type": "generate",
        "messages": messages,
        "model": model or DEFAULT_LLM_ALIAS,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "top_p": top_p,
        "clean_artifacts": clean_artifacts,
        "remove_reasoning": remove_reasoning,
        "allow_tool_calls": allow_tool_calls,
        "enable_thinking": enable_thinking,
        "thinking_budget": thinking_budget,
        "source": source,
        "out_q": out_q,
        "stop_event": stop_event,
    }

    # 队列满时，这里应抛出 LLMQueueFullError。
    _submit_llm_job(
        job,
        timeout=0.5,
    )

    try:
        item = out_q.get(timeout=timeout)

    except queue.Empty as exc:
        stop_event.set()

        raise TimeoutError(
            f"LLM generation job timed out after {timeout:.1f} seconds"
        ) from exc

    if not isinstance(item, tuple):
        raise RuntimeError("LLM worker returned an invalid response")

    typ = item[0]

    payload = item[1] if len(item) > 1 else None

    if typ == "result":
        return payload

    if typ == "error":
        raise RuntimeError(str(payload))

    raise RuntimeError(f"LLM worker returned an unexpected response type: {typ!r}")


def _submit_embed_job(
    texts: Union[str, list[str]],
    model: Optional[str] = None,
    batch_size: int = DEFAULT_EMBED_BATCH_SIZE,
    timeout: float = 120.0,
) -> Optional[list]:
    if SERVER_SHUTTING_DOWN.is_set():
        return None

    start_llm_worker()

    out_q = queue.Queue(maxsize=4)
    stop_event = threading.Event()

    job = {
        "type": "embed",
        "model": resolve_embed_model_name(model),
        "texts": texts,
        "batch_size": batch_size,
        "out_q": out_q,
        "stop_event": stop_event,
    }

    _submit_llm_job(job)

    try:
        item = out_q.get(timeout=timeout)

    except queue.Empty as exc:
        stop_event.set()

        raise TimeoutError(
            f"Embed generation job timed out after {timeout:.1f} seconds"
        ) from exc

    if not isinstance(item, tuple):
        raise RuntimeError("Embed worker returned an invalid response")

    typ = item[0]

    payload = item[1] if len(item) > 1 else None

    if typ == "result":
        return payload

    if typ == "error":
        raise RuntimeError(str(payload))

    raise RuntimeError(f"Embed worker returned an unexpected response type: {typ!r}")


def _submit_rerank_job(
    query: str,
    docs: list,
    model: Optional[str] = None,
    batch_size: int = DEFAULT_RERANK_BATCH_SIZE,
    timeout: float = 120.0,
) -> Optional[RerankPayload]:
    if SERVER_SHUTTING_DOWN.is_set():
        return None

    start_llm_worker()

    out_q = queue.Queue(maxsize=4)
    stop_event = threading.Event()

    job = {
        "type": "rerank",
        "model": resolve_rerank_model_name(model),
        "query": query,
        "docs": docs,
        "batch_size": batch_size,
        "out_q": out_q,
        "stop_event": stop_event,
    }

    _submit_llm_job(job)

    try:
        item = out_q.get(timeout=timeout)

    except queue.Empty as exc:
        stop_event.set()

        raise TimeoutError(
            f"Rerank generation job timed out after {timeout:.1f} seconds"
        ) from exc

    if not isinstance(item, tuple):
        raise RuntimeError("Rerank worker returned an invalid response")

    typ = item[0]

    payload = item[1] if len(item) > 1 else None

    if typ == "result":
        return payload

    if typ == "error":
        raise RuntimeError(str(payload))

    raise RuntimeError(f"Rerank worker returned an unexpected response type: {typ!r}")


def _generate_llm_text_via_worker(
    messages: list,
    model: Optional[str] = None,
    max_tokens: int = 500,
    temperature: float = 0.3,
    top_p: float = 1.0,
    clean_artifacts: bool = True,
    remove_reasoning: bool = True,
    allow_tool_calls: bool = False,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
    source: Optional[str] = None,
) -> Optional[str]:
    """
    Normalize messages, submit generation to the dedicated
    LLM worker, and wait for the result.

    This function does not execute MLX inference directly.
    """
    try:
        normalized_messages = normalize_chat_messages_for_template(messages)

        return _submit_llm_generate_job(
            messages=normalized_messages,
            model=model,
            max_tokens=max_tokens,
            temperature=temperature,
            top_p=top_p,
            clean_artifacts=clean_artifacts,
            remove_reasoning=remove_reasoning,
            allow_tool_calls=allow_tool_calls,
            enable_thinking=enable_thinking,
            thinking_budget=thinking_budget,
            source=source,
        )

    except LLMQueueFullError:
        # 必须让 HTTP 层有机会返回 503。
        raise

    except Exception as exc:
        _llm_log.warning(
            "MLX LLM generation error: %s",
            exc,
            exc_info=True,
        )

        return None


def strip_llm_artifacts(text: str, remove_reasoning: bool = True) -> str:
    """
    Remove model-side artifacts from raw mlx_lm output.

    Handles:
    - reasoning traces:
      - <think>...</think>
      - reasoning...</think>answer
      - <think>reasoning...
    - chat / EOS special markers:
      - <|im_end|>
      - <|endoftext|>
      - <|eot_id|>
      - <|end|>
      - </s>
    - HTML-escaped variants
    - echoed labels
    """
    if not text:
        return ""

    text = text.strip()

    # Normalize common escaped markers.
    text = text.replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")

    if remove_reasoning:
        # If there is any closing think tag, keep only content after the LAST one.
        # This handles: reasoning...</think>final answer
        close_matches = list(re.finditer(r"</think\s*>", text, flags=re.IGNORECASE))
        if close_matches:
            text = text[close_matches[-1].end() :].strip()

        # Remove complete think blocks that still remain.
        text = re.sub(
            r"<think\b[^>]*>.*?</think\s*>",
            "",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        ).strip()

        # Remove dangling opening think block.
        text = re.sub(
            r"<think\b[^>]*>.*",
            "",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        ).strip()

    # Cut at EOS/chat markers like <|im_end|>.
    text, _ = cut_at_llm_stop_marker(text)
    text = text.strip()

    # Remove common answer labels.
    text = re.sub(
        r"^\s*(Corrected text|Correction|Output|Answer|Final|Final answer|"
        r"结果|修正后|修正文本|最终答案)\s*[:：]\s*",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()

    # Remove wrapping quotes if the whole answer is quoted.
    if len(text) >= 2:
        quote_pairs = [
            ('"', '"'),
            ("'", "'"),
            ("“", "”"),
            ("「", "」"),
            ("『", "』"),
        ]
        for left, right in quote_pairs:
            if text.startswith(left) and text.endswith(right):
                text = text[1:-1].strip()
                break

    return text


def strip_vlm_artifacts(text: str) -> str:
    if not text:
        return ""

    text, _ = cut_at_stop_sequences(text, VLM_STOP_SEQUENCES)

    # 清理已经泄漏出来的工具调用块
    text = re.sub(
        r"<\|tool_call\|>.*?(<tool_call\|>|$)",
        "",
        text,
        flags=re.DOTALL,
    )

    text = re.sub(
        r"<\|channel\>.*?(<channel\|>|$)",
        "",
        text,
        flags=re.DOTALL,
    )

    # 防止 GoalGoalGoal 这种退化尾巴
    text = re.sub(r"(Goal){5,}.*$", "", text, flags=re.DOTALL)

    return text.strip()


def correct_text_sync(text: str, context: str = "") -> str:
    """Correct transcription errors using LLM."""
    result = _generate_llm_text_via_worker(
        messages=[
            {
                "role": "system",
                "content": (
                    "You are a transcription corrector. Your ONLY job is to fix errors in dictated text.\n"
                    "CRITICAL RULES:\n"
                    "1. PRESERVE the original language. If the input is English, output English. If Chinese, output Chinese. If a mix, stay a mix. NEVER translate.\n"
                    "2. Fix obvious transcription errors (misheard words, homophones).\n"
                    "3. Add appropriate punctuation.\n"
                    "4. If Chinese text contains Traditional characters, convert to Simplified (繁體→简体).\n"
                    "5. Do NOT change meaning, add content, or remove content.\n"
                    "6. Output ONLY the corrected text.\n"
                    "7. DO NOT output reasoning, analysis, explanations, markdown, XML tags, or <think> blocks.\n"
                    "8. Do not think step by step.\n"
                    "9. Do not use <think> or </think>. If you need to reason, do it silently."
                ),
            },
            {
                "role": "user",
                "content": f"Dictated text: {text}\n\nCorrected text:",
            },
        ],
        model=DICTATION_CORRECTION_MODEL,
        max_tokens=500,
        temperature=0.1,
    )

    if result:
        return result

    _llm_log.warning("LLM correction failed, using raw text")
    return text


def _complete_missing_json_closers(
    text: str,
    *,
    max_missing_closers: int = 8,
) -> str:
    """
    Append only missing trailing JSON object/array closers.

    This function does not repair:

    - missing commas
    - invalid object keys
    - unescaped quotes
    - unterminated strings
    - mismatched brackets
    - unexpected closing brackets
    - malformed content in the middle

    Examples:

        {"name":"search_web","arguments":{"query":"x"}

    becomes:

        {"name":"search_web","arguments":{"query":"x"}}


        call:search_web{query:"x"

    becomes:

        call:search_web{query:"x"}


        {"name":"x","arguments":{"items":[1,2,3]}

    becomes:

        {"name":"x","arguments":{"items":[1,2,3]}}

    Args:
        text:
            Raw tool-call payload.

        max_missing_closers:
            Maximum number of trailing braces/brackets that may be
            appended. This prevents accepting severely truncated output.

    Returns:
        Original text plus any required trailing '}' or ']'.

    Raises:
        ValueError:
            If strings are unterminated, brackets are mismatched,
            an unexpected closing bracket is found, or too many
            closers would be required.
    """
    text = str(text or "")

    stack: list[str] = []

    quote_char: Optional[str] = None
    escaped = False

    for index, char in enumerate(text):
        # ----------------------------------------------------
        # Inside a quoted string
        # ----------------------------------------------------
        if quote_char is not None:
            if escaped:
                escaped = False
                continue

            if char == "\\":
                escaped = True
                continue

            if char == quote_char:
                quote_char = None

            continue

        # ----------------------------------------------------
        # Enter a quoted string
        # ----------------------------------------------------
        if char in ('"', "'"):
            quote_char = char
            continue

        # ----------------------------------------------------
        # Opening object/array
        # ----------------------------------------------------
        if char in ("{", "["):
            stack.append(char)
            continue

        # ----------------------------------------------------
        # Closing object/array
        # ----------------------------------------------------
        if char in ("}", "]"):
            if not stack:
                raise ValueError(
                    f"Unexpected closing bracket {char!r} at offset {index}"
                )

            opening = stack.pop()

            expected_closing = "}" if opening == "{" else "]"

            if char != expected_closing:
                raise ValueError(
                    "Mismatched brackets at offset "
                    f"{index}: opening={opening!r}, "
                    f"closing={char!r}, "
                    f"expected={expected_closing!r}"
                )

    # An incomplete quoted string is not safe to repair by merely
    # appending braces.
    if quote_char is not None:
        raise ValueError(
            f"Cannot repair tool payload because {quote_char!r} string is unterminated"
        )

    if len(stack) > max_missing_closers:
        raise ValueError(
            "Tool payload requires too many trailing "
            f"closers: required={len(stack)}, "
            f"maximum={max_missing_closers}"
        )

    closers: list[str] = []

    while stack:
        opening = stack.pop()

        closers.append("}" if opening == "{" else "]")

    return text + "".join(closers)


# ==================== Recording ====================


def _begin_question_recording_session() -> int:
    """
    Start a new interactive question-recording session.

    Returns:
        The generation assigned to this session.
    """
    global QUESTION_RECORDING_ACTIVE
    global QUESTION_RECORDING_GENERATION
    global QUESTION_RECORDING_ESC_TIMER
    global QUESTION_RECORDING_LAST_ESC_AT

    with QUESTION_RECORDING_LOCK:
        old_timer = QUESTION_RECORDING_ESC_TIMER

        QUESTION_RECORDING_ESC_TIMER = None
        QUESTION_RECORDING_LAST_ESC_AT = 0.0

        QUESTION_RECORDING_GENERATION += 1

        generation = QUESTION_RECORDING_GENERATION

        QUESTION_RECORDING_STOP.clear()
        QUESTION_RECORDING_SKIP.clear()
        QUESTION_RECORDING_CANCEL_ALL.clear()

        QUESTION_RECORDING_ACTIVE = True

    if old_timer is not None:
        try:
            old_timer.cancel()
        except Exception:
            pass

    _dictation_log.debug(
        "Interactive question recording session started: generation=%d",
        generation,
    )

    return generation


def _end_question_recording_session(
    generation: int,
):
    """
    End one interactive question-recording session.

    A stale session is not allowed to clear the state of a newer
    question.
    """
    global QUESTION_RECORDING_ACTIVE
    global QUESTION_RECORDING_ESC_TIMER
    global QUESTION_RECORDING_LAST_ESC_AT

    timer = None

    with QUESTION_RECORDING_LOCK:
        if generation != QUESTION_RECORDING_GENERATION:
            _dictation_log.debug(
                "Ignoring stale question-recording cleanup: generation=%d current=%d",
                generation,
                QUESTION_RECORDING_GENERATION,
            )

            return

        QUESTION_RECORDING_ACTIVE = False
        QUESTION_RECORDING_LAST_ESC_AT = 0.0

        timer = QUESTION_RECORDING_ESC_TIMER

        QUESTION_RECORDING_ESC_TIMER = None

    if timer is not None:
        try:
            timer.cancel()
        except Exception:
            pass

    _dictation_log.debug(
        "Interactive question recording session ended: generation=%d",
        generation,
    )


def record_audio_interactive(
    question: str,
    num: int,
    total: int,
    cancel_flag: dict,
) -> Optional[np.ndarray]:
    """
    Record one answer for ask_user_dictation().

    Keyboard behavior:
    - Enter:
        Stop and keep the current recording.
    - Single ESC:
        Skip the current question.
    - Double ESC:
        Cancel the current and all remaining questions.
    """
    global IS_DICTATION_ACTIVE

    audio_chunks = []
    total_frames = 0
    recording = True

    was_skipped = False
    was_cancelled_all = False

    question_generation = _begin_question_recording_session()

    with DICTATION_LOCK:
        IS_DICTATION_ACTIVE = True

    def audio_callback(
        indata,
        frames,
        time_info,
        status,
    ):
        nonlocal total_frames

        if not recording:
            return

        if total_frames >= MAX_AUDIO_BUFFER_SIZE:
            return

        remaining = MAX_AUDIO_BUFFER_SIZE - total_frames

        chunk = indata[
            : min(
                frames,
                remaining,
            ),
            0,
        ].copy()

        audio_chunks.append(chunk)

        total_frames += len(chunk)

    hud.show(
        "recording",
        f"Question {num}/{total}",
        question,
    )

    _dictation_log.debug(
        "Dictation Q%d/%d: %s...",
        num,
        total,
        question[:60],
    )

    stream = None

    try:
        try:
            stream = _open_audio_input_stream(audio_callback)

        except Exception as exc:
            _audio_log.error(
                "Failed to open audio input stream: %s",
                exc,
            )

            hud.show(
                "dictation_error",
                f"Question {num}/{total}",
                question,
            )

            time.sleep(2.0)

            return None

        with stream:
            while True:
                if SERVER_SHUTTING_DOWN.is_set():
                    cancel_flag["cancel_all"] = True

                    break

                if QUESTION_RECORDING_CANCEL_ALL.is_set():
                    was_cancelled_all = True
                    cancel_flag["cancel_all"] = True

                    _dictation_log.debug(
                        "Interactive question recording cancelled all: generation=%d",
                        question_generation,
                    )

                    break

                if QUESTION_RECORDING_SKIP.is_set():
                    was_skipped = True
                    _dictation_log.debug(
                        "Interactive question recording skipped: generation=%d",
                        question_generation,
                    )

                    break

                if QUESTION_RECORDING_STOP.is_set():
                    _dictation_log.debug(
                        "Interactive question "
                        "recording stopped: "
                        "generation=%d "
                        "frames=%d",
                        question_generation,
                        total_frames,
                    )

                    break

                if total_frames >= MAX_AUDIO_BUFFER_SIZE:
                    _audio_log.warning("Interactive recording reached maximum length")

                    break

                time.sleep(0.02)

    finally:
        recording = False

        # `with stream` has already stopped/closed the stream before
        # IS_DICTATION_ACTIVE is cleared.
        with DICTATION_LOCK:
            IS_DICTATION_ACTIVE = False

        _end_question_recording_session(question_generation)

    if was_cancelled_all:
        hud.show(
            "cancelled_all",
            f"Question {num}/{total}",
            question,
        )

        time.sleep(1.0)

        return None

    if was_skipped:
        hud.show(
            "skipped",
            f"Question {num}/{total}",
            question,
        )

        time.sleep(0.8)

        return None

    if total_frames >= MAX_AUDIO_BUFFER_SIZE:
        _audio_log.warning("Recording reached maximum length, truncating")

    if not audio_chunks:
        return None

    try:
        return np.concatenate(audio_chunks)

    except Exception as exc:
        _audio_log.error(
            "Failed to concatenate interactive recording: %s",
            exc,
        )

        return None


def transcribe_question_with_apple_speech() -> tuple[str, Optional[str]]:
    """Return (status, text) for one ask_user_dictation recording.

    Status is one of: ok, skipped, cancelled, or no_speech. This function does
    not display or hide the HUD; ask_user_dictation retains the original HUD
    lifecycle unchanged.
    """
    global IS_DICTATION_ACTIVE

    question_generation = _begin_question_recording_session()
    with DICTATION_LOCK:
        IS_DICTATION_ACTIVE = True
    try:
        text = _run_apple_speech_dictation(
            DICTATION_LOCALE_DEFAULT,
            generation=None,
            question_generation=question_generation,
        )
        with QUESTION_RECORDING_LOCK:
            cancelled = QUESTION_RECORDING_CANCEL_ALL.is_set()
            skipped = QUESTION_RECORDING_SKIP.is_set()
    finally:
        with DICTATION_LOCK:
            IS_DICTATION_ACTIVE = False
        _end_question_recording_session(question_generation)

    if cancelled:
        return "cancelled", None
    if skipped:
        return "skipped", None
    text = str(text or "").strip()
    if not text:
        return "no_speech", None
    return "ok", text


def _handle_enter_during_question_recording() -> bool:
    """
    Route Enter to the active interactive-question recorder.

    Returns:
        True when Enter was consumed by question recording.
        False when no question recording is active.
    """
    with QUESTION_RECORDING_LOCK:
        if not QUESTION_RECORDING_ACTIVE:
            return False

        generation = QUESTION_RECORDING_GENERATION

        if QUESTION_RECORDING_CANCEL_ALL.is_set():
            return True

        if QUESTION_RECORDING_SKIP.is_set():
            return True

        QUESTION_RECORDING_STOP.set()

    _dictation_log.debug(
        "Enter swallowed during question "
        "recording: stop current answer "
        "(generation=%d)",
        generation,
    )

    return True


def _commit_question_single_escape(
    generation: int,
):
    """
    Commit a single ESC as 'skip current question'.

    This runs after ESC_DOUBLE_TAP_WINDOW has elapsed without a
    second ESC.
    """
    global QUESTION_RECORDING_ESC_TIMER
    global QUESTION_RECORDING_LAST_ESC_AT

    with QUESTION_RECORDING_LOCK:
        if not QUESTION_RECORDING_ACTIVE or generation != QUESTION_RECORDING_GENERATION:
            return

        QUESTION_RECORDING_ESC_TIMER = None
        QUESTION_RECORDING_LAST_ESC_AT = 0.0

        if QUESTION_RECORDING_CANCEL_ALL.is_set():
            return

        QUESTION_RECORDING_SKIP.set()

    _dictation_log.debug(
        "Single ESC committed during question "
        "recording: skip current question "
        "(generation=%d)",
        generation,
    )


def _handle_escape_during_question_recording() -> bool:
    """
    Handle ESC while interactive question recording is active.

    Behavior:
    - First ESC:
        Wait ESC_DOUBLE_TAP_WINDOW before committing a skip.
    - Second ESC within the window:
        Cancel the pending skip and cancel all questions.

    Returns:
        True when ESC belongs to question recording and should be
        swallowed.
        False when no interactive question recording is active.
    """
    global QUESTION_RECORDING_ESC_TIMER
    global QUESTION_RECORDING_LAST_ESC_AT

    now = time.monotonic()

    old_timer = None
    start_timer = None
    cancel_all = False
    generation = None

    with QUESTION_RECORDING_LOCK:
        if not QUESTION_RECORDING_ACTIVE:
            return False

        generation = QUESTION_RECORDING_GENERATION

        if (
            now - QUESTION_RECORDING_LAST_ESC_AT <= ESC_DOUBLE_TAP_WINDOW
            and QUESTION_RECORDING_LAST_ESC_AT > 0
        ):
            # Second ESC:
            # cancel the pending single-ESC skip and cancel all.
            old_timer = QUESTION_RECORDING_ESC_TIMER

            QUESTION_RECORDING_ESC_TIMER = None
            QUESTION_RECORDING_LAST_ESC_AT = 0.0

            QUESTION_RECORDING_CANCEL_ALL.set()

            cancel_all = True

        else:
            # First ESC:
            # do not skip immediately because a second ESC may arrive.
            old_timer = QUESTION_RECORDING_ESC_TIMER

            QUESTION_RECORDING_LAST_ESC_AT = now

            timer = threading.Timer(
                ESC_DOUBLE_TAP_WINDOW,
                _commit_question_single_escape,
                args=(generation,),
            )

            timer.daemon = True

            QUESTION_RECORDING_ESC_TIMER = timer
            start_timer = timer

    # Timer operations are performed outside the state lock.
    if old_timer is not None:
        try:
            old_timer.cancel()
        except Exception:
            pass

    if cancel_all:
        _dictation_log.debug(
            "Double ESC detected during question "
            "recording: cancel all questions "
            "(generation=%d)",
            generation,
        )

        # Stop any question TTS or leftover ffmpeg process as well.
        threading.Thread(
            target=stop_tts_immediately,
            kwargs={
                "reason": "question_double_esc",
            },
            daemon=True,
            name="QuestionDoubleEscCancelTTS",
        ).start()

    elif start_timer is not None:
        _dictation_log.debug(
            "First ESC detected during question "
            "recording; waiting %.2fs for "
            "possible second ESC "
            "(generation=%d)",
            ESC_DOUBLE_TAP_WINDOW,
            generation,
        )

        start_timer.start()

    # Always swallow ESC while question recording is active.
    return True


# ==================== Global Dictation (Ctrl+Opt Double-Tap) ====================


def _cancel_question_or_stop_speaking_from_esc():
    with QUESTION_RECORDING_LOCK:
        question_active = QUESTION_RECORDING_ACTIVE

        if question_active:
            QUESTION_RECORDING_CANCEL_ALL.set()

    cancel_active_dictation()

    stop_tts_immediately(reason="double_esc")

    return True


def _handle_escape_keydown_global():
    """
    Handle Escape keydown.

    Behavior:
    - During dictation: single ESC cancels dictation and is swallowed.
    - Otherwise: double-tap ESC cancels active question / stops speaking.
      First ESC passes through; second ESC is swallowed.
    """
    global _last_esc_tap_at, _suppress_esc_until

    now = time.monotonic()

    # Avoid duplicated ESC events after cancellation.
    if now < _suppress_esc_until:
        return True

    # Dictation active: single ESC cancels and should be swallowed.
    if _handle_escape_during_dictation():
        _last_esc_tap_at = 0.0
        _suppress_esc_until = now + 0.35
        return True

    # Not dictating: double-tap ESC.
    if now - _last_esc_tap_at <= ESC_DOUBLE_TAP_WINDOW:
        _last_esc_tap_at = 0.0
        _suppress_esc_until = now + 0.35

        _app_log.debug("Detected ESC double-tap via Quartz")

        threading.Thread(
            target=_cancel_question_or_stop_speaking_from_esc,
            daemon=True,
            name="EscDoubleTapCancel",
        ).start()

        # Swallow second ESC so it does not also hit foreground app.
        return True

    _last_esc_tap_at = now

    # First ESC should usually pass through when no dictation is active.
    return False


def _insert_text_at_cursor(text: str):
    """Insert text with NSPasteboard and guarded best-effort restoration."""
    if not HAS_APPKIT or NSPasteboard is None:
        _app_log.error("AppKit NSPasteboard unavailable; cannot insert text")
        return False

    pasteboard = NSPasteboard.generalPasteboard()
    try:
        original = pasteboard.stringForType_(NSPasteboardTypeString)
        inserted_text = str(text)

        pasteboard.clearContents()
        if not pasteboard.setString_forType_(
            inserted_text,
            NSPasteboardTypeString,
        ):
            raise RuntimeError("Failed setting NSPasteboard text")
        owned_change_count = int(pasteboard.changeCount())

        time.sleep(0.05)
        _press_cmd_v()

        # Give Electron/WebKit applications more time to consume the paste.
        time.sleep(0.8)
        if int(pasteboard.changeCount()) != owned_change_count:
            _dictation_log.debug(
                "Clipboard changed after dictation paste; skipping restore"
            )
            return True

        current = pasteboard.stringForType_(NSPasteboardTypeString)
        if current != inserted_text:
            _dictation_log.debug(
                "Clipboard contents changed after dictation paste; skipping restore"
            )
            return True

        pasteboard.clearContents()
        if original is not None:
            pasteboard.setString_forType_(
                str(original),
                NSPasteboardTypeString,
            )
        return True

    except Exception as exc:
        _app_log.error("Failed to insert text at cursor: %s", exc)
        return False


def _post_key_event(
    keycode: int,
    down: bool,
    flags: int = 0,
    *,
    user_data: int = 0,
):
    if not HAS_QUARTZ:
        return False

    event = Quartz.CGEventCreateKeyboardEvent(None, keycode, down)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    if flags:
        Quartz.CGEventSetFlags(event, flags)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
    if user_data:
        Quartz.CGEventSetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            event,
            Quartz.kCGEventSourceUserData,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            int(user_data),
        )

    Quartz.CGEventPost(Quartz.kCGHIDEventTap, event)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
    return True


def _tap_key(keycode: int, delay: float = 0.03, flags: int = 0):
    _post_key_event(keycode, True, flags=flags)
    time.sleep(delay)
    _post_key_event(keycode, False, flags=flags)


def _press_cmd_v():
    V_KEYCODE = 9
    cmd_flag = Quartz.kCGEventFlagMaskCommand  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    # Send Cmd+V directly by setting command flag on V key events.
    _tap_key(V_KEYCODE, delay=0.03, flags=cmd_flag)


def _press_enter_after_insert():
    """
    Re-send Enter after dictation text has been inserted.

    The synthetic event is tagged with kCGEventSourceUserData so the Quartz
    event tap can distinguish it from a physical Enter.
    """
    try:
        time.sleep(0.12)

        # Return key. Tag both events so the Quartz tap can distinguish the
        # synthetic replay from a physical Enter pressed at the same time.
        _post_key_event(
            36,
            True,
            user_data=SYNTHETIC_ENTER_EVENT_TAG,
        )
        time.sleep(0.03)
        _post_key_event(
            36,
            False,
            user_data=SYNTHETIC_ENTER_EVENT_TAG,
        )

        time.sleep(0.05)
        return True

    except Exception as e:
        _dictation_log.error(f"Failed to replay Enter after dictation insert: {e}")
        return False


def _compute_hud_stream_delta(
    last_partial: str, current_partial: str, hud_text: str
) -> str:
    """
    Compute append-only delta for live HUD preview.

    This compares the previous partial window with the current partial window,
    NOT hud_text with current_partial.

    Why:
    - current_partial may be only the latest rolling window
    - hud_text is accumulated full preview
    - comparing current_partial against hud_text often produces empty delta forever
    """
    last_partial = (last_partial or "").strip()
    current_partial = (current_partial or "").strip()
    hud_text = hud_text or ""

    if not current_partial:
        return ""

    if not last_partial:
        if current_partial in hud_text:
            return ""
        return current_partial

    if current_partial == last_partial:
        return ""

    # If current expands previous:
    # last:    今天下午
    # current: 今天下午三点开会
    # delta:       三点开会
    if current_partial.startswith(last_partial):
        return current_partial[len(last_partial) :]

    # If current is already visible in HUD, do nothing.
    if current_partial in hud_text:
        return ""

    # If previous partial appears inside current partial:
    idx = current_partial.find(last_partial)
    if idx != -1:
        return current_partial[idx + len(last_partial) :]

    # Suffix-prefix overlap:
    # last:    今天下午三点
    # current:       三点开会
    # delta:            开会
    max_overlap = min(len(last_partial), len(current_partial))
    best = 0

    for n in range(max_overlap, 0, -1):
        if last_partial[-n:] == current_partial[:n]:
            best = n
            break

    if best >= 2:
        return current_partial[best:]

    # If no overlap, this is probably a new rolling-window phrase.
    # For HUD preview, append it instead of replacing old text.
    return current_partial


def _register_apple_speech_process(proc: subprocess.Popen):
    global CURRENT_APPLE_SPEECH_PROCESS

    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        previous = CURRENT_APPLE_SPEECH_PROCESS

        if previous is not None and previous is not proc and previous.poll() is None:
            raise RuntimeError(
                f"Another Apple Speech helper is still running: pid={previous.pid}"
            )

        CURRENT_APPLE_SPEECH_PROCESS = proc


def _clear_apple_speech_process_if_exited(
    proc: subprocess.Popen,
) -> bool:
    global CURRENT_APPLE_SPEECH_PROCESS
    global _LAST_APPLE_SPEECH_EXIT_AT

    if proc.poll() is None:
        return False

    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        if CURRENT_APPLE_SPEECH_PROCESS is proc:
            CURRENT_APPLE_SPEECH_PROCESS = None
            _LAST_APPLE_SPEECH_EXIT_AT = time.monotonic()

            _app_log.info(
                "Cleared exited Apple Speech helper reference: pid=%s, returncode=%s",
                proc.pid,
                proc.returncode,
            )

    return True


def _apple_speech_process_is_running() -> bool:
    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        proc = CURRENT_APPLE_SPEECH_PROCESS

    return proc is not None and proc.poll() is None


def _start_apple_speech_reaper(
    proc: subprocess.Popen,
):
    """
    Observe an Apple Speech helper until it actually exits.

    Important:
    - Never SIGKILL a helper that may still own AVAudioEngine/CoreAudio.
    - Never clear CURRENT_APPLE_SPEECH_PROCESS while the process is alive.
    - The process reference is released only after proc.poll() confirms exit.
    """
    reaper_key = (
        proc.pid,
        id(proc),
    )

    with _APPLE_SPEECH_REAPER_LOCK:
        if reaper_key in _APPLE_SPEECH_REAPER_KEYS:
            return

        _APPLE_SPEECH_REAPER_KEYS.add(reaper_key)

    def reaper():
        try:
            _audio_log.warning(
                "Apple Speech helper is still completing CoreAudio teardown; "
                "retaining process ownership until actual exit: pid=%s",
                proc.pid,
            )

            while proc.poll() is None:
                try:
                    returncode = proc.wait(
                        timeout=APPLE_SPEECH_REAPER_LOG_INTERVAL,
                    )
                except subprocess.TimeoutExpired:
                    _audio_log.warning(
                        "Apple Speech helper is still alive; "
                        "not sending SIGKILL because it may still own "
                        "AVAudioEngine/CoreAudio: pid=%s",
                        proc.pid,
                    )
                    continue

                _shutdown_log.debug(
                    "Apple Speech helper exited after delayed cleanup: "
                    "pid=%s, returncode=%s",
                    proc.pid,
                    returncode,
                )
                break

            if proc.poll() is not None:
                _clear_apple_speech_process_if_exited(proc)

        except Exception:
            _dictation_log.exception(
                "Apple Speech helper reaper failed: pid=%s",
                proc.pid,
            )

        finally:
            with _APPLE_SPEECH_REAPER_LOCK:
                _APPLE_SPEECH_REAPER_KEYS.discard(reaper_key)

    threading.Thread(
        target=reaper,
        daemon=True,
        name=f"AppleSpeechReaper-{proc.pid}",
    ).start()


def _ensure_apple_speech_helper_binary(
    helper_bin: str,
    helper_swift: str,
    helper_plist: str,
) -> bool:
    try:
        source_mtime = os.path.getmtime(helper_swift)
        plist_mtime = os.path.getmtime(helper_plist)

        binary_mtime = os.path.getmtime(helper_bin) if os.path.exists(helper_bin) else 0

        needs_build = (
            not os.path.exists(helper_bin)
            or not os.access(helper_bin, os.X_OK)
            or source_mtime > binary_mtime
            or plist_mtime > binary_mtime
        )

        if not needs_build:
            return True

        _app_log.info("Compiling Apple Speech helper because source is newer")

        result = subprocess.run(
            [
                "/usr/bin/swiftc",
                "-O",
                helper_swift,
                "-o",
                helper_bin,
                "-Xlinker",
                "-sectcreate",
                "-Xlinker",
                "__TEXT",
                "-Xlinker",
                "__info_plist",
                "-Xlinker",
                helper_plist,
            ],
            capture_output=True,
            text=True,
            timeout=60,
        )

        if result.returncode != 0:
            _dictation_log.error(
                "Failed to compile Apple Speech helper:\n%s",
                result.stderr.strip(),
            )
            return False

        os.chmod(helper_bin, 0o755)

        _app_log.info(
            "Apple Speech helper compiled successfully: %s",
            helper_bin,
        )
        return True

    except Exception as e:
        _dictation_log.exception(
            "Apple Speech helper compilation failed: %s",
            e,
        )
        return False


def _handoff_apple_speech_to_dictation() -> bool:
    """Acquire the single Apple Speech/CoreAudio owner before starting Dictation."""
    global _LAST_APPLE_SPEECH_EXIT_AT
    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        previous = CURRENT_APPLE_SPEECH_PROCESS
    if previous is not None and previous.poll() is None:
        _dictation_log.debug(
            "Dictation requesting Apple KWS helper handoff: pid=%s", previous.pid
        )
        try:
            previous.terminate()
            previous.wait(timeout=5.0)
        except subprocess.TimeoutExpired:
            _dictation_log.error(
                "Dictation handoff failed: Apple Speech helper still alive after SIGTERM: pid=%s",
                previous.pid,
            )
            return False
        except ProcessLookupError:
            pass
        except Exception:
            _dictation_log.exception(
                "Dictation handoff failed while stopping Apple Speech helper"
            )
            return False
        _clear_apple_speech_process_if_exited(previous)
    if _apple_speech_process_is_running():
        return False
    last_exit = _LAST_APPLE_SPEECH_EXIT_AT
    gap = APPLE_SPEECH_RESTART_GAP - (time.monotonic() - last_exit)
    if last_exit > 0 and gap > 0:
        time.sleep(gap)
    stable = wait_for_audio_route_stability(timeout=VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT)
    _dictation_log.debug(
        "Dictation Apple Speech handoff route stability: stable=%s", stable
    )
    return bool(stable)


def _run_apple_speech_dictation(
    locale: str = "zh-CN",
    generation: Optional[int] = None,
    *,
    question_generation: Optional[int] = None,
    show_hud: bool = True,
) -> Optional[str]:
    """
    Run Apple Speech helper.

    - partial updates HUD
    - final returns final text
    - _dictation_stop gracefully stops helper and may use last partial as fallback
    - _dictation_cancel gracefully stops helper but discards text
    - generation prevents stale sessions from affecting new dictation sessions
    """
    global _LAST_APPLE_SPEECH_EXIT_AT
    global CURRENT_APPLE_SPEECH_PROCESS

    base_dir = os.path.dirname(os.path.abspath(__file__))
    helper_path = os.path.join(base_dir, "apple_speech_helper.swift")

    if not os.path.exists(helper_path):
        _dictation_log.error(f"Apple speech helper not found: {helper_path}")
        if show_hud:
            hud.show(
                "dictation_error",
                "Apple Dictation",
                "apple_speech_helper.swift not found",
            )
        time.sleep(1.0)
        return None

    helper_bin = os.path.join(base_dir, "apple_speech_helper")
    helper_swift = os.path.join(base_dir, "apple_speech_helper.swift")
    helper_plist = os.path.join(base_dir, "Info.plist")

    if _ensure_apple_speech_helper_binary(helper_bin, helper_swift, helper_plist):
        cmd = [helper_bin, locale]
    else:
        _dictation_log.warning(
            "Using Swift interpreter because helper compilation failed"
        )
        cmd = ["/usr/bin/swift", helper_swift, locale]

    if not _handoff_apple_speech_to_dictation():
        _dictation_log.error("Apple Dictation could not acquire microphone ownership")
        if show_hud:
            hud.show(
                "dictation_error", "Apple Dictation", "Microphone route is still busy"
            )
        return None

    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        last_exit_at = _LAST_APPLE_SPEECH_EXIT_AT

    elapsed_since_exit = time.monotonic() - last_exit_at

    if last_exit_at > 0 and elapsed_since_exit < APPLE_SPEECH_RESTART_GAP:
        wait_time = APPLE_SPEECH_RESTART_GAP - elapsed_since_exit

        _dictation_log.debug(
            "Waiting %.2fs before restarting Apple Speech helper "
            "to allow CoreAudio teardown",
            wait_time,
        )

        time.sleep(wait_time)

    _dictation_log.debug(f"Starting Apple Speech helper: {' '.join(cmd)}")

    with APPLE_SPEECH_START_LOCK:
        if _apple_speech_process_is_running():
            _dictation_log.error(
                "Apple Dictation ownership invariant failed: helper still running after handoff"
            )
            return None
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                bufsize=1,
                env=dict(
                    os.environ,
                    SPEECH_HELPER_ON_DEVICE=(
                        "1" if VE_VOICE_CHAT_APPLE_ON_DEVICE else "0"
                    ),
                ),
            )
        except OSError as e:
            _dictation_log.exception("Failed to start Apple Speech helper: %s", e)
            if show_hud:
                hud.show(
                    "dictation_error",
                    "Apple Dictation",
                    f"Could not start speech helper: {e}",
                )
            time.sleep(1.0)
            return None
        try:
            _register_apple_speech_process(proc)
        except Exception:
            try:
                proc.terminate()
                proc.wait(timeout=3.0)
            except Exception:
                pass
            raise

    stdout_queue = queue.Queue()
    stderr_queue = queue.Queue()
    stdout_eof = threading.Event()
    stderr_eof = threading.Event()

    def stdout_reader():
        try:
            if proc.stdout:
                for line in proc.stdout:
                    stdout_queue.put(line)
        except Exception as e:
            _app_log.debug(f"Apple Speech stdout reader ended with error: {e}")
        finally:
            stdout_eof.set()

    def stderr_reader():
        try:
            if proc.stderr:
                for line in proc.stderr:
                    stderr_queue.put(line)
        except Exception as e:
            _app_log.debug(f"Apple Speech stderr reader ended with error: {e}")
        finally:
            stderr_eof.set()

    stdout_thread = threading.Thread(
        target=stdout_reader,
        daemon=True,
        name=f"AppleSpeechStdout-{proc.pid}",
    )

    stderr_thread = threading.Thread(
        target=stderr_reader,
        daemon=True,
        name=f"AppleSpeechStderr-{proc.pid}",
    )

    stdout_thread.start()
    stderr_thread.start()

    def stop_helper_gracefully(
        reason: str,
        timeout: float = 5.0,
    ) -> bool:
        """
        Request graceful Apple Speech helper shutdown.

        SIGKILL is disabled by default because killing AVAudioEngine during CoreAudio
        teardown can leave the macOS audio service in a bad state.

        Returns:
            True if the helper exited, otherwise False.
        """
        try:
            if proc.poll() is not None:
                return True

            _shutdown_log.debug(
                "Stopping Apple Speech helper gracefully: %s, pid=%s",
                reason,
                proc.pid,
            )

            proc.terminate()

            try:
                proc.wait(timeout=timeout)
                _shutdown_log.debug(
                    "Apple Speech helper exited gracefully: pid=%s, returncode=%s",
                    proc.pid,
                    proc.returncode,
                )
                return True

            except subprocess.TimeoutExpired:
                _dictation_log.error(
                    "Apple Speech helper did not exit within %.1fs after SIGTERM: "
                    "reason=%s, pid=%s. Refusing immediate SIGKILL to protect CoreAudio.",
                    timeout,
                    reason,
                    proc.pid,
                )

                return False

        except Exception as e:
            _dictation_log.exception(
                "Failed to stop Apple Speech helper cleanly: %s",
                e,
            )
            return proc.poll() is not None

    final_text = None
    last_partial = ""
    last_partial_at = 0.0

    cancel_requested = False
    stop_requested = False
    stale_requested = False

    helper_reported_stopped = False
    helper_exited = False

    shutdown_requested = False
    graceful_finish_requested = False
    graceful_finish_requested_at = 0.0

    final_received = False
    final_received_at = 0.0

    try:
        if question_generation is None and show_hud:
            hud.show(
                "dictation_recording",
                f"Apple Dictation [{locale}]",
                "Listening...",
            )

        while True:
            if question_generation is None:
                with _dictation_state_lock:
                    is_stale = (
                        generation is not None and generation != _dictation_generation
                    )
                    should_cancel = _dictation_cancel
                    should_stop = _dictation_stop
            else:
                with QUESTION_RECORDING_LOCK:
                    is_stale = (
                        question_generation != QUESTION_RECORDING_GENERATION
                        or QUESTION_RECORDING_SKIP.is_set()
                    )
                    should_cancel = QUESTION_RECORDING_CANCEL_ALL.is_set()
                    should_stop = QUESTION_RECORDING_STOP.is_set()

            if is_stale:
                _dictation_log.debug(
                    f"Apple Speech helper stale session detected: "
                    f"generation={generation}, current={_dictation_generation}"
                )
                stale_requested = True
                final_text = None

                # Stale session should also stop gracefully to release mic.
                helper_exited = stop_helper_gracefully(
                    "stale session",
                    timeout=3.0,
                )
                break

            if should_cancel:
                _dictation_log.debug("Cancelling Apple Speech helper")
                cancel_requested = True
                shutdown_requested = True
                final_text = None

                # Allow SIGKILL after a short grace period.
                # A stuck helper holding the mic is worse than a potential
                # CoreAudio glitch that will recover on next session.
                helper_exited = stop_helper_gracefully(
                    "cancel requested",
                    timeout=3.0,
                )
                break

            # 静音自停(仅 wake 单句听写): 有内容后连续 N 秒无新 partial => 说完了,
            # 复用优雅收尾链路(SIGUSR1 -> helper 出 final + stopped), 不再干等硬墙钟。
            if (
                generation is None
                and question_generation is None
                and last_partial
                and not graceful_finish_requested
                and last_partial_at > 0.0
                and (time.monotonic() - last_partial_at)
                >= APPLE_SPEECH_SILENCE_STOP_SECONDS
            ):
                _dictation_log.debug(
                    "Apple Speech silence stop: no new partial for %.1fs "
                    "(last_partial=%r)",
                    APPLE_SPEECH_SILENCE_STOP_SECONDS,
                    last_partial[-60:],
                )
                should_stop = True

            if should_stop and not graceful_finish_requested:
                _dictation_log.debug(
                    "Requesting graceful Apple Speech finalization: pid=%s",
                    proc.pid,
                )

                stop_requested = True
                shutdown_requested = True
                graceful_finish_requested = True
                graceful_finish_requested_at = time.monotonic()

                try:
                    proc.send_signal(signal.SIGUSR1)
                except Exception as e:
                    _dictation_log.error(
                        "Failed sending SIGUSR1 to Apple Speech helper: %s",
                        e,
                    )

                # Do not break.
                # Continue reading stdout for the final result.

            if proc.poll() is not None and stdout_eof.is_set() and stdout_queue.empty():
                helper_exited = True
                returncode = proc.returncode

                expected_exit = (
                    cancel_requested
                    or stop_requested
                    or stale_requested
                    or final_received
                    or helper_reported_stopped
                )

                if returncode not in (0, None) and not expected_exit:
                    _dictation_log.error(
                        "Apple Speech helper exited abnormally: pid=%s, returncode=%s",
                        proc.pid,
                        returncode,
                    )

                    TTS_OUTPUT_RECOVERY_REQUIRED.set()

                    _dictation_log.warning(
                        "Marked persistent TTS output "
                        "for recovery after abnormal "
                        "Apple Speech helper exit"
                    )

                    log_persistent_audio_output_state(
                        "after Apple Speech helper abnormal exit"
                    )
                else:
                    _dictation_log.debug(
                        "Apple Speech helper exited: "
                        "pid=%s, returncode=%s, "
                        "expected=%s, final_received=%s, "
                        "stopped_event=%s",
                        proc.pid,
                        returncode,
                        expected_exit,
                        final_received,
                        helper_reported_stopped,
                    )

                if not final_received:
                    final_text = None

                break

            if (
                graceful_finish_requested
                and not final_received
                and (time.monotonic() - graceful_finish_requested_at)
                > APPLE_SPEECH_FINAL_EXIT_TIMEOUT
            ):
                _dictation_log.warning(
                    "Apple Speech graceful finalization timed out; "
                    "leaving the helper registered until it actually exits: "
                    "pid=%s",
                    proc.pid,
                )
                break

            if (
                final_received
                and not helper_reported_stopped
                and (time.monotonic() - final_received_at)
                > APPLE_SPEECH_FINAL_EXIT_TIMEOUT
            ):
                _dictation_log.warning(
                    "Apple Speech final result was received, but helper "
                    "did not report stopped within %.1fs; "
                    "returning the final text while retaining helper "
                    "ownership until actual process exit: pid=%s",
                    APPLE_SPEECH_FINAL_EXIT_TIMEOUT,
                    proc.pid,
                )
                break

            try:
                line = stdout_queue.get(timeout=0.05)
            except queue.Empty:
                continue

            line = line.strip()
            if not line:
                continue

            try:
                event = json.loads(line)
            except Exception:
                _dictation_log.debug(f"Apple Speech non-json line: {line}")
                continue

            typ = event.get("type")

            if typ == "started":
                _dictation_log.debug(f"Apple Speech started: {event}")
                continue

            if typ == "partial":
                text = (event.get("text") or "").strip()
                if text and text != last_partial:
                    last_partial = text
                    last_partial_at = time.monotonic()
                    if question_generation is None and show_hud:
                        hud.show(
                            "dictation_recording",
                            f"Apple Dictation [{locale}]",
                            text[-500:],
                        )
                continue

            if typ == "final":
                text = (event.get("text") or "").strip()

                if text:
                    final_text = text

                if not final_received:
                    final_received_at = time.monotonic()

                final_received = True

                _dictation_log.debug(
                    "Apple Speech final result received; "
                    "waiting for helper CoreAudio teardown: "
                    "pid=%s, text=%r",
                    proc.pid,
                    final_text,
                )

                # Do not break here.
                # The helper still needs time to stop AVAudioEngine,
                # remove the input tap, emit "stopped", and exit.
                continue

            if typ == "error":
                err = str(event.get("error", ""))
                _dictation_log.debug(f"Apple Speech error: {err}")
                if show_hud:
                    hud.show("dictation_error", "Apple Dictation", err[:300])
                time.sleep(1.0)
                final_text = None
                break

            if typ == "stopped":
                helper_reported_stopped = True

                _dictation_log.debug(
                    "Apple Speech helper reported CoreAudio teardown complete: pid=%s",
                    proc.pid,
                )

                try:
                    proc.wait(
                        timeout=APPLE_SPEECH_FINAL_EXIT_TIMEOUT,
                    )
                except subprocess.TimeoutExpired:
                    _dictation_log.warning(
                        "Apple Speech helper reported stopped but has not "
                        "exited yet; handing ownership to reaper: pid=%s",
                        proc.pid,
                    )
                else:
                    helper_exited = True
                    _clear_apple_speech_process_if_exited(proc)

                break

        # Fallback behavior:
        # - ESC card text
        # - stale session: discard text
        # - normal stop: use final; if no final, use last partial
        if cancel_requested or stale_requested:
            final_text = None
        elif not final_text and last_partial:
            final_text = last_partial

    finally:
        if proc.poll() is not None:
            helper_exited = True
            stdout_eof.wait(timeout=0.5)
            stderr_eof.wait(timeout=0.5)

        stdout_thread.join(timeout=0.2)
        stderr_thread.join(timeout=0.2)

        if proc.poll() is None and not shutdown_requested and not final_received:
            helper_exited = stop_helper_gracefully(
                "finally cleanup before final result",
                timeout=3.0,
            )

        if proc.poll() is None and final_received:
            _dictation_log.warning(
                "Apple Speech helper produced a final result but "
                "is still completing teardown; refusing SIGTERM/SIGKILL "
                "and retaining process ownership: pid=%s",
                proc.pid,
            )
            _start_apple_speech_reaper(proc)

        # If the helper is still alive, retain the process reference.
        # This deliberately blocks a new Apple Speech session until the
        # old helper has actually released its process lifetime.
        if proc.poll() is None and not helper_exited:
            _dictation_log.warning(
                "Apple Speech helper has not exited; "
                "the process reference will remain registered "
                "until actual exit: pid=%s",
                proc.pid,
            )
            _start_apple_speech_reaper(proc)

        # Drain stderr for diagnostics.
        stderr_lines = []

        try:
            while not stderr_queue.empty():
                err_line = stderr_queue.get_nowait().strip()
                if err_line:
                    stderr_lines.append(err_line)
        except Exception:
            pass

        if stderr_lines:
            _dictation_log.debug(
                "Apple Speech stderr:\n%s",
                "\n".join(stderr_lines[-20:]),
            )

        if cancel_requested or stale_requested:
            time.sleep(APPLE_SPEECH_RELEASE_COOLDOWN_AFTER_CANCEL)
        elif stop_requested:
            time.sleep(APPLE_SPEECH_RELEASE_COOLDOWN)

        # Only clear the global process reference after actual process exit.
        if helper_exited:
            _clear_apple_speech_process_if_exited(proc)
        else:
            _dictation_log.warning(
                "Apple Speech helper is still cleaning up: "
                "pid=%s, stopped_event=%s, shutdown_requested=%s",
                proc.pid,
                helper_reported_stopped,
                shutdown_requested,
            )
            _start_apple_speech_reaper(proc)

    return final_text


def show_dictation_hud_if_current(
    generation: Optional[int],
    status: str,
    title: str,
    question: str = "",
) -> bool:
    """Update the global-dictation HUD only for the active generation."""
    if not _is_current_dictation_generation(generation):
        _hud_log.debug(
            "Stale dictation session skipped HUD update: generation=%r status=%s",
            generation,
            status,
        )
        return False

    hud.show(status, title, question)
    return True


def hide_dictation_hud_if_current(
    generation: Optional[int],
):
    if not _is_current_dictation_generation(generation):
        _hud_log.debug(
            "Stale dictation session skipped HUD hide: generation=%r",
            generation,
        )

        return

    try:
        hud.hide_visual_only()
    except Exception:
        _hud_log.debug(
            "Failed to hide dictation HUD",
            exc_info=True,
        )


def _global_dictation_flow(
    locale: Optional[str] = None, generation: Optional[int] = None
):
    """Global dictation flow triggered by double-tap Ctrl+Opt.

    Live HUD mode:
    - While recording, periodically transcribes accumulated audio.
    - Shows partial transcription in HUD only.
    - Does NOT insert partial text at cursor.
    - On Enter/stop, performs final transcription + optional correction.
    - Inserts final text once at cursor.
    """
    global _dictation_state, _dictation_cancel, _dictation_stop, IS_DICTATION_ACTIVE
    global _dictation_generation

    _dictation_log.debug("🎤 Global dictation starting")

    dictation_locale = locale or DICTATION_LOCALE_DEFAULT

    _dictation_log.debug(f"🎤 Dictation locale: {dictation_locale}")

    with _dictation_state_lock:
        if generation is None:
            generation = _dictation_generation

        # If this is already stale, exit immediately.
        if generation != _dictation_generation:
            _dictation_log.debug(
                f"Stale dictation flow ignored: generation={generation}, current={_dictation_generation}"
            )
            return

        # Clear stale flags at the start of a confirmed new session.
        _dictation_cancel = False
        _dictation_stop = False

    with DICTATION_LOCK:
        IS_DICTATION_ACTIVE = True

    should_check_audio_input = not (
        GLOBAL_DICTATION_USE_APPLE_SPEECH
        and GLOBAL_DICTATION_SKIP_PORTAUDIO_PRECHECK_FOR_APPLE
    )

    if should_check_audio_input and not check_audio_input_device():
        _dictation_log.error("No audio input device available for global dictation")
        show_dictation_hud_if_current(
            generation, "dictation_error", "Dictation", "No microphone detected"
        )
        time.sleep(2.0)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)

        with DICTATION_LOCK:
            IS_DICTATION_ACTIVE = False
        return

    if GLOBAL_DICTATION_USE_APPLE_SPEECH:
        try:
            final_text = _run_apple_speech_dictation(dictation_locale, generation)

            with _dictation_state_lock:
                is_stale = generation != _dictation_generation
                cancelled = _dictation_cancel

            if is_stale:
                _dictation_log.debug(
                    f"Apple dictation flow stale after helper returned: "
                    f"generation={generation}, current={_dictation_generation}"
                )
                return

            if cancelled:
                _dictation_log.debug("Dictation cancelled, no text inserted")
                show_dictation_hud_if_current(
                    generation, "dictation_cancelled", "Dictation", "Cancelled"
                )
                time.sleep(0.4)
                hide_dictation_hud_if_current(generation)
                return

            if not final_text or not final_text.strip():
                show_dictation_hud_if_current(
                    generation,
                    "dictation_nospeech",
                    "Dictation",
                    "No speech recognized",
                )
                time.sleep(0.8)
                hide_dictation_hud_if_current(generation)
                return

            final_text = strip_llm_artifacts(final_text, remove_reasoning=True).strip()

            should_correct = (
                GLOBAL_DICTATION_FINAL_CORRECT
                and len(final_text.strip()) >= GLOBAL_DICTATION_CORRECTION_MIN_CHARS
            )

            if should_correct:
                if not GLOBAL_DICTATION_SILENT_FINALIZE:
                    show_dictation_hud_if_current(
                        generation, "dictation_processing", "Dictation", "Correcting..."
                    )

                try:
                    corrected = correct_text_sync(final_text)
                    corrected = strip_llm_artifacts(
                        corrected, remove_reasoning=True
                    ).strip()
                    if corrected:
                        final_text = corrected
                except Exception as e:
                    _dictation_log.warning(
                        f"Apple dictation correction failed, using raw: {e}"
                    )

            with _dictation_state_lock:
                if generation != _dictation_generation:
                    _dictation_log.debug(
                        "Discarding stale Apple "
                        "dictation result before insert: "
                        "generation=%r current=%r",
                        generation,
                        _dictation_generation,
                    )

                    return

                submit_after_insert = _dictation_submit_after_insert

            success = _insert_text_at_cursor(final_text)

            if success:
                _dictation_log.debug("Apple dictation final text inserted")

                if submit_after_insert:
                    _dictation_log.debug(
                        "Replaying Enter after dictation text insertion"
                    )
                    _press_enter_after_insert()

                if GLOBAL_DICTATION_SHOW_DONE:
                    if not _is_current_dictation_generation(generation):
                        _hud_log.info(
                            "Apple dictation became stale "
                            "after text insertion; skipping "
                            "HUD updates"
                        )

                        return
                    show_dictation_hud_if_current(
                        generation, "dictation_done", "Dictation", final_text[:500]
                    )
                    time.sleep(0.6)

                hide_dictation_hud_if_current(generation)
            else:
                show_dictation_hud_if_current(
                    generation, "dictation_error", "Dictation", "Failed to insert text"
                )
                time.sleep(0.8)
                hide_dictation_hud_if_current(generation)

        finally:
            with _dictation_state_lock:
                is_current_generation = generation == _dictation_generation
                was_cancelled = _dictation_cancel

            if is_current_generation:
                try:
                    hud.hide_visual_only()
                except Exception:
                    _hud_log.debug(
                        "Failed hiding Apple dictation HUD during final cleanup",
                        exc_info=True,
                    )

            with _dictation_state_lock:
                _reset_dictation_state(
                    cooldown=1.8 if was_cancelled else 1.0,
                    generation=generation,
                )

            if is_current_generation:
                with DICTATION_LOCK:
                    IS_DICTATION_ACTIVE = False

        return

    audio_chunks = []
    total_frames = 0

    audio_lock = threading.Lock()
    state_lock = threading.Lock()
    live_stop_event = threading.Event()

    is_recording = True
    is_cancelled = False

    live_state = {
        "last_partial_text": "",
        "hud_text": "",
        "partial_updated_at": 0.0,
    }

    def audio_callback(indata, frames, time_info, status):
        nonlocal total_frames

        if not is_recording:
            return

        with audio_lock:
            if total_frames >= MAX_AUDIO_BUFFER_SIZE:
                return

            remaining = MAX_AUDIO_BUFFER_SIZE - total_frames
            chunk = indata[: min(frames, remaining), 0].copy()
            audio_chunks.append(chunk)
            total_frames += len(chunk)

    def take_audio_snapshot() -> Optional[np.ndarray]:
        with audio_lock:
            if not audio_chunks:
                return None

            detached_chunks = list(audio_chunks)

            audio_chunks.clear()

        try:
            return np.concatenate(detached_chunks)

        except Exception as exc:
            _audio_log.error(
                "Failed to concatenate final audio chunks: %s",
                exc,
            )

            return None

        finally:
            detached_chunks.clear()

    def get_recent_audio_snapshot(
        chunks: list[np.ndarray],
        max_frames: int,
    ) -> Optional[np.ndarray]:
        if not chunks:
            return None

        selected = []
        selected_frames = 0

        for chunk in reversed(chunks):
            selected.append(chunk)
            selected_frames += len(chunk)

            if selected_frames >= max_frames:
                break

        selected.reverse()

        snapshot = np.concatenate(selected)

        if len(snapshot) > max_frames:
            snapshot = snapshot[-max_frames:]

        return snapshot

    def live_partial_worker():
        """Background worker that periodically transcribes and updates HUD only."""
        _hud_log.info("🎙️ Live HUD dictation partial worker ENTERED")

        min_frames = int(AUDIO_INPUT_SAMPLE_RATE * GLOBAL_DICTATION_PARTIAL_MIN_SECONDS)
        partial_window_frames = int(
            AUDIO_INPUT_SAMPLE_RATE * GLOBAL_DICTATION_PARTIAL_WINDOW_SECONDS
        )

        last_hud_heartbeat = 0.0
        next_transcribe_at = time.monotonic() + GLOBAL_DICTATION_FIRST_PARTIAL_DELAY

        try:
            show_dictation_hud_if_current(
                generation,
                "dictation_recording",
                "Dictation Live Preview",
                "Listening... waiting for audio",
            )
        except Exception as e:
            _hud_log.error(f"Live HUD initial show failed: {e}")

        while not live_stop_event.is_set():
            time.sleep(0.05)

            with state_lock:
                if is_cancelled:
                    _hud_log.info("Live HUD worker sees cancellation")
                    break

            with audio_lock:
                frames_now = total_frames
                chunks_now = len(audio_chunks)

            audio_seconds = (
                frames_now / AUDIO_INPUT_SAMPLE_RATE if AUDIO_INPUT_SAMPLE_RATE else 0.0
            )
            now = time.monotonic()

            if GLOBAL_DICTATION_HUD_HEARTBEAT and now - last_hud_heartbeat >= 0.5:
                last_hud_heartbeat = now

                if live_state["hud_text"]:
                    display_text = live_state["hud_text"][-500:]
                else:
                    display_text = (
                        f"Listening... {audio_seconds:.1f}s audio ({chunks_now} chunks)"
                    )

                try:
                    show_dictation_hud_if_current(
                        generation,
                        "dictation_recording",
                        "Dictation Live Preview",
                        display_text,
                    )
                except Exception as e:
                    _hud_log.error(f"Live HUD heartbeat show failed: {e}")

            if frames_now < min_frames:
                continue

            if now < next_transcribe_at:
                continue

            next_transcribe_at = now + GLOBAL_DICTATION_PARTIAL_INTERVAL

            with audio_lock:
                chunk_refs = list(audio_chunks)

            audio_snapshot = get_recent_audio_snapshot(
                chunk_refs,
                partial_window_frames,
            )

            if audio_snapshot is None or len(audio_snapshot) == 0:
                continue

            _hud_log.info(
                f"Live HUD transcribing snapshot: {len(audio_snapshot) / AUDIO_INPUT_SAMPLE_RATE:.2f}s"
            )

            try:
                audio_16k = resample_audio(
                    audio_snapshot,
                    AUDIO_INPUT_SAMPLE_RATE,
                    WHISPER_SAMPLE_RATE,
                )

                raw = transcribe_audio_sync_live(audio_16k, language=None)
                partial_text = strip_llm_artifacts(raw, remove_reasoning=True).strip()

            except Exception as e:
                _hud_log.warning(f"Live HUD partial transcription failed: {e}")
                try:
                    show_dictation_hud_if_current(
                        generation,
                        "dictation_recording",
                        "Dictation Live Preview",
                        f"Listening... {audio_seconds:.1f}s audio\nPartial error: {e}",
                    )
                except Exception:
                    pass
                continue

            if not partial_text:
                _hud_log.info("Live HUD partial empty")
                continue

            last_partial = live_state["last_partial_text"]
            hud_text = live_state["hud_text"]

            delta = _compute_hud_stream_delta(
                last_partial=last_partial,
                current_partial=partial_text,
                hud_text=hud_text,
            )

            # Always update last partial for next alignment.
            live_state["last_partial_text"] = partial_text
            live_state["partial_updated_at"] = time.monotonic()

            if not delta.strip():
                _hud_log.info("Live HUD delta empty")
                continue

            # Avoid duplicated exact phrase if already visible.
            if delta.strip() in live_state["hud_text"]:
                _hud_log.info("Live HUD delta already exists in hud_text")
                continue

            # English/number spacing guard. Chinese unaffected.
            if hud_text and delta:
                if (
                    hud_text[-1].isascii()
                    and hud_text[-1].isalnum()
                    and delta[0].isascii()
                    and delta[0].isalnum()
                ):
                    delta = " " + delta

            live_state["hud_text"] = (hud_text + delta)[-MAX_LIVE_HUD_TEXT_CHARS:]

            _hud_log.info(
                f"Live HUD delta: {delta[:80]!r}, hud_text={live_state['hud_text'][-160:]!r}"
            )

            try:
                show_dictation_hud_if_current(
                    generation,
                    "dictation_recording",
                    "Dictation Live Preview",
                    live_state["hud_text"][-500:],
                )
            except Exception as e:
                _hud_log.error(f"Live HUD partial show failed: {e}")

        _hud_log.info("🎙️ Live HUD dictation partial worker EXITED")

    show_dictation_hud_if_current(
        generation,
        "dictation_recording",
        "Dictation Live Preview" if GLOBAL_DICTATION_LIVE_HUD else "Dictation",
        "Listening...",
    )

    _dictation_log.debug("Global dictation: recording started")

    partial_thread = None

    _dictation_log.debug(f"GLOBAL_DICTATION_LIVE_HUD={GLOBAL_DICTATION_LIVE_HUD}")

    if GLOBAL_DICTATION_LIVE_HUD:
        partial_thread = threading.Thread(target=live_partial_worker, daemon=True)
        partial_thread.start()
        _hud_log.info("Live HUD partial thread started")
    else:
        _hud_log.info("Live HUD disabled")

    try:
        stream = _open_audio_input_stream(audio_callback)
    except Exception as e:
        _dictation_log.error(f"Failed to open audio input stream for dictation: {e}")

        live_stop_event.set()
        if partial_thread and partial_thread.is_alive():
            partial_thread.join(timeout=1.0)

        show_dictation_hud_if_current(
            generation, "dictation_error", "Dictation", "No microphone available"
        )
        time.sleep(2.0)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)

        with DICTATION_LOCK:
            IS_DICTATION_ACTIVE = False
        return

    try:
        with stream:
            while True:
                with _dictation_state_lock:
                    stale_requested = generation != _dictation_generation

                    cancel_requested = _dictation_cancel

                    stop_requested = _dictation_stop

                if stale_requested:
                    with state_lock:
                        is_cancelled = True

                    _dictation_log.debug(
                        "Global dictation became stale: generation=%r current=%r",
                        generation,
                        _dictation_generation,
                    )

                    break

                if cancel_requested:
                    with state_lock:
                        is_cancelled = True

                    _dictation_log.debug("Global dictation: cancel signal received")

                    break

                if stop_requested:
                    _dictation_log.debug("Global dictation: stop signal received")

                    break

                time.sleep(0.02)

    finally:
        is_recording = False
        live_stop_event.set()

        if partial_thread is not None and partial_thread.is_alive():
            partial_thread.join(timeout=2.0)

            if partial_thread.is_alive():
                _dictation_log.warning(
                    "Live partial transcription thread "
                    "is still finishing its current "
                    "transcription"
                )

        with DICTATION_LOCK:
            IS_DICTATION_ACTIVE = False

    if is_cancelled:
        _dictation_log.debug("Global dictation: cancelled")
        show_dictation_hud_if_current(
            generation, "dictation_cancelled", "Dictation", "Cancelled"
        )
        time.sleep(1.0)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)
        return

    with audio_lock:
        frames_final = total_frames

    if frames_final >= MAX_AUDIO_BUFFER_SIZE:
        _dictation_log.warning(
            f"Global dictation reached maximum length ({MAX_RECORDING_SECONDS}s), truncating"
        )

    audio = take_audio_snapshot()

    if audio is None or len(audio) == 0:
        _dictation_log.debug("Global dictation: no audio captured")
        show_dictation_hud_if_current(
            generation, "dictation_nospeech", "Dictation", "No speech detected"
        )
        time.sleep(1.5)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)
        return

    with _dictation_state_lock:
        _dictation_state = "processing"

    if not GLOBAL_DICTATION_SILENT_FINALIZE:
        show_dictation_hud_if_current(
            generation, "dictation_processing", "Dictation", "Final transcription..."
        )

    _dictation_log.debug("Global dictation: final transcription...")

    try:
        audio_16k = resample_audio(audio, AUDIO_INPUT_SAMPLE_RATE, WHISPER_SAMPLE_RATE)
        raw = transcribe_audio_sync(audio_16k, language=None)
        raw = strip_llm_artifacts(raw, remove_reasoning=True).strip()

    except Exception as e:
        _dictation_log.error(f"Global dictation transcription failed: {e}")
        show_dictation_hud_if_current(
            generation, "dictation_error", "Dictation", "Transcription failed"
        )
        time.sleep(1.5)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)
        return

    if not raw.strip():
        _dictation_log.debug("Global dictation: no speech recognized")
        show_dictation_hud_if_current(
            generation, "dictation_nospeech", "Dictation", "No speech recognized"
        )
        time.sleep(1.5)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)
        return

    final_text = raw

    if GLOBAL_DICTATION_FINAL_CORRECT:
        if not GLOBAL_DICTATION_SILENT_FINALIZE:
            show_dictation_hud_if_current(
                generation, "dictation_processing", "Dictation", "Correcting..."
            )

        _dictation_log.debug(f"Global dictation: raw text = '{raw[:100]}...'")

        try:
            corrected = correct_text_sync(raw)
            corrected = strip_llm_artifacts(corrected, remove_reasoning=True).strip()

            if corrected:
                final_text = corrected
            else:
                _dictation_log.warning(
                    "Global dictation correction empty, using raw text"
                )

        except Exception as e:
            _dictation_log.warning(
                f"Global dictation correction failed, using raw text: {e}"
            )

    if not final_text.strip():
        _dictation_log.warning("Global dictation: final text is empty")
        show_dictation_hud_if_current(
            generation, "dictation_nospeech", "Dictation", "No usable text recognized"
        )
        time.sleep(1.5)
        hide_dictation_hud_if_current(generation)

        with _dictation_state_lock:
            _reset_dictation_state(cooldown=0.8, generation=generation)
        return

    _dictation_log.debug(
        "Global dictation final text = %r",
        final_text[:120],
    )

    with _dictation_state_lock:
        if generation != _dictation_generation:
            _dictation_log.debug(
                "Discarding stale Whisper "
                "dictation result before insert: "
                "generation=%r current=%r",
                generation,
                _dictation_generation,
            )

            return

        submit_after_insert = _dictation_submit_after_insert

    success = _insert_text_at_cursor(final_text)

    if success:
        _dictation_log.debug("Global dictation: final text inserted at cursor")

        if submit_after_insert:
            _dictation_log.debug("Replaying Enter after dictation text insertion")

            _press_enter_after_insert()

        if GLOBAL_DICTATION_SHOW_DONE:
            show_dictation_hud_if_current(
                generation,
                "dictation_done",
                "Dictation",
                final_text[:500],
            )

        try:
            preview = final_text[:80] + "..." if len(final_text) > 80 else final_text
            preview = (
                preview.replace("\\", "\\\\")
                .replace('"', '\\"')
                .replace("\n", " ")
                .replace("\r", " ")
            )

            subprocess.run(
                [
                    "/usr/bin/osascript",
                    "-e",
                    f'display notification "{preview}" with title "Dictation" subtitle "Text inserted"',
                ],
                capture_output=True,
            )
        except Exception:
            pass

    else:
        show_dictation_hud_if_current(
            generation, "dictation_error", "Dictation", "Failed to insert text"
        )
        _dictation_log.error("Global dictation: failed to insert final text")

    if GLOBAL_DICTATION_SHOW_DONE:
        time.sleep(1)

    hide_dictation_hud_if_current(generation)

    with _dictation_state_lock:
        _reset_dictation_state(cooldown=0.8, generation=generation)


# ==================== Combined Global Keyboard Listener ====================


def _physical_key_down(keycode: int) -> bool:
    try:
        return bool(
            Quartz.CGEventSourceKeyState(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                Quartz.kCGEventSourceStateHIDSystemState,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                keycode,
            )
        )
    except Exception:
        return False


def _physical_ctrl_down() -> bool:
    return _physical_key_down(59) or _physical_key_down(62)  # left/right Ctrl


def _physical_option_down() -> bool:
    return _physical_key_down(58) or _physical_key_down(61)  # left/right Option


def _set_dictation_state(state: str):
    global _dictation_state, _dictation_state_changed_at, _dictation_started_at

    now = time.monotonic()
    _dictation_state = state
    _dictation_state_changed_at = now

    if state == "recording":
        _dictation_started_at = now


def _is_current_dictation_generation(
    generation: Optional[int],
) -> bool:
    """
    Return whether a dictation worker still owns the active session.
    """
    if generation is None:
        return False

    with _dictation_state_lock:
        return generation == _dictation_generation


def _force_reset_timed_out_dictation_locked(
    *,
    cooldown: float = 0.8,
) -> int:
    """
    Invalidate a timed-out dictation session.

    IMPORTANT:
    The caller must already hold _dictation_state_lock.

    Returns:
        The invalidated generation.
    """
    global _dictation_state
    global _dictation_cancel
    global _dictation_stop
    global _dictation_generation
    global _dictation_state_changed_at
    global _dictation_shortcut_block_until
    global _dictation_submit_after_insert

    invalidated_generation = _dictation_generation

    # Let an old non-Apple recording loop observe cancellation.
    _dictation_cancel = True
    _dictation_stop = False
    _dictation_submit_after_insert = False

    # The old worker can no longer pass generation checks.
    _dictation_generation += 1

    now = time.monotonic()

    _dictation_state = "idle"
    _dictation_state_changed_at = now

    _dictation_shortcut_block_until = now + max(
        0.0,
        float(cooldown),
    )

    _dictation_log.warning(
        "Invalidated timed-out dictation: "
        "old_generation=%d "
        "new_generation=%d "
        "cooldown=%.2fs",
        invalidated_generation,
        _dictation_generation,
        cooldown,
    )

    return invalidated_generation


def _reset_dictation_state(cooldown: float = 0.8, generation: Optional[int] = None):
    global _dictation_state, _dictation_cancel, _dictation_stop
    global _dictation_state_changed_at, _dictation_shortcut_block_until
    global _dictation_generation
    global _dictation_submit_after_insert

    # Important:
    # An old dictation thread must not reset a newer dictation session.
    if generation is not None and generation != _dictation_generation:
        _dictation_log.debug(
            f"Skip reset from stale dictation generation={generation}, current={_dictation_generation}"
        )
        return

    _dictation_state = "idle"
    _dictation_cancel = False
    _dictation_stop = False
    _dictation_submit_after_insert = False
    _dictation_state_changed_at = time.monotonic()
    _dictation_shortcut_block_until = time.monotonic() + cooldown


def _dictation_processing_timed_out(timeout: float = 12.0) -> bool:
    with _dictation_state_lock:
        return (
            _dictation_state == "processing"
            and time.monotonic() - _dictation_state_changed_at > timeout
        )


def reset_tap_state():
    global _last_ctrl_tap_at, _last_ctrl_opt_tap_at
    global _modifier_down_since, _ctrl_tap_had_option
    global _suppress_plain_ctrl_until
    global _last_esc_tap_at, _suppress_esc_until

    with _MODIFIER_STATE_LOCK:
        _last_ctrl_tap_at = 0.0
        _last_ctrl_opt_tap_at = 0.0
        _modifier_down_since.clear()
        _ctrl_tap_had_option.clear()
        _suppress_plain_ctrl_until = time.monotonic() + DOUBLE_TAP_WINDOW
        _last_esc_tap_at = 0.0
        _suppress_esc_until = 0.0


def _toggle_dictation_from_hotkey(locale: str, label: str):
    """
    Start/stop dictation from keyboard hotkey.

    locale:
      - "en"
      - "zh"
    """
    global _dictation_cancel, _dictation_stop
    global _dictation_generation, _dictation_shortcut_block_until
    global _dictation_submit_after_insert

    now = time.monotonic()

    with _dictation_state_lock:
        # Ignore shortcut residue immediately after stop/cancel/reset.
        if now < _dictation_shortcut_block_until:
            _keyboard_log.warning(
                f"{label} ignored because shortcut cooldown active "
                f"({_dictation_shortcut_block_until - now:.2f}s left)"
            )
            return

        # Safety recovery: processing should not last forever.
        if _dictation_state == "processing":
            elapsed = now - _dictation_state_changed_at

            if elapsed > 12.0:
                _keyboard_log.warning(
                    "Dictation stuck in processing "
                    "for %.1fs; invalidating the "
                    "old session",
                    elapsed,
                )

                _force_reset_timed_out_dictation_locked(cooldown=0.8)

                # Do not start a new session in this same hotkey call.
                #
                # This gives the old recording/helper thread time to observe
                # cancellation or generation invalidation. The user may start
                # a new session after the short cooldown.
                return

            _keyboard_log.warning(
                "%s ignored because dictation state=processing",
                label,
            )

            return

        if _dictation_state == "idle":
            if _apple_speech_process_is_running():
                with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
                    previous_proc = CURRENT_APPLE_SPEECH_PROCESS

                _keyboard_log.warning(
                    "Cannot start dictation because previous Apple Speech helper "
                    "is still running: pid=%s",
                    previous_proc.pid if previous_proc else "unknown",
                )

                hud.show(
                    "dictation_error",
                    "Dictation",
                    "Previous speech session is still stopping",
                )

                threading.Timer(
                    1.0,
                    hud.hide_visual_only,
                ).start()

                _dictation_shortcut_block_until = time.monotonic() + 1.5
                return

            _keyboard_log.debug(f"{label} dictation shortcut detected: locale={locale}")

            _dictation_generation += 1
            generation = _dictation_generation

            _set_dictation_state("recording")
            _dictation_cancel = False
            _dictation_stop = False
            _dictation_submit_after_insert = False

            # Prevent leftover modifier events from immediately starting/stopping again.
            _dictation_shortcut_block_until = time.monotonic() + 0.35

            threading.Thread(
                target=_global_dictation_flow,
                args=(locale, generation),
                daemon=True,
            ).start()

            return

        if _dictation_state == "recording":
            elapsed_since_start = now - _dictation_started_at

            # Critical guard:
            # Ignore stop shortcuts that arrive immediately after startup.
            # These are usually leftover Ctrl/Ctrl+Opt release events from the start shortcut.
            if elapsed_since_start < 1.3:
                _keyboard_log.warning(
                    f"{label} stop ignored because dictation just started "
                    f"({elapsed_since_start:.2f}s ago)"
                )

                _dictation_shortcut_block_until = now + 0.9
                reset_tap_state()
                return

            _keyboard_log.debug(
                f"{label} shortcut detected while recording: stop dictation"
            )

            _dictation_stop = True
            _dictation_cancel = False
            _dictation_submit_after_insert = False
            _set_dictation_state("processing")

            # Absorb repeated key release/press events after stop.
            _dictation_shortcut_block_until = time.monotonic() + 1.0
            reset_tap_state()

            return

        _keyboard_log.debug(
            f"{label} ignored because dictation state={_dictation_state}"
        )
    pass


def cancel_active_dictation():
    global _dictation_cancel, _dictation_stop
    global _dictation_shortcut_block_until
    global _dictation_submit_after_insert

    with _dictation_state_lock:
        if _dictation_state in ("recording", "processing"):
            _dictation_log.debug("ESC pressed during dictation: cancel dictation")

            _dictation_cancel = True
            _dictation_stop = False
            _dictation_submit_after_insert = False
            _set_dictation_state("processing")

            # Absorb leftover key events after ESC.
            _dictation_shortcut_block_until = time.monotonic() + 1.0

            return True

    return False


def _handle_enter_during_dictation():
    global _dictation_stop, _dictation_cancel
    global _dictation_submit_after_insert, _dictation_shortcut_block_until

    with _dictation_state_lock:
        if _dictation_state == "recording":
            _dictation_log.debug(
                "Enter swallowed during dictation: stop and submit after insert"
            )

            _dictation_submit_after_insert = True
            _dictation_stop = True
            _dictation_cancel = False
            _set_dictation_state("processing")
            _dictation_shortcut_block_until = time.monotonic() + 1.0

            return True  # swallow

        if _dictation_state == "processing":
            _dictation_log.debug("Enter swallowed because dictation is processing")
            return True

    return False


def _handle_escape_during_dictation():
    with _dictation_state_lock:
        active = _dictation_state in ("recording", "processing")

    if not active:
        return False

    _dictation_log.debug("Esc swallowed during dictation: cancel")
    threading.Thread(
        target=cancel_active_dictation,
        daemon=True,
    ).start()

    return True


def _handle_modifier_flags_changed(event):
    # Right-cmd double-tap toggles the local wake-word voice chat. It uses its
    # own state (not _MODIFIER_STATE_LOCK) and ignores non-keycode-54 events, so
    # run it first, outside the lock, without disturbing Ctrl/Opt dictation.
    _voice_chat_on_flags_changed(event)
    with _MODIFIER_STATE_LOCK:
        return _handle_modifier_flags_changed_locked(event)


def _handle_modifier_flags_changed_locked(event):
    """
    Quartz flagsChanged handler. Caller holds _MODIFIER_STATE_LOCK.

    Detect:
    - Ctrl double tap -> English dictation
    - Ctrl+Opt double tap -> Chinese dictation

    Fixes:
    - Ctrl+Opt tap will not fall through to plain Ctrl.
    - Media/system key events recently seen by AppKit suppress plain Ctrl.
    """
    global _last_ctrl_tap_at, _last_ctrl_opt_tap_at
    global _suppress_plain_ctrl_until

    now = time.monotonic()

    keycode = Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
        event,
        Quartz.kCGKeyboardEventKeycode,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
    )

    flags = Quartz.CGEventGetFlags(event)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    ctrl_down = bool(flags & Quartz.kCGEventFlagMaskControl)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
    opt_down = bool(flags & Quartz.kCGEventFlagMaskAlternate)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    CTRL_KEYCODES = {59, 62}  # left ctrl, right ctrl
    OPT_KEYCODES = {58, 61}  # left option, right option

    _keyboard_log.debug(
        "Quartz flagsChanged: keycode=%s ctrl_down=%s opt_down=%s flags=%s",
        keycode,
        ctrl_down,
        opt_down,
        flags,
    )

    # Ignore non Ctrl/Option flagsChanged events.
    if keycode not in CTRL_KEYCODES and keycode not in OPT_KEYCODES:
        return

    # If AppKit just saw a media/system key, suppress plain Ctrl interpretation.
    # This protects against Launchpad/media keys causing weird modifier residue.
    if now - _last_appkit_media_event_at < 0.35:
        _keyboard_log.debug(
            "Suppress modifier event after media/system key: keycode=%s",
            keycode,
        )
        reset_tap_state()
        return

    # ------------------------------------------------------------
    # Option changed:
    # If Option becomes down while any Ctrl key is down, mark active Ctrl taps
    # as Ctrl+Opt chord.
    # ------------------------------------------------------------
    if keycode in OPT_KEYCODES:
        if opt_down:
            for ctrl_key in CTRL_KEYCODES:
                if ctrl_key in _modifier_down_since:
                    _ctrl_tap_had_option[ctrl_key] = True
        return

    # ------------------------------------------------------------
    # Ctrl key down
    # ------------------------------------------------------------
    if keycode in CTRL_KEYCODES and ctrl_down:
        previous_down = _modifier_down_since.get(keycode)
        if previous_down is not None:
            age = now - previous_down
            if age <= MAX_MODIFIER_TAP_DURATION:
                _keyboard_log.debug(
                    "Ignoring duplicate Ctrl down: keycode=%d age=%.3f",
                    keycode,
                    age,
                )
                return
            _modifier_down_since.pop(keycode, None)
            _ctrl_tap_had_option.pop(keycode, None)
            _keyboard_log.debug(
                "Discarded stale Ctrl down: keycode=%d age=%.3f",
                keycode,
                age,
            )

        _modifier_down_since[keycode] = now

        # If Option is already held when Ctrl goes down, this is a chord tap.
        _ctrl_tap_had_option[keycode] = bool(opt_down)

        _keyboard_log.debug(
            "Ctrl down tracked: keycode=%s opt_down=%s", keycode, opt_down
        )

        return

    # ------------------------------------------------------------
    # Ctrl key release
    # ------------------------------------------------------------
    if keycode in CTRL_KEYCODES and not ctrl_down:
        down_at = _modifier_down_since.pop(
            keycode,
            None,
        )

        if down_at is None:
            #
            # Ignore an unmatched release. It may be a synchronization
            # event received after startup, wake, reconnect, or event-tap
            # recovery, but it is not a complete key tap observed by us.
            #
            _ctrl_tap_had_option.pop(
                keycode,
                None,
            )

            _keyboard_log.debug(
                "Ignoring unmatched Ctrl release: keycode=%d flags=0x%x",
                keycode,
                flags,
            )

            return

        duration = now - down_at

        had_option = bool(_ctrl_tap_had_option.pop(keycode, False)) or bool(opt_down)

        _keyboard_log.debug(
            "Ctrl release tracked: keycode=%s duration=%.3f had_option=%s",
            keycode,
            duration,
            had_option,
        )

        if duration > MAX_MODIFIER_TAP_DURATION:
            return

        # -----------------------------
        # Ctrl+Opt tap path
        # -----------------------------
        if had_option:
            _suppress_plain_ctrl_until = now + DOUBLE_TAP_WINDOW
            _last_ctrl_tap_at = 0.0

            if now - _last_ctrl_opt_tap_at <= DOUBLE_TAP_WINDOW:
                _last_ctrl_opt_tap_at = 0.0

                _keyboard_log.debug("Detected Ctrl+Opt double tap via Quartz")

                threading.Thread(
                    target=_toggle_dictation_from_hotkey,
                    args=("zh", "Ctrl+Opt double-tap"),
                    daemon=True,
                ).start()
            else:
                _last_ctrl_opt_tap_at = now

            return

        # -----------------------------
        # Plain Ctrl tap path
        # -----------------------------
        if now < _suppress_plain_ctrl_until:
            _keyboard_log.debug("Plain Ctrl tap suppressed")
            return

        if now - _last_ctrl_tap_at <= DOUBLE_TAP_WINDOW:
            _last_ctrl_tap_at = 0.0

            _keyboard_log.debug("Detected Ctrl double tap via Quartz")

            threading.Thread(
                target=_toggle_dictation_from_hotkey,
                args=("en", "Ctrl double-tap"),
                daemon=True,
            ).start()
        else:
            _last_ctrl_tap_at = now


def _debug_flags_event(event):
    try:
        keycode = Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            event,
            Quartz.kCGKeyboardEventKeycode,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
        )
        flags = Quartz.CGEventGetFlags(event)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

        _keyboard_log.debug(
            "flagsChanged raw keycode=%s flags=%s physical_ctrl=%s physical_opt=%s",
            keycode,
            flags,
            _physical_ctrl_down(),
            _physical_option_down(),
        )
    except Exception:
        pass


def _start_quartz_keyboard_event_tap():
    """
    Start Quartz keyboard event tap.

    Handles:
    - Enter swallow during dictation
    - Esc cancel during dictation
    - Ctrl double tap
    - Ctrl+Opt double tap

    This replaces pynput.Listener.
    """
    global _keyboard_event_tap_started
    global _keyboard_event_tap_port
    global _keyboard_event_tap_runloop

    if _keyboard_event_tap_started:
        return True

    if not HAS_QUARTZ:
        _keyboard_log.warning("Quartz not available; keyboard event tap disabled")
        return False

    started = threading.Event()

    ENTER_KEYCODES = {36, 76}  # Return, keypad Enter
    ESC_KEYCODE = 53

    def callback(proxy, event_type, event, refcon):
        try:
            # Re-enable if macOS disables the tap after timeout/user input lag.
            if event_type in (
                Quartz.kCGEventTapDisabledByTimeout,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                Quartz.kCGEventTapDisabledByUserInput,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            ):
                reset_tap_state()

                if _keyboard_event_tap_port is not None:
                    Quartz.CGEventTapEnable(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                        _keyboard_event_tap_port,
                        True,
                    )

                _keyboard_log.warning(
                    "Keyboard event tap was re-enabled; modifier tap state was reset"
                )

                return event

            if event_type == Quartz.kCGEventFlagsChanged:  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                _debug_flags_event(event)
                _handle_modifier_flags_changed(event)
                return event

            if event_type != Quartz.kCGEventKeyDown:  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                return event

            keycode = Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                event,
                Quartz.kCGKeyboardEventKeycode,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            )

            if keycode in ENTER_KEYCODES:
                try:
                    event_tag = int(
                        Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                            event,
                            Quartz.kCGEventSourceUserData,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                        )
                    )
                except Exception:
                    event_tag = 0

                if event_tag == SYNTHETIC_ENTER_EVENT_TAG:
                    return event

                # Interactive MCP question recording has priority.
                if _handle_enter_during_question_recording():
                    return None

                # Global Ctrl/Ctrl+Opt dictation.
                if _handle_enter_during_dictation():
                    return None

                return event

            if keycode == ESC_KEYCODE:
                try:
                    is_repeat = bool(
                        Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                            event,
                            Quartz.kCGKeyboardEventAutorepeat,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                        )
                    )

                except Exception:
                    is_repeat = False

                if is_repeat:
                    return event

                # Interactive MCP question recording has priority.
                #
                # In this mode:
                # - one ESC skips the current question after the double-tap
                #   window expires;
                # - two ESC presses cancel all remaining questions.
                if _handle_escape_during_question_recording():
                    return None

                # Global dictation / ordinary global TTS behavior.
                if _handle_escape_keydown_global():
                    return None

                return event

            return event

        except Exception as e:
            _keyboard_log.error(f"Quartz keyboard event tap callback error: {e}")
            return event

    def event_tap_thread():
        global _keyboard_event_tap_started
        global _keyboard_event_tap_port
        global _keyboard_event_tap_runloop

        try:
            event_mask = (
                (1 << Quartz.kCGEventKeyDown)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                | (1 << Quartz.kCGEventKeyUp)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                | (1 << Quartz.kCGEventFlagsChanged)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            )

            tap = Quartz.CGEventTapCreate(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                Quartz.kCGHIDEventTap,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                Quartz.kCGHeadInsertEventTap,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                Quartz.kCGEventTapOptionDefault,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                event_mask,
                callback,
                None,
            )

            if tap is None:
                _keyboard_log.warning(
                    "Failed to create Quartz keyboard event tap. "
                    "Grant Accessibility/Input Monitoring permission to Terminal/Python."
                )
                started.set()
                return

            source = Quartz.CFMachPortCreateRunLoopSource(None, tap, 0)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            runloop = Quartz.CFRunLoopGetCurrent()  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

            Quartz.CFRunLoopAddSource(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                runloop,
                source,
                Quartz.kCFRunLoopCommonModes,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            )

            Quartz.CGEventTapEnable(tap, True)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

            _keyboard_event_tap_port = tap
            _keyboard_event_tap_runloop = runloop
            _keyboard_event_tap_started = True

            reset_tap_state()

            _keyboard_log.debug("Quartz keyboard event tap started")
            started.set()

            Quartz.CFRunLoopRun()  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

        except Exception as e:
            _keyboard_log.error(f"Quartz keyboard event tap thread failed: {e}")
            started.set()

    threading.Thread(
        target=event_tap_thread,
        daemon=True,
        name="QuartzKeyboardEventTap",
    ).start()

    started.wait(timeout=3.0)

    return _keyboard_event_tap_started


def _stop_quartz_keyboard_event_tap():
    global _keyboard_event_tap_started
    global _keyboard_event_tap_port
    global _keyboard_event_tap_runloop

    try:
        if _keyboard_event_tap_port is not None:
            Quartz.CGEventTapEnable(_keyboard_event_tap_port, False)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

        if _keyboard_event_tap_runloop is not None:
            Quartz.CFRunLoopStop(_keyboard_event_tap_runloop)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]

    except Exception as e:
        _keyboard_log.debug(f"Failed to stop Quartz keyboard event tap cleanly: {e}")

    _keyboard_event_tap_started = False
    _keyboard_event_tap_port = None
    _keyboard_event_tap_runloop = None


def _decode_system_defined_media_key(event):
    subtype = int(event.subtype())

    if subtype != MEDIA_KEY_SUBTYPE:
        return None

    data1 = int(event.data1())

    key_code = (data1 >> 16) & 0xFFFF
    key_state = (data1 >> 8) & 0xFF
    repeat = data1 & 0xFF

    return key_code, key_state, repeat


def _handle_appkit_media_event(event):
    global _last_appkit_media_event_at

    decoded = _decode_system_defined_media_key(event)

    if decoded is None:
        return

    _last_appkit_media_event_at = time.monotonic()

    key_code, key_state, repeat = decoded

    if key_state != 0x0A:
        return

    if key_code == NX_KEYTYPE_PLAY:
        _keyboard_log.debug("Media key: Play/Pause")
    elif key_code == NX_KEYTYPE_NEXT:
        _keyboard_log.debug("Media key: Next")
    elif key_code == NX_KEYTYPE_PREVIOUS:
        _keyboard_log.debug("Media key: Previous")
    elif key_code == NX_KEYTYPE_MUTE:
        _keyboard_log.debug("Media key: Mute")
    elif key_code == NX_KEYTYPE_SOUND_UP:
        _keyboard_log.debug("Media key: Volume Up")
    elif key_code == NX_KEYTYPE_SOUND_DOWN:
        _keyboard_log.debug("Media key: Volume Down")
    else:
        _keyboard_log.debug(
            "Media/system key ignored: code=%s state=%s", key_code, key_state
        )


def _start_appkit_media_monitor():
    global _appkit_media_monitor

    if not HAS_APPKIT:
        _keyboard_log.warning("AppKit not available; media key monitor disabled")
        return False

    if _appkit_media_monitor is not None:
        return True

    try:
        mask = 1 << int(NSSystemDefined)  # pyright: ignore[reportArgumentType]

        _appkit_media_monitor = NSEvent.addGlobalMonitorForEventsMatchingMask_handler_(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess]
            mask,
            _handle_appkit_media_event,
        )

        _keyboard_log.debug("AppKit systemDefined media monitor started")
        return True

    except Exception as e:
        _keyboard_log.warning(f"Failed to start AppKit media monitor: {e}")
        return False


# ==================== Xiaomi / XiaoAI Streaming Bridge ====================
# Embedded control plane + continuous audio data plane.
#
# Control: EmbeddedMiAccount -> XiaoAIMiNAClient -> player_play_url / stop.
# Audio: LLM SSE -> coalesced speech segments -> Edge-TTS -> segment decoder
#        -> one persistent MP3 encoder -> byte-bounded HTTP stream -> speaker.

XIAOAI_ENABLED = os.getenv("XIAOAI_ENABLED", "0") == "1"
XIAOAI_LATEST_ASK_API = (
    "https://userprofile.mina.mi.com/device_profile/v2/conversation"
    "?source=dialogu&hardware={hardware}&timestamp={timestamp}&limit=2"
)
XIAOAI_WAKEUP_KEYWORD = "小爱同学"
# Hardware actions use two distinct conventions:
# - directive: XiaoGPT-style execute-text action with ["小爱同学", 0]
