def _parse_xiaoai_command(value: str) -> Optional[tuple[int, int]]:
    value = str(value or "").strip()
    if not value:
        return None
    match = re.fullmatch(r"\s*(\d+)\s*[-,/:]\s*(\d+)\s*", value)
    if not match:
        raise ValueError(f"Invalid XiaoAI MIoT command: {value!r}")
    return int(match.group(1)), int(match.group(2))


def _parse_xiaoai_args(value: str, default: list) -> list:
    value = str(value or "").strip()
    if not value:
        return list(default)
    parsed = json.loads(value)
    if not isinstance(parsed, list):
        raise ValueError("XIAOAI_WAKEUP_ARGS must be a JSON array")
    return parsed


class XiaoAIPollFatalError(RuntimeError):
    def __init__(self, status: int, message: str):
        self.status = int(status)
        super().__init__(message)


def _notify_xiaoai_auth_failure(status: int) -> None:
    if int(status) != 401:
        return
    osascript = "/usr/bin/osascript"
    if not os.path.isfile(osascript) or not os.access(osascript, os.X_OK):
        _auth_log.warning(
            "Cannot send Xiaomi 401 notification: %s unavailable", osascript
        )
        return
    script = (
        "display notification "
        '"小爱轮询认证自动恢复失败，轮询已停止。请检查账号状态或重新登录。" '
        'with title "Voice Edge：小米认证失败" '
        'subtitle "HTTP 401 Unauthorized" '
        'sound name "Basso"'
    )
    try:
        subprocess.run(
            [osascript, "-e", script],
            check=False,
            timeout=5.0,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        _auth_log.debug("Failed sending Xiaomi 401 notification", exc_info=True)


def _env_csv(name: str, default: str) -> tuple[str, ...]:
    raw = os.getenv(name, default)
    return tuple(item.strip() for item in re.split(r"[,，;；\n]+", raw) if item.strip())


def _discover_lan_ip() -> str:
    configured = os.getenv("XIAOAI_AUDIO_PUBLIC_HOST", "").strip()
    if configured:
        return configured
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.connect(("8.8.8.8", 80))
        address = str(sock.getsockname()[0])
    except OSError:
        address = socket.gethostbyname(socket.gethostname())
    finally:
        sock.close()
    if not address or address.startswith("127."):
        raise RuntimeError(
            "Unable to discover a LAN address; set XIAOAI_AUDIO_PUBLIC_HOST"
        )
    return address


