    poll_debug: bool = field(default_factory=lambda: VE_XIAOAI_LOG_DEBUG)
    poll_log_every: int = field(
        default_factory=lambda: max(1, int(os.getenv("XIAOAI_POLL_LOG_EVERY", "60")))
    )
