def _ve_voice_chat_norm_text(s: str) -> str:
    return re.sub(r"[\W_]+", "", s or "", flags=re.UNICODE).lower()


def _ve_voice_chat_has_cjk(text: str) -> bool:
    return bool(re.search(r"[\u3400-\u9fff]", text or ""))


def _ve_voice_chat_pinyin(text: str):
    parts = lazy_pinyin(
        text or "",
        style=Style.NORMAL,
        neutral_tone_with_five=False,
        errors=lambda value: value,
    )
    return re.sub(r"[^a-z0-9]+", "", "".join(parts).lower())


def _ve_voice_chat_similarity(left: str, right: str) -> float:
    """Dependency-free normalized edit similarity in [0, 1]."""
    if left == right:
        return 1.0
    if not left or not right:
        return 0.0
    previous = list(range(len(right) + 1))
    for i, char_left in enumerate(left, 1):
        current = [i]
        for j, char_right in enumerate(right, 1):
            current.append(
                min(
                    current[-1] + 1,
                    previous[j] + 1,
                    previous[j - 1] + (char_left != char_right),
                )
            )
        previous = current
    return 1.0 - (previous[-1] / max(len(left), len(right)))


def _ve_voice_chat_jaro_winkler(left: str, right: str) -> float:
    """Jaro-Winkler similarity for short English recognition variants."""
    if left == right:
        return 1.0
    if not left or not right:
        return 0.0
    match_distance = max(len(left), len(right)) // 2 - 1
    match_distance = max(0, match_distance)
    left_matches = [False] * len(left)
    right_matches = [False] * len(right)
    matches = 0
    for index, char in enumerate(left):
        start = max(0, index - match_distance)
        end = min(index + match_distance + 1, len(right))
        for candidate in range(start, end):
            if right_matches[candidate] or right[candidate] != char:
                continue
            left_matches[index] = True
            right_matches[candidate] = True
            matches += 1
            break
    if matches == 0:
        return 0.0
    left_ordered = [char for index, char in enumerate(left) if left_matches[index]]
    right_ordered = [char for index, char in enumerate(right) if right_matches[index]]
    transpositions = (
        sum(a != b for a, b in zip(left_ordered, right_ordered, strict=True)) / 2
    )
    jaro = (
        matches / len(left)
        + matches / len(right)
        + (matches - transpositions) / matches
    ) / 3
    prefix = 0
    for a, b in zip(left, right, strict=False):
        if a != b or prefix == 4:
            break
        prefix += 1
    return jaro + prefix * 0.1 * (1.0 - jaro)


def _ve_voice_chat_best_window_score(text: str, target: str):
    """Return best composite English score, method, and aligned normalized window."""
    if not text or not target:
        return 0.0, "none", ""
    if target in text:
        return 1.0, "exact_window", target
    low = max(1, len(target) - 3)
    high = min(len(text), len(target) + 3)
    windows = (
        [text]
        if len(text) <= high
        else [
            text[start : start + size]
            for size in range(low, high + 1)
            for start in range(0, len(text) - size + 1)
        ]
    )
    best_score, best_method, best_window = 0.0, "none", ""
    for window in windows:
        edit_score = _ve_voice_chat_similarity(window, target)
        jaro_score = _ve_voice_chat_jaro_winkler(window, target)
        score, method = (
            (jaro_score, "jaro_winkler")
            if jaro_score > edit_score
            else (edit_score, "levenshtein")
        )
        if score > best_score:
            best_score, best_method, best_window = score, method, window
    return best_score, best_method, best_window


def _ve_voice_chat_best_window_similarity(text: str, target: str) -> float:
    """Compare target with nearby-length windows so command suffixes do not dilute a wake word."""
    if not text or not target:
        return 0.0
    if target in text:
        return 1.0
    low = max(1, len(target) - 2)
    high = min(len(text), len(target) + 2)
    if len(text) <= high:
        return _ve_voice_chat_similarity(text, target)
    best = 0.0
    for size in range(low, high + 1):
        for start in range(0, len(text) - size + 1):
            best = max(
                best, _ve_voice_chat_similarity(text[start : start + size], target)
            )
    return best


def _ve_voice_chat_wake_lookup():
    lookup = {}

    def add_mapping(spoken_form, keyword, config, kind):
        normalized = _ve_voice_chat_norm_text(spoken_form)
        if not normalized:
            raise ValueError(f"Voice chat {kind} must not normalize to an empty string")
        existing = lookup.get(normalized)
        if existing is not None and existing[1] is not config:
            existing_keyword = existing[0]
            raise ValueError(
                f"Voice chat {kind} {spoken_form!r} for {keyword!r} conflicts "
                f"with keyword {existing_keyword!r} after normalization"
            )
        lookup[normalized] = (keyword, config)

    for keyword, config in _ve_voice_chat_wake_entries():
        if not isinstance(keyword, str) or not keyword.strip():
            raise ValueError(
                "Each VE_VOICE_CHAT_WAKE_CONFIG item requires one non-empty keyword"
            )
        if "keywords" in config:
            raise ValueError(
                "Use singular 'keyword'; one config item cannot contain multiple keywords"
            )
        threshold = config.get("apple_threshold")
        if threshold is not None and not 0.0 <= float(threshold) <= 1.0:
            raise ValueError("apple_threshold must be between 0.0 and 1.0")
        add_mapping(keyword, keyword, config, "keyword")

    for config in VE_VOICE_CHAT_WAKE_CONFIG:
        keyword = config["keyword"]
        aliases = config.get("aliases") or ()
        if isinstance(aliases, str):
            raise ValueError("aliases must be a tuple; use ('alias',) for one alias")
        for alias in aliases:
            add_mapping(alias, keyword, config, "alias")
    return lookup


_VE_VOICE_CHAT_WAKE_LOOKUP = _ve_voice_chat_wake_lookup()


def _ve_voice_chat_match_keyword(partial_text: str):
    norm = _ve_voice_chat_norm_text(partial_text)
    exact = _VE_VOICE_CHAT_WAKE_LOOKUP.get(norm)
    if exact is not None:
        return exact[0]

    # Exact substring remains the safest path and supports "wake word + command".
    best, best_pos = None, -1
    for normalized, (keyword, _config) in _VE_VOICE_CHAT_WAKE_LOOKUP.items():
        pos = norm.find(normalized)
        if normalized and pos >= 0 and (best_pos < 0 or pos < best_pos):
            best_pos, best = pos, keyword
    if best is not None:
        return best

    # Fuzzy matching is Apple-Speech-only text post-processing. Chinese entries use
    # tone-free pinyin when pypinyin is installed; English uses normalized character
    # edit similarity. Aliases participate as additional reference pronunciations.
    winner = None
    winner_score = 0.0
    winner_reference = None
    winner_method = None
    winner_window = None
    for config in VE_VOICE_CHAT_WAKE_CONFIG:
        threshold = config.get("apple_threshold")
        if threshold is None:
            continue
        references = (
            config["keyword"],
            *(config.get("aliases") or ()),
        )
        for reference in references:
            if _ve_voice_chat_has_cjk(reference):
                observed = _ve_voice_chat_pinyin(partial_text)
                expected = _ve_voice_chat_pinyin(reference)
                if not observed or not expected:
                    observed = norm
                    expected = _ve_voice_chat_norm_text(reference)
                score = _ve_voice_chat_best_window_similarity(observed, expected)
                method = "pinyin_levenshtein"
                window = observed
            else:
                observed = norm
                expected = _ve_voice_chat_norm_text(reference)
                score, method, window = _ve_voice_chat_best_window_score(
                    observed, expected
                )
            if not observed or not expected:
                continue
            if score >= float(threshold) and score > winner_score:
                winner = config["keyword"]
                winner_score = score
                winner_reference = reference
                winner_method = method
                winner_window = window
    if winner is not None:
        _kws_log.debug(
            "Voice chat apple KWS fuzzy matched: keyword=%r reference=%r "
            "method=%s score=%.3f window=%r text=%r",
            winner,
            winner_reference,
            winner_method,
            winner_score,
            winner_window,
            (partial_text or "")[:120],
        )
    return winner


def _ve_voice_chat_wake_config(keyword):
    found = _VE_VOICE_CHAT_WAKE_LOOKUP.get(_ve_voice_chat_norm_text(keyword))
    return found[1] if found else None


def _ve_voice_chat_wake_route(keyword):
    config = _ve_voice_chat_wake_config(keyword)
    return config.get("route") if config else None


def _ve_voice_chat_command_locale(keyword):
    config = _ve_voice_chat_wake_config(keyword)
    if not config:
        return None
    return config.get("command_locale")


def _ve_voice_chat_build_model_aliases():
    aliases = {}
    for config in VE_VOICE_CHAT_WAKE_CONFIG:
        route = config.get("route")
        alias = config.get("model_alias")
        if not route or route[0] != "model" or not alias:
            continue
        model = route[1]
        existing = aliases.get(model)
        if existing is not None and existing != alias:
            raise ValueError(
                f"Conflicting model_alias values for {model!r}: "
                f"{existing!r} and {alias!r}"
            )
        aliases[model] = alias
    return aliases


_VE_VOICE_CHAT_MODEL_ALIASES = _ve_voice_chat_build_model_aliases()


def _ve_voice_chat_model_alias(model):
    alias = _VE_VOICE_CHAT_MODEL_ALIASES.get(model)
    if alias:
        return alias
    name = str(model or "")
    return name.split(":", 1)[1] if ":" in name else (name or "AI")


def _ve_voice_chat_build_keywords_string(items=VE_VOICE_CHAT_KEYWORDS) -> str:
    """纯文本词表 -> 官方 text2token -> keywords 内容(每行 <tokens> [score] [#th] @显示名)。

    官方 raw 格式: 英文段大写、中英文段之间留空格(否则 "你好DEEPSEEK" 会被当成
    一个词整行跳过)、@显示名用下划线。返回前校验所有 token 都在 tokens.txt 中,
    不合法直接抛 ValueError —— sherpa 拿到坏 keywords 会 C++ 侧硬退出。
    """
    raw_lines = []
    meta = []  # (display, score, threshold)
    for item in items:
        word, score, threshold = item[0], item[1], item[2]
        segs = re.findall(r"[\u4e00-\u9fff]+|[A-Za-z']+", word)
        raw_word = " ".join(seg.upper() if seg[0].isascii() else seg for seg in segs)
        display = word.replace(" ", "_")
        raw_lines.append(f"{raw_word} @{display}")
        meta.append((display, score, threshold))

    lines = _ve_voice_chat_text2token(raw_lines)
    if len(lines) != len(meta):
        raise ValueError(f"text2token 输出行数({len(lines)}) != 词表行数({len(meta)})")

    out = []
    for line, (display, score, threshold) in zip(lines, meta, strict=True):
        parts = [line.split("@")[0].strip()]
        if score is not None:
            parts.append(f":{score}")
        if threshold is not None:
            parts.append(f"#{threshold}")
        parts.append(f"@{display}")
        out.append(" ".join(parts))
    content = "\n".join(out)
    _ve_voice_chat_validate_keywords(content)
    return content


def _ve_voice_chat_text2token(raw_lines: list[str]) -> list[str]:
    """调用官方 sherpa-onnx-cli text2token, 把文本词表转成 token 行。

    命令与官方文档一致: text2token --tokens <模型>/tokens.txt
    --tokens-type phone+ppinyin --lexicon <en.phone + OOV 扩充> raw out。
    返回按序排列的输出行(每行 <tokens> @<显示名>)。
    """
    import subprocess as _sp

    cli = os.path.join(os.path.dirname(sys.executable), "sherpa-onnx-cli")
    if not os.path.isfile(cli):
        raise FileNotFoundError(f"找不到 sherpa-onnx-cli: {cli}")
    model_dir = VE_VOICE_CHAT_MODEL_DIR
    raw_path = out_path = lex_path = None
    try:
        fd, raw_path = tempfile.mkstemp(suffix="_keywords_raw.txt", text=True)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write("\n".join(raw_lines) + "\n")
        out_path = raw_path + ".out"
        lex_path = raw_path + ".phone"
        with open(lex_path, "w", encoding="utf-8") as lf:
            with open(os.path.join(model_dir, "en.phone"), encoding="utf-8") as ef:
                lf.write(ef.read())
            for word, phones in VE_VOICE_CHAT_EN_PHONE_EXTRA.items():
                lf.write(f"{word} {phones}\n")
        proc = _sp.run(
            [
                cli,
                "text2token",
                "--tokens",
                os.path.join(model_dir, "tokens.txt"),
                "--tokens-type",
                "phone+ppinyin",
                "--lexicon",
                lex_path,
                raw_path,
                out_path,
            ],
            capture_output=True,
            text=True,
            timeout=60,
        )
        if proc.returncode != 0 or not os.path.isfile(out_path):
            raise RuntimeError(
                f"text2token 失败 rc={proc.returncode}: {proc.stderr[-300:]}"
            )
        with open(out_path, encoding="utf-8") as f:
            content = f.read().strip()
        if not content:
            raise RuntimeError("text2token 输出为空")
        return content.splitlines()
    finally:
        for p in (raw_path, out_path, lex_path):
            if p:
                try:
                    os.unlink(p)
                except OSError:
                    pass


_ve_voice_chat_tokens_set_cache = None


def _ve_voice_chat_tokens_set() -> set:
    """模型 tokens.txt 的 token 集合(进程内缓存)。"""
    global _ve_voice_chat_tokens_set_cache
    if _ve_voice_chat_tokens_set_cache is None:
        tokens_path = os.path.join(VE_VOICE_CHAT_MODEL_DIR, "tokens.txt")
        with open(tokens_path, encoding="utf-8") as f:
            _ve_voice_chat_tokens_set_cache = {
                line.split()[0] for line in f if line.strip()
            }
    return _ve_voice_chat_tokens_set_cache


def _ve_voice_chat_validate_keywords(content: str) -> None:
    """校验 keywords 文本的每个 token 都在 tokens.txt 中, 未知 token 抛 ValueError。

    sherpa-onnx 对未知 token 是 C++ 侧硬退出(Encode keywords failed), 会拖垮整个
    应用; 必须在写文件前拦住, 转成可捕获的 Python 异常。
    """
    if not content.strip():
        return
    token_set = _ve_voice_chat_tokens_set()
    unknown = []
    for line in content.splitlines():
        tokens = []
        for seg in line.split():
            if seg.startswith(":") or seg.startswith("#") or seg.startswith("@"):
                break
            tokens.append(seg)
        for tok in tokens:
            if tok not in token_set:
                unknown.append((tok, line))
    if unknown:
        bad = "; ".join(f"{tok!r}(行: {line})" for tok, line in unknown[:5])
        raise ValueError(f"关键词含 tokens.txt 之外的 token: {bad}")


# 动态关键词字符串 -> 临时 keywords_file 缓存。
# key = 关键词内容字符串; 内容不变命中缓存, 变了才重写文件。
_ve_voice_chat_keywords_file_cache: dict[str, str] = {}
_ve_voice_chat_keywords_file_lock = threading.Lock()


def _ve_voice_chat_keywords_file(content: Optional[str] = None) -> str:
    """把动态关键词字符串写入临时文件并缓存路径, 供 keywords_file= 使用。"""
    if content is None:
        content = _ve_voice_chat_build_keywords_string()
    with _ve_voice_chat_keywords_file_lock:
        cached = _ve_voice_chat_keywords_file_cache.get(content)
        if cached and os.path.exists(cached):
            return cached
        handle = tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".txt",
            prefix="ve_voice_chat_kws_",
            delete=False,
            encoding="utf-8",
        )
        try:
            handle.write(content + "\n")
            handle.flush()
        finally:
            handle.close()
        atexit.register(
            lambda path=handle.name: os.path.exists(path) and os.remove(path)
        )
        _ve_voice_chat_keywords_file_cache[content] = handle.name
        return handle.name


# 全局 KeywordSpotter 缓存: 按 (关键词内容, 模型参数) 为 key。
# 方案 A 的核心: Trie 计算图只在首次 __init__ 编译一次, 关键词/分数/阈值
# 文本不变则命中内存单例, 变了才重建。跨实例共享, 不挂在 subsystem 实例上。
_ve_voice_chat_spotter_cache: dict = {}
_ve_voice_chat_spotter_lock = threading.Lock()


def _ve_voice_chat_get_spotter():
    """返回按关键词内容缓存的全局 KeywordSpotter 单例。

    key 覆盖所有影响 Trie 编译的输入: 关键词内容 + 模型四件套路径 +
    num_threads/score/threshold/provider。任一变化才重新编译, 否则 0 开销复用。
    """
    keywords_content = _ve_voice_chat_build_keywords_string()
    encoder, decoder, joiner, tokens_path = _ve_voice_chat_model_files()
    cache_key = (
        keywords_content,
        tokens_path,
        encoder,
        decoder,
        joiner,
        2,
        VE_VOICE_CHAT_KWS_SCORE,
        VE_VOICE_CHAT_KWS_THRESHOLD,
        "cpu",
    )
    with _ve_voice_chat_spotter_lock:
        cached = _ve_voice_chat_spotter_cache.get(cache_key)
        if cached is not None:
            return cached
        import sherpa_onnx  # lazy

        spotter = sherpa_onnx.KeywordSpotter(
            tokens=tokens_path,
            encoder=encoder,
            decoder=decoder,
            joiner=joiner,
            keywords_file=_ve_voice_chat_keywords_file(keywords_content),
            num_threads=2,
            keywords_score=VE_VOICE_CHAT_KWS_SCORE,
            keywords_threshold=VE_VOICE_CHAT_KWS_THRESHOLD,
            provider="cpu",
        )
        _ve_voice_chat_spotter_cache[cache_key] = spotter
        return spotter


# 模型三件套不再硬编码文件名: 按"非 int8 + chunk-16-left-64"优先在模型目录里自动挑。
# 旧(wenetspeech epoch-12)和新(zh-en epoch-13)模型都能直接用, 换模型只需改目录。
# 懒解析(真正创建 spotter 时才调用), 避免缺模型时拖垮整个应用启动。
def _ve_voice_chat_model_files() -> tuple[str, str, str, str]:
    import glob as _glob

    def pick(kind: str) -> str:
        base = os.path.join(VE_VOICE_CHAT_MODEL_DIR, kind + "-")
        for pattern in (
            f"{base}*-chunk-16-left-64.onnx",  # 首选: 非 int8 + chunk-16
            f"{base}*-left-64.onnx",  # 其次: 非 int8 任意 chunk
            f"{base}*.onnx",  # 再其次: 任意非 int8
        ):
            hits = sorted(p for p in _glob.glob(pattern) if ".int8." not in p)
            if hits:
                return hits[0]
        hits = sorted(_glob.glob(f"{base}*.int8.onnx"))  # 兜底: int8
        if hits:
            return hits[0]
        raise FileNotFoundError(
            f"模型目录 {VE_VOICE_CHAT_MODEL_DIR} 里找不到 {kind}-*.onnx"
        )

    return (
        pick("encoder"),
        pick("decoder"),
        pick("joiner"),
        os.path.join(VE_VOICE_CHAT_MODEL_DIR, "tokens.txt"),
    )


# 灵敏度:默认 0.25 太严(实测全漏),这里 0.20 起步、可配。
VE_VOICE_CHAT_KWS_THRESHOLD = max(
    0.01, float(os.getenv("VE_VOICE_CHAT_KWS_THRESHOLD", "0.20"))
)

VE_VOICE_CHAT_KWS_SCORE = max(0.0, float(os.getenv("VE_VOICE_CHAT_KWS_SCORE", "2.0")))

VE_VOICE_CHAT_SAMPLE_RATE = 16000

# Apple KWS 识别语言列表。默认同时启用中文 primary 和英文 secondary。
# 如需单语，只需设 VE_VOICE_CHAT_CAPTURE_LOCALES=zh-CN 或 en-US。
VE_VOICE_CHAT_CAPTURE_LOCALES = tuple(
    locale.strip()
    for locale in os.getenv("VE_VOICE_CHAT_CAPTURE_LOCALES", "zh-CN,en-US").split(",")
    if locale.strip()
) or ("zh-CN", "en-US")

# helper 命令行 locale 实参: 单 locale 时就是原来的字符串(逐字兼容), 多 locale 时为
# "primary,secondary,...", 由 helper 解析为一 primary + N secondary 被动流。
VE_VOICE_CHAT_CAPTURE_LOCALE_ARG = ",".join(VE_VOICE_CHAT_CAPTURE_LOCALES)

# 指令文本以哪个流为准: primary(第一个)。secondary 只负责更稳地命中唤醒词;
# 命中后指令累计/final 归属为"命中唤醒词的那个流", 未命中过时回退到 primary。
VE_VOICE_CHAT_PRIMARY_LOCALE = VE_VOICE_CHAT_CAPTURE_LOCALES[0]

VE_VOICE_CHAT_TTS_VOICE = os.getenv("VE_VOICE_CHAT_TTS_VOICE", "zh").strip()

VE_VOICE_CHAT_TTS_SPEED = float(os.getenv("VE_VOICE_CHAT_TTS_SPEED", "1.0"))

# Quartz keycode: 54 = 右⌘(不碰 dictation);如需左⌘可加 55。
VE_VOICE_CHAT_RIGHT_CMD_KEYCODES = frozenset({54})
VE_VOICE_CHAT_DOUBLE_TAP_WINDOW = 0.45

# 唤醒后单句听写的硬墙钟上限:helper 靠静音自停,但"唤醒后一句不说"会永久阻塞
# owner 线程并让 KWS 停摆。超时即 SIGTERM helper 放麦、返回 None。可配。
VE_VOICE_CHAT_DICTATION_TIMEOUT = max(
    3.0, float(os.getenv("VE_VOICE_CHAT_DICTATION_TIMEOUT", "15.0"))
)

# 同一 Apple KWS 会话在已经捕获命令后，连续静音多久提交给模型。唤醒词本身不启动
# 此计时；只有 _make_turn() 得到非空命令后才生效。
VE_VOICE_CHAT_COMMAND_SILENCE_SECONDS = max(
    0.5, float(os.getenv("VE_VOICE_CHAT_COMMAND_SILENCE_SECONDS", "2.0"))
)

# wake 语音助手是否显示 HUD。默认关:唤醒采集/播报走后台, 不弹任何 HUD 窗口。
# Apple Speech 仅作采集后端, 与"听写(光标插入)"功能无关, 故这里独立开关。
# 置 1 才显示(采集"Listening…"、partial、以及暂停/没听清等提示)。
VE_VOICE_CHAT_SHOW_HUD = os.getenv("VE_VOICE_CHAT_SHOW_HUD", "0").strip() == "1"

# 无输入设备时的等待兜底超时(秒)。正常靠 AUDIO_INPUT_DEVICE_CHANGED 事件即时唤醒
# (由 CoreAudio route monitor 在设备变化时置位), 此超时仅作事件在 teardown 期可能丢失
# 时的兜底重探。普通常量即可, 无人需要 env 调这个旋钮。
# 设备探测复用既有 check_audio_input_device(); PortAudio 生命周期(热插拔/route change
# 的 terminate/reinit)完全交给既有 CoreAudio route-change 链路, 本子系统不自行触碰。
_VE_VOICE_CHAT_DEVICE_WAIT_FALLBACK = 10.0

# fast-fail(helper spawn 了却从没 emit "started", 如无麦时 CoreAudio 秒退 code=10)
# 之后两次 spawn 之间的【最小间隔】。设计: 事件优先(蓝牙重连由 CoreAudio route monitor
# 置位 AUDIO_INPUT_DEVICE_CHANGED, 立即唤醒), 之后仅补足"距本次 spawn 不足此间隔"的那点
# 剩余时间。这既防住无麦时 macOS 反复重选缺失默认输入 -> 事件被秒唤醒 -> 紧密重生的 flood
# (每次至少隔 MIN_INTERVAL), 又不把蓝牙重连拖慢(最坏只等 ~MIN_INTERVAL, 不是几十秒)。
# 取代之前那个不可被事件打断、把重连拖到 30s 的指数地板。
_VE_VOICE_CHAT_FASTFAIL_MIN_INTERVAL = max(
    0.3, float(os.getenv("VE_VOICE_CHAT_FASTFAIL_MIN_INTERVAL", "2.0"))
)

# 一轮回答播报的等待上限(原 180s 偏长)。可配。
VE_VOICE_CHAT_ANSWER_TIMEOUT = max(
    5.0, float(os.getenv("VE_VOICE_CHAT_ANSWER_TIMEOUT", "90.0"))
)

# 流式读的 socket 超时(替掉写死的 180s)。这是单次读的静默上限:上游卡住不发数据
# 超过它即抛 socket timeout 跳出, 避免 pause/stop 后最长卡 180s、与 answer timeout
# 不匹配。正常 chunk 间隔远小于此值; abort 仍在行间即时检查。可配。
VE_VOICE_CHAT_STREAM_READ_TIMEOUT = max(
    3.0, float(os.getenv("VE_VOICE_CHAT_STREAM_READ_TIMEOUT", "30.0"))
)

# 跨模型"虚拟会话历史"的字符预算。唤醒词切到另一个模型时, 新模型没有自己的
# browser conversation_id, 就把这份累计历史(历轮 user query + 助手完整回答)重放
# 给它, 让它继承此前对话上下文。超预算则从最旧一轮起丢弃, 防止请求体无限膨胀。
VE_VOICE_CHAT_HISTORY_CHAR_BUDGET = max(
    0, int(os.getenv("VE_VOICE_CHAT_HISTORY_CHAR_BUDGET", "6000"))
)

# KWS 输入路径本身没有恢复机制: PortAudio 设备表只在 TTS 输出恢复的 refresh_portaudio
# 档 sd._terminate/_initialize 时刷新, 而该恢复只由阻塞在 TTS_TEXT_QUEUE.get() 的 owner
# 线程按队列项驱动。连蓝牙耳机等路由变化后若无 TTS 流过, 恢复永不触发, KWS 看不到新麦。
# 顺应既有架构: 卡住时主动发一句 TTS(经 TTS_TEXT_QUEUE)唤醒 owner 线程跑恢复。下面是两次
# 这种"恢复提示"之间的最小间隔(秒), 防止连发刷屏/反复出声。
VE_VOICE_CHAT_RECOVERY_NUDGE_INTERVAL = max(
    1.0, float(os.getenv("VE_VOICE_CHAT_RECOVERY_NUDGE_INTERVAL", "3.0"))
)

# 发恢复提示前等 CoreAudio route 稳定的上限(秒)。用 wait_for_audio_route_stability
# 等拓扑 AUDIO_ROUTE_MIN_STABLE_SECONDS(2s) 无新变化才返回, 自适应不同蓝牙耳机的连接
# 耗时(而非固定延迟), 避免设备还没连稳就发 TTS。须 > MIN_STABLE + 典型连接耗时。
VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT = max(
    2.0, float(os.getenv("VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT", "8.0"))
)

# 回答前预热 TTS 输出流开关(【默认开】: 默认值 "1")。
# 病因: voice chat 懒启动 consumer -> A2DP 输出流在【首句 TTS 前一刻】才建 -> 蓝牙冷启动
# ramp 削掉首句开头("冷启动首句吞字")。原先"开机预启动"无此问题(流一直热), 但 voice chat
# 不能开机建流(会抢占 HFP 麦, 触发 no-mic loop), 故改懒启动才引入本回归。
# 在 KWS 停麦【之后】、进入 _handle_wake(LLM+TTS)【之前】——此刻麦(HFP)已释放、
# 正切 A2DP、且尚未开始 LLM——【同步】等 route 稳 + cold-start consumer 建好 A2DP 输出流。
# 等 LLM 跑完首句 TTS 到达时, 流已热, 开头不再被 ramp 削。串行代价: 首句前多 ~route稳+probation
# (约 <1s), 但不与 HFP 麦冲突、逻辑最简。
# 注: 默认开启会给【每轮首句】加上述 <1s 串行预热(consumer 已在运行时零开销早退, 故仅每次
# 冷启动付出一次); 若想恢复"极限低延迟、允许首句吞字"的旧行为, 设 VE_TTS_PREWARM_BEFORE_ANSWER=0。
VE_TTS_PREWARM_BEFORE_ANSWER = (
    os.getenv("VE_TTS_PREWARM_BEFORE_ANSWER", "1").strip() == "1"
)

# 【KWS 抢占预热】开关(【默认开】: 默认值 "1"; 设 0 关闭退回旧行为)。
# 覆盖 _run_apple_session.finally 覆盖不到的路径(典型: M365 -> MCP speak 工具 -> speak_local_async,
# 不经唤醒->回答, apple KWS 只是被动让麦)。开启后: 任意 TTS 入口(speak_local_async)在建输出流前,
# 先置 _TTS_PREEMPT_KWS 让 apple KWS 主动让麦释放 HFP、等切 A2DP 稳定, 再把流一次建在 A2DP,
# 消除"HFP 建流 + 释麦切 A2DP recreate"的两次建流。已实测(2026-08): MCP speak 触发仅 1 次建流、
# 内容零丢失、播完 KWS 正常恢复监听(session listening), 故转为默认开。
# 代价: 首次 TTS(冷启动)会多等 KWS 让麦 + route 稳(~<1s); 且此期间 KWS 让麦短暂不监听唤醒词。热流
# (consumer 已运行)零开销。动到 KWS 让麦体系, 若发现唤醒被吞/恢复慢, 设 VE_TTS_KWS_PREEMPT_PREWARM=0
# 关闭退回。
VE_TTS_KWS_PREEMPT_PREWARM = os.getenv("VE_TTS_KWS_PREEMPT_PREWARM", "1").strip() == "1"

# 【日志降噪】apple KWS helper 的 stderr 生命周期日志分级白名单: 只有包含这些子串的行才以
# INFO 打(诊断关键: 无麦/致命启动/重启上限/引擎重启失败等); 其余每次会话必刷的常规生命周期
# (停麦、取消识别、cleanup、RunLoop 退出、no-speech、装 tap、引擎起停、配置变化等)降到 DEBUG,
# 默认 INFO 级别下不再刷屏, 需要排障时开 DEBUG 仍可见。大小写不敏感匹配。
_APPLE_KWS_KEEP_INFO_MARKERS = (
    "fatal startup error",
    "code=10",
    "no default microphone",
    "microphone input is unavailable",
    "restart limit reached",
    "audio engine restart failed",
    "repeatedly stopped",
    "helper start failed",
)

VE_VOICE_CHAT_CONCISE_HINT = (
    "（请用简洁、口语化的中文回答，适合语音朗读，不要使用 markdown 或代码块）\n"
)

# 虚拟会话历史里"我方"标签(可 env 改)。历史折叠给浏览器模型时用于标注用户轮。
VE_VOICE_CHAT_USER_LABEL = os.getenv("VE_VOICE_CHAT_USER_LABEL", "用户")


def _ve_voice_chat_is_browser_model(model):
    """本地模型 vs 浏览器模型判定。

    本地模型(别名在本地引擎映射表 LLM_MODEL_BACKENDS 中, 如 mlx_vlm/mlx_lm)吃标准
    OpenAI messages 多轮数组; 浏览器模型(deepseek/doubao 等经 relay 旁路, ClientTurn
    只取最后一条 user 消息)必须把历史折叠进单条文本。映射表缺失时保守按浏览器处理,
    至少不丢上下文。"""
    try:
        return model not in LLM_MODEL_BACKENDS
    except NameError:
        return True


def _ve_voice_chat_notify(text, *, title="语音助手", subtitle="", sound=""):
    """后台发一条 macOS 通知(osascript), best-effort, 绝不阻塞调用线程。

    唤醒助手默认 HUD 关闭(VE_VOICE_CHAT_SHOW_HUD=0)时, 唤醒后是静默进入聆听、无任何
    可见提示 —— 用户不知道助手已经在听。这条通知补上"已唤醒、正在聆听"的视觉反馈。
    仅 macOS; osascript 不可用或失败都静默跳过。放到一次性 daemon 线程执行, 使
    osascript 调用(即使偶发几百毫秒)绝不拖慢"唤醒 -> 开始聆听"这条关键路径。
    """
    if sys.platform != "darwin":
        return
    osascript = "/usr/bin/osascript"
    if not (os.path.isfile(osascript) and os.access(osascript, os.X_OK)):
        return

    def _applescript_quote(value):
        # AppleScript 字符串字面量: 转义反斜杠与双引号, 并去掉换行, 避免语法破坏/注入。
        return (
            str(value or "")
            .replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\r", " ")
            .replace("\n", " ")
        )

    script = 'display notification "%s" with title "%s"' % (
        _applescript_quote(text),
        _applescript_quote(title),
    )
    if subtitle:
        script += ' subtitle "%s"' % _applescript_quote(subtitle)
    if sound:
        script += ' sound name "%s"' % _applescript_quote(sound)

    def _run():
        try:
            subprocess.run(
                [osascript, "-e", script],
                check=False,
                timeout=5.0,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            _app_log.debug("Voice chat notification failed", exc_info=True)

    try:
        threading.Thread(target=_run, name="voice-chat-notify", daemon=True).start()
    except Exception:
        _xiaoai_log.debug(
            "Voice chat notification thread failed to start", exc_info=True
        )


_voice_chat_subsystem = None
_voice_chat_lock = threading.Lock()


def _voice_chat_force_stop_apple_speech(reason: str) -> bool:
    """SIGTERM 当前已注册的 Apple Speech helper 以立即释放麦克风。

    与 stop_helper_gracefully 一致:只发 SIGTERM(proc.terminate()), 绝不 SIGKILL,
    避免在 CoreAudio teardown 期间杀进程把音频服务打坏。返回 True 表示已无存活
    helper(已退出或本就没有)。
    """
    with CURRENT_APPLE_SPEECH_PROCESS_LOCK:
        proc = CURRENT_APPLE_SPEECH_PROCESS
    if proc is None or proc.poll() is not None:
        return True
    try:
        _xiaoai_log.info(
            "Voice chat force-stopping Apple Speech helper: %s pid=%s",
            reason,
            proc.pid,
        )
        proc.terminate()
    except Exception:
        _xiaoai_log.debug("Voice chat force-stop terminate failed", exc_info=True)
    try:
        proc.wait(timeout=3.0)
        return True
    except Exception:
        return proc.poll() is not None


def _ve_voice_chat_is_no_input_device_error(exc: BaseException) -> bool:
    """判断异常是否属于"无输入设备/设备被拔"这类可安静重试的情况。

    命中则按预期状态处理(不刷 traceback); 否则当作真实故障照常记录。
    """
    if isinstance(exc, sd.PortAudioError):
        text = str(exc).lower()
        # 只保留具体的\"无设备/设备不可用\"模式。之前的 `"-1" in text` 过于宽泛: 任何含
        # "-1" 的 PortAudioError(错误码 / 帧数 / 无关索引里的巧合数字)都会被当成\"无输入
        # 设备\"而静默等待, 可能掩盖真实故障。PortAudio 报无设备时会带 "Invalid device"
        # (paInvalidDevice)等明确措辞, 已被下列模式覆盖。
        return (
            "querying device" in text
            or "invalid device" in text
            or "device unavailable" in text
        )
    return False


class VoiceChatSubsystem:
    """唤醒词驱动的本机语音助手。单 owner 线程 + 一条 KWS 麦克风流。"""

    def __init__(self):
        self._spotter = None
        self._thread = None
        self._stop = threading.Event()
        self._enabled = threading.Event()  # 常驻监听开关
        self._enabled.set()
        self._conversations = {}  # model 别名 -> browser conversation_id
        self._conversations_lock = threading.Lock()
        # 跨模型的"虚拟会话历史": 每轮追加 user query + 助手完整回答。唤醒词切到另一
        # 个模型时, 新模型没有自己的 browser conversation_id, 就把这份历史重放给它,
        # 让它继承此前对话的上下文(既有 conversation_id 路径的服务端历史由 relay 侧
        # 维护, 无需重放)。"换个话题"时连同 _conversations 一并清空。
        self._history = []  # list[dict{"role","content"[,"model"][,"seq"]}]
        self._history_lock = threading.Lock()
        # 切回旧模型不丢中途对话: 给每条历史轮打单调 seq, 并记录每个模型的服务端
        # 会话"已覆盖到的最高 seq"(水位线)。切回某个已有 conversation_id 的模型时, 只补它
        # 未覆盖(其间在别的模型上产生)的 delta, 既不只发当前句(会丢中途对话)、也不重发它
        # 服务端已有的历史。
        self._history_seq = 0
        self._history_covered = {}  # model -> 已覆盖的最高历史 seq
        # 上次发"恢复提示 TTS"的单调时刻, 用于节流(见 _nudge_audio_recovery)。
        self._last_recovery_nudge_at = 0.0
        self._rcmd_down_since = 0.0
        self._last_rcmd_tap_at = 0.0
        # 中止进行中的一轮对话(暂停/关闭时置位): 打断听写/流式/播报等待。
        self._turn_abort = threading.Event()
        # HUD 一次性隐藏定时器句柄: 每次 flash 前取消上一个, 避免 Timer 堆积。
        self._hud_timer = None
        self._hud_timer_lock = threading.Lock()
        # 麦克风打开失败的连续错误计数, 用于退避 + 日志节流。
        self._listen_error_count = 0
        # apple 单会话 helper 本轮是否真正进入过聆听(emit "started")。用于外层循环
        # 区分"正常会话结束"与"无麦致命 fast-fail", 后者需退避而非立即重生。
        self._apple_session_started = False
        # 本轮是否真的 spawn 了 helper 进程。用于区分"已 spawn 但未 started"(真 fast-fail,
        # 需事件驱动等待重试)与"restart-gap 后状态变脏、根本没 spawn 的干净退出"(外层直接
        # 回顶重判, 不可误计为 fast-fail)。
        self._apple_spawned = False
        # 本轮 helper 进程被 spawn 的单调时间戳。fast-fail 退避按"距本次 spawn"计, 会话已
        # 耗时则只补剩余, 故重连不被额外拖慢。
        self._apple_spawn_at = 0.0
        self._apple_route_start_failures = 0
        self._apple_route_start_cooldown_until = 0.0
        self._apple_last_start_error = None
        # 连续 -10868 达阈值后不再定时 spawn。只等 CoreAudio 权威输入事件，事件后
        # settle，再放行一次 probe；失败则重新 parking。
        self._apple_route_quarantined = False
        # 无麦克风时的"等待"状态标志: 用于状态转移只记一条日志(等待/恢复), 不忙等刷屏。
        self._mic_waiting = False
        # 上次真开流探测的单调时间戳: 无设备且被高频事件唤醒时限速, 避免密集抢
        # PORTAUDIO_LIFECYCLE_LOCK 与音频恢复路径争用(典型: 蓝牙麦反复重选默认输入)。
        self._last_probe_at = 0.0
        # apple 会话 partial 节流日志用的上一条文本。
        self._last_partial_logged = None
        # ---- owner 守卫: 只中断 wake 自己发起的听写/播报, 绝不误伤 ----
        # Ctrl 听写或其他功能的 TTS。wake 与 Ctrl 听写经 IS_DICTATION_ACTIVE 互斥,
        # 故 _wake_dictation_active 为真 <=> 当前 Apple Speech helper 是 wake 启动的。
        self._wake_dictation_active = threading.Event()  # wake 听写进行中
        self._wake_speaking_active = threading.Event()  # wake 回答播报进行中

    def start(self):
        if self._thread is not None and self._thread.is_alive():
            return
        # sherpa 引擎先校验关键词配置: 坏 keywords 会让 sherpa C++ 侧硬退出
        # (Encode keywords failed), 表现为 launchd 无限重启循环。apple 引擎是
        # 纯文本匹配, 不需要 keywords 文件。
        if VE_VOICE_CHAT_KWS_ENGINE == "sherpa":
            try:
                kw_path = _ve_voice_chat_keywords_file()
                _ve_voice_chat_build_keywords_string()
            except Exception:
                _xiaoai_log.exception("Voice chat keywords invalid; subsystem disabled")
                return
        else:
            kw_path = "apple engine (文本匹配, 无需 keywords 文件)"
        self._stop.clear()
        self._thread = threading.Thread(
            target=self._run, name="VoiceChatWakeWord", daemon=True
        )
        self._thread.start()
        _xiaoai_log.info(
            "Voice chat subsystem started: keywords=%s threshold=%.3f score=%.2f",
            kw_path,
            VE_VOICE_CHAT_KWS_THRESHOLD,
            VE_VOICE_CHAT_KWS_SCORE,
        )
        # 诊断: 打印实际喂给 sherpa 的 keywords 内容(pypinyin 生成的 token 串)。
        # 若这里的拼音与 tokens.txt 约定不一致, 唤醒词永远匹配不到, 再调阈值也没用。
        if VE_VOICE_CHAT_KWS_ENGINE == "sherpa":
            try:
                _kws_log.info(
                    "Voice chat KWS keywords content:\n%s",
                    _ve_voice_chat_build_keywords_string(),
                )
            except Exception:
                _kws_log.exception("Voice chat KWS keywords dump failed")
        else:
            _kws_log.info(
                "Voice chat apple KWS keywords: %s",
                [w for w, _s, _t in VE_VOICE_CHAT_KEYWORDS],
            )

    def stop(self):
        self._stop.set()
        self._turn_abort.set()
        # 唤醒可能正 block 在"等待输入设备"事件上的 _run 线程, 使关闭即时生效,
        # 而非空等兜底超时导致 join 超时。
        AUDIO_INPUT_DEVICE_CHANGED.set()
        # 只中断 wake 自己发起的听写/播报, 绝不误杀 Ctrl 听写或他人 TTS。
        self._abort_own_turn("subsystem stop")
        thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=6.0)
            if thread.is_alive():
                _xiaoai_log.warning(
                    "Voice chat thread did not exit within join timeout; "
                    "mic already released via helper SIGTERM"
                )
        self._thread = None
        self._cancel_hud_timer()

    # ---- 右⌘ 双击(由 Quartz flagsChanged seam 调用)----
    def on_flags_changed(self, event):
        try:
            keycode = int(
                Quartz.CGEventGetIntegerValueField(  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                    event,
                    Quartz.kCGKeyboardEventKeycode,  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
                )
            )
        except Exception:
            return
        if keycode not in VE_VOICE_CHAT_RIGHT_CMD_KEYCODES:
            return
        try:
            flags = Quartz.CGEventGetFlags(event)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
            cmd_down = bool(flags & Quartz.kCGEventFlagMaskCommand)  # pyright: ignore[reportAttributeAccessIssue, reportOptionalMemberAccess, reportArgumentType]
        except Exception:
            return
        now = time.monotonic()
        if cmd_down:
            self._rcmd_down_since = now
            return
        down_at = self._rcmd_down_since
        self._rcmd_down_since = 0.0
        if down_at <= 0 or (now - down_at) > MAX_MODIFIER_TAP_DURATION:
            return
        if now - self._last_rcmd_tap_at <= VE_VOICE_CHAT_DOUBLE_TAP_WINDOW:
            self._last_rcmd_tap_at = 0.0
            self._toggle_enabled()
        else:
            self._last_rcmd_tap_at = now

    def _toggle_enabled(self):
        if self._enabled.is_set():
            self._enabled.clear()
            # 暂停要能打断"正在进行的一轮":置中止标志, 并只中断 wake 自己发起的
            # 听写/播报, 让其尽快退出, 而不是只影响下一次监听、也不误伤他人。
            self._turn_abort.set()
            self._abort_own_turn("voice chat paused")
            _xiaoai_log.info("Voice chat listening PAUSED (double-tap right cmd)")
            self._flash_hud("voice_paused", "监听已暂停")
        else:
            self._turn_abort.clear()
            self._enabled.set()
            _xiaoai_log.info("Voice chat listening RESUMED (double-tap right cmd)")
            self._flash_hud("voice_listen", "监听已开启，说出唤醒词")

    def _abort_own_turn(self, reason: str):
        """中断 wake 自己发起的一轮, 严格避免误伤其他麦克风/TTS 消费者。

        - 仅当 _wake_dictation_active 为真才 SIGTERM Apple Speech helper: 此时该
          helper 必是 wake 启动的(wake 与 Ctrl 听写经 IS_DICTATION_ACTIVE 互斥),
          绝不会掐断用户正在进行的 Ctrl 听写。
        - 仅当 _wake_speaking_active 为真才切 TTS: 避免暂停语音助手时误切其他功能
          (如 MCP ask_user_dictation 读题)正在播放的语音。
        """
        if self._wake_dictation_active.is_set():
            try:
                exited = _voice_chat_force_stop_apple_speech(reason)
                if not exited:
                    # helper 在 CoreAudio teardown 中拒绝 SIGTERM, 受
                    # "绝不 SIGKILL"策略约束, 可能短暂继续占麦、与 KWS 新流并存。
                    _dictation_log.warning(
                        "Voice chat: wake dictation helper refused SIGTERM (%s); "
                        "mic may stay busy briefly until CoreAudio teardown completes",
                        reason,
                    )
            except Exception:
                _xiaoai_log.debug(
                    "abort: force-stop apple speech failed", exc_info=True
                )
        if self._wake_speaking_active.is_set():
            try:
                stop_tts_immediately(reason)
            except Exception:
                _xiaoai_log.debug("abort: stop_tts_immediately failed", exc_info=True)

    def _flash_hud(self, status, text):
        # 默认无 HUD:唤醒助手走后台, 不弹任何提示窗。置 VE_VOICE_CHAT_SHOW_HUD=1 才显示。
        if not VE_VOICE_CHAT_SHOW_HUD:
            return
        try:
            hud.show(status, "语音助手", text)
        except Exception:
            return
        # 取消上一个隐藏定时器再排新的, 否则快速连续 flash 会堆积 Timer。
        self._cancel_hud_timer()
        try:
            timer = threading.Timer(0.8, hud.hide_visual_only)
            timer.daemon = True
            with self._hud_timer_lock:
                self._hud_timer = timer
            timer.start()
        except Exception:
            pass

    def _cancel_hud_timer(self):
        with self._hud_timer_lock:
            timer = self._hud_timer
            self._hud_timer = None
        if timer is not None:
            try:
                timer.cancel()
            except Exception:
                pass

    # ---- KWS ----
    def _ensure_spotter(self):
        # 复用全局按内容缓存的 spotter: Trie 只编译一次, 多实例共享同一图。
        if self._spotter is None:
            self._spotter = _ve_voice_chat_get_spotter()
        return self._spotter

    def _run(self):
        if VE_VOICE_CHAT_KWS_ENGINE == "apple":
            self._run_apple()
            return
        try:
            spotter = self._ensure_spotter()
        except Exception:
            _kws_log.exception("Voice chat KWS init failed; subsystem disabled")
            return
        while not self._stop.is_set():
            if not self._enabled.is_set():
                self._enabled.wait(timeout=0.25)
                continue
            # 让麦: 听写/播报要用麦时不开流, 避免与既有音频生命周期抢占。
            if IS_DICTATION_ACTIVE or IS_SPEAKING:
                time.sleep(0.2)
                continue
            # route change 待处理: 既有链路即将 terminate/reinit PortAudio 时不开流。但
            # AUDIO_ROUTE_CHANGE_PENDING 只由 TTS 输出恢复清除 —— 连蓝牙耳机后若无 TTS 流过
            # 则永不清, 本循环永久卡死。顺着架构主动发一句 TTS(节流)唤醒 owner 线程跑恢复,
            # 恢复完成会清掉该标志, 下一轮即可推进。
            if AUDIO_ROUTE_CHANGE_PENDING.is_set():
                self._nudge_audio_recovery("route change pending")
                time.sleep(0.2)
                continue
            # 懒加载: 开麦前先用既有 check_audio_input_device() 确认有输入设备。无麦 ->
            # 安静等待(状态转移只记一条)。热插拔后的 PortAudio 刷新交给既有 route-change
            # 链路, 本子系统只轮询探测, 不自行 terminate/reinit。
            if not self._wait_for_input_device():
                continue
            try:
                keyword = self._listen_for_keyword(spotter)
            except Exception as exc:
                # 无设备/设备被拔: 属预期状态, 转入安静等待, 不刷 traceback。
                if _ve_voice_chat_is_no_input_device_error(exc):
                    if not self._mic_waiting:
                        _audio_log.warning(
                            "Voice chat: input device lost; "
                            "waiting for a microphone (event-driven)"
                        )
                        self._mic_waiting = True
                    self._wait_input_device_event()
                    continue
                # 其他真实故障: 退避 + 日志节流。
                self._listen_error_count += 1
                delay = min(5.0, 0.5 * (2 ** min(self._listen_error_count - 1, 4)))
                if self._listen_error_count == 1 or self._listen_error_count % 10 == 0:
                    _kws_log.exception(
                        "Voice chat KWS listen error (#%d); backing off %.1fs",
                        self._listen_error_count,
                        delay,
                    )
                else:
                    _kws_log.debug(
                        "Voice chat KWS listen error (#%d): %r",
                        self._listen_error_count,
                        exc,
                    )
                self._stop.wait(timeout=delay)
                continue
            self._listen_error_count = 0
            if not keyword or self._stop.is_set():
                continue
            try:
                self._handle_wake(keyword)
            except Exception:
                _xiaoai_log.exception("Voice chat turn failed: keyword=%r", keyword)

    def _wait_for_input_device(self) -> bool:
        """确保有可用输入设备; 无则事件驱动地等待, 不轮询。

        返回 True 表示设备就绪(可以开麦); False 表示本轮仍无设备(调用方 continue)。
        - 探测复用既有 check_audio_input_device()(持 PORTAUDIO_LIFECYCLE_LOCK, 真开一
          次 InputStream 验证可用), 不再重造设备扫描。
        - 状态转移只记一条日志(等待 / 恢复), 不忙等刷屏。
        - 无设备时 block 在 AUDIO_INPUT_DEVICE_CHANGED 上: CoreAudio route monitor 在设备
          变化时置位 -> 即时唤醒; stop() 也会置位 -> 关闭即时醒。兜底超时仅防事件在
          teardown 期丢失。热插拔的 PortAudio 刷新仍交给既有 route-change 链路。
        - 限速: 仅在无设备等待态(_mic_waiting)下, 距上次探测 <0.5s 则不重复开流探测,
          再等一次事件。挡住高频输入变化突发(如蓝牙麦反复重选默认输入, 该路径只置
          AUDIO_INPUT_DEVICE_CHANGED 不置 PENDING, 不被 _run 顶部 PENDING 门拦下)密集
          抢 PORTAUDIO_LIFECYCLE_LOCK。稳态与首次探测不受影响(_mic_waiting 为 False)。
        """
        now = time.monotonic()
        if self._mic_waiting and (now - self._last_probe_at) < 0.5:
            self._wait_input_device_event()
            return False
        self._last_probe_at = now
        if check_audio_input_device():
            if self._mic_waiting:
                _audio_log.debug("Voice chat: microphone detected; resuming listening")
                self._mic_waiting = False
                self._listen_error_count = 0
            return True
        # 无设备: 首次进入记一条, 之后静默等待事件。
        if not self._mic_waiting:
            _audio_log.warning(
                "Voice chat: no input device; waiting for a microphone (event-driven)"
            )
            self._mic_waiting = True
        # 事件驱动等待设备变化。仅当被真实设备变化事件唤醒(而非空闲兜底超时)才考虑发
        # 恢复提示 —— 避免无麦/无变化的空闲机器每隔兜底超时就空转刷 TTS。时机检测(等
        # route 稳定 + 稳定后重探, 覆盖纯输入设备变化: 只置 AUDIO_INPUT_DEVICE_CHANGED、
        # 不置 PENDING, 故 _run 的 PENDING 门不触发)都在 _nudge_audio_recovery 内。
        if self._wait_input_device_event():
            self._nudge_audio_recovery("input device changed")
        return False

    def _wait_input_device_event(self) -> bool:
        """block 直到输入设备变化事件、或 stop, 或兜底超时。取代固定间隔轮询。

        返回 True 表示被真实的设备变化事件唤醒(用于边沿触发: 只有确有拓扑变化才考虑
        发恢复提示); False 表示兜底超时或 stop(空闲无变化, 不应发 TTS, 避免无麦机器空转
        刷屏)。
        """
        # 先 clear 再 wait: clear 后 monitor/stop 的 set 仍会即时唤醒(Event 持久),
        # 不丢通知; clear 前的陈旧 set 则被丢弃, 避免消费旧事件空转。
        # 单 owner 线程消费, 无并发 clear 竞争。
        AUDIO_INPUT_DEVICE_CHANGED.clear()
        if self._stop.is_set():
            return False
        # Event.wait 返回 True <=> 事件被置位(真实设备变化); False <=> 超时。
        return AUDIO_INPUT_DEVICE_CHANGED.wait(
            timeout=_VE_VOICE_CHAT_DEVICE_WAIT_FALLBACK
        )

    def _nudge_audio_recovery(self, reason: str):
        """路由变化后驱动一次音频恢复清 AUDIO_ROUTE_CHANGE_PENDING, 全程静音。

        为什么需要: KWS 的 _run 与内层 _listen 都 gate 在 AUDIO_ROUTE_CHANGE_PENDING 上,
        而该标志只由 owner 线程(TTS 消费者)的输出恢复清除。连/断蓝牙耳机后若无 TTS 流过,
        该标志永不清 -> KWS 永久卡死(既不开麦也不打 wake 日志)。

        怎么做(不出声): 往 TTS 队列投一个"静音恢复标记"(__ve_audio_recovery__), owner
        线程收到后只跑一次 ensure_tts_output_ready(清 PENDING/刷新输出)、不播放任何音频。
        恢复仍在 owner 线程执行, 不违反 owner 守卫, 也不在 KWS 线程碰 PortAudio 生命周期。
        连接与断开都不出声 -> 解决"关蓝牙误发 TTS"。KWS 阻塞在 PENDING 门时不持麦, 故
        owner 线程即便走到 stage-2 terminate/reinit 也无竞争。

        时机: 先 wait_for_audio_route_stability 等 CoreAudio 拓扑稳定(自适应不同耳机的
        连接耗时, 而非固定延迟)-> 不会在设备还没连稳时驱动。节流: 两次至少间隔
        VE_VOICE_CHAT_RECOVERY_NUDGE_INTERVAL, 若一次恢复未清掉 PENDING 也不会紧凑刷队列。
        """
        if self._stop.is_set():
            return
        now = time.monotonic()
        if (now - self._last_recovery_nudge_at) < VE_VOICE_CHAT_RECOVERY_NUDGE_INTERVAL:
            return
        self._last_recovery_nudge_at = now
        # 时机: 等拓扑稳定, 自适应不同蓝牙耳机的连接耗时。
        wait_for_audio_route_stability(timeout=VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT)
        if self._stop.is_set():
            return
        _audio_log.debug("Voice chat: driving silent audio recovery (%s)", reason)
        # 懒启动 TTS consumer(幂等, 已运行则零开销返回): recovery 标记需要
        # consumer 线程处理, voice chat 模式启动时不预启动 consumer。
        # 记录本次 nudge 是否【冷启动】了 consumer(启动前它未在运行): 若是, 冷启动会在
        # 上面 wait_for_audio_route_stability 稳定后的【当前路由】上建好一条健康流, 后续
        # recovery 标记只需清 PENDING、无需再 recreate(否则每次冷启动必建 2 次流: 冷启动 1
        # 次 + 标记 recreate 1 次, 正是"关耳机刷新 2 次"的来源)。已运行时不改变既有行为。
        _cold_started = not (
            TTS_CONSUMER_THREAD is not None and TTS_CONSUMER_THREAD.is_alive()
        )
        _ensure_tts_consumer_started()
        try:
            done_result = TTSCompletionResult()
            TTS_TEXT_QUEUE.put(
                {
                    "__ve_audio_recovery__": True,
                    "cold_started": _cold_started,
                    "done_results": [done_result],
                },
                timeout=5.0,
            )
            # 等 owner 线程处理完标记(恢复跑完)再返回, 下一轮 PENDING 已清即可推进。
            done_result.event.wait(timeout=VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT + 5.0)
        except Exception:
            _audio_log.debug("Voice chat: silent audio recovery failed", exc_info=True)

    def _prewarm_output_before_answer(self):
        """Voice chat 回答前使用统一 TTS 准备事务。"""
        if self._stop.is_set():
            return
        ready = _prepare_tts_output(preempt_kws=False)
        _tts_log.debug(
            "Voice chat: TTS output preparation before answer ready=%s", ready
        )

    def _run_apple(self):
        """Apple Speech 单会话唤醒引擎: 一个常驻听写会话干到底。

        同一会话持续输出 partial 文本: 未唤醒时匹配唤醒词; 命中后同一会话继续
        收集指令(partial 是累计全文, 取最新一条), 静音自停结束; 然后停麦走回答
        (LLM+TTS), 播报完重启会话。Ctrl 听写/其他功能要麦时让出。
        """
        _kws_log.debug("Voice chat KWS engine: apple (single continuous session)")
        while not self._stop.is_set():
            if not self._enabled.is_set():
                self._enabled.wait(timeout=0.25)
                continue
            # 让麦: 播报/听写期间不起会话。_TTS_PREEMPT_KWS: TTS 即将播放, 提前让麦释放 HFP,
            # 使输出流一次建在 A2DP(见 _prewarm_output_via_kws_preempt)。开关关时该信号恒 clear。
            if IS_DICTATION_ACTIVE or IS_SPEAKING or _TTS_PREEMPT_KWS.is_set():
                self._stop.wait(timeout=0.2)
                continue

            if self._apple_route_quarantined:
                _kws_log.debug(
                    "Voice chat apple KWS parked after repeated CoreAudio -10868; "
                    "waiting for an input-device event"
                )
                changed = self._wait_input_device_event()
                if not changed or self._stop.is_set():
                    continue
                stable = wait_for_audio_route_stability(
                    timeout=VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT
                )
                _kws_log.debug(
                    "Voice chat apple KWS quarantine probe gate: route_stable=%s",
                    stable,
                )
                if not stable:
                    continue
                # 只放行一次 probe。若仍为 -10868，下面 fast-fail 分支会再次 quarantine。
                self._apple_route_quarantined = False
                self._apple_route_start_cooldown_until = 0.0
                self._apple_last_start_error = None

            # route change 待处理: 与 sherpa 引擎(_run)同构 —— 既有链路即将 terminate/
            # reinit PortAudio 时不开 helper。AUDIO_ROUTE_CHANGE_PENDING 只由 TTS 输出恢复
            # 清除, 连蓝牙耳机后若无 TTS 流过则永不清; 顺架构主动 nudge 一次恢复(节流)驱动
            # owner 线程跑恢复并清标志, 下一轮即可推进。不在 teardown 窗口里起 helper, 避免
            # 与 CoreAudio 重配相撞再次触发 route change。
            if AUDIO_ROUTE_CHANGE_PENDING.is_set():
                self._nudge_audio_recovery("route change pending")
                self._stop.wait(timeout=0.2)
                continue

            # CoreAudio 权威麦克风闸门(与 helper 同一子系统, 不是 PortAudio)。
            # audio_route_monitor.swift 每个事件都带 input_device_ids = 当前【带输入流】的
            # 设备 id 集合(内置麦/蓝牙耳机麦有, 纯输出设备无)。空集 = CoreAudio 视角下【根本
            # 没有麦克风】——正是 helper 打开 CoreAudio 默认输入会 code=10 的同源原因。无麦时
            # 【一个 helper 都不 spawn】, 事件驱动等蓝牙重连(route monitor 在设备变化时置位
            # AUDIO_INPUT_DEVICE_CHANGED 立即唤醒)。这从源头消灭"每 2s spawn 一个必死 helper"
            # 的刷屏(下方 fast-fail 的最小间隔只是限速、并不停; 这里才真正停)。仅在 monitor
            # 就绪且确认发过该字段时才据此拦截, 旧 Swift 二进制(不发该字段)回退到让 helper 去探。
            # 无麦闸门(两条判据 OR, 任一成立即判定无麦: 不 spawn 必死 helper, 改事件驱动等麦)。
            # (a) input_device_ids 空集 —— 判的是【设备表里带输入流的设备数为 0】。
            # (b) _AUDIO_DEFAULT_INPUT_ID 为 None —— 判的是【CoreAudio 当前默认输入设备缺失】,
            #     与 helper code=10 的条件逐字对齐(start()->validateDefaultInputHardware()->
            #     currentDefaultInputDeviceID(), 默认输入 == kAudioObjectUnknown 时抛错)。
            # 为何 (a) 不够: audio_route_monitor 的 inputDeviceIDs() 用 deviceHasInput(input
            #   scope streams>0)枚举【设备表】, 蓝牙耳机登记一条 HFP 输入流 -> 集合非空 -> (a) 恒
            #   假。且 default_input 移除事件【不刷新】该集合, 关耳机后集合仍残留 -> (a) 永不拦。
            # 为何 (b) 用【专用镜像 _AUDIO_DEFAULT_INPUT_ID】而非 AUDIO_ROUTE_LAST_INPUT_ID:
            #   后者在移除(input_id=None)时【故意保留旧值】(实测关耳机后仍为 165, 见日志
            #   "input_id=165"), 给静音恢复 force_refresh 去重复用 -> 用它判 (b) 对"连了再关"
            #   永远为假, 正是二次 loop 的真因。_AUDIO_DEFAULT_INPUT_ID 由每个 route 事件按
            #   event["default_input_id"] 忠实刷新(缺失即 None), 关耳机即归零 -> (b) 命中。
            # SNAPSHOT 非空守卫: 排除 monitor 崩溃却置 READY(无快照)时误判有麦机器。
            # 有麦时 (a)(b) 均为假, 正常放行。
            if AUDIO_ROUTE_MONITOR_READY.is_set() and (
                (_AUDIO_INPUT_DEVICE_IDS_SEEN and not _AUDIO_INPUT_DEVICE_IDS)
                or (
                    AUDIO_ROUTE_LAST_SWIFT_SNAPSHOT is not None
                    and _AUDIO_DEFAULT_INPUT_ID is None
                )
            ):
                if not self._mic_waiting:
                    _audio_log.info(
                        "Voice chat apple: CoreAudio reports no input device; not "
                        "spawning helper (event-driven wait for a microphone)"
                    )
                    self._mic_waiting = True
                # 蓝牙重连即时醒; 无变化时兜底超时后重探。不 spawn, 不刷屏。
                self._wait_input_device_event()
                continue
            if self._mic_waiting:
                _xiaoai_log.info(
                    "Voice chat apple: microphone present; resuming listening"
                )
                self._mic_waiting = False
                self._listen_error_count = 0

            # 【不再查 PortAudio】。apple 路径的麦克风探针就是 helper 本身: 它用 CoreAudio
            # AVAudioEngine 的默认输入, 起不来就 emit code=10(权威)。而 check_audio_input_
            # device() 走 PortAudio, 两个子系统视角会打架 —— 这台机器上蓝牙拔掉后 PortAudio
            # 仍报"有输入"(假阳性), 顶部闸门被放行、照样 spawn -> code=10, 查它毫无意义还每轮
            # 白开一次 InputStream 抢锁。故这里【直接让 helper 去探】: spawn 成功 = 有麦、正常
            # 长会话; spawn 后秒退(未 emit started)= 无麦, 由下方 fast-fail 分支【事件优先 +
            # 最小间隔】处理: 蓝牙重连时 CoreAudio route monitor 置位 AUDIO_INPUT_DEVICE_CHANGED
            # 立即唤醒(重连 <= 一个最小间隔即恢复), churn 被最小间隔钳住不 flood。
            # 注: sherpa 引擎(_run)仍用 _wait_for_input_device —— 它的 KWS 直接读 PortAudio
            # 流, 用 PortAudio 探针才对口径; 只有 apple(CoreAudio helper)路径不该问 PortAudio。
            try:
                self._run_apple_session()
            except Exception:
                self._listen_error_count += 1
                delay = min(5.0, 0.5 * (2 ** min(self._listen_error_count - 1, 4)))
                if self._listen_error_count == 1 or self._listen_error_count % 10 == 0:
                    _xiaoai_log.exception(
                        "Voice chat apple session error (#%d); backing off %.1fs",
                        self._listen_error_count,
                        delay,
                    )
                self._stop.wait(timeout=delay)
                continue

            # helper 是否真正进入过聆听(emit 了 "started")? started 只在引擎起、tap 装好后
            # 才发, code=10 无麦致命启动路径【绝不会】发。据此区分:
            #  - 起来过(productive): 清零错误计数, 立刻重启下一会话(旧行为)。
            #  - 从未起来(fast-fail): helper spawn 了却从没 emit "started"。以 helper 回传
            #    为准(code=10 = CoreAudio 无默认麦克风), 不再问 PortAudio。处理 =【事件优先
            #    + 最小间隔】: 先在 AUDIO_INPUT_DEVICE_CHANGED 上等(蓝牙重连由 CoreAudio route
            #    monitor 置位 -> 立即唤醒, 重连快), 再补足"距本次 spawn 不足 MIN_INTERVAL"的
            #    剩余时间(只按时间, 不可被设备 churn 缩短 -> 无麦时反复重选缺失默认输入的 churn
            #    被钳住, 每次至少隔 MIN_INTERVAL, 不 flood)。不再用 30s 指数地板, 故重连最坏
            #    只等 ~MIN_INTERVAL(默认 2s)。
            if self._apple_session_started:
                self._listen_error_count = 0
            elif not self._apple_spawned:
                # gap 后状态变脏、根本没 spawn helper 的干净退出: 不是故障, 不计数、不退避。
                # 外层回顶重判(暂停/停止/route-pending)各自的闸门自会处理。
                self._listen_error_count = 0
            else:
                self._listen_error_count += 1
                if self._apple_last_start_error == "-10868":
                    self._apple_route_start_failures += 1
                    cooldown = min(
                        12.0, 2.0 * (2 ** min(self._apple_route_start_failures - 1, 3))
                    )
                    self._apple_route_start_cooldown_until = max(
                        self._apple_route_start_cooldown_until,
                        time.monotonic() + cooldown,
                    )
                    _kws_log.warning(
                        "Voice chat apple KWS CoreAudio -10868 cooldown: failures=%d delay=%.1fs",
                        self._apple_route_start_failures,
                        cooldown,
                    )
                    if self._apple_route_start_failures >= 3:
                        self._apple_route_quarantined = True
                        _kws_log.error(
                            "Voice chat apple KWS entering CoreAudio route quarantine "
                            "after %d consecutive -10868 failures; periodic helper spawn disabled",
                            self._apple_route_start_failures,
                        )
                if self._listen_error_count == 1 or self._listen_error_count % 5 == 0:
                    _xiaoai_log.info(
                        "Voice chat apple session did not start (#%d; helper cannot "
                        "open the mic); waiting for a device change (min %.1fs between "
                        "retries)",
                        self._listen_error_count,
                        _VE_VOICE_CHAT_FASTFAIL_MIN_INTERVAL,
                    )
                # 事件优先: 蓝牙重连 -> AUDIO_INPUT_DEVICE_CHANGED 置位 -> 立即唤醒;
                # 无变化时兜底超时(_VE_VOICE_CHAT_DEVICE_WAIT_FALLBACK)后重试。
                if self._apple_route_quarantined:
                    # 外层回顶后进入纯事件 parking；这里不再等 fallback timeout 后重试。
                    continue
                self._wait_input_device_event()
                cooldown_remaining = (
                    self._apple_route_start_cooldown_until - time.monotonic()
                )
                if cooldown_remaining > 0 and not self._stop.is_set():
                    self._stop.wait(timeout=cooldown_remaining)
                # 最小间隔: 只补足"距本次 spawn"不足的剩余(会话已耗时则更短或为 0),
                # 仅可被 stop 打断, 不可被设备 churn 缩短 -> 钳住 flood, 又不额外拖慢重连。
                remaining = _VE_VOICE_CHAT_FASTFAIL_MIN_INTERVAL - (
                    time.monotonic() - self._apple_spawn_at
                )
                if remaining > 0 and not self._stop.is_set():
                    self._stop.wait(timeout=remaining)

    def _run_apple_session(self):
        """一次常驻会话: 直接跑 helper 持续听 -> 唤醒匹配 -> 收集指令 -> 回答。

        与 Ctrl 听写(_run_apple_speech_dictation)同构: 不搞 HFP 占位流、不锁
        采样率、不动持久输出流, 让 helper 按设备原生格式工作。唤醒词匹配靠
        helper 的 partial 文本, 命中后同一会话继续收指令, 静音自停结束。
        """
        # 本会话 helper 是否 emit 过 "started"(引擎起+tap 装好才发)。外层循环据此区分
        # "起来过的正常会话" vs "无麦致命 fast-fail", 决定是否退避。默认 False。
        self._apple_session_started = False
        # 本会话是否真的 spawn 了 helper。restart-gap 后若状态变脏会在 spawn 前干净退出,
        # 届时此标志仍为 False, 外层据此不误计 fast-fail。
        self._apple_spawned = False

        base_dir = os.path.dirname(os.path.abspath(__file__))
        helper_bin = os.path.join(base_dir, "apple_speech_helper")
        helper_swift = os.path.join(base_dir, "apple_speech_helper.swift")
        helper_plist = os.path.join(base_dir, "Info.plist")
        # 多 locale: 传 "primary,secondary,..." 给 helper(单 locale 时就是原字符串)。
        # helper 内 primary 驱动生命周期, 每个 secondary 起一条被动流并行识别唤醒词。
        if _ensure_apple_speech_helper_binary(helper_bin, helper_swift, helper_plist):
            cmd = [helper_bin, VE_VOICE_CHAT_CAPTURE_LOCALE_ARG]
        else:
            cmd = ["/usr/bin/swift", helper_swift, VE_VOICE_CHAT_CAPTURE_LOCALE_ARG]

        global _APPLE_KWS_RESUME_NOT_BEFORE
        with _APPLE_KWS_RESUME_LOCK:
            resume_not_before = _APPLE_KWS_RESUME_NOT_BEFORE
        resume_wait = resume_not_before - time.monotonic()
        if resume_wait > 0:
            _kws_log.debug(
                "Voice chat apple KWS waiting %.2fs for post-TTS route recovery",
                resume_wait,
            )
            self._stop.wait(timeout=resume_wait)
            if self._stop.is_set():
                return
            route_stable = wait_for_audio_route_stability(
                timeout=VE_VOICE_CHAT_ROUTE_SETTLE_TIMEOUT
            )
            _kws_log.debug(
                "Voice chat apple KWS post-TTS route stability: stable=%s",
                route_stable,
            )
            if not route_stable:
                return
            with _APPLE_KWS_RESUME_LOCK:
                if _APPLE_KWS_RESUME_NOT_BEFORE <= time.monotonic():
                    _APPLE_KWS_RESUME_NOT_BEFORE = 0.0

        route_cooldown = self._apple_route_start_cooldown_until - time.monotonic()
        if route_cooldown > 0:
            _kws_log.debug(
                "Voice chat apple KWS spawn held by -10868 cooldown: %.2fs",
                route_cooldown,
            )
            self._stop.wait(timeout=route_cooldown)
            if self._stop.is_set():
                return

        # 与上次 helper 退出拉开间隔(CoreAudio teardown 保护)。这段【必须】等满 —— 它的
        # 目的就是给音频栈留拆解时间; 绝不能因为 route-change 就缩短它去抢那零点几秒, 因为
        # route-change 正是 CoreAudio churn 高峰, 提前 spawn 会撞进半拆状态再次触发失败 loop。
        # 但等满之后要重新校验: 这 1.2s 里若状态变脏(停止/暂停/被听写抢麦/route-change 变
        # pending), 就【不 spawn】干净退出, 让外层回顶走事件驱动闸门。_apple_spawned 仍为
        # False, 外层据此不把这次干净退出误计为 fast-fail。
        global _LAST_APPLE_SPEECH_EXIT_AT
        last_exit = _LAST_APPLE_SPEECH_EXIT_AT
        if last_exit > 0:
            gap = APPLE_SPEECH_RESTART_GAP - (time.monotonic() - last_exit)
            if gap > 0:
                self._stop.wait(timeout=gap)
        # gap 后重新校验: 状态变脏则 spawn 前干净退出(不撞 CoreAudio churn, 不占麦)。
        if (
            self._stop.is_set()
            or not self._enabled.is_set()
            or IS_DICTATION_ACTIVE
            or IS_SPEAKING
            or _TTS_PREEMPT_KWS.is_set()
            or AUDIO_ROUTE_CHANGE_PENDING.is_set()
        ):
            _kws_log.debug(
                "Voice chat apple KWS: state changed during restart gap; "
                "skipping helper spawn this round"
            )
            return

        env = dict(os.environ)
        env["SPEECH_HELPER_ON_DEVICE"] = "1" if VE_VOICE_CHAT_APPLE_ON_DEVICE else "0"
        env["SPEECH_HELPER_CONTEXTUAL_STRINGS"] = json.dumps(
            [word for word, _score, _threshold in VE_VOICE_CHAT_KEYWORDS],
            ensure_ascii=False,
        )
        proc = None
        try:
            try:
                proc = subprocess.Popen(
                    cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    encoding="utf-8",
                    bufsize=1,
                    env=env,
                )
            except Exception as exc:
                _kws_log.warning("Voice chat apple KWS: helper start failed: %s", exc)
                return

            # helper 进程已起(不代表已进入聆听 —— 那要等 "started" 事件)。标记本轮确实
            # spawn 过, 使外层能把"spawn 了但没 started"(真 fast-fail)与"gap 后干净退出"
            # (未 spawn)区分开。同时记录 spawn 时刻, 供 fast-fail 的最小间隔退避按此计。
            self._apple_spawned = True
            self._apple_spawn_at = time.monotonic()

            def _stderr_relay():
                try:
                    if proc.stderr:
                        for line in proc.stderr:
                            line = line.strip()
                            if not line:
                                continue
                            # 分级: 关键诊断行(无麦/致命/重启上限等)保持 INFO; 其余每次会话必刷
                            # 的常规生命周期降 DEBUG, 默认级别下不刷屏, 排障开 DEBUG 仍可见。
                            _low = line.lower()
                            if any(m in _low for m in _APPLE_KWS_KEEP_INFO_MARKERS):
                                _kws_log.info("Apple KWS helper: %s", line)
                            else:
                                _kws_log.debug("Apple KWS helper: %s", line)
                except Exception:
                    pass

            threading.Thread(
                target=_stderr_relay, daemon=True, name="AppleKWSStderr"
            ).start()

            _kws_log.debug("Voice chat apple KWS: session listening (pid=%d)", proc.pid)

            q: queue.Queue = queue.Queue()
            eof = threading.Event()

            def _reader():
                try:
                    if proc.stdout:
                        for line in proc.stdout:
                            q.put(line)
                except Exception:
                    pass
                finally:
                    eof.set()

            threading.Thread(target=_reader, daemon=True, name="AppleKWSRead").start()

            def _make_turn(kw, text):
                """Remove a literal keyword/alias prefix; fuzzy-only wake text yields no command."""
                query = text or ""
                config = _ve_voice_chat_wake_config(kw) or {}
                references = (
                    kw,
                    *(config.get("aliases") or ()),
                )
                # Map every casefolded code point to the exclusive end offset of its
                # source character. This preserves the original command text even when
                # Unicode casefold expands a character, for example German ß -> ss.
                folded_parts = []
                folded_end_offsets = []
                for source_index, char in enumerate(query):
                    folded_char = char.casefold()
                    folded_parts.append(folded_char)
                    folded_end_offsets.extend([source_index + 1] * len(folded_char))
                folded_query = "".join(folded_parts)

                # Prefer the longest folded reference so a short alias such as
                # "hello deep" cannot leave "seek" behind from "hello deepseek".
                for reference in sorted(
                    references,
                    key=lambda value: len(value.casefold()),
                    reverse=True,
                ):
                    folded_reference = reference.casefold()
                    idx = folded_query.find(folded_reference)
                    if idx >= 0:
                        folded_end = idx + len(folded_reference)
                        tail_start = folded_end_offsets[folded_end - 1]
                        tail = query[tail_start:]
                        return tail.strip(" ，,。.!！?？") or None
                return None

            wake_keyword = None
            wake_matched_at = 0.0
            # Segment-only recognition yields two locale transcripts for the same captured
            # utterance. Once one locale matches the wake word, sibling locale results from
            # that same segment must never be interpreted as the next command.
            wake_segment_id = None
            command_min_segment_id = None
            command_segment_id = None
            configured_command_locale = None
            command_segment_in_progress = False
            # 命中唤醒词的流的 locale。多 locale 下每条流各发【本流累计全文】的 partial,
            # 若不区分流"取最新一条"会在两种语言转写间反复横跳、互相覆盖。故命中唤醒词后
            # 把指令累计【钉】在命中那条流上(唤醒词与后续指令天然同语言同流), 使
            # _make_turn 的字面去唤醒词有效。单 locale 时 helper 不发 locale 字段 -> None,
            # 一切退化为旧行为。
            matched_locale = None
            command_locale = None
            query_text = ""
            stream_texts = {}
            stream_text_updated_at = {}
            recognizer_states = {
                locale: "pending" for locale in VE_VOICE_CHAT_CAPTURE_LOCALES
            }
            wake_stream_snapshot = {}
            last_partial_at = 0.0
            # SIGUSR2 是异步软重置；收到 recognition_reset 前丢弃旧 generation 事件。
            resetting_recognition = False

            def _same_stream(ev_locale):
                # 已命中: 只认命中那条流; 未命中: 认 primary(或单 locale 的无标签流),
                # 使唤醒前的 last_partial_at/日志仍以主流为节拍。
                if matched_locale is not None:
                    return ev_locale == matched_locale
                return ev_locale is None or ev_locale == VE_VOICE_CHAT_PRIMARY_LOCALE

            def _notification_model(kw):
                route = _ve_voice_chat_wake_route(kw)
                if route and route[0] == "model":
                    return route[1]
                return None

            while not self._stop.is_set() and self._enabled.is_set():
                if IS_DICTATION_ACTIVE:
                    # Ctrl Dictation remains the only path that takes CoreAudio ownership.
                    return
                try:
                    line = q.get(timeout=0.05)
                except queue.Empty:
                    if wake_keyword:
                        now = time.monotonic()
                        command = (
                            query_text.strip(" ，,。.!！?？") or None
                            if command_segment_id is not None
                            else None
                        )
                        # Segment-only mode never derives a command from the wake segment's
                        # transcript. Wait until a later segment has produced usable text.
                        # 只有已经识别到非空命令，之后的静音才请求 final 并结束本会话。
                        if (
                            command
                            and not command_segment_in_progress
                            and last_partial_at > 0
                            and (now - last_partial_at)
                            >= VE_VOICE_CHAT_COMMAND_SILENCE_SECONDS
                        ):
                            _kws_log.debug(
                                "Voice chat apple KWS: command complete in persistent session, query=%r",
                                command[:80],
                            )
                            try:
                                self._handle_wake(wake_keyword, captured_query=command)
                            except Exception:
                                _xiaoai_log.exception(
                                    "Voice chat turn failed in persistent Apple session: keyword=%r",
                                    wake_keyword,
                                )
                            # Drop all recognition events accumulated while LLM/TTS was active.
                            while True:
                                try:
                                    q.get_nowait()
                                except queue.Empty:
                                    break
                            try:
                                proc.send_signal(signal.SIGUSR2)
                                resetting_recognition = True
                            except Exception as exc:
                                _kws_log.error(
                                    "Voice chat apple KWS: SIGUSR2 soft reset failed: %s",
                                    exc,
                                )
                                return
                            wake_keyword = None
                            wake_matched_at = 0.0
                            wake_segment_id = None
                            command_min_segment_id = None
                            command_segment_id = None
                            configured_command_locale = None
                            command_segment_in_progress = False
                            matched_locale = None
                            command_locale = None
                            query_text = ""
                            stream_texts.clear()
                            stream_text_updated_at.clear()
                            wake_stream_snapshot.clear()
                            last_partial_at = 0.0
                            recognizer_states = {
                                locale: "resetting"
                                for locale in VE_VOICE_CHAT_CAPTURE_LOCALES
                            }
                            _kws_log.debug(
                                "Voice chat apple KWS resumed on persistent AVAudioEngine after TTS"
                            )
                        elif (
                            not command
                            and wake_matched_at > 0
                            and (now - wake_matched_at)
                            >= VE_VOICE_CHAT_DICTATION_TIMEOUT
                        ):
                            _kws_log.debug(
                                "Voice chat apple KWS: command wait timed out after %.1fs; soft resetting",
                                VE_VOICE_CHAT_DICTATION_TIMEOUT,
                            )
                            try:
                                proc.send_signal(signal.SIGUSR2)
                                resetting_recognition = True
                            except Exception:
                                return
                            wake_keyword = None
                            wake_matched_at = 0.0
                            wake_segment_id = None
                            command_min_segment_id = None
                            command_segment_id = None
                            configured_command_locale = None
                            command_segment_in_progress = False
                            matched_locale = None
                            command_locale = None
                            query_text = ""
                            stream_texts.clear()
                            stream_text_updated_at.clear()
                            wake_stream_snapshot.clear()
                            last_partial_at = 0.0
                            continue
                    continue
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                except Exception:
                    continue
                typ = event.get("type")
                if typ == "segment_listener_started":
                    _kws_log.debug(
                        "Voice chat apple KWS segment listener started: preroll=%ss end_silence=%ss maximum=%ss",
                        event.get("preroll_seconds"),
                        event.get("end_silence_seconds"),
                        event.get("maximum_seconds"),
                    )
                    continue
                if typ == "segment_meter":
                    _kws_log.debug(
                        "Voice chat apple KWS segment meter: level=%.5f noise=%.5f start=%.5f hold=%.5f speaking=%s buffers=%s",
                        float(event.get("level") or 0.0),
                        float(event.get("noise_floor") or 0.0),
                        float(event.get("start_threshold") or 0.0),
                        float(event.get("hold_threshold") or 0.0),
                        bool(event.get("speaking")),
                        event.get("observed_buffers"),
                    )
                    continue
                if typ in {
                    "segment_speech_started",
                    "segment_speech_ended",
                    "segment_captured",
                    "segment_complete",
                    "segment_dropped",
                    "segment_error",
                }:
                    _kws_log.debug("Voice chat apple KWS %s: %s", typ, event)
                    if wake_keyword is not None:
                        if typ in {"segment_speech_started", "segment_captured"}:
                            command_segment_in_progress = True
                            last_partial_at = time.monotonic()
                        elif typ in {"segment_complete", "segment_dropped"}:
                            command_segment_in_progress = False
                            last_partial_at = time.monotonic()
                    continue
                if typ == "recognition_reset":
                    resetting_recognition = False
                    stream_texts.clear()
                    stream_text_updated_at.clear()
                    wake_stream_snapshot.clear()
                    for locale in VE_VOICE_CHAT_CAPTURE_LOCALES:
                        recognizer_states[locale] = "resetting"
                    continue
                if resetting_recognition and typ in {"partial", "final"}:
                    _kws_log.debug(
                        "Voice chat apple KWS: ignoring %s while recognition reset is pending",
                        typ,
                    )
                    continue
                if typ == "started":
                    # helper 已真正进入聆听(引擎起+tap 装好)。标记本会话为 productive。
                    self._apple_session_started = True
                    self._apple_route_start_failures = 0
                    self._apple_route_start_cooldown_until = 0.0
                    self._apple_last_start_error = None
                    self._apple_route_quarantined = False
                    primary = event.get("locale") or VE_VOICE_CHAT_PRIMARY_LOCALE
                    recognition_mode = event.get("recognition_mode") or "streaming"
                    recognizer_states[primary] = (
                        "segment_ready"
                        if recognition_mode.startswith("segment_only")
                        else "armed"
                    )
                    _kws_log.debug(
                        "Voice chat apple KWS started: recognition_mode=%s",
                        recognition_mode,
                    )
                    for locale in event.get("secondary_locales") or ():
                        recognizer_states.setdefault(locale, "starting")
                elif typ == "recognizer_state":
                    locale = event.get("locale")
                    state = event.get("state") or "unknown"
                    if locale:
                        recognizer_states[locale] = state
                    debug = event.get("secondary_debug") or {}
                    _kws_log.debug(
                        "Voice chat apple KWS recognizer state: locale=%s state=%s "
                        "failures=%s retry_after=%s error=%r generation=%s "
                        "buffers=%s frames=%s results=%s lifetime=%.3fs "
                        "first_audio_delay=%.3fs last_audio_age=%.3fs",
                        locale,
                        state,
                        event.get("failures"),
                        event.get("retry_after"),
                        event.get("error"),
                        debug.get("generation", event.get("generation")),
                        debug.get("audio_buffers"),
                        debug.get("audio_frames"),
                        debug.get("results"),
                        float(debug.get("task_lifetime", 0.0)),
                        float(debug.get("first_audio_delay", -1.0)),
                        float(debug.get("last_audio_age", -1.0)),
                    )
                    continue
                if typ == "partial":
                    text = (event.get("text") or "").strip()
                    if not text:
                        continue
                    ev_locale = event.get("locale") or VE_VOICE_CHAT_PRIMARY_LOCALE
                    event_source = event.get("source") or "stream"
                    event_segment_id = event.get("segment_id")
                    now = time.monotonic()
                    if (
                        event_source == "segment"
                        and wake_keyword is not None
                        and wake_segment_id is not None
                        and event_segment_id == wake_segment_id
                    ):
                        _kws_log.debug(
                            "Voice chat apple KWS ignoring wake-segment sibling transcript: id=%s locale=%s text=%r",
                            event_segment_id,
                            ev_locale,
                            text[:120],
                        )
                        continue
                    if (
                        event_source == "segment"
                        and command_min_segment_id is not None
                        and event_segment_id is not None
                        and event_segment_id < command_min_segment_id
                    ):
                        continue
                    if event_source == "segment":
                        _kws_log.debug(
                            "Voice chat apple KWS segment transcript: id=%s locale=%s text=%r",
                            event_segment_id,
                            ev_locale,
                            text[:120],
                        )
                    stream_texts[ev_locale] = text
                    stream_text_updated_at[ev_locale] = now
                    recognizer_states[ev_locale] = "active"
                    secondary_debug = event.get("secondary_debug")
                    if secondary_debug:
                        _kws_log.debug(
                            "Voice chat apple KWS recognizer result debug: locale=%s "
                            "generation=%s buffers=%s frames=%s results=%s lifetime=%.3fs "
                            "first_audio_delay=%.3fs last_audio_age=%.3fs",
                            ev_locale,
                            secondary_debug.get("generation"),
                            secondary_debug.get("audio_buffers"),
                            secondary_debug.get("audio_frames"),
                            secondary_debug.get("results"),
                            float(secondary_debug.get("task_lifetime", 0.0)),
                            float(secondary_debug.get("first_audio_delay", -1.0)),
                            float(secondary_debug.get("last_audio_age", -1.0)),
                        )
                    # 任一 recognizer 更新时，同时打印全部配置流的最新快照。没有新回调的
                    # 一侧保留旧值并显示 age，明确它不是与本次事件同步产生的结果。
                    snapshot = []
                    for locale in VE_VOICE_CHAT_CAPTURE_LOCALES:
                        latest = stream_texts.get(locale)
                        updated_at = stream_text_updated_at.get(locale)
                        if latest is None or updated_at is None:
                            snapshot.append(
                                f"{locale}=<{recognizer_states.get(locale, 'pending')}>"
                            )
                        else:
                            snapshot.append(
                                f"{locale}={latest[:80]!r} age={max(0.0, now - updated_at):.2f}s"
                            )
                    log_key = tuple(
                        (locale, stream_texts.get(locale))
                        for locale in VE_VOICE_CHAT_CAPTURE_LOCALES
                    )
                    if log_key != self._last_partial_logged:
                        self._last_partial_logged = log_key
                        _kws_log.debug(
                            "Voice chat apple KWS bilingual[%s updated]: %s",
                            ev_locale,
                            " | ".join(snapshot),
                        )
                    if wake_keyword is None:
                        # 唤醒前: 任一 locale 流的 partial 都参与唤醒词匹配(多 locale
                        # 的意义就在这里 —— 中英文唤醒词各由本语言流更可靠地命中)。
                        hit = _ve_voice_chat_match_keyword(text)
                        if hit:
                            wake_keyword = hit
                            wake_segment_id = (
                                event_segment_id if event_source == "segment" else None
                            )
                            command_min_segment_id = (
                                event_segment_id + 1
                                if isinstance(event_segment_id, int)
                                else None
                            )
                            matched_locale = ev_locale
                            configured_command_locale = _ve_voice_chat_command_locale(
                                hit
                            )
                            command_locale = configured_command_locale
                            inline_command = _make_turn(hit, text)
                            query_text = inline_command or ""
                            command_segment_id = (
                                event_segment_id
                                if event_source == "segment" and inline_command
                                else None
                            )
                            command_segment_in_progress = bool(
                                event_source == "segment" and inline_command
                            )
                            _kws_log.debug(
                                "Voice chat apple KWS command locale mapping: keyword=%r wake_locale=%s command_locale=%s",
                                hit,
                                ev_locale,
                                configured_command_locale or "auto",
                            )
                            wake_stream_snapshot = dict(stream_texts)
                            wake_matched_at = time.monotonic()
                            last_partial_at = wake_matched_at
                            _kws_log.debug(
                                "Voice chat apple KWS matched: %r "
                                "(locale=%s partial=%r inline_command=%r)",
                                hit,
                                ev_locale or VE_VOICE_CHAT_PRIMARY_LOCALE,
                                text[:60],
                                inline_command,
                            )
                            # 已经在当前双语 helper 中持续收音，不需要启动第二个听写 helper。
                            # HUD 关闭时用现有 osascript 通知给出明确反馈；HUD 开启时由 HUD
                            # 自己承担可见反馈，避免重复弹窗。
                            if not VE_VOICE_CHAT_SHOW_HUD:
                                model_alias = _ve_voice_chat_model_alias(
                                    _notification_model(hit)
                                )
                                if inline_command:
                                    preview = (
                                        inline_command[:48] + "…"
                                        if len(inline_command) > 48
                                        else inline_command
                                    )
                                    _ve_voice_chat_notify(
                                        "已收到指令",
                                        subtitle=f"{model_alias} · {preview}",
                                    )
                                else:
                                    _ve_voice_chat_notify(
                                        "正在聆听，请继续说话…",
                                        subtitle="已唤醒 " + model_alias,
                                    )
                        elif _same_stream(ev_locale):
                            # 未命中: 仅主流刷新静音节拍, secondary 不扰动。
                            last_partial_at = time.monotonic()
                    else:
                        # 命中后不再钉死 recognizer。两条 recognizer 共享音频，实际中文可能
                        # 由 en-US 先给出可用文本，英文也可能由 zh-CN 先给出。任一流在唤醒后
                        # 产生了新文本且能提取出命令，就允许它接管本轮。
                        previous = wake_stream_snapshot.get(ev_locale)
                        if (
                            event_source == "segment"
                            and configured_command_locale
                            and ev_locale != configured_command_locale
                        ):
                            _kws_log.debug(
                                "Voice chat apple KWS ignoring unmapped command locale: id=%s locale=%s required=%s text=%r",
                                event_segment_id,
                                ev_locale,
                                configured_command_locale,
                                text[:120],
                            )
                            continue
                        if (
                            event_source == "segment"
                            and event_segment_id != wake_segment_id
                        ):
                            candidate = text.strip(" ，,。.!！?？") or None
                        else:
                            candidate = _make_turn(wake_keyword, text)
                        nested_wake = _ve_voice_chat_match_keyword(text)
                        if (
                            text != previous
                            and candidate
                            and not (nested_wake and candidate == text)
                        ):
                            if event_source == "segment":
                                # First usable locale wins for this command segment. The sibling
                                # locale is merely another transcription of identical PCM and
                                # must not overwrite the command.
                                if command_segment_id is None:
                                    command_segment_id = event_segment_id
                                    command_locale = (
                                        configured_command_locale or ev_locale
                                    )
                                elif (
                                    event_segment_id != command_segment_id
                                    or ev_locale != command_locale
                                ):
                                    _kws_log.debug(
                                        "Voice chat apple KWS ignoring command-segment sibling transcript: id=%s locale=%s locked_id=%s locked_locale=%s text=%r",
                                        event_segment_id,
                                        ev_locale,
                                        command_segment_id,
                                        command_locale,
                                        text[:120],
                                    )
                                    continue
                            else:
                                command_locale = ev_locale
                            query_text = text
                            last_partial_at = time.monotonic()
                elif typ == "final":
                    ev_locale = event.get("locale") or VE_VOICE_CHAT_PRIMARY_LOCALE
                    text = (event.get("text") or "").strip()
                    # Segment-only: final must belong to the exact command segment and the
                    # locale selected by its first usable partial. A sibling locale cannot win
                    # later solely because it finishes later.
                    final_matches_command = event.get("source") != "segment" or (
                        command_segment_id is not None
                        and event.get("segment_id") == command_segment_id
                        and ev_locale == command_locale
                    )
                    final_candidate = None
                    if text and final_matches_command:
                        if (
                            wake_keyword
                            and event.get("source") == "segment"
                            and event.get("segment_id") != wake_segment_id
                        ):
                            final_candidate = text.strip(" ，,。.!！?？") or None
                        else:
                            final_candidate = (
                                _make_turn(wake_keyword, text) if wake_keyword else None
                            )
                    _kws_log.debug(
                        "Voice chat apple KWS final[recognizer=%s source=%s segment=%s candidate=%r]",
                        ev_locale,
                        event.get("source") or "stream",
                        event.get("segment_id"),
                        (final_candidate or "")[:80],
                    )
                elif typ == "error":
                    error_text = str(event.get("error") or "")
                    self._apple_last_start_error = (
                        "-10868" if "-10868" in error_text else "other"
                    )
                    _kws_log.info(
                        "Voice chat apple KWS helper: %s",
                        error_text,
                    )
                    return
                elif typ == "stopped":
                    return
                if eof.is_set() and q.empty():
                    return
                # 持久会话只用 SIGUSR2 软重置，由 recognition_reset 作为完成屏障；
                # SIGUSR1/final 超时兜底仅属于一次性 Ctrl 听写路径。
            return
        finally:
            # This function exits only for subsystem stop, Ctrl Dictation ownership handoff,
            # or a terminal helper failure. Normal TTS turns never reach this teardown.
            if proc is not None and proc.poll() is None:
                try:
                    proc.terminate()
                    proc.wait(timeout=5.0)
                except Exception:
                    pass
            if proc is not None and proc.poll() is not None:
                _clear_apple_speech_process_if_exited(proc)

    def _listen_for_keyword(self, spotter):
        stream = spotter.create_stream()
        blocksize = int(VE_VOICE_CHAT_SAMPLE_RATE * 0.1)
        # 与既有输入路径对齐: 用 _find_usable_input_device() 选设备(优先系统默认),
        # 并在 PORTAUDIO_LIFECYCLE_LOCK 下构造流 —— 仅构造持锁, 与既有
        # _open_audio_input_stream 一致。绝不在整个 read 循环期间持锁, 否则会饿死
        # route-change refresh 和输出流创建。KWS 需要 16k + 阻塞 read(sherpa 模型定死),
        # 与 _open_audio_input_stream 的 48k/callback 不兼容, 故复用其锁与选设备纪律,
        # 而非直接调用它。
        try:
            device_index = _find_usable_input_device()
        except Exception:
            device_index = None
        with PORTAUDIO_LIFECYCLE_LOCK:
            mic_stream = sd.InputStream(
                device=device_index,
                channels=1,
                samplerate=VE_VOICE_CHAT_SAMPLE_RATE,
                dtype="float32",
                blocksize=blocksize,
            )
        # 不用 `with mic_stream`(其 __exit__ 会在 KWS 线程上对蓝牙输入流调 stop()/close(),
        # 与 Pa_StopStream 同类, 可能永久阻塞 -> KWS 想让麦/暂停却卡死)。改手动
        # start + try/finally, 关麦经 _pa_call_with_timeout 超时护栏, 绝不焊死 KWS 线程。
        mic = mic_stream
        # start() 必须在 try 内: 若因并发 route-change 的 terminate 而抛错, finally 仍会
        # 经超时护栏 close 掉已构造的流, 避免泄漏(否则底层流悬空未关, 且异常上抛被分类为
        # "无设备"进入等待, 而该流从未释放)。
        try:
            mic.start()
            _kws_log.debug(
                "Voice chat KWS: input stream opened (device=%r rate=%d blocksize=%d)",
                device_index,
                VE_VOICE_CHAT_SAMPLE_RATE,
                blocksize,
            )
            _kws_dead_since = 0.0
            _kws_stream_started_at = time.monotonic()
            while not self._stop.is_set() and self._enabled.is_set():
                # 让麦: 听写/播报要用麦, 或 route change 待处理(既有链路即将 terminate/
                # reinit PortAudio)时, 立即关流退出, 让既有机制安全刷新, 之后再重开。
                # 这样 KWS 裸流不会在 PortAudio 被 terminate 时还开着 -> 消除竞态。
                if (
                    IS_DICTATION_ACTIVE
                    or IS_SPEAKING
                    or AUDIO_ROUTE_CHANGE_PENDING.is_set()
                ):
                    return None
                # 不做无界阻塞 read(蓝牙断开时 mic.read -> Pa_ReadStream 在设备
                # 消失后永久阻塞, KWS 线程焊死, 永远回不到上面的 PENDING 检查 -> 不 nudge、
                # 不恢复; 只有 TTS 的 sd._terminate 强拆输入流才解脱)。改用 read_available
                # (Pa_GetStreamReadAvailable, 非阻塞)判定是否有足够数据: 设备断开时它不再
                # 增长, 于是不进阻塞 read, 短憩后回到顶部检查 PENDING 并退出让既有机制刷新。
                # 正常有数据时开销可忽略(唤醒词对 ~20ms 轮询延迟无感)。
                try:
                    available = mic.read_available
                except Exception:
                    # read_available 抛错通常意味着设备已消失: 退出让既有 route-change
                    # 链路刷新 PortAudio, 之后 _run 会重开麦。
                    _kws_log.debug(
                        "Voice chat KWS: input device lost (read_available error); "
                        "releasing mic"
                    )
                    return None
                if available < 160:  # 至少 ~10ms 数据才读; 纯防空转
                    self._stop.wait(timeout=0.02)
                    continue
                # HFP 麦按设备周期投递(实测每次最多 ~1024 帧), 永远凑不满 blocksize
                # (1600) -> 旧门控会把 KWS 饿死: 流正常打开但永远不读, 无报错无命中。
                # 改为有多少读多少(sherpa 流式模型接受任意块长), 上限仍按 blocksize
                # 封顶防积压; 设备消失时 read_available 仍会先抛错/归零, 防阻塞不丢。
                samples, _overflowed = mic.read(min(available, blocksize))
                block = samples.reshape(-1)
                # 仅把持续数字静音视为死流：RMS 判定 + 5s 启动宽限 + 8s 连续窗口，
                # 避免噪声门控设备在正常思考停顿时过早触发 recovery。
                now = time.monotonic()
                block_rms = float(np.sqrt(np.mean(np.square(block, dtype=np.float64))))
                dead_stream_detection_armed = now - _kws_stream_started_at >= 5.0
                if dead_stream_detection_armed and block_rms <= 1e-7:
                    if _kws_dead_since == 0.0:
                        _kws_dead_since = now
                    elif now - _kws_dead_since >= 8.0:
                        _kws_log.warning(
                            "Voice chat KWS: input stream RMS remained near zero "
                            "for %.1fs after startup grace; forcing audio recovery",
                            now - _kws_dead_since,
                        )
                        AUDIO_ROUTE_CHANGE_PENDING.set()
                        TTS_OUTPUT_RECOVERY_REQUIRED.set()
                        return None
                else:
                    _kws_dead_since = 0.0
                # 原样喂给模型(不叠加任何增益处理: 实测增益会丢英文词命中)。
                stream.accept_waveform(VE_VOICE_CHAT_SAMPLE_RATE, block)
                while spotter.is_ready(stream):
                    spotter.decode_stream(stream)
                    result = spotter.get_result(stream)
                    if result:
                        _kws_log.debug("Voice chat KWS raw hit: %r", result)
                        spotter.reset_stream(stream)
                        return result
            return None
        finally:
            # 关麦经超时护栏: 蓝牙 stop()/close() 可能永久阻塞, 超时即泄漏该流,
            # 不焊死 KWS 线程, 使暂停/让麦即时生效。
            _pa_call_with_timeout(
                lambda: mic.stop(ignore_errors=True),
                timeout=_PA_CLOSE_TIMEOUT,
                label="KWS InputStream.stop()",
            )
            _pa_call_with_timeout(
                lambda: mic.close(ignore_errors=True),
                timeout=_PA_CLOSE_TIMEOUT,
                label="KWS InputStream.close()",
            )

    # ---- 一轮对话 ----
    def _handle_wake(self, keyword, captured_query: Optional[str] = None):
        route = _ve_voice_chat_wake_route(keyword)
        if route is None:
            _xiaoai_log.warning("Voice chat wake without route: %r", keyword)
            return
        kind, value = route
        if kind == "command" and value == "new_session":
            with self._conversations_lock:
                self._conversations.clear()
            self._history_clear()
            _xiaoai_log.info("Voice chat: virtual sessions cleared (new topic)")
            self._wake_speaking_active.set()
            try:
                speak_local_async(
                    "好的，我们换个话题。",
                    voice=VE_VOICE_CHAT_TTS_VOICE,
                    speed=VE_VOICE_CHAT_TTS_SPEED,
                )
                self._wait_playback_idle(timeout=30.0)
            finally:
                self._wake_speaking_active.clear()
            return

        global IS_DICTATION_ACTIVE

        model = value
        _xiaoai_log.info("Voice chat wake: keyword=%r -> model=%s", keyword, model)

        # 竞态守卫:绝不在 Ctrl 听写已在录音时再开第二个麦克风消费者。
        # 置位 IS_DICTATION_ACTIVE 让 wake 听写成为一等公民, 与既有互斥体系
        # (IS_DICTATION_ACTIVE + Apple Speech 进程单例) 对齐, 关掉竞态窗口。
        with DICTATION_LOCK:
            if IS_DICTATION_ACTIVE:
                _dictation_log.debug(
                    "Voice chat wake ignored: dictation already active"
                )
                return
            IS_DICTATION_ACTIVE = True

        # HUD 关闭时唤醒后是静默进入聆听、无可见反馈。补一条系统通知告知"已唤醒、请说话",
        # 让用户知道助手已在聆听。放在竞态守卫通过之后(真正要开始聆听这一句), 唤醒被忽略
        # 时不会误报。HUD 开启时内部听写 HUD 已有可见提示, 故不重复通知。
        # (apple 单会话引擎的指令已在同一会话捕获, 不再需要"请说话"提示。)
        if captured_query is None and not VE_VOICE_CHAT_SHOW_HUD:
            _ve_voice_chat_notify(
                "正在聆听，请说话…",
                subtitle=f"已唤醒 {_ve_voice_chat_model_alias(model)}",
            )

        self._turn_abort.clear()
        # 不再预闪 voice_wake HUD —— _run_apple_speech_dictation 内部会立刻用
        # "Apple Dictation [locale] Listening..." 覆盖它, 预闪只会一闪即逝造成误导。
        # 让内部听写 HUD(含 partial 实时反馈)直接接管, 反而更真实。
        if captured_query is None:
            try:
                # sherpa 引擎: 唤醒由 KWS 自己完成, 这里只采集一句指令。
                # _run_apple_speech_dictation 不做 locale 区分(会"取最新 partial"),
                # 故只用 primary 单 locale, 不传多 locale 实参。
                query = self._run_wake_dictation(VE_VOICE_CHAT_PRIMARY_LOCALE)
            finally:
                with DICTATION_LOCK:
                    IS_DICTATION_ACTIVE = False
        else:
            # apple 单会话引擎: 指令已在同一听写会话里捕获, 不再开新 helper。
            query = captured_query
            with DICTATION_LOCK:
                IS_DICTATION_ACTIVE = False

        query = strip_llm_artifacts(query or "", remove_reasoning=True).strip()
        if self._turn_abort.is_set() or self._stop.is_set():
            return
        if not query:
            self._flash_hud("voice_nospeech", "没有听清")
            return

        _xiaoai_log.info("Voice chat query: %s", query[:120])
        # 标记 wake 正在播报: 覆盖流式+播报等待整个生命周期, 使暂停/关闭的 owner
        # 守卫只切 wake 自己的 TTS, 不误伤其他功能正在播放的语音。
        self._wake_speaking_active.set()
        # 覆盖“模型流式响应 -> 首个 TTS 入队 -> IS_SPEAKING 置位”的空窗。否则 answer
        # 已生成但合并缓冲尚未 flush 时，Apple KWS 会提前重启并抢回蓝牙 HFP。
        _TTS_PREEMPT_KWS.set()
        try:
            spoken_any = self._stream_and_speak(model, query)
            if spoken_any:
                self._wait_playback_idle(timeout=VE_VOICE_CHAT_ANSWER_TIMEOUT)
            else:
                _TTS_PREEMPT_KWS.clear()
        finally:
            # 正常播放由 consumer 在队列完全排空时清；异常/无语音路径在这里兜底释放。
            if not IS_SPEAKING and TTS_TEXT_QUEUE.empty():
                _TTS_PREEMPT_KWS.clear()
            self._wake_speaking_active.clear()

    def _run_wake_dictation(self, locale):
        """跑一次 Apple Speech 采集, 带硬墙钟上限。

        helper 会因静音自停, 但"唤醒后完全不说话"会让本线程(以及 KWS)永久阻塞。
        超时即 SIGTERM helper 放麦并返回 None。不触碰 Ctrl 听写的共享 generation/
        cancel 全局, 避免跨路径干扰。
        """
        # 防御性清零:若上一次会话(Ctrl 或 wake)异常结束遗留了 stop/cancel
        # 标志, 新的 helper 会秒被这些残留请求关掉 -> 立刻返回 None -> 莫名"没听清"。
        # Ctrl 路径在会话开始也会清; wake 之前漏了这步。
        global _dictation_cancel, _dictation_stop
        with _dictation_state_lock:
            _dictation_cancel = False
            _dictation_stop = False

        result: dict[str, Optional[str]] = {"text": None}
        done = threading.Event()

        def worker():
            try:
                result["text"] = _run_apple_speech_dictation(
                    locale, generation=None, show_hud=VE_VOICE_CHAT_SHOW_HUD
                )
            except Exception:
                _dictation_log.exception("Voice chat wake dictation failed")
            finally:
                done.set()

        thread = threading.Thread(
            target=worker, name="VoiceChatWakeDictation", daemon=True
        )
        # 标记 wake 拥有麦克风: 使暂停/关闭的 owner 守卫只中断本次 wake 听写。
        # 关竞态窗口: set 之后、start 之前再查一次 _turn_abort。若这瞬间恰好
        # 暂停/关闭, abort 会因 helper 尚未启动而空过, 麦会白占到静音自停/超时。
        # 这里直接放弃本次采集, 避免那几秒占麦。
        self._wake_dictation_active.set()
        if self._turn_abort.is_set() or self._stop.is_set():
            self._wake_dictation_active.clear()
            _dictation_log.debug("Voice chat wake dictation aborted before start")
            return None
        thread.start()
        try:
            if not done.wait(timeout=VE_VOICE_CHAT_DICTATION_TIMEOUT):
                _dictation_log.warning(
                    "Voice chat wake dictation timed out after %.1fs; releasing mic",
                    VE_VOICE_CHAT_DICTATION_TIMEOUT,
                )
                exited = _voice_chat_force_stop_apple_speech("wake dictation timeout")
                if not exited:
                    # SIGTERM 被拒(CoreAudio teardown 中), 受"绝不 SIGKILL"
                    # 约束, 该听写线程可能继续占麦、与 KWS 新流短暂并存。
                    _dictation_log.warning(
                        "Voice chat wake dictation helper refused SIGTERM; mic may "
                        "stay busy briefly and coexist with KWS until it exits"
                    )
                done.wait(timeout=3.0)
        finally:
            self._wake_dictation_active.clear()
        return result["text"]

    def _history_snapshot(self):
        with self._history_lock:
            return [dict(m) for m in self._history]

    def _history_append(self, role, content, model=None):
        content = (content or "").strip()
        if not content:
            return
        with self._history_lock:
            self._history_seq += 1
            entry = {"role": role, "content": content, "seq": self._history_seq}
            if model:
                # 记录产出该(助手)轮的模型, 供之后唤醒词切模型重放时按"各轮自己的模型
                # 别名"标注; 否则会误用当前目标模型别名, 把旧模型(如豆包)的回答挂到新模型
                # (如 DeepSeek)名下。用户轮不带 model。
                entry["model"] = model
            self._history.append(entry)
            # 上限裁剪: 按字符预算从最旧一轮起丢弃, 防止请求体无限膨胀。至少保留
            # 最近一轮(2 条), 避免把刚追加的当前轮也裁掉。
            budget = VE_VOICE_CHAT_HISTORY_CHAR_BUDGET
            if budget > 0:
                total = sum(len(m["content"]) for m in self._history)
                while len(self._history) > 2 and total > budget:
                    removed = self._history.pop(0)
                    total -= len(removed["content"])

    def _history_clear(self):
        with self._history_lock:
            self._history.clear()
            # "换个话题"清空虚拟历史时一并清水位线(此时 _conversations 也被清空, 全部模型
            # 回到无服务端会话状态)。seq 保持单调不重置即可。
            self._history_covered.clear()

    def _get_history_covered(self, model):
        with self._history_lock:
            return int(self._history_covered.get(model, 0))

    def _mark_history_covered(self, model):
        """标记该模型服务端会话已覆盖到"当前历史里的最高 seq"。

        本轮已把缺口 delta 折进请求、当前问答也进入了该模型的服务端会话, 故它现已
        看过截至此刻的全部虚拟历史轮次。下次切回它时, 只需再补此刻之后(其它模型产生)的
        新增 delta。
        """
        with self._history_lock:
            max_seq = 0
            for m in self._history:
                seq = int(m.get("seq", 0))
                if seq > max_seq:
                    max_seq = seq
            self._history_covered[model] = max_seq

    def _get_conversation_id(self, model):
        with self._conversations_lock:
            return self._conversations.get(model, "")

    def _set_conversation_id(self, model, conversation_id):
        conversation_id = str(conversation_id or "").strip()
        if not conversation_id:
            return
        with self._conversations_lock:
            self._conversations[model] = conversation_id

    def _stream_and_speak(self, model, query):
        import urllib.request  # lazy;全局只 import 了 urllib.parse

        coalescer = SpeechChunkCoalescer(
            first_chars=int(os.getenv("VE_VOICE_CHAT_FIRST_CHARS", "18")),
            target_chars=int(os.getenv("VE_VOICE_CHAT_TARGET_CHARS", "42")),
            max_chars=int(os.getenv("VE_VOICE_CHAT_MAX_CHARS", "96")),
        )
        conversation_id = self._get_conversation_id(model)
        # messages 组装(切回旧模型不丢中途对话)。历史里存的是不带 hint 前缀的
        # 干净文本; 仅当前这一轮加简洁口语 hint。
        full_history = self._history_snapshot()
        if conversation_id:
            # 目标模型已有服务端会话(relay 侧维护其自身历史)。不再"只发当前句"——那会丢掉
            # 自本模型上次作答后、在其它模型上发生、它服务端还没见过的那些轮次。改为只补
            # "缺口 delta"(按 seq > 水位线判定): 已在其服务端的历史不重发, delta 为空则只发
            # 当前句, delta 非空则把这段折进当前轮文本。
            covered = self._get_history_covered(model)
            history = [m for m in full_history if int(m.get("seq", 0)) > covered]
        else:
            # 首次切到该模型(或"换个话题"后): 无服务端会话, 重放全部虚拟历史让它继承上下文。
            history = full_history
        if not history:
            messages = [{"role": "user", "content": VE_VOICE_CHAT_CONCISE_HINT + query}]
        elif _ve_voice_chat_is_browser_model(model):
            # 浏览器模型: relay 旁路(ClientTurn.from_openai)只取最后一条 user 消息, 历史
            # 必须折叠进单条文本。助手轮用"产出该轮的那个模型"的别名标注(不用"助手"二字):
            # 切模型后旧轮仍显示其原模型别名(如豆包), 不会被误挂到当前目标模型名下。缺失
            # model 的旧条目回退到当前模型别名。用户轮用 VE_VOICE_CHAT_USER_LABEL。
            transcript = "\n".join(
                (
                    VE_VOICE_CHAT_USER_LABEL
                    if m.get("role") == "user"
                    else _ve_voice_chat_model_alias(m.get("model") or model)
                )
                + "："
                + m.get("content", "")
                for m in history
            )
            user_content = (
                VE_VOICE_CHAT_CONCISE_HINT
                + "以下是我们之前的对话：\n"
                + transcript
                + "\n\n现在请回答：\n"
                + query
            )
            messages = [{"role": "user", "content": user_content}]
        else:
            # 本地模型: 标准 OpenAI 多轮 messages 数组, role 各自 user/assistant。
            # 只取 role/content, 丢弃历史条目附带的 model 标注(仅供浏览器模型折叠标注用),
            # 避免把非标准键混进发往本地引擎的 OpenAI messages。
            messages = [{"role": m["role"], "content": m["content"]} for m in history]
            messages.append(
                {"role": "user", "content": VE_VOICE_CHAT_CONCISE_HINT + query}
            )
        body = {
            "model": model,
            "messages": messages,
            "stream": True,
            "enable_thinking": False,
            "source": "xiaoai",  # 走 relay 旁路:无系统提示/工具注入
        }
        if conversation_id:
            body["conversation_id"] = conversation_id
        payload = json.dumps(body, ensure_ascii=False).encode("utf-8")
        endpoint = f"http://127.0.0.1:{HTTP_PORT}/v1/chat/completions"
        request = urllib.request.Request(
            endpoint,
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )

        spoken_any = False
        answer_chars = 0
        answer_parts = []  # 累积助手完整回答文本, 供写回虚拟会话历史
        try:
            with urllib.request.urlopen(
                request, timeout=VE_VOICE_CHAT_STREAM_READ_TIMEOUT
            ) as response:
                for raw_line in response:
                    if self._stop.is_set() or self._turn_abort.is_set():
                        break
                    line = raw_line.decode("utf-8", errors="replace").strip()
                    if not line.startswith("data:"):
                        continue
                    data = line[5:].strip()
                    if data == "[DONE]":
                        break
                    if not data:
                        continue
                    try:
                        event = json.loads(data)
                    except (TypeError, ValueError):
                        continue
                    if event.get("error"):
                        _xiaoai_log.warning(
                            "Voice chat upstream error: %s", event["error"]
                        )
                        break
                    conv = str(event.get("conversation_id") or "").strip()
                    if conv:
                        self._set_conversation_id(model, conv)
                    choices = event.get("choices") or []
                    delta = choices[0].get("delta", {}) if choices else {}
                    content = delta.get("content")
                    if isinstance(content, str) and content:
                        answer_chars += len(content)
                        answer_parts.append(content)
                        for chunk in coalescer.feed(content):
                            cleaned = clean_text_for_tts(chunk)
                            if cleaned:
                                spoken_any = True
                                speak_local_async(
                                    cleaned,
                                    voice=VE_VOICE_CHAT_TTS_VOICE,
                                    speed=VE_VOICE_CHAT_TTS_SPEED,
                                )
            # abort 后不再朗读尾段缓冲(≤max_chars), 否则 stop_tts 之后又冒出
            # 一句, 暂停/停止不彻底。coalescer 为局部变量, 跳过即随方法返回销毁。
            if self._stop.is_set() or self._turn_abort.is_set():
                _xiaoai_log.info("Voice chat aborted; skipping coalescer tail flush")
            else:
                for chunk in coalescer.finish():
                    cleaned = clean_text_for_tts(chunk)
                    if cleaned:
                        spoken_any = True
                        speak_local_async(
                            cleaned,
                            voice=VE_VOICE_CHAT_TTS_VOICE,
                            speed=VE_VOICE_CHAT_TTS_SPEED,
                        )
        except Exception:
            # 正常暂停/关闭:abort 置位时读超时(默认 30s)会抛异常, 属预期打断,
            # 降级为 info, 不刷 traceback。非 abort 的真实故障仍按 exception 记录。
            if self._turn_abort.is_set() or self._stop.is_set():
                _xiaoai_log.info("Voice chat streaming interrupted by pause/stop")
            else:
                _xiaoai_log.exception("Voice chat streaming request failed")

        try:
            hud.hide_visual_only()
        except Exception:
            pass
        _xiaoai_log.info(
            "Voice chat answer done: model=%s chars=%d spoken=%s",
            model,
            answer_chars,
            spoken_any,
        )

        # 写回虚拟会话历史(存干净文本, 不含 hint 前缀), 供之后唤醒词切模型时重放给
        # 新模型。无论本轮是否走 conversation_id 都记录, 保证历史完整; 助手回答为空
        # (如本轮被打断)时只记 user 轮, 由 _history_append 自行忽略空串。
        self._history_append("user", query)
        self._history_append("assistant", "".join(answer_parts), model=model)
        # 若该模型确有服务端 conversation_id(本轮已把缺口 delta 折进请求、当前问答
        # 也已进入其服务端会话), 则推进它的水位线到当前最高 seq —— 它现已覆盖截至此刻的
        # 全部虚拟历史, 下次切回只需再补此刻之后(其它模型产生)的新增 delta。本地模型无服务端
        # 记忆(conversation_id 恒空)、恒走全量重放, 故不标记水位线。
        if self._get_conversation_id(model) and answer_chars > 0:
            self._mark_history_covered(model)
        elif self._get_conversation_id(model):
            _xiaoai_log.warning(
                "Voice chat history watermark not advanced: model=%s returned no answer delta",
                model,
            )

        return spoken_any

    def _wait_playback_idle(self, *, timeout):
        # 以 KWS-preempt lease 为提交边界，而不是在固定 300ms 后瞬时检查队列。
        # speak_local_async 在第一段入队前保持该 lease，consumer 仅在整批播放排空后清除，
        # 因此覆盖合并缓冲、输出恢复和 IS_SPEAKING 尚未置位的全部空窗。
        deadline = time.monotonic() + max(0.0, timeout)
        while time.monotonic() < deadline and not self._stop.is_set():
            if self._turn_abort.is_set():
                _TTS_PREEMPT_KWS.clear()
                return
            if not _TTS_PREEMPT_KWS.is_set():
                return
            time.sleep(0.1)
        if _TTS_PREEMPT_KWS.is_set():
            _kws_log.warning(
                "Voice chat TTS lifecycle wait timed out; releasing KWS preempt"
            )
            _TTS_PREEMPT_KWS.clear()


def start_voice_chat_subsystem():
    global _voice_chat_subsystem
    if not VE_VOICE_CHAT_ENABLED:
        _xiaoai_log.info("Voice chat subsystem disabled (set VE_VOICE_CHAT_ENABLED=1)")
        return
    with _voice_chat_lock:
        if _voice_chat_subsystem is None:
            _voice_chat_subsystem = VoiceChatSubsystem()
        _voice_chat_subsystem.start()


def stop_voice_chat_subsystem():
    with _voice_chat_lock:
        subsystem = _voice_chat_subsystem
    if subsystem is not None:
        subsystem.stop()


def _voice_chat_on_flags_changed(event):
    subsystem = _voice_chat_subsystem
    if subsystem is not None:
        subsystem.on_flags_changed(event)


# ==================== FastMCP Server Tools ====================


def reset_question_recording_state():
    global QUESTION_RECORDING_ACTIVE
    global QUESTION_RECORDING_GENERATION
    global QUESTION_RECORDING_ESC_TIMER
    global QUESTION_RECORDING_LAST_ESC_AT

    timer = None

    with QUESTION_RECORDING_LOCK:
        QUESTION_RECORDING_GENERATION += 1
        QUESTION_RECORDING_ACTIVE = False
        QUESTION_RECORDING_LAST_ESC_AT = 0.0

        timer = QUESTION_RECORDING_ESC_TIMER
        QUESTION_RECORDING_ESC_TIMER = None

        QUESTION_RECORDING_STOP.clear()
        QUESTION_RECORDING_SKIP.clear()
        QUESTION_RECORDING_CANCEL_ALL.clear()

    if timer is not None:
        try:
            timer.cancel()
        except Exception:
            pass


mcp = FastMCP("STT/TTS MCP Server", host="127.0.0.1", port=MCP_PORT)


@mcp.tool()
def ask_user_dictation(
    questions: Annotated[
        List[str], Field(default=..., description="Questions to display")
    ],
    read_questions: Annotated[
        bool, Field(default=True, description="TTS reads each question first")
    ] = True,
) -> str:
    """
    Voice dictation with HUD. TTS reads question, then auto-records.
    Enter=stop, ESC=skip, 2xESC=cancel ALL remaining.
    """
    if SERVER_SHUTTING_DOWN.is_set():
        return "Server is shutting down"

    if not questions:
        return "No questions provided"

    reset_question_recording_state()

    _dictation_log.debug(f"Dictation: {len(questions)} questions")
    answers = []
    cancel_flag = {"cancel_all": False}

    # 🔧 重置取消管理器状态
    cancel_manager.reset()

    # Avoid stale async TTS blocking question reading.
    # This tool owns the current question/answer interaction, so queued background
    # speech should not run before the questions.
    tts_merge_buffer.clear()
    cancel_manager.clear_queue(TTS_TEXT_QUEUE)
    cancel_manager.kill_all_ffmpeg()

    try:
        for i, question in enumerate(questions):
            # 🔧 在每轮循环开始前检查取消状态
            if cancel_manager.is_cancel_requested():
                _dictation_log.debug("🛑 检测到取消请求，停止所有问题")
                cancel_flag["cancel_all"] = True

            if cancel_flag["cancel_all"]:
                # 消费取消请求
                cancel_manager.consume_cancel()
                answers.append(f"**{question}**\n[CANCELLED]\n")
                # 标记后续所有问题为已取消
                for remaining_q in questions[i + 1 :]:
                    answers.append(f"**{remaining_q}**\n[CANCELLED]\n")
                _dictation_log.debug("所有剩余问题已标记为取消")
                break

            hud.show("reading", f"Question {i + 1}/{len(questions)}", question)

            if read_questions:
                if not speak_local_sync_and_wait(question):
                    _dictation_log.warning(
                        "TTS queue item did not finish "
                        "within the expected time for Q%d",
                        i + 1,
                    )

            # 再次检查取消状态（TTS 播放期间可能触发取消）
            if cancel_manager.is_cancel_requested():
                cancel_flag["cancel_all"] = True

            if cancel_flag["cancel_all"]:
                cancel_manager.consume_cancel()
                answers.append(f"**{question}**\n[CANCELLED]\n")
                for remaining_q in questions[i + 1 :]:
                    answers.append(f"**{remaining_q}**\n[CANCELLED]\n")
                break

            # Question TTS schedules a delayed HUD hide. Cancel it before
            # transferring HUD ownership to the recording phase; otherwise the
            # timer hides the recording HUD about 1.2 seconds after TTS ends.
            _cancel_tts_hud_hide()

            # Preserve the original recording HUD exactly; only the ASR
            # backend changes from PCM+Whisper to Apple Speech.
            hud.show(
                "recording",
                f"Question {i + 1}/{len(questions)}",
                question,
            )
            recognition_status, raw = transcribe_question_with_apple_speech()

            if recognition_status == "cancelled":
                cancel_flag["cancel_all"] = True
                cancel_manager.consume_cancel()
                answers.append(f"**{question}**\n[CANCELLED]\n")
                for remaining_q in questions[i + 1 :]:
                    answers.append(f"**{remaining_q}**\n[CANCELLED]\n")
                break

            if recognition_status == "skipped":
                answers.append(f"**{question}**\n[SKIPPED]\n")
                continue

            if recognition_status == "no_speech" or not raw:
                hud.show(
                    "dictation_nospeech",
                    f"Question {i + 1}/{len(questions)}",
                    question,
                )
                time.sleep(0.8)
                answers.append(f"**{question}**\n[NO SPEECH]\n")
                continue

            hud.show("correcting", f"Question {i + 1}/{len(questions)}", question)
            corrected = strip_llm_artifacts(
                correct_text_sync(raw, question), remove_reasoning=True
            )

            hud.show("answer", f"Question {i + 1}/{len(questions)}", corrected[:100])
            time.sleep(1.5)
            answers.append(f"**{question}**\n{corrected}\n")

    finally:
        reset_question_recording_state()
        cancel_manager.reset()
        hud.hide_visual_only()

    return "\n".join(answers)


@mcp.tool()
def transcribe_file(
    file_path: Annotated[
        str, Field(default=..., description="Absolute path to audio/video file")
    ],
    format: Annotated[
        str, Field(default="text", description="text, json, srt, verbose_json")
    ] = "text",
    speakers: Annotated[
        bool, Field(default=False, description="Include speaker labels")
    ] = False,
) -> str:
    """Transcribe an audio or video file."""
    if SERVER_SHUTTING_DOWN.is_set():
        return "Server is shutting down"

    if not file_path or not os.path.exists(file_path):
        return f"Error: File not found: {file_path}"

    try:
        result = transcribe_file_sync(file_path)
    except RuntimeError as e:
        return f"Error: {e}"
    except Exception as e:
        return f"Error transcribing file: {e}"

    if format == "verbose_json":
        return json.dumps(result, ensure_ascii=False, indent=2)
    elif format == "json":
        return json.dumps(
            {"language": result["language"], "segments": result["segments"]},
            ensure_ascii=False,
            indent=2,
        )
    elif format == "srt":
        lines = []
        for i, seg in enumerate(result["segments"], 1):
            s, e = seg["start"], seg["end"]
            lines.append(
                f"{i}\n"
                f"{int(s // 3600):02d}:{int((s % 3600) // 60):02d}:{int(s % 60):02d},{int((s % 1) * 1000):03d} --> "
                f"{int(e // 3600):02d}:{int((e % 3600) // 60):02d}:{int(e % 60):02d},{int((e % 1) * 1000):03d}\n"
                f"{seg['text']}\n"
            )
        return "\n".join(lines)
    elif speakers:
        return "\n".join(f"[Speaker] {s['text']}" for s in result["segments"])
    else:
        return result["text"]


@mcp.tool()
def speak(
    text: Annotated[str, Field(default=..., description="Text to speak aloud")],
    clean_text: Annotated[
        bool, Field(default=False, description="Use LLM to clean text before speaking")
    ] = False,
    voice: Annotated[str, Field(default="zh", description="Voice alias")] = "zh",
    speed: Annotated[
        float, Field(default=1.0, ge=0.25, le=4.0, description="Speech playback speed")
    ] = 1.0,
) -> str:
    """
    Speak text using Edge-TTS natively. Double-tap ESC to stop speaking.
    Uses intelligent merging to combine rapid successive requests.
    """
    if SERVER_SHUTTING_DOWN.is_set():
        return "Server is shutting down"

    if not text or not text.strip():
        return "Error: No text provided"

    # Cheap deterministic cleanup.
    text = filter_streaming_tts_reasoning(text)

    if not text:
        _tts_log.debug(
            "TTS chunk skipped because it contained only reasoning/artifacts"
        )
        return "Skipped reasoning-only TTS chunk"

    _app_log.debug(
        "Speaking (%s): %s...",
        "cleaned" if clean_text else "sanitized",
        text[:100],
    )

    if clean_text:
        try:
            cleaned_text = _generate_llm_text_via_worker(
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "You are a text cleaner for TTS reading. Your ONLY job is to prepare text for speech synthesis.\n"
                            "CRITICAL RULES:\n"
                            "1. PRESERVE the original language. NEVER translate.\n"
                            "2. Remove all markdown formatting (**, *, `, ```, ##, etc.)\n"
                            "3. Remove all emoji and emoticons\n"
                            "4. Remove URLs and links\n"
                            "5. Remove code blocks and inline code\n"
                            "6. Remove HTML tags\n"
                            "7. Add appropriate punctuation for natural reading\n"
                            "8. Output ONLY the cleaned text, no explanations."
                        ),
                    },
                    {
                        "role": "user",
                        "content": f"Original text: {text}\n\nCleaned text:",
                    },
                ],
                max_tokens=1000,
                temperature=0.1,
            )

            if cleaned_text is not None:
                text = cleaned_text
            text = clean_text_for_tts(text)

        except Exception as e:
            _llm_log.warning(f"LLM clean failed; using sanitized text: {e}")

    if not text or not text.strip():
        return "Skipped empty TTS text after cleaning"

    speak_local_async(text, voice=voice, speed=speed)
    return f"Speaking (queued): {text[:100]}..."


@mcp.tool()
def embed_texts(texts: List[str]) -> str:
    if SERVER_SHUTTING_DOWN.is_set():
        return "Server is shutting down"

    vectors = _submit_embed_job(texts)
    if vectors is None:
        return "Embedding failed"

    return json.dumps(
        {"embeddings": vectors},
        ensure_ascii=False,
    )


@mcp.tool()
def rerank_documents(query: str, documents: List[str]) -> str:
    if SERVER_SHUTTING_DOWN.is_set():
        return "Server is shutting down"

    payload = _submit_rerank_job(
        query,
        documents,
    )

    if payload is None:
        return "Rerank failed"

    scores = payload["scores"]
    score_method = payload["score_method"]

    results = [
        {
            "index": index,
            "score": float(score),
            "document": documents[index],
        }
        for index, score in enumerate(scores)
    ]

    results.sort(
        key=lambda item: item["score"],
        reverse=True,
    )

    return json.dumps(
        {
            "score_method": score_method,
            "results": results,
        },
        ensure_ascii=False,
        indent=2,
    )


# ==================== BLE MiBeacon remote ====================


def _ble_remote_decrypt_frame(frame: bytes) -> tuple[int, bytes] | None:
    """Authenticate one MiBeacon frame and return its counter and plaintext."""

    key_hex = re.sub(r"[^0-9a-fA-F]", "", VE_BLE_REMOTE_KEY)
    mac_hex = re.sub(r"[^0-9a-fA-F]", "", VE_BLE_REMOTE_MAC)
    if len(key_hex) != 32 or len(mac_hex) != 12:
        raise ValueError("VE_BLE_REMOTE_KEY or VE_BLE_REMOTE_MAC is invalid")
    expected_mac = bytes.fromhex(mac_hex)[::-1]
    if len(frame) < 18 or frame[5:11] != expected_mac:
        return None

    counter = frame[4]
    nonce = frame[5:11] + frame[2:5] + frame[-7:-4]
    try:
        plaintext = AESCCM(bytes.fromhex(key_hex), tag_length=4).decrypt(
            nonce, frame[11:-7] + frame[-4:], b"\x11"
        )
    except InvalidTag:
        return None
    return counter, plaintext


def _ble_remote_event(counter: int, plaintext: bytes) -> dict[str, Any] | None:
    """Build a remote event for one recognized authenticated payload."""

    action = _BLE_REMOTE_ACTIONS.get(plaintext)
    if action is None:
        return None
    return {
        "type": "BLE_REMOTE",
        "action": action,
        "counter": counter,
        "plaintext": plaintext.hex(),
    }


def _ble_advertisement_service_data(advertisement: Any) -> dict[str, bytes]:
    return {
        str(uuid).casefold(): bytes(value)
        for uuid, value in advertisement.service_data.items()
    }


def _ble_remote_decrypt_advertisement(
    advertisement: Any,
) -> tuple[bytes, int, bytes] | None:
    """Extract and authenticate the configured MiBeacon remote advertisement."""

    frame = _ble_advertisement_service_data(advertisement).get(
        _BLE_REMOTE_SERVICE_UUID_NORM
    )
    if frame is None:
        return None
    decoded = _ble_remote_decrypt_frame(frame)
    if decoded is None:
        return None
    counter, plaintext = decoded
    return frame, counter, plaintext


def _ble_scan_is_remote_candidate(name: str, advertisement: Any) -> bool:
    """Match the same remote hints used by the standalone scan.py helper."""

    keywords = ("yeelink", "ylyk", "remote", "rc", "miot", "xiaomi")
    lower_name = name.casefold()
    service_data = _ble_advertisement_service_data(advertisement)
    is_named_remote = any(keyword in lower_name for keyword in keywords)
    is_mibeacon = any(
        uuid.startswith("0000fe9f") or uuid.startswith("0000fe95")
        for uuid in service_data
    )
    manufacturer_text = str(advertisement.manufacturer_data).casefold()
    return is_named_remote or is_mibeacon or "yeel" in manufacturer_text


async def _run_ble_scan_cli() -> None:
    """Continuously list each nearby BLE device once, highlighting remotes."""

    print("🔍 开始扫描周围的 BLE 蓝牙设备...", flush=True)
    print("👉 【重要】请现在频繁按压你的遥控器按键，以便发出广播！\n", flush=True)
    print(f"{'MAC 地址 / UUID':<38} | {'信号 RSSI':<9} | {'设备名称':<20}")
    print("-" * 75, flush=True)
    seen_addresses: set[str] = set()

    def detection_callback(device: Any, advertisement: Any) -> None:
        address = str(getattr(device, "address", "") or "unknown")
        if address in seen_addresses:
            return
        seen_addresses.add(address)
        name = str(
            getattr(device, "name", None)
            or getattr(advertisement, "local_name", None)
            or "未知设备"
        )
        rssi = getattr(advertisement, "rssi", None)
        rssi_text = f"{rssi} dBm" if rssi is not None else "未知"
        if _ble_scan_is_remote_candidate(name, advertisement):
            print(
                f"🎯 [找到疑似遥控器!] {address:<25} | {rssi_text:<9} | {name}",
                flush=True,
            )
            service_uuids = sorted(_ble_advertisement_service_data(advertisement))
            print(f"   └── 广播数据 Service Data: {service_uuids}", flush=True)
        else:
            print(
                f"   [普通 BLE 设备]   {address:<25} | {rssi_text:<9} | {name}",
                flush=True,
            )

    scanner = BleakScanner(detection_callback=detection_callback)
    await scanner.start()
    try:
        await asyncio.Event().wait()
    finally:
        await scanner.stop()


async def _run_ble_listen_cli() -> None:
    """Print decrypted button payload hex values for one MiBeacon remote."""

    service_uuid = _BLE_REMOTE_SERVICE_UUID_NORM
    if not VE_BLE_REMOTE_MAC.strip() or not service_uuid:
        raise ValueError(
            "--ble-listen requires VE_BLE_REMOTE_MAC and VE_BLE_REMOTE_SERVICE_UUID"
        )
    key_hex = re.sub(r"[^0-9a-fA-F]", "", VE_BLE_REMOTE_KEY)
    if len(key_hex) != 32:
        raise ValueError(
            "--ble-listen requires a 16-byte VE_BLE_REMOTE_KEY to decrypt "
            "MiBeacon button payloads"
        )

    seen: deque[tuple[int, bytes]] = deque(maxlen=64)

    def on_advertisement(_device: Any, advertisement: Any) -> None:
        decoded = _ble_remote_decrypt_advertisement(advertisement)
        if decoded is None:
            return
        frame, counter, plaintext = decoded
        signature = (counter, frame[-7:])
        if signature in seen:
            return
        seen.append(signature)
        action = _BLE_REMOTE_ACTIONS.get(plaintext)
        suffix = f" action={action}" if action is not None else ""
        print(f"{plaintext.hex()}{suffix}", flush=True)

    print(
        f"BLE listen started for {VE_BLE_REMOTE_MAC} service={service_uuid}",
        file=sys.stderr,
        flush=True,
    )
    scanner = BleakScanner(detection_callback=on_advertisement)
    await scanner.start()
    try:
        await asyncio.Event().wait()
    finally:
        await scanner.stop()


def _run_ble_cli_from_argv(argv: list[str]) -> bool:
    commands = [option for option in ("--ble-scan", "--ble-listen") if option in argv]
    if not commands:
        return False
    if len(commands) != 1 or argv != commands:
        print(
            "Usage: python voice_edge.py (--ble-scan | --ble-listen)",
            file=sys.stderr,
        )
        raise SystemExit(2)
    try:
        asyncio.run(
            _run_ble_scan_cli()
            if commands[0] == "--ble-scan"
            else _run_ble_listen_cli()
        )
    except KeyboardInterrupt:
        print("BLE monitoring stopped", file=sys.stderr)
        raise SystemExit(0) from None
    except Exception as exc:
        print(f"BLE monitoring failed: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc
    raise SystemExit(0)


def _ble_remote_publish(event: dict[str, Any]) -> None:
    with _BLE_REMOTE_SUBSCRIBERS_LOCK:
        subscribers = tuple(_BLE_REMOTE_SUBSCRIBERS)
    for subscriber in subscribers:
        try:
            subscriber.put_nowait(event)
        except queue.Full:
            try:
                subscriber.get_nowait()
            except queue.Empty:
                pass
            try:
                subscriber.put_nowait(event)
            except queue.Full:
                pass


def _ble_remote_scanner_thread() -> None:
    async def run_scanner() -> None:

        seen: deque[tuple[int, bytes]] = deque(maxlen=64)

        def on_advertisement(_device: Any, advertisement: Any) -> None:
            decoded = _ble_remote_decrypt_advertisement(advertisement)
            if decoded is None:
                return
            frame, counter, plaintext = decoded
            event = _ble_remote_event(counter, plaintext)
            if event is None:
                return
            signature = (counter, frame[-7:])
            if signature in seen:
                return
            seen.append(signature)
            _ble_remote_publish(event)
            _app_log.debug(
                "BLE remote action=%s counter=%d plaintext=%s",
                event["action"],
                event["counter"],
                event["plaintext"],
            )

        scanner = BleakScanner(detection_callback=on_advertisement)
        stop_event = asyncio.Event()
        event_loop = asyncio.get_running_loop()

        def forward_stop_request() -> None:
            _BLE_REMOTE_STOP.wait()
            event_loop.call_soon_threadsafe(stop_event.set)

        stop_forwarder = threading.Thread(
            target=forward_stop_request,
            name="BleMiBeaconRemoteStop",
            daemon=True,
        )
        stop_forwarder.start()

        await scanner.start()
        _app_log.info("BLE remote scanner started for MAC %s", VE_BLE_REMOTE_MAC)
        try:
            await stop_event.wait()
        finally:
            await scanner.stop()

    try:
        asyncio.run(run_scanner())
    except Exception as exc:
        _app_log.exception("BLE remote scanner stopped: %s", exc)
        _ble_remote_publish({"type": "BLE_REMOTE_ERROR", "message": str(exc)})


def _ensure_ble_remote_scanner() -> None:
    global _BLE_REMOTE_THREAD
    if not VE_BLE_REMOTE_ENABLED or _BLE_REMOTE_STOP.is_set():
        return
    key_hex = re.sub(r"[^0-9a-fA-F]", "", VE_BLE_REMOTE_KEY)
    mac_hex = re.sub(r"[^0-9a-fA-F]", "", VE_BLE_REMOTE_MAC)
    if len(key_hex) != 32 or len(mac_hex) != 12:
        _app_log.error(
            "BLE remote scanner disabled: VE_BLE_REMOTE_KEY must be 32 hex "
            "characters and VE_BLE_REMOTE_MAC must be 12 hex characters"
        )
        return
    if not _BLE_REMOTE_SERVICE_UUID_NORM:
        _app_log.error(
            "BLE remote scanner disabled: VE_BLE_REMOTE_SERVICE_UUID is empty"
        )
        return
    with _BLE_REMOTE_THREAD_LOCK:
        if _BLE_REMOTE_THREAD is not None and _BLE_REMOTE_THREAD.is_alive():
            return
        _BLE_REMOTE_THREAD = threading.Thread(
            target=_ble_remote_scanner_thread, name="BleMiBeaconRemote", daemon=True
        )
        _BLE_REMOTE_THREAD.start()


def _stop_ble_remote_scanner() -> None:
    first_stop = not _BLE_REMOTE_STOP.is_set()
    _BLE_REMOTE_STOP.set()
    if first_stop:
        # Wake every long-lived StreamingResponse before Uvicorn begins its
        # graceful shutdown. Otherwise each response can remain blocked in
        # queue.get() until its 15-second keepalive timeout and Uvicorn cancels
        # the ASGI task after timeout_graceful_shutdown.
        _ble_remote_publish({"type": "BLE_REMOTE_SHUTDOWN"})
    thread = _BLE_REMOTE_THREAD
    if thread is not None and thread.is_alive():
        thread.join(timeout=2.0)


async def ble_remote_events_api(request):
    """Stream BLE button events as newline-delimited JSON."""
    client_host = request.client.host if request.client is not None else None
    debug = request.query_params.get("debug") == "1"
    if debug:
        _http_log.info(
            "BLE remote event stream request: client=%s debug=%s enabled=%s",
            client_host,
            debug,
            VE_BLE_REMOTE_ENABLED,
        )
    if client_host not in {"127.0.0.1", "::1"}:
        _http_log.warning("BLE remote event stream rejected: client=%s", client_host)
        return JSONResponse({"error": "local access only"}, status_code=403)
    if not VE_BLE_REMOTE_ENABLED:
        _http_log.warning("BLE remote event stream rejected: BLE remote disabled")
        return JSONResponse({"error": "BLE remote disabled"}, status_code=503)

    subscriber: queue.Queue = queue.Queue(maxsize=32)
    with _BLE_REMOTE_SUBSCRIBERS_LOCK:
        _BLE_REMOTE_SUBSCRIBERS.add(subscriber)
    _ensure_ble_remote_scanner()
    if debug:
        _http_log.info("BLE remote event stream connected: client=%s", client_host)

    async def stream():
        try:
            yield b'{"type":"BLE_REMOTE_READY"}\n'
            # A client can connect *inside* the shutdown window, i.e. after
            # _stop_ble_remote_scanner() has already published its one-shot
            # BLE_REMOTE_SHUTDOWN marker. Such a late subscriber is registered
            # too late to receive that broadcast, so without this guard it would
            # block in queue.get() until Uvicorn force-cancels the ASGI task at
            # timeout_graceful_shutdown, surfacing an uncaught CancelledError
            # ("Exception in ASGI application") in the logs. Detect the already
            # -set stop flag and end the stream immediately instead.
            if _BLE_REMOTE_STOP.is_set():
                if debug:
                    _http_log.info(
                        "BLE remote event stream closing for shutdown: client=%s",
                        client_host,
                    )
                yield b'{"type":"BLE_REMOTE_SHUTDOWN"}\n'
                return
            while True:
                try:
                    event = await asyncio.to_thread(subscriber.get, True, 15.0)
                except queue.Empty:
                    # Fall through to shutdown if the stop flag was raised while
                    # we were parked in queue.get() but the wake-up broadcast
                    # never reached this subscriber (do not rely solely on the
                    # one-shot BLE_REMOTE_SHUTDOWN event to unblock).
                    if _BLE_REMOTE_STOP.is_set():
                        break
                    yield b'{"type":"KEEPALIVE"}\n'
                    continue
                if (
                    event.get("type") == "BLE_REMOTE_SHUTDOWN"
                    or _BLE_REMOTE_STOP.is_set()
                ):
                    if debug:
                        _http_log.info(
                            "BLE remote event stream closing for shutdown: client=%s",
                            client_host,
                        )
                    break
                if debug:
                    _http_log.info(
                        "BLE remote event stream send: client=%s type=%s action=%s counter=%s",
                        client_host,
                        event.get("type"),
                        event.get("action"),
                        event.get("counter"),
                    )
                yield json.dumps(event, separators=(",", ":")).encode() + b"\n"
        finally:
            with _BLE_REMOTE_SUBSCRIBERS_LOCK:
                _BLE_REMOTE_SUBSCRIBERS.discard(subscriber)
            if debug:
                _http_log.info(
                    "BLE remote event stream disconnected: client=%s", client_host
                )

    return StreamingResponse(
        stream(),
        media_type="application/x-ndjson",
        headers={"Cache-Control": "no-store", "X-Accel-Buffering": "no"},
    )


