async def audio_runtime_status_api(
    request,
):
    (
        stream,
        context,
        signature,
        sample_rate,
    ) = _get_persistent_output_snapshot()

    with OUTPUT_STREAM_LOCK:
        pending_close = OUTPUT_STREAM_PENDING_CLOSE

    latest_fault = context.latest_fault if context is not None else None

    callback_age = None
    if context is not None and context.last_callback_at > 0:
        callback_age = max(
            0.0,
            time.monotonic() - context.last_callback_at,
        )

    stream_active = None
    stream_stopped = None

    if stream is not None:
        try:
            stream_active = bool(stream.active)
        except Exception:
            pass

        try:
            stream_stopped = bool(stream.stopped)
        except Exception:
            pass

    return JSONResponse(
        {
            "object": "audio.runtime",
            "runtime": audio_runtime.snapshot(),
            "stream": {
                "exists": stream is not None,
                "active": stream_active,
                "stopped": stream_stopped,
                "signature": signature,
                "sample_rate": sample_rate,
                "closure_unconfirmed": (pending_close is not None),
                "pending_close": (
                    {
                        "stream_epoch": (
                            pending_close.context.stream_epoch
                            if (pending_close.context is not None)
                            else None
                        ),
                        "attempts": (pending_close.attempts),
                        "max_attempts": (AUDIO_OUTPUT_CLOSE_MAX_ATTEMPTS),
                        "last_error": (pending_close.last_error),
                        "restart_required": (
                            pending_close.attempts >= AUDIO_OUTPUT_CLOSE_MAX_ATTEMPTS
                        ),
                    }
                    if pending_close is not None
                    else None
                ),
            },
            "callback": {
                "stream_epoch": (context.stream_epoch if context is not None else None),
                "count": (context.callback_count if context is not None else 0),
                "last_callback_age": callback_age,
                "consumed_items": (
                    context.consumed_items if context is not None else 0
                ),
                "discarded_items": (
                    context.discarded_items if context is not None else 0
                ),
                "consumed_frames": (
                    context.consumed_frames if context is not None else 0
                ),
                "discarded_frames": (
                    context.discarded_frames if context is not None else 0
                ),
                "latest_fault": (
                    {
                        "sequence": (latest_fault.sequence),
                        "source_stream_epoch": (latest_fault.source_stream_epoch),
                        "code": (latest_fault.code.value),
                        "reason": (latest_fault.reason),
                        "observed_at": (latest_fault.observed_at),
                    }
                    if latest_fault is not None
                    else None
                ),
            },
            "aggregate_callback": {
                "total_count": (AUDIO_CALLBACK_TELEMETRY.total_callback_count),
                "consumed_items": (AUDIO_CALLBACK_TELEMETRY.consumed_items),
                "discarded_items": (AUDIO_CALLBACK_TELEMETRY.discarded_items),
                "consumed_frames": (AUDIO_CALLBACK_TELEMETRY.consumed_frames),
                "discarded_frames": (AUDIO_CALLBACK_TELEMETRY.discarded_frames),
            },
            "queue": {
                "text_size": (TTS_TEXT_QUEUE.qsize()),
                "pcm_size": (GLOBAL_AUDIO_QUEUE.qsize()),
            },
            "route": {
                "coreaudio_output_id": (AUDIO_ROUTE_LAST_OUTPUT_ID),
                "coreaudio_output_name": (AUDIO_ROUTE_LAST_OUTPUT_NAME),
                "change_sequence": (AUDIO_ROUTE_CHANGE_SEQUENCE),
                "change_pending": (AUDIO_ROUTE_CHANGE_PENDING.is_set()),
            },
            "compatibility_signals": {
                "output_recovery_required": (TTS_OUTPUT_RECOVERY_REQUIRED.is_set()),
            },
        }
    )


def _open_upload_destination(destination: str):
    return open(destination, "wb")


def _write_upload_chunk(output_file, chunk: bytes) -> None:
    output_file.write(chunk)


def _close_upload_destination(output_file) -> None:
    output_file.close()


async def _save_upload_file(
    upload_file,
    destination: str,
    *,
    max_bytes: int,
    chunk_size: int = 1024 * 1024,
) -> int:
    total_bytes = 0
    output_file = await asyncio.to_thread(_open_upload_destination, destination)
    try:
        while True:
            chunk = await upload_file.read(chunk_size)

            if not chunk:
                break

            total_bytes += len(chunk)

            if total_bytes > max_bytes:
                raise ValueError("Audio file is too large")

            await asyncio.to_thread(_write_upload_chunk, output_file, chunk)
    finally:
        await asyncio.to_thread(_close_upload_destination, output_file)

    return total_bytes


async def transcribe_api(request):
    """
    OpenAI-compatible /v1/audio/transcriptions endpoint with SSE streaming.
    Supports:
      - multipart/form-data: file + model + language + response_format + stream
      - stream=true → SSE streams segments as they are produced after the uploaded file is received.
    """
    temp_path = None
    stream_mode = False
    try:
        content_type = request.headers.get("content-type", "")
        content_length = request.headers.get("content-length")
        if content_length:
            try:
                if int(content_length) > MAX_HTTP_AUDIO_UPLOAD_BYTES:
                    return JSONResponse(
                        {"error": "Audio file is too large"}, status_code=413
                    )
            except ValueError:
                return JSONResponse(
                    {"error": "Invalid Content-Length"}, status_code=400
                )

        language = "zh"
        response_format = "json"

        if "multipart/form-data" in content_type:
            form = await request.form()
            file = form.get("file")
            if not file:
                return JSONResponse({"error": "No file provided"}, status_code=400)

            filename = (
                getattr(
                    file,
                    "filename",
                    "",
                )
                or ""
            )

            suffix = os.path.splitext(filename)[1] or ".audio"

            fd, temp_path = tempfile.mkstemp(suffix=suffix)

            os.close(fd)

            try:
                bytes_written = await _save_upload_file(
                    file,
                    temp_path,
                    max_bytes=MAX_HTTP_AUDIO_UPLOAD_BYTES,
                )

            except ValueError as exc:
                _safe_unlink(temp_path)
                temp_path = None

                return JSONResponse(
                    {"error": str(exc)},
                    status_code=413,
                )

            if bytes_written == 0:
                return JSONResponse(
                    {"error": "Empty file"},
                    status_code=400,
                )

            language = form.get("language", "zh")
            response_format = form.get("response_format", "json")
            stream_mode = form.get("stream", "false") in ("true", "True", "1")

        elif "application/json" in content_type:
            body = await request.json()
            if not isinstance(body, dict):
                return JSONResponse(
                    {"error": "JSON body must be an object"}, status_code=400
                )

            file_b64 = body.get("file", "")
            if not file_b64:
                return JSONResponse({"error": "No file provided"}, status_code=400)

            if not isinstance(file_b64, str):
                return JSONResponse(
                    {"error": "file must be base64 text"}, status_code=400
                )

            MAX_BASE64_AUDIO_CHARS = (MAX_HTTP_AUDIO_UPLOAD_BYTES + 2) // 3 * 4

            if len(file_b64) > MAX_BASE64_AUDIO_CHARS:
                return JSONResponse(
                    {"error": "Audio file is too large"},
                    status_code=413,
                )

            try:
                audio_bytes = base64.b64decode(file_b64, validate=True)
            except (ValueError, binascii.Error):
                return JSONResponse(
                    {"error": "Invalid base64 audio data"}, status_code=400
                )

            if not audio_bytes:
                return JSONResponse({"error": "Empty file"}, status_code=400)
            if len(audio_bytes) > MAX_HTTP_AUDIO_UPLOAD_BYTES:
                return JSONResponse(
                    {"error": "Audio file is too large"}, status_code=413
                )

            fd, temp_path = tempfile.mkstemp(suffix=".audio")
            with os.fdopen(fd, "wb") as f:
                f.write(audio_bytes)

            language = body.get("language", "zh")
            response_format = body.get("response_format", "json")
            stream_mode = body.get("stream", False) in (True, "true", "True", "1")
        else:
            return JSONResponse(
                {"error": f"Unsupported content-type: {content_type}"}, status_code=400
            )

        # Streaming mode: SSE with real-time segments
        if stream_mode:

            async def stream_transcription_segments():
                """Generator that yields SSE events as transcription segments arrive."""
                END = object()

                segments_generator = None
                info = None

                def start_transcription():
                    # transcribe() returns a generator + info. Loading is also
                    # performed in this worker thread on the first STT request.
                    whisper_model = get_whisper_model()
                    with WHISPER_LOCK:
                        return whisper_model.transcribe(
                            temp_path,
                            beam_size=5,
                            language=language,
                            vad_filter=True,
                            vad_parameters=dict(min_silence_duration_ms=500),
                        )

                def get_next_segment():
                    try:
                        with WHISPER_LOCK:
                            return next(segments_generator)  # pyright: ignore[reportArgumentType]
                    except StopIteration:
                        return END

                try:
                    segments, info = await asyncio.to_thread(start_transcription)
                    segments_generator = iter(segments)

                    meta = {
                        "language": info.language,
                        "language_probability": info.language_probability,
                        "duration": info.duration,
                    }

                    yield (
                        f"data: "
                        f"{json.dumps({'type': 'metadata', **meta}, ensure_ascii=False)}"
                        f"\n\n"
                    )

                    all_texts = []

                    while True:
                        if SERVER_SHUTTING_DOWN.is_set():
                            _transcription_log.info(
                                "HTTP transcription stream ending because server is shutting down"
                            )
                            return

                        if await request.is_disconnected():
                            _transcription_log.info(
                                "HTTP transcription client disconnected"
                            )
                            return

                        seg = await asyncio.to_thread(get_next_segment)

                        if seg is END:
                            break

                        text = seg.text.strip()  # pyright: ignore[reportAttributeAccessIssue]

                        seg_data = {
                            "type": "segment",
                            "start": round(seg.start, 2),  # pyright: ignore[reportAttributeAccessIssue]
                            "end": round(seg.end, 2),  # pyright: ignore[reportAttributeAccessIssue]
                            "text": text,
                        }

                        if text:
                            all_texts.append(text)

                        yield f"data: {json.dumps(seg_data, ensure_ascii=False)}\n\n"

                    yield (
                        f"data: "
                        f"{json.dumps({'type': 'done', 'text': ' '.join(all_texts)}, ensure_ascii=False)}"
                        f"\n\n"
                    )
                    yield _SSE_DONE_FRAME

                except asyncio.CancelledError:
                    _transcription_log.info("HTTP transcription stream cancelled")
                    return

                except Exception as e:
                    _transcription_log.error(f"Stream transcription error: {e}")
                    yield (
                        f"data: "
                        f"{json.dumps({'type': 'error', 'error': str(e)}, ensure_ascii=False)}"
                        f"\n\n"
                    )
                    yield _SSE_DONE_FRAME

                finally:
                    if segments_generator is not None:
                        close_method = getattr(
                            segments_generator,
                            "close",
                            None,
                        )

                        if callable(close_method):
                            try:
                                await asyncio.to_thread(close_method)
                            except Exception:
                                _transcription_log.debug(
                                    "Failed to close Whisper segment generator",
                                    exc_info=True,
                                )

                    _safe_unlink(temp_path)

            return StreamingResponse(
                stream_transcription_segments(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                    "Access-Control-Allow-Origin": "*",
                },
                background=BackgroundTask(
                    _safe_unlink,
                    temp_path,
                ),
            )

        # Non-streaming mode: return full result
        result = await asyncio.to_thread(transcribe_file_sync, temp_path, language)

        if response_format == "verbose_json":
            return JSONResponse(result)
        elif response_format == "text":
            return Response(
                content=result["text"],
                media_type="text/plain; charset=utf-8",
                headers={"Access-Control-Allow-Origin": "*"},
            )
        elif response_format == "srt":
            lines = []
            for i, seg in enumerate(result.get("segments", []), 1):
                s, e = seg["start"], seg["end"]
                lines.append(
                    f"{i}\n"
                    f"{int(s // 3600):02d}:{int((s % 3600) // 60):02d}:{int(s % 60):02d},{int((s % 1) * 1000):03d} --> "
                    f"{int(e // 3600):02d}:{int((e % 3600) // 60):02d}:{int(e % 60):02d},{int((e % 1) * 1000):03d}\n"
                    f"{seg['text']}\n"
                )
            return Response(
                content="\n".join(lines),
                media_type="text/plain; charset=utf-8",
                headers={"Access-Control-Allow-Origin": "*"},
            )
        elif response_format == "vtt":
            lines = ["WEBVTT\n"]
            for i, seg in enumerate(result.get("segments", []), 1):
                s, e = seg["start"], seg["end"]
                lines.append(
                    f"\n{i}\n"
                    f"{int(s // 3600):02d}:{int((s % 3600) // 60):02d}:{int(s % 60):02d}.{int((s % 1) * 1000):03d} --> "
                    f"{int(e // 3600):02d}:{int((e % 3600) // 60):02d}:{int(e % 60):02d}.{int((e % 1) * 1000):03d}\n"
                    f"{seg['text']}"
                )
            return Response(
                content="\n".join(lines) + "\n",
                media_type="text/vtt; charset=utf-8",
                headers={"Access-Control-Allow-Origin": "*"},
            )
        else:
            return JSONResponse(
                {
                    "text": result["text"],
                    "language": result.get("language"),
                }
            )

    except ClientDisconnect:
        _transcription_log.info("Transcription API client disconnected")
        return Response(status_code=499)
    except asyncio.CancelledError:
        _transcription_log.info("Transcription API cancelled during shutdown")
        raise
    except Exception as e:
        _transcription_log.error(f"Transcription API error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)
    finally:
        if not stream_mode:
            _safe_unlink(temp_path)


async def speech_api(request):
    """
    OpenAI-compatible /v1/audio/speech endpoint.
    Supports SSE streaming: when stream=true, streams audio chunks as SSE events.
    When stream=false, returns full audio/mpeg binary.
    Accepts JSON: { model, input, voice, response_format, speed, stream }
    """
    try:
        body = await request.json()
        if not isinstance(body, dict):
            return JSONResponse(
                {"error": "JSON body must be an object"}, status_code=400
            )

        raw_text = body.get("input", "")
        if not isinstance(raw_text, str):
            return JSONResponse({"error": "input must be text"}, status_code=400)

        text = raw_text.strip()
        if not text:
            return JSONResponse({"error": "Empty input text"}, status_code=400)

        voice = resolve_voice(str(body.get("voice", "en")))
        try:
            speed = parse_tts_speed(body.get("speed", 1.0))
        except ValueError as exc:
            return JSONResponse({"error": str(exc)}, status_code=400)
        stream_mode = body.get("stream", False) in (True, "true", "True", "1")

        _tts_log.debug(
            "HTTP TTS: voice=%s  speed=%.2f  chars=%d  stream=%s",
            voice,
            speed,
            len(text),
            stream_mode,
        )

        if speed >= 1.0:
            rate_str = f"+{int((speed - 1) * 100)}%"
        else:
            rate_str = f"-{int((1 - speed) * 100)}%"

        if stream_mode:

            async def stream_tts_audio():
                try:
                    communicate = edge_tts.Communicate(
                        text,
                        voice=voice,
                        rate=rate_str,
                    )

                    total_bytes = 0

                    async for chunk in communicate.stream():
                        if SERVER_SHUTTING_DOWN.is_set():
                            _tts_log.debug(
                                "HTTP TTS stream ending because server is shutting down"
                            )
                            return

                        if await request.is_disconnected():
                            _tts_log.debug("HTTP TTS client disconnected")
                            return

                        if chunk.get("type") == "audio":
                            data = chunk.get("data")
                            if not data:
                                continue

                            encoded = base64.b64encode(data).decode("ascii")
                            total_bytes += len(data)

                            yield (
                                "data: "
                                + json.dumps(
                                    {
                                        "type": "audio",
                                        "data": encoded,
                                    }
                                )
                                + "\n\n"
                            )

                            await asyncio.sleep(0)

                        elif chunk["type"] == "WordBoundary":
                            yield (
                                "data: "
                                + json.dumps(
                                    {
                                        "type": "word_boundary",
                                        **chunk,
                                    }
                                )
                                + "\n\n"
                            )

                    yield (
                        "data: "
                        + json.dumps(
                            {
                                "type": "done",
                                "total_bytes": total_bytes,
                            }
                        )
                        + "\n\n"
                    )

                    yield _SSE_DONE_FRAME

                except asyncio.CancelledError:
                    _tts_log.debug("HTTP TTS stream cancelled")
                    raise

                except Exception as exc:
                    _tts_log.exception("HTTP TTS stream failed")

                    yield (
                        "data: "
                        + json.dumps(
                            {
                                "type": "error",
                                "error": str(exc),
                            }
                        )
                        + "\n\n"
                    )

                    yield _SSE_DONE_FRAME

            return StreamingResponse(
                stream_tts_audio(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                    "Access-Control-Allow-Origin": "*",
                },
            )

        # Non-streaming mode
        communicate = edge_tts.Communicate(text, voice=voice, rate=rate_str)

        from io import BytesIO

        buffer = BytesIO()
        total_bytes = 0

        async for chunk in communicate.stream():
            if SERVER_SHUTTING_DOWN.is_set():
                return JSONResponse(
                    {"error": "Server is shutting down"},
                    status_code=503,
                )

            if await request.is_disconnected():
                raise ClientDisconnect()

            if chunk.get("type") != "audio":
                continue

            audio_chunk = chunk.get("data")

            if not audio_chunk:
                continue

            total_bytes += len(audio_chunk)

            if total_bytes > MAX_HTTP_TTS_BYTES:
                return JSONResponse(
                    {"error": "Generated audio is too large"},
                    status_code=413,
                )

            buffer.write(audio_chunk)

        audio_data = buffer.getvalue()

        if not audio_data:
            return JSONResponse({"error": "No audio generated"}, status_code=500)

        _tts_log.debug("HTTP TTS done: %d bytes generated", len(audio_data))
        return Response(
            content=audio_data,
            media_type="audio/mpeg",
            headers={
                "X-Voice": voice,
                "X-Chars": str(len(text)),
                "Access-Control-Allow-Origin": "*",
            },
        )

    except ClientDisconnect:
        _http_log.info("Speech API client disconnected")
        return Response(status_code=499)
    except asyncio.CancelledError:
        _http_log.info("Speech API cancelled during shutdown")
        raise
    except Exception as e:
        _tts_log.error("Speech API error: %s", e)
        return JSONResponse({"error": str(e)}, status_code=500)


# ==================== FIM ====================


def get_fim_profile_for_model(model_name: Optional[str]) -> dict:
    model_name = str(model_name or "").strip()

    profile_name = MODEL_FIM_PROFILE.get(model_name)

    if not profile_name:
        # fallback: 根据模型名猜
        lower = model_name.lower()

        if "qwen" in lower or "coder" in lower:
            profile_name = "qwen"
        else:
            profile_name = "continue"

    return FIM_PROFILES.get(profile_name, FIM_PROFILES["continue"])


def canonicalize_fim_special_tokens(
    text: str, fim_profile: Optional[dict] = None
) -> str:
    if text is None:
        return ""

    text = str(text)

    profile = fim_profile or FIM_PROFILES["qwen"]

    if not profile.get("canonicalize_continue", False):
        return text

    replacements = {
        "<fim_prefix>": profile["prefix"],
        "<fim_suffix>": profile["suffix"],
        "<fim_middle>": profile["middle"],
        "<fim_pad>": profile.get("pad", ""),
        "<file_sep>": profile.get("file_sep", ""),
    }

    for old, new in replacements.items():
        if new:
            text = text.replace(old, new)

    return text


def extract_fim_from_prompt(prompt: str, fim_profile: Optional[dict] = None):
    """
    Detect and extract FIM prompt.

    Supports:
    - Continue style:
      <fim_prefix>prefix<fim_suffix>suffix<fim_middle>

    - Qwen style:
      <|fim_prefix|>prefix<|fim_suffix|>suffix<|fim_middle|>

    Returns:
        (is_fim, prefix, suffix)
    """
    if not prompt:
        return False, "", ""

    profile = fim_profile or FIM_PROFILES["qwen"]

    prompt = canonicalize_fim_special_tokens(prompt, profile)

    p_tok = profile["prefix"]
    s_tok = profile["suffix"]
    m_tok = profile["middle"]

    if not p_tok or not s_tok or not m_tok:
        return False, prompt, ""

    p_idx = prompt.find(p_tok)
    s_idx = prompt.find(s_tok)
    m_idx = prompt.find(m_tok)

    if p_idx == -1 or s_idx == -1 or m_idx == -1:
        return False, prompt, ""

    if not (p_idx < s_idx < m_idx):
        return False, prompt, ""

    prefix = prompt[p_idx + len(p_tok) : s_idx]
    suffix = prompt[s_idx + len(s_tok) : m_idx]

    return True, prefix, suffix


def build_completion_prompt(
    prompt: str,
    suffix: Optional[str] = None,
    fim_profile: Optional[dict] = None,
) -> str:
    """Build a completion prompt using the selected FIM token profile."""
    prompt = "" if prompt is None else str(prompt)
    profile = fim_profile or FIM_PROFILES["qwen"]

    p_tok = profile["prefix"]
    s_tok = profile["suffix"]
    m_tok = profile["middle"]

    if suffix is not None and p_tok and s_tok and m_tok:
        suffix = "" if suffix is None else str(suffix)
        return f"{p_tok}{prompt}{s_tok}{suffix}{m_tok}"

    is_fim, prefix, extracted_suffix = extract_fim_from_prompt(prompt, profile)

    if is_fim and p_tok and s_tok and m_tok:
        return f"{p_tok}{prefix}{s_tok}{extracted_suffix}{m_tok}"

    return canonicalize_fim_special_tokens(prompt, profile)


def convert_legacy_functions(body: dict) -> dict:
    if body.get("tools"):
        return body

    functions = body.get("functions")
    if isinstance(functions, list) and functions:
        body = dict(body)
        body["tools"] = [
            {"type": "function", "function": fn}
            for fn in functions
            if isinstance(fn, dict)
        ]

        fc = body.get("function_call")
        if fc == "none":
            body["tool_choice"] = "none"
        elif fc in (None, "auto"):
            body["tool_choice"] = "auto"
        elif isinstance(fc, dict) and fc.get("name"):
            body["tool_choice"] = {
                "type": "function",
                "function": {"name": fc["name"]},
            }

    return body


def prepare_response_format_messages(messages, response_format):
    if not response_format:
        return messages, None

    rtype = response_format.get("type")

    if rtype == "json_object":
        instruction = (
            "You must respond with a valid JSON object only. "
            "Do not include markdown, code fences, or explanations."
        )
    elif rtype == "json_schema":
        schema = response_format.get("json_schema", {}).get("schema")
        instruction = (
            "You must respond with valid JSON that matches this JSON Schema. "
            "Do not include markdown, code fences, or explanations.\n"
            f"JSON Schema: {json.dumps(schema, ensure_ascii=False)}"
        )
    else:
        return messages, f"Unsupported response_format type: {rtype}"

    return [{"role": "system", "content": instruction}, *list(messages)], None


def _dbg_trunc(value, max_chars: int | None = None) -> str:
    max_chars = max_chars or VE_LLM_LOG_DEBUG_MAX_CHARS

    try:
        if value is None:
            return "None"

        if not isinstance(value, str):
            value = json.dumps(value, ensure_ascii=False, default=str)

        value = value.replace("\r", "\\r").replace("\n", "\\n")

        if len(value) > max_chars:
            return value[:max_chars] + f"... <truncated {len(value) - max_chars} chars>"

        return value

    except Exception:
        return repr(value)


def _debug_completion_log(label: str, **kwargs):
    if not VE_LLM_LOG_DEBUG:
        return

    parts = []
    for k, v in kwargs.items():
        parts.append(f"{k}={_dbg_trunc(v)}")

    _llm_log.info("[COMPLETIONS DEBUG] %s | %s", label, " | ".join(parts))


async def completions_api(request):
    """
    OpenAI-compatible /v1/completions endpoint.

    Supports:
    - prompt: string or list[string]
    - suffix: optional FIM suffix
    - stream: SSE streaming
    - stop: string or list[string]
    """
    try:
        body = await request.json()

        _debug_completion_log(
            "request_body",
            body=body,
        )

        prompt_input = body.get("prompt", "")
        suffix = body.get("suffix", None)

        # Continue sends FIM in prompt:
        # <fim_prefix>prefix<fim_suffix>suffix<fim_middle>
        detected_fim = False

        if isinstance(prompt_input, str) and suffix is None:
            detected_fim, detected_prefix, detected_suffix = extract_fim_from_prompt(
                prompt_input
            )

            if detected_fim:
                prompt_input = detected_prefix
                suffix = detected_suffix

        if isinstance(prompt_input, list):
            prompts = [str(x) for x in prompt_input]
        else:
            prompts = [str(prompt_input)]

        is_fim_request = suffix is not None or detected_fim

        requested_model = body.get("model", None)

        if _openrouter_is_model(requested_model):
            openrouter_stream = body.get("stream", False) in (True, "true", "True", "1")
            return await _direct_openrouter_text_completion(
                dict(body), openrouter_stream
            )

        if is_fim_request:
            requested_model = requested_model or DEFAULT_FIM_ALIAS

            err = reject_wrong_model_namespace(
                requested_model,
                expected_prefix="FIM:",
                endpoint_name="/v1/completions FIM",
            )

            if err:
                _llm_log.warning(err)
                return JSONResponse({"error": err}, status_code=400)

            resolved_model = resolve_fim_model_name(requested_model)
            model_kind = "fim"

        else:
            requested_model = requested_model or DEFAULT_LLM_ALIAS

            err = reject_wrong_model_namespace(
                requested_model,
                expected_prefix="LLM:",
                endpoint_name="/v1/completions",
            )

            if err:
                _llm_log.warning(err)
                return JSONResponse({"error": err}, status_code=400)

            resolved_model = resolve_llm_model_name(requested_model)
            model_kind = "llm"

        fim_profile = get_fim_profile_for_model(requested_model)

        max_tokens = int(body.get("max_tokens", body.get("max_completion_tokens", 256)))
        temperature = float(body.get("temperature", 0.7))
        top_p_val = float(body.get("top_p", 1.0))
        stream_mode = body.get("stream", False) in (True, "true", "True", "1")
        echo = bool(body.get("echo", False))

        stream_options = body.get("stream_options") or {}
        if stream_options and not stream_mode:
            return JSONResponse(
                {"error": "stream_options can only be used when stream=true"},
                status_code=400,
            )

        if not isinstance(stream_options, dict):
            return JSONResponse(
                {"error": "stream_options must be an object"},
                status_code=400,
            )

        include_stream_usage = bool(stream_options.get("include_usage", False))

        stop_sequences = normalize_stop_sequences(body.get("stop"), fim_profile)

        if is_fim_request:
            fim_stops = [
                fim_profile.get("prefix", ""),
                fim_profile.get("suffix", ""),
                fim_profile.get("middle", ""),
                fim_profile.get("pad", ""),
                fim_profile.get("file_sep", ""),
                "<|endoftext|>",
            ]

            # In FIM mode, if the model starts reproducing suffix, stop there.
            suffix_text = str(suffix).strip()
            if suffix_text and suffix_text not in stop_sequences:
                stop_sequences.append(suffix_text)

            for s in fim_stops:
                if s and s not in stop_sequences:
                    stop_sequences.append(s)

        _debug_completion_log(
            "parsed_request",
            model=requested_model,
            model_kind=model_kind,
            resolved_model=resolved_model,
            stream=stream_mode,
            detected_fim=detected_fim,
            is_fim_request=is_fim_request,
            prompt_type=type(prompt_input).__name__,
            prompt_count=len(prompts),
            suffix=suffix,
            max_tokens=max_tokens,
            temperature=temperature,
            top_p=top_p_val,
            stop=body.get("stop"),
            normalized_stop=stop_sequences,
            echo=echo,
        )

        if not prompts:
            return JSONResponse({"error": "No prompt provided"}, status_code=400)

        # Streaming only supports one prompt for simplicity.
        if stream_mode and len(prompts) != 1:
            return JSONResponse(
                {"error": "Streaming completions only support a single prompt"},
                status_code=400,
            )

        completion_id = f"cmpl-{time.monotonic_ns()}"

        created = int(time.time())
        model_name = requested_model

        if stream_mode:
            raw_prompt = build_completion_prompt(
                prompts[0], suffix=suffix, fim_profile=fim_profile
            )

            _debug_completion_log(
                "built_prompt",
                is_fim=suffix is not None,
                raw_prompt=raw_prompt,
                stop_sequences=stop_sequences,
            )

            result_queue = queue.Queue(maxsize=32)

            stop_event = threading.Event()

            start_llm_worker()

            job = {
                "type": "completion_stream",
                "model_kind": model_kind,
                "model": requested_model,
                "prompt": raw_prompt,
                "max_tokens": max_tokens,
                "temperature": temperature,
                "top_p": top_p_val,
                "out_q": result_queue,
                "stop_event": stop_event,
            }

            try:
                _submit_llm_job(job)

            except LLMQueueFullError as exc:
                return JSONResponse(
                    {
                        "error": {
                            "message": str(exc),
                            "type": "server_busy",
                        }
                    },
                    status_code=503,
                    headers={
                        "Retry-After": "1",
                    },
                )

            async def stream_completion():

                pending_text = ""

                suffix_tail = len(str(suffix or "")) - 1 if suffix is not None else 0

                max_stop_tail = max(
                    max([len(s) for s in stop_sequences], default=0) - 1,
                    suffix_tail,
                )
                max_stop_tail = max(0, max_stop_tail)

                finish_reason = None

                try:
                    while True:
                        if SERVER_SHUTTING_DOWN.is_set():
                            _llm_log.info(
                                "Completion stream ending because server is shutting down"
                            )
                            stop_event.set()
                            return

                        if await request.is_disconnected():
                            _llm_log.info("Completion API client disconnected")
                            stop_event.set()
                            return

                        try:
                            item = await asyncio.to_thread(
                                result_queue.get,
                                timeout=0.1,
                            )
                        except queue.Empty:
                            continue

                        if not isinstance(item, tuple):
                            continue

                        item_type = item[0]
                        payload = item[1] if len(item) > 1 else None

                        if item_type == "error":
                            yield f"data: {json.dumps({'error': payload})}\n\n"
                            yield _SSE_DONE_FRAME
                            return

                        if item_type == "done":
                            finish_reason = payload or "stop"

                            final_text = pending_text
                            hit_stop = False
                            hit_suffix_overlap = False

                            if final_text:
                                final_text, hit_stop = cut_at_stop_sequences(
                                    final_text,
                                    stop_sequences,
                                )

                                # if suffix is not None:
                                #     final_text, hit_suffix_overlap = cut_at_suffix_overlap(
                                #         final_text,
                                #         suffix,
                                #     )

                            _debug_completion_log(
                                "stream_done_flush",
                                pending_text=pending_text,
                                final_text=final_text,
                                hit_stop=hit_stop,
                                hit_suffix_overlap=hit_suffix_overlap,
                                finish_reason=finish_reason,
                            )

                            if hit_stop or hit_suffix_overlap:
                                finish_reason = "stop"

                            if final_text:
                                chunk = {
                                    "id": completion_id,
                                    "object": "text_completion",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "text": final_text,
                                            "index": 0,
                                            "logprobs": None,
                                            "finish_reason": None,
                                        }
                                    ],
                                }

                                _debug_completion_log(
                                    "stream_yield_done_flush",
                                    text=final_text,
                                    finish_reason=finish_reason,
                                )

                                yield f"data: {json.dumps(chunk, ensure_ascii=False)}\n\n"
                                await asyncio.sleep(0)

                            pending_text = ""
                            break

                        if item_type == "token_text":
                            token_text = payload or ""

                        elif item_type == "token":
                            gen_resp = payload
                            if gen_resp is None:
                                continue
                            token_text = gen_resp.text or ""

                        else:
                            continue

                        # if token_text:
                        #     _debug_completion_log(
                        #         "stream_token",
                        #         token_text=token_text,
                        #         pending_text=pending_text,
                        #         finish_reason=finish_reason,
                        #     )

                        token_text, hit_llm_stop = cut_at_llm_stop_marker(token_text)

                        if hit_llm_stop:
                            finish_reason = "stop"

                        pending_text += token_text

                        emit_text, hit_stop = cut_at_stop_sequences(
                            pending_text,
                            stop_sequences,
                        )

                        if hit_stop:
                            finish_reason = "stop"

                            if emit_text:
                                chunk = {
                                    "id": completion_id,
                                    "object": "text_completion",
                                    "created": created,
                                    "model": model_name,
                                    "choices": [
                                        {
                                            "text": emit_text,
                                            "index": 0,
                                            "logprobs": None,
                                            "finish_reason": None,
                                        }
                                    ],
                                }

                                yield f"data: {json.dumps(chunk, ensure_ascii=False)}\n\n"

                            break

                        # Hold a small tail so stop sequences split across tokens
                        # are less likely to leak.
                        if max_stop_tail and len(pending_text) > max_stop_tail:
                            emit = pending_text[:-max_stop_tail]
                            pending_text = pending_text[-max_stop_tail:]
                        else:
                            emit = ""

                        if emit:
                            chunk = {
                                "id": completion_id,
                                "object": "text_completion",
                                "created": created,
                                "model": model_name,
                                "choices": [
                                    {
                                        "text": emit,
                                        "index": 0,
                                        "logprobs": None,
                                        "finish_reason": None,
                                    }
                                ],
                            }

                            # _debug_completion_log(
                            #     "stream_yield_chunk",
                            #     emit=emit,
                            #     finish_reason=finish_reason,
                            # )

                            yield f"data: {json.dumps(chunk, ensure_ascii=False)}\n\n"

                        if hit_llm_stop:
                            break

                    final_chunk = {
                        "id": completion_id,
                        "object": "text_completion",
                        "created": created,
                        "model": model_name,
                        "choices": [
                            {
                                "text": "",
                                "index": 0,
                                "logprobs": None,
                                "finish_reason": finish_reason or "stop",
                            }
                        ],
                    }

                    _debug_completion_log(
                        "stream_final_chunk",
                        finish_reason=finish_reason or "stop",
                    )

                    yield f"data: {json.dumps(final_chunk, ensure_ascii=False)}\n\n"

                    if include_stream_usage:
                        usage_chunk = {
                            "id": completion_id,
                            "object": "text_completion",
                            "created": created,
                            "model": model_name,
                            "choices": [],
                            "usage": {
                                "prompt_tokens": 0,
                                "completion_tokens": 0,
                                "total_tokens": 0,
                            },
                        }

                        yield f"data: {json.dumps(usage_chunk, ensure_ascii=False)}\n\n"

                    yield _SSE_DONE_FRAME

                except asyncio.CancelledError:
                    # _app_log.info("Completion stream cancelled")
                    stop_event.set()
                    return

                finally:
                    stop_event.set()

                    try:
                        while True:
                            result_queue.get_nowait()
                    except queue.Empty:
                        pass

            return StreamingResponse(
                stream_completion(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                    "Access-Control-Allow-Origin": "*",
                },
            )

        # Non-streaming mode
        choices = []

        for idx, p in enumerate(prompts):
            raw_prompt = build_completion_prompt(
                p, suffix=suffix, fim_profile=fim_profile
            )

            _debug_completion_log(
                "built_prompt",
                is_fim=suffix is not None,
                raw_prompt=raw_prompt,
                stop_sequences=stop_sequences,
            )

            try:
                output = await asyncio.to_thread(
                    _submit_completion_job,
                    prompt=raw_prompt,
                    model=requested_model,
                    model_kind=model_kind,
                    max_tokens=max_tokens,
                    temperature=temperature,
                    top_p=top_p_val,
                )

            except LLMQueueFullError as exc:
                return JSONResponse(
                    {
                        "error": {
                            "message": str(exc),
                            "type": "server_busy",
                        }
                    },
                    status_code=503,
                    headers={
                        "Retry-After": "1",
                    },
                )

            _debug_completion_log(
                "worker_raw_output",
                index=idx,
                output=output,
            )

            if output is None:
                return JSONResponse(
                    {"error": "Completion generation failed"},
                    status_code=500,
                )

            output_before_cleanup = output

            output = strip_llm_artifacts(output, remove_reasoning=False)
            output_after_artifact_cleanup = output

            output, hit_user_stop = cut_at_stop_sequences(output, stop_sequences)

            hit_suffix_overlap = False

            # if suffix is not None:
            #     output, hit_suffix_overlap = cut_at_suffix_overlap(output, suffix)

            _debug_completion_log(
                "postprocess_output",
                index=idx,
                before_cleanup=output_before_cleanup,
                after_artifact_cleanup=output_after_artifact_cleanup,
                after_stop_cut=output,
                hit_user_stop=hit_user_stop,
                hit_suffix_overlap=hit_suffix_overlap,
            )

            if echo:
                visible_prompt = p
                text = visible_prompt + output
            else:
                text = output

            choices.append(
                {
                    "text": text,
                    "index": idx,
                    "logprobs": None,
                    "finish_reason": "stop",
                }
            )

        return JSONResponse(
            {
                "id": completion_id,
                "object": "text_completion",
                "created": created,
                "model": model_name,
                "choices": choices,
                "usage": {
                    "prompt_tokens": 0,
                    "completion_tokens": 0,
                    "total_tokens": 0,
                },
            }
        )

    except ClientDisconnect:
        _llm_log.info("Completions API client disconnected")
        return Response(status_code=499)
    except asyncio.CancelledError:
        _llm_log.info("Completions API cancelled during shutdown")
        raise
    except Exception as e:
        _llm_log.error(f"Completions API error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


def apply_parallel_tool_call_policy(
    tool_calls: list, parallel_tool_calls: bool
) -> list:
    if not tool_calls:
        return tool_calls

    if parallel_tool_calls:
        return tool_calls

    if len(tool_calls) > 1:
        _llm_log.warning(
            "Model emitted %d tool calls while parallel_tool_calls=false; keeping only the first",
            len(tool_calls),
        )

    return tool_calls[:1]


def parse_optional_bool(
    value,
    *,
    default: bool,
    field_name: str,
) -> bool:
    if value is None:
        return default

    if isinstance(value, bool):
        return value

    if value in (1, "1", "true", "True", "TRUE"):
        return True

    if value in (0, "0", "false", "False", "FALSE"):
        return False

    raise ValueError(f"{field_name} must be a boolean")


def parse_bool_field(
    body: dict,
    field_name: str,
    *,
    default: bool,
):
    """Parse an OpenAI-compatible optional boolean request field.

    This intentionally does not use bool(value): bool("false") is True.
    Returns (value, error_response), so endpoint code stays explicit.
    """
    try:
        return (
            parse_optional_bool(
                body.get(field_name),
                default=default,
                field_name=field_name,
            ),
            None,
        )
    except ValueError as exc:
        return (
            default,
            JSONResponse(
                {"error": str(exc)},
                status_code=400,
            ),
        )


def _chat_sse_data(
    payload: dict,
) -> str:
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
    )

    _http_log.debug(
        "[CHAT SSE OUT] %s",
        encoded,
    )

    return "data: " + encoded + "\n\n"


def _make_chat_content_chunk(
    *,
    prompt_id: str,
    created: int,
    model_name: str,
    text: str,
    include_role: bool = False,
) -> str:
    delta = {}

    if include_role:
        delta["role"] = "assistant"

    if text:
        delta["content"] = text

    payload = {
        "id": prompt_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model_name,
        "choices": [
            {
                "index": 0,
                "delta": delta,
                "finish_reason": None,
            }
        ],
    }

    return _chat_sse_data(payload)


def _make_chat_reasoning_chunk(
    *,
    prompt_id: str,
    created: int,
    model_name: str,
    text: str,
    include_role: bool = False,
) -> str:
    delta = {}

    if include_role:
        delta["role"] = "assistant"

    if text:
        delta["reasoning_content"] = text

    payload = {
        "id": prompt_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model_name,
        "choices": [
            {
                "index": 0,
                "delta": delta,
                "finish_reason": None,
            }
        ],
    }

    return _chat_sse_data(payload)


def _make_chat_tool_chunk(
    *,
    prompt_id: str,
    created: int,
    model_name: str,
    call_index: int,
    call_id: Optional[str] = None,
    function_name: Optional[str] = None,
    arguments_delta: Optional[str] = None,
    include_role: bool = False,
) -> str:
    delta = {}

    if include_role:
        delta["role"] = "assistant"

    function_delta = {}

    if function_name is not None:
        function_delta["name"] = function_name

    if arguments_delta is not None:
        function_delta["arguments"] = arguments_delta

    tool_call_delta = {
        "index": call_index,
        "function": function_delta,
    }

    if call_id is not None:
        tool_call_delta["id"] = call_id

    if function_name is not None:
        tool_call_delta["type"] = "function"

    delta["tool_calls"] = [tool_call_delta]

    payload = {
        "id": prompt_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model_name,
        "choices": [
            {
                "index": 0,
                "delta": delta,
                "finish_reason": None,
            }
        ],
    }

    return _chat_sse_data(payload)


def _make_chat_finish_chunk(
    *,
    prompt_id: str,
    created: int,
    model_name: str,
    finish_reason: str,
) -> str:
    payload = {
        "id": prompt_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model_name,
        "choices": [
            {
                "index": 0,
                "delta": {},
                "finish_reason": finish_reason,
            }
        ],
    }

    return _chat_sse_data(payload)


def _resolve_chat_completion_max_tokens(body: dict, *, default: int = 500) -> int:
    """Resolve Chat Completions output budget with OpenAI-compatible precedence.

    ``max_completion_tokens`` is the current Chat Completions parameter.
    ``max_tokens`` remains supported as a legacy compatibility alias.
    Responses API's ``max_output_tokens`` is intentionally not accepted here.
    """
    requested = body.get("max_completion_tokens")
    if requested is None:
        requested = body.get("max_tokens")
    return _normalize_max_tokens(requested, default=default)


@dataclass(frozen=True)
class OpenRouterConfig:
    """OpenRouter configuration; only API keys come from the environment."""

    api_keys: tuple[str, ...]
    base_url: str = OPENROUTER_BASE_URL
    model_prefix: str = OPENROUTER_MODEL_PREFIX
    alternate_model_prefix: str = OPENROUTER_ALTERNATE_MODEL_PREFIX
    default_model: str = OPENROUTER_DEFAULT_MODEL
    exposed_models: tuple[str, ...] = OPENROUTER_EXPOSED_MODELS
    aliases: dict[str, str] = field(
        default_factory=lambda: dict(OPENROUTER_MODEL_ALIASES)
    )
    app_name: str = OPENROUTER_APP_NAME
    http_referer: str = OPENROUTER_HTTP_REFERER
    connect_timeout: float = OPENROUTER_CONNECT_TIMEOUT_SECONDS
    first_event_timeout: float = OPENROUTER_FIRST_EVENT_TIMEOUT_SECONDS
    stream_idle_timeout: float = OPENROUTER_STREAM_IDLE_TIMEOUT_SECONDS
    total_timeout: float = OPENROUTER_TOTAL_TIMEOUT_SECONDS
    max_attempts: int = OPENROUTER_MAX_ATTEMPTS
    retry_base_seconds: float = OPENROUTER_RETRY_BASE_SECONDS
    key_cooldown_seconds: float = OPENROUTER_KEY_COOLDOWN_SECONDS
    max_inflight_per_key: int = OPENROUTER_MAX_INFLIGHT_PER_KEY
    key_strategy: str = OPENROUTER_KEY_SELECTION_STRATEGY
    key_options: tuple[str, ...] = OPENROUTER_KEY_SELECTION_OPTS
    global_rate_delay: float = OPENROUTER_GLOBAL_RATE_DELAY_SECONDS

    @classmethod
    def load(cls) -> "OpenRouterConfig":
        return cls(api_keys=tuple(_openrouter_parse_api_keys()))


@dataclass(frozen=True)
class OpenRouterModelSpec:
    public_id: str
    upstream_id: str
    capabilities: frozenset[str] = frozenset({"chat", "completions", "stream"})

    @classmethod
    def from_public_id(cls, public_id: str) -> "OpenRouterModelSpec":
        upstream_id = _openrouter_upstream_model(public_id)
        return cls(
            public_id=public_id,
            upstream_id=upstream_id,
            capabilities=OPENROUTER_MODEL_CAPABILITIES.get(
                upstream_id,
                frozenset({"chat", "completions", "stream"}),
            ),
        )

    def as_openai_model(self) -> dict[str, Any]:
        return {
            "id": self.public_id,
            "object": "model",
            "created": 0,
            "owned_by": "openrouter",
            "root": self.upstream_id,
            "capabilities": sorted(self.capabilities),
        }


@dataclass
class OpenRouterKeyState:
    secret: str
    key_id: str
    inflight: int = 0
    disabled_until: float = 0.0
    failures: int = 0
    last_used: float = 0.0


class OpenRouterNoKeyError(RuntimeError):
    def __init__(self, wait_seconds: float = 0.0):
        self.wait_seconds = max(0.0, float(wait_seconds))
        super().__init__(
            "No OpenRouter API key is available"
            + (f"; retry in {self.wait_seconds:.0f}s" if self.wait_seconds else "")
        )


def _openrouter_parse_api_keys() -> list[str]:
    raw = os.getenv("VE_OPENROUTER_API_KEYS", "").strip()
    if not raw:
        return []
    if raw.startswith("["):
        try:
            decoded = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "VE_OPENROUTER_API_KEYS must be JSON or comma/newline separated"
            ) from exc
        if not isinstance(decoded, list):
            raise RuntimeError("VE_OPENROUTER_API_KEYS JSON must be an array")
        values = [str(value).strip() for value in decoded]
    else:
        values = [part.strip() for part in re.split(r"[,\r\n]+", raw)]
    return list(dict.fromkeys(value for value in values if value))


def _openrouter_mask(key: str) -> str:
    if len(key) <= 8:
        return "****"
    return f"{key[:4]}****{key[-4:]}"


def _openrouter_is_model(model_name: Any) -> bool:
    return isinstance(model_name, str) and (
        model_name.startswith(OPENROUTER_MODEL_PREFIX)
        or model_name.startswith(OPENROUTER_ALTERNATE_MODEL_PREFIX)
    )


def _openrouter_upstream_model(model_name: str) -> str:
    if model_name in OPENROUTER_MODEL_ALIASES:
        return OPENROUTER_MODEL_ALIASES[model_name]
    if model_name.startswith(OPENROUTER_MODEL_PREFIX):
        model_name = model_name[len(OPENROUTER_MODEL_PREFIX) :]
    elif model_name.startswith(OPENROUTER_ALTERNATE_MODEL_PREFIX):
        model_name = model_name[len(OPENROUTER_ALTERNATE_MODEL_PREFIX) :]
    return model_name.strip() or OPENROUTER_DEFAULT_MODEL


class OpenRouterKeyManager:
    """Concurrency-aware first/random/round-robin selector with sticky option."""

    def __init__(self, config: OpenRouterConfig):
        self.config = config
        self._states = [
            OpenRouterKeyState(
                secret=key,
                key_id=hashlib.sha256(key.encode()).hexdigest()[:10],
            )
            for key in config.api_keys
        ]
        self._cursor = 0
        self._last_good_id: str | None = None
        self._lock = asyncio.Lock()

    async def acquire(self, excluded: set[str] | None = None) -> OpenRouterKeyState:
        excluded = excluded or set()
        async with self._lock:
            now = time.monotonic()
            candidates = [
                state
                for state in self._states
                if state.key_id not in excluded
                and state.disabled_until <= now
                and state.inflight < self.config.max_inflight_per_key
            ]
            if not candidates:
                candidates = [
                    state
                    for state in self._states
                    if state.key_id not in excluded and state.disabled_until <= now
                ]
            if not candidates:
                waits = [
                    s.disabled_until - now
                    for s in self._states
                    if s.disabled_until > now
                ]
                raise OpenRouterNoKeyError(min(waits) if waits else 0.0)
            if "same" in {value.lower() for value in self.config.key_options}:
                sticky = next(
                    (s for s in candidates if s.key_id == self._last_good_id), None
                )
            else:
                sticky = None
            if sticky is not None:
                chosen = sticky
            elif self.config.key_strategy == "first":
                chosen = candidates[0]
            elif self.config.key_strategy == "random":
                chosen = secrets.choice(candidates)
            else:
                ordered = sorted(
                    candidates, key=lambda state: self._states.index(state)
                )
                chosen = ordered[self._cursor % len(ordered)]
                self._cursor = (self._cursor + 1) % max(1, len(self._states))
            chosen.inflight += 1
            chosen.last_used = now
            return chosen

    async def release(self, state: OpenRouterKeyState, *, success: bool) -> None:
        async with self._lock:
            state.inflight = max(0, state.inflight - 1)
            if success:
                state.failures = 0
                self._last_good_id = state.key_id
            else:
                state.failures += 1

    async def penalize(self, state: OpenRouterKeyState) -> None:
        async with self._lock:
            state.disabled_until = time.monotonic() + self.config.key_cooldown_seconds
            if self._last_good_id == state.key_id:
                self._last_good_id = None
            _http_log.warning(
                "OpenRouter key %s cooling down for %.0fs",
                _openrouter_mask(state.secret),
                self.config.key_cooldown_seconds,
            )


@dataclass
class StreamableOutputItem:
    id: str
    type: Literal["reasoning", "message", "function_call"]
    text: str = ""
    name: str = ""
    arguments: str = ""
    call_id: str = ""
    index: int = 0


@dataclass(frozen=True)
class VoiceEdgeEvent:
    kind: Literal["reasoning", "message", "function_call", "error", "done", "metadata"]
    item: StreamableOutputItem | None = None
    delta: str = ""
    payload: Any = None


class OpenRouterItemAssembler:
    """Replace-by-id item store that emits only each snapshot's new suffix."""

    def __init__(self, completion_id: str, created: int, model: str):
        self.completion_id = completion_id
        self.created = created
        self.model = model
        self.items_by_id: OrderedDict[str, StreamableOutputItem] = OrderedDict()
        self.role_sent = False
        self.finish_reason: str | None = None
        self.terminal = False

    def _item(
        self, item_id: str, item_type: str, index: int = 0
    ) -> StreamableOutputItem:
        item = self.items_by_id.get(item_id)
        if item is None:
            item = StreamableOutputItem(item_id, cast(Any, item_type), index=index)
            self.items_by_id[item_id] = item
        return item

    @staticmethod
    def _new_suffix(previous: str, updated: str) -> str:
        if updated.startswith(previous):
            return updated[len(previous) :]
        # Upstream OpenAI chunks are deltas. A non-prefix item update is therefore
        # interpreted as an additional fragment, never as replacement output.
        return updated

    def push(self, chunk: dict) -> list[VoiceEdgeEvent]:
        if self.terminal:
            return []
        if chunk.get("error") is not None:
            self.terminal = True
            return [VoiceEdgeEvent("error", payload=chunk.get("error"))]
        events: list[VoiceEdgeEvent] = []
        choices = chunk.get("choices") or []
        if not choices and chunk.get("usage") is not None:
            return [VoiceEdgeEvent("metadata", payload={"usage": chunk["usage"]})]
        for choice in choices:
            if not isinstance(choice, dict):
                continue
            choice_index = int(choice.get("index", 0) or 0)
            if choice.get("finish_reason") is not None:
                self.finish_reason = str(choice["finish_reason"])
            delta = choice.get("delta") or {}
            if not isinstance(delta, dict):
                continue
            reasoning = delta.get("reasoning_content", delta.get("reasoning"))
            if reasoning:
                item_id = f"reasoning:{choice_index}"
                item = self._item(item_id, "reasoning", choice_index)
                fragment = str(reasoning)
                new_text = item.text + fragment
                added = self._new_suffix(item.text, new_text)
                item.text = new_text
                if added:
                    events.append(VoiceEdgeEvent("reasoning", replace(item), added))
            content = delta.get("content")
            if content:
                item_id = f"message:{choice_index}"
                item = self._item(item_id, "message", choice_index)
                fragment = str(content)
                new_text = item.text + fragment
                added = self._new_suffix(item.text, new_text)
                item.text = new_text
                if added:
                    events.append(VoiceEdgeEvent("message", replace(item), added))
            for call in delta.get("tool_calls") or []:
                if not isinstance(call, dict):
                    continue
                tool_index = int(call.get("index", 0) or 0)
                item_id = f"function_call:{choice_index}:{tool_index}"
                item = self._item(item_id, "function_call", tool_index)
                if call.get("id"):
                    item.call_id = str(call["id"])
                function = call.get("function") or {}
                if function.get("name"):
                    item.name = str(function["name"])
                argument_fragment = str(function.get("arguments") or "")
                item.arguments += argument_fragment
                events.append(
                    VoiceEdgeEvent("function_call", replace(item), argument_fragment)
                )
        return events

    def _chunk(self, delta: dict, *, finish_reason: str | None = None) -> dict:
        if not self.role_sent and delta:
            delta = {"role": "assistant", **delta}
            self.role_sent = True
        return {
            "id": self.completion_id,
            "object": "chat.completion.chunk",
            "created": self.created,
            "model": self.model,
            "choices": [{"index": 0, "delta": delta, "finish_reason": finish_reason}],
        }

    def serialize(self, event: VoiceEdgeEvent) -> dict | None:
        if event.kind == "reasoning":
            return self._chunk({"reasoning_content": event.delta})
        if event.kind == "message":
            return self._chunk({"content": event.delta})
        if event.kind == "function_call" and event.item is not None:
            function: dict[str, str] = {}
            # Stable snapshots keep name/call id available; only emit them once.
            name_marker = f"name-sent:{event.item.id}"
            id_marker = f"id-sent:{event.item.id}"
            if not hasattr(self, "_sent_markers"):
                self._sent_markers: set[str] = set()
            call: dict[str, Any] = {"index": event.item.index, "type": "function"}
            if id_marker not in self._sent_markers and event.item.call_id:
                call["id"] = event.item.call_id
                self._sent_markers.add(id_marker)
            if name_marker not in self._sent_markers and event.item.name:
                function["name"] = event.item.name
                self._sent_markers.add(name_marker)
            if event.delta:
                function["arguments"] = event.delta
            if function:
                call["function"] = function
            return self._chunk({"tool_calls": [call]})
        if event.kind == "metadata" and isinstance(event.payload, dict):
            return {
                "id": self.completion_id,
                "object": "chat.completion.chunk",
                "created": self.created,
                "model": self.model,
                "choices": [],
                **event.payload,
            }
        return None

    def finalize(self) -> dict:
        reason = self.finish_reason
        if reason is None:
            reason = (
                "tool_calls"
                if any(
                    item.type == "function_call" for item in self.items_by_id.values()
                )
                else "stop"
            )
        return self._chunk({}, finish_reason=reason)


class _OpenRouterSSEDecoder:
    """SSE frame decoder; comments are discarded and [DONE] is terminal."""

    def __init__(self):
        self.buffer = bytearray()
        self.done = False

    def feed(self, chunk: bytes) -> list[dict | None]:
        if self.done:
            return []
        self.buffer.extend(chunk)
        output: list[dict | None] = []
        while True:
            raw_buffer = bytes(self.buffer)
            lf_at = raw_buffer.find(b"\n\n")
            crlf_at = raw_buffer.find(b"\r\n\r\n")
            if crlf_at >= 0 and (lf_at < 0 or crlf_at < lf_at):
                frame_end, delimiter_size = crlf_at, 4
            elif lf_at >= 0:
                frame_end, delimiter_size = lf_at, 2
            else:
                break
            frame = raw_buffer[:frame_end].replace(b"\r\n", b"\n")
            del self.buffer[: frame_end + delimiter_size]
            data_lines = [
                line[5:].lstrip()
                for line in frame.split(b"\n")
                if line.startswith(b"data:")
            ]
            if not data_lines:
                continue
            raw = b"\n".join(data_lines)
            if raw == b"[DONE]":
                self.done = True
                output.append(None)
                self.buffer.clear()
                break
            try:
                payload = json.loads(raw)
            except Exception:
                continue
            if isinstance(payload, dict):
                output.append(payload)
        return output


class OpenRouterHTTPClient:
    """Owns transport, key policy and structured chat stream transformation."""

    RETRYABLE = frozenset({408, 425, 429, 500, 502, 503, 504})

    def __init__(self, config: OpenRouterConfig):
        self.config = config
        self.keys = OpenRouterKeyManager(config)

    def headers(self, state: OpenRouterKeyState, *, stream: bool) -> dict[str, str]:
        headers = {
            "Authorization": f"Bearer {state.secret}",
            "Content-Type": "application/json",
            "Accept": "text/event-stream" if stream else "application/json",
            "X-Title": self.config.app_name,
        }
        if self.config.http_referer:
            headers["HTTP-Referer"] = self.config.http_referer
        return headers

    async def _open(self, path: str, payload: dict, stream: bool):
        excluded: set[str] = set()
        attempts = max(1, self.config.max_attempts)
        last_error = "OpenRouter request failed"
        # Preserve the most recent REAL upstream error (HTTP status + body) so it
        # can be shown to the client even when the loop later ends on key
        # exhaustion/cooldown (OpenRouterNoKeyError). Otherwise that generic
        # "No OpenRouter API key is available; retry in Ns" message overwrites
        # OpenRouter's own explanation (e.g. the 429 body that says WHY: free-tier
        # cap, rate limit, no credits, ...).
        last_upstream_status: int | None = None
        last_upstream_body: bytes = b""
        retry_after_seconds = 0.0
        for attempt in range(attempts):
            if len(excluded) >= len(self.config.api_keys):
                excluded.clear()
            try:
                state = await self.keys.acquire(excluded)
            except OpenRouterNoKeyError as exc:
                last_error = str(exc)
                retry_after_seconds = getattr(exc, "wait_seconds", 0.0)
                break
            excluded.add(state.key_id)
            timeout = aiohttp.ClientTimeout(
                total=None if stream else self.config.total_timeout,
                connect=self.config.connect_timeout,
                sock_read=self.config.stream_idle_timeout
                if stream
                else self.config.total_timeout,
            )
            session = aiohttp.ClientSession(timeout=timeout)
            try:
                response = await session.post(
                    self.config.base_url.rstrip("/") + path,
                    json=payload,
                    headers=self.headers(state, stream=stream),
                )
            except (aiohttp.ClientError, asyncio.TimeoutError) as exc:
                await session.close()
                await self.keys.release(state, success=False)
                last_error = str(exc) or exc.__class__.__name__
                continue
            if response.status == 429:
                raw = await response.read()
                last_error = raw.decode(errors="replace")
                last_upstream_status = 429
                last_upstream_body = raw
                response.release()
                await session.close()
                await self.keys.penalize(state)
                await self.keys.release(state, success=False)
                if self.config.global_rate_delay:
                    await asyncio.sleep(self.config.global_rate_delay)
                continue
            if response.status >= 400:
                raw = await response.read()
                status = response.status
                last_upstream_status = status
                last_upstream_body = raw
                response.release()
                await session.close()
                await self.keys.release(state, success=False)
                if status in self.RETRYABLE and attempt + 1 < attempts:
                    last_error = raw.decode(errors="replace")
                    await asyncio.sleep(self.config.retry_base_seconds * (2**attempt))
                    continue
                return None, None, None, _openrouter_error_response(status, raw)
            return session, response, state, None
        # Loop exhausted (every key retried/cooling) or no key was available.
        # Prefer surfacing OpenRouter's OWN last error (real status + body) so the
        # client sees why — annotated with the cooldown hint when the pool is in
        # cooldown. Fall back to the generic 503 only when no upstream response
        # was ever seen (e.g. all keys were already cooling before the first try).
        if last_upstream_status is not None:
            return (
                None,
                None,
                None,
                _openrouter_error_response(
                    last_upstream_status,
                    last_upstream_body,
                    retry_after_seconds=retry_after_seconds,
                ),
            )
        return (
            None,
            None,
            None,
            JSONResponse(
                {"error": {"message": last_error, "type": "openrouter_upstream_error"}},
                status_code=503,
            ),
        )

    async def complete(self, path: str, payload: dict) -> Response:
        session, response, state, error = await self._open(path, payload, False)
        if error is not None:
            return error
        assert session is not None and response is not None and state is not None
        try:
            raw = await response.read()
            return Response(
                raw,
                status_code=response.status,
                media_type=response.headers.get("content-type", "application/json"),
            )
        finally:
            response.release()
            await session.close()
            await self.keys.release(state, success=True)

    async def chat_stream(
        self, payload: dict, public_model: str
    ) -> AsyncGenerator[str, None]:
        session, response, state, error = await self._open(
            "/chat/completions", payload, True
        )
        if error is not None:
            body = getattr(error, "body", b"")
            message = _openrouter_error_message(body)
            yield _chat_sse_data(
                {
                    "error": {
                        "message": message,
                        "type": "openrouter_stream_error",
                        "code": getattr(error, "status_code", None),
                    }
                }
            )
            yield _SSE_DONE_FRAME
            return
        assert session is not None and response is not None and state is not None
        assembler = OpenRouterItemAssembler(
            f"chatcmpl-or-{uuid.uuid4().hex}", int(time.time()), public_model
        )
        decoder = _OpenRouterSSEDecoder()
        saw_done = False
        clean = False
        try:
            iterator = response.content.iter_any().__aiter__()
            first = await asyncio.wait_for(
                iterator.__anext__(), timeout=self.config.first_event_timeout
            )
            chunks = [first]

            async def remaining():
                for initial in chunks:
                    yield initial
                async for value in iterator:
                    yield value

            async for raw_chunk in remaining():
                for payload_chunk in decoder.feed(raw_chunk):
                    if payload_chunk is None:
                        saw_done = True
                        break
                    events = assembler.push(payload_chunk)
                    for event in events:
                        if event.kind == "error":
                            message = (
                                event.payload.get("message")
                                if isinstance(event.payload, dict)
                                else str(event.payload)
                            )
                            yield _chat_sse_data(
                                {
                                    "id": assembler.completion_id,
                                    "object": "chat.completion.chunk",
                                    "created": assembler.created,
                                    "model": public_model,
                                    "choices": [
                                        {
                                            "index": 0,
                                            "delta": {},
                                            "finish_reason": "error",
                                        }
                                    ],
                                    "error": {
                                        "message": message or "OpenRouter stream error",
                                        "type": "openrouter_stream_error",
                                    },
                                }
                            )
                            yield _SSE_DONE_FRAME
                            return
                        frame = assembler.serialize(event)
                        if frame is not None:
                            yield _chat_sse_data(frame)
                if saw_done:
                    break
            yield _chat_sse_data(assembler.finalize())
            yield _SSE_DONE_FRAME
            clean = True
        except StopAsyncIteration:
            yield _chat_sse_data(assembler.finalize())
            yield _SSE_DONE_FRAME
            clean = True
        except (aiohttp.ClientError, asyncio.TimeoutError) as exc:
            yield _chat_sse_data(
                {
                    "id": assembler.completion_id,
                    "object": "chat.completion.chunk",
                    "created": assembler.created,
                    "model": public_model,
                    "choices": [{"index": 0, "delta": {}, "finish_reason": "error"}],
                    "error": {
                        "message": str(exc) or exc.__class__.__name__,
                        "type": "openrouter_stream_error",
                    },
                }
            )
            yield _SSE_DONE_FRAME
        finally:
            response.release()
            await session.close()
            await self.keys.release(state, success=clean)

    async def passthrough_stream(
        self, path: str, payload: dict
    ) -> AsyncGenerator[bytes, None]:
        session, response, state, error = await self._open(path, payload, True)
        if error is not None:
            yield getattr(error, "body", b"")
            return
        assert session is not None and response is not None and state is not None
        clean = False
        try:
            async for chunk in response.content.iter_any():
                if chunk:
                    yield chunk
            clean = True
        finally:
            response.release()
            await session.close()
            await self.keys.release(state, success=clean)


def _openrouter_request_payload(
    body: dict, messages: list | None, stream: bool
) -> dict:
    payload = {
        key: value
        for key, value in body.items()
        if key not in {"conversation_id", "new_conversation", "source"}
    }
    payload["model"] = _openrouter_upstream_model(str(body.get("model", "")))
    if messages is not None:
        payload["messages"] = messages
    payload["stream"] = stream
    return payload


def _openrouter_message_from_error_obj(error: dict) -> str:
    """Best human-readable message from an OpenRouter `error` object.

    OpenRouter frequently returns a terse top-level message like
    "Provider returned error" while the ACTUAL cause (rate limit, no credits,
    the upstream provider's own text) is nested in `error.metadata` — commonly
    `metadata.raw` (a string or JSON) plus `metadata.provider_name`. Surface
    those so the client sees why, not just "Provider returned error".
    """
    base = str(error.get("message") or "").strip()
    details: list[str] = []
    metadata = error.get("metadata")
    if isinstance(metadata, dict):
        provider = metadata.get("provider_name") or metadata.get("provider")
        raw = metadata.get("raw")
        raw_text = ""
        if isinstance(raw, (dict, list)):
            # The provider's raw error is sometimes itself a JSON object with a
            # nested message.
            if isinstance(raw, dict):
                nested = raw.get("error")
                if isinstance(nested, dict) and nested.get("message"):
                    raw_text = str(nested["message"])
                elif raw.get("message"):
                    raw_text = str(raw["message"])
            if not raw_text:
                try:
                    raw_text = json.dumps(raw, ensure_ascii=False)
                except Exception:
                    raw_text = str(raw)
        elif raw is not None:
            raw_text = str(raw).strip()
        if provider:
            details.append(f"provider={provider}")
        if raw_text and raw_text not in base:
            details.append(raw_text)
    code = error.get("code")
    if code is not None and str(code) not in base:
        details.append(f"code={code}")
    if base and details:
        return f"{base}: " + "; ".join(details)
    if details:
        return "; ".join(details)
    return base


def _openrouter_error_message(body: bytes) -> str:
    """Human-readable message from an OpenRouter error body.

    The body is usually OpenRouter's JSON ({"error": {"message": ...,
    "metadata": {...}}}); return the enriched message (including nested
    metadata detail) when present, else the decoded text, so the streamed
    error the client sees is OpenRouter's real explanation rather than a raw
    JSON blob or a generic placeholder.
    """
    if not body:
        return "OpenRouter stream failed"
    try:
        parsed = json.loads(body)
    except Exception:
        return body.decode(errors="replace") or "OpenRouter stream failed"
    if isinstance(parsed, dict):
        error = parsed.get("error")
        if isinstance(error, dict):
            message = _openrouter_message_from_error_obj(error)
            if message:
                return message
        if isinstance(error, str) and error:
            return error
        if parsed.get("message"):
            return str(parsed["message"])
    return body.decode(errors="replace") or "OpenRouter stream failed"


def _openrouter_error_response(
    status: int, raw: bytes, retry_after_seconds: float = 0.0
) -> JSONResponse:
    try:
        payload = json.loads(raw)
    except Exception:
        payload = {
            "error": {
                "message": raw.decode(errors="replace") or "OpenRouter error",
                "type": "openrouter_upstream_error",
            }
        }
    # Enrich the terse top-level message with nested metadata detail (provider,
    # raw provider error, code) so the client sees WHY, not just "Provider
    # returned error". When the pool is cooling down, also append the retry hint
    # (instead of replacing OpenRouter's own message with the generic no-key one).
    if isinstance(payload, dict):
        error = payload.get("error")
        if isinstance(error, dict):
            enriched = _openrouter_message_from_error_obj(error)
            if enriched:
                error["message"] = enriched
            if (
                retry_after_seconds
                and "retry in" not in str(error.get("message", "")).lower()
            ):
                error["message"] = (
                    f"{error.get('message') or 'OpenRouter error'} "
                    f"(all API keys are cooling down; "
                    f"retry in {retry_after_seconds:.0f}s)"
                )
    headers = (
        {"Retry-After": str(int(retry_after_seconds))} if retry_after_seconds else None
    )
    return JSONResponse(payload, status_code=status, headers=headers)


async def _direct_openrouter_chat_response(
    body: dict, messages: list, stream_mode: bool
):
    config = OpenRouterConfig.load()
    if not config.api_keys:
        return JSONResponse(
            {
                "error": {
                    "message": "VE_OPENROUTER_API_KEYS is not configured",
                    "type": "openrouter_config_error",
                }
            },
            status_code=503,
        )
    client = OpenRouterHTTPClient(config)
    payload = _openrouter_request_payload(body, messages, stream_mode)
    public_model = str(
        body.get("model") or f"{OPENROUTER_MODEL_PREFIX}{config.default_model}"
    )
    if not stream_mode:
        return await client.complete("/chat/completions", payload)
    return StreamingResponse(
        client.chat_stream(payload, public_model),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


async def _direct_openrouter_text_completion(body: dict, stream_mode: bool):
    config = OpenRouterConfig.load()
    if not config.api_keys:
        return JSONResponse(
            {
                "error": {
                    "message": "VE_OPENROUTER_API_KEYS is not configured",
                    "type": "openrouter_config_error",
                }
            },
            status_code=503,
        )
    client = OpenRouterHTTPClient(config)
    payload = _openrouter_request_payload(body, None, stream_mode)
    if not stream_mode:
        return await client.complete("/completions", payload)
    return StreamingResponse(
        client.passthrough_stream("/completions", payload),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


async def chat_api(request):
    """
    OpenAI-compatible /v1/chat/completions endpoint.
    Supports full SSE streaming when stream=true.
    Tool calling is enabled only when tools/tool_choice is supplied.
    Accepts JSON: { model, messages, tools, tool_choice, temperature, max_completion_tokens, max_tokens, stream }
    """
    try:
        body = await request.json()
        if not isinstance(body, dict):
            return JSONResponse(
                {"error": "JSON body must be an object"}, status_code=400
            )

        body = convert_legacy_functions(body)
        messages = body.get("messages", [])
        temperature = body.get("temperature", 0.7)
        top_p_val = body.get("top_p", 1.0)
        try:
            max_tokens = _resolve_chat_completion_max_tokens(body, default=500)
        except ValueError as exc:
            invalid_param = (
                "max_completion_tokens"
                if body.get("max_completion_tokens") is not None
                else "max_tokens"
            )
            return JSONResponse(
                {
                    "error": {
                        "message": str(exc),
                        "type": "invalid_request_error",
                        "param": invalid_param,
                        "code": None,
                    }
                },
                status_code=400,
            )

        stream_mode = body.get("stream", False) in (True, "true", "True", "1")

        try:
            enable_thinking = parse_optional_bool(
                body.get("enable_thinking"),
                default=False,
                field_name="enable_thinking",
            )
        except ValueError as exc:
            return JSONResponse(
                {"error": str(exc)},
                status_code=400,
            )

        thinking_budget = body.get("thinking_budget")

        if thinking_budget is not None:
            try:
                thinking_budget = int(thinking_budget)
            except (TypeError, ValueError):
                return JSONResponse(
                    {"error": ("thinking_budget must be an integer or null")},
                    status_code=400,
                )

        if not enable_thinking:
            thinking_budget = 0
        elif thinking_budget is not None and thinking_budget <= 0:
            thinking_budget = None

        stream_options = body.get("stream_options") or {}
        if stream_options and not stream_mode:
            return JSONResponse(
                {"error": "stream_options can only be used when stream=true"},
                status_code=400,
            )

        if not isinstance(stream_options, dict):
            return JSONResponse(
                {"error": "stream_options must be an object"},
                status_code=400,
            )

        include_stream_usage = bool(stream_options.get("include_usage", False))

        response_format = body.get("response_format")
        if response_format:
            messages, response_format_error = prepare_response_format_messages(
                messages,
                response_format,
            )
            if response_format_error:
                return JSONResponse({"error": response_format_error}, status_code=400)

        if not messages:
            return JSONResponse({"error": "No messages provided"}, status_code=400)

        parallel_tool_calls = body.get("parallel_tool_calls", True)

        if not isinstance(parallel_tool_calls, bool):
            return JSONResponse(
                {"error": "parallel_tool_calls must be a boolean"},
                status_code=400,
            )

        messages = apply_thinking_policy_to_messages(
            messages,
            enable_thinking=enable_thinking,
        )
        # Snapshot BEFORE normalize. Browser-backed providers (M365, Qwen,
        # Doubao, DeepSeek) parse multimodal content (image_url parts) natively,
        # but normalize_chat_messages_for_template json.dumps()-es any non-str
        # content into literal text for strict local MLX chat templates. Running
        # it first collapsed a pasted image into a giant JSON string, so the
        # browser vision path saw only text. Give browser providers the raw,
        # un-normalized messages; local models still use the normalized copy.
        browser_source_messages = messages
        messages = normalize_chat_messages_for_template(messages)
        requested_model = body.get("model", DEFAULT_LLM_ALIAS)

        # OpenRouter is a native HTTP upstream. Keep raw multimodal messages and
        # native OpenAI tool fields intact instead of applying the browser prompt
        # relay or local-model tool protocol.
        if _openrouter_is_model(requested_model):
            return await _direct_openrouter_chat_response(
                dict(body),
                list(browser_source_messages),
                stream_mode,
            )

        # Browser-backed models are plain chat providers. Route them before
        # OpenAI tool validation/instruction injection, stripping tool protocol
        # fields instead of rejecting an otherwise valid chat request.
        if requested_model in BROWSER_MODEL_ALIASES:
            # Keep the OpenAI tool-call fields for ANY browser model whose relay
            # policy advertises tool support (supports_tools=True), so the unified
            # relay can inject <tool_use_instructions> and intercept tool calls.
            if BROWSER_RELAY.policy_for(requested_model).supports_tools:
                browser_body, browser_messages = (
                    dict(body),
                    list(browser_source_messages),
                )
            else:
                browser_body, browser_messages = _sanitize_browser_chat_request(
                    body,
                    browser_source_messages,
                )
                if any(
                    key in body
                    for key in (
                        "tools",
                        "tool_choice",
                        "parallel_tool_calls",
                        "functions",
                        "function_call",
                    )
                ):
                    _http_log.info(
                        "Ignoring OpenAI tool-call fields for plain browser model %s",
                        requested_model,
                    )
            return await dispatch_browser_chat_model(
                requested_model,
                browser_body,
                browser_messages,
                stream_mode,
            )

        (
            tool_mode,
            tool_choice_mode,
            forced_tool_name,
            messages,
            allowed_tool_names,
            tool_error,
        ) = prepare_tool_call_messages(
            messages,
            body.get("tools"),
            body.get("tool_choice"),
            parallel_tool_calls=parallel_tool_calls,
        )

        if tool_error:
            return JSONResponse(
                {"error": tool_error},
                status_code=400,
            )

        messages = normalize_chat_messages_for_template(messages)

        err = reject_wrong_model_namespace(
            requested_model,
            expected_prefix="LLM:",
            endpoint_name="/v1/chat/completions",
        )

        if err:
            _http_log.warning(err)
            return JSONResponse({"error": err}, status_code=400)

        resolved_model = resolve_llm_model_name(requested_model)
        model_name = requested_model or DEFAULT_LLM_ALIAS

        if stream_mode:
            result_queue = queue.Queue(maxsize=32)

            stop_event = threading.Event()

            start_llm_worker()

            job = {
                "type": "stream",
                "model": resolved_model,
                "messages": messages,
                "max_tokens": max_tokens,
                "temperature": temperature,
                "top_p": top_p_val,
                "allow_tool_calls": tool_mode,
                "tool_choice_mode": tool_choice_mode,
                "forced_tool_name": forced_tool_name,
                "enable_thinking": enable_thinking,
                "thinking_budget": thinking_budget,
                "out_q": result_queue,
                "stop_event": stop_event,
                "source": body.get("source"),
            }

            try:
                log_memory_state("before tool-result LLM pass")
                _submit_llm_job(job)
                log_memory_state("after tool-result LLM pass")
            except LLMQueueFullError as exc:
                return JSONResponse(
                    {
                        "error": {
                            "message": str(exc),
                            "type": "server_busy",
                        }
                    },
                    status_code=503,
                    headers={
                        "Retry-After": "1",
                    },
                )

            except RuntimeError as exc:
                # 例如服务器正在关闭。
                return JSONResponse(
                    {
                        "error": {
                            "message": str(exc),
                            "type": "service_unavailable",
                        }
                    },
                    status_code=503,
                )

            async def stream_chat_completions():
                prompt_id = f"chatcmpl-{time.monotonic_ns()}"

                created = int(time.time())

                protocol_parser = ModelProtocolParser(
                    allowed_tools=allowed_tool_names,
                    tool_policy=tool_choice_mode,
                    forced_tool=(
                        forced_tool_name if tool_choice_mode == "forced" else None
                    ),
                    parallel_tool_calls=parallel_tool_calls,
                    expose_reasoning=enable_thinking,
                )

                eos_filter = StreamingStopFilter(CHAT_EOS_MARKERS)

                finish_reason = None
                role_sent = False
                parser_finalized = False

                def serialize_parser_events(
                    parser_events: Sequence[ParserEvent],
                ) -> list[str]:
                    """
                    Convert semantic parser events to OpenAI-compatible SSE chunks.

                    This function does not parse raw model text. It only converts
                    already-classified parser events into SSE output.
                    """
                    nonlocal role_sent

                    sse_events: list[str] = []

                    for event in parser_events:
                        # ====================================================
                        # Visible assistant content
                        # ====================================================
                        if event.kind == "content":
                            if not event.text:
                                continue

                            sse_events.append(
                                _make_chat_content_chunk(
                                    prompt_id=prompt_id,
                                    created=created,
                                    model_name=model_name,
                                    text=event.text,
                                    include_role=not role_sent,
                                )
                            )

                            role_sent = True
                            continue

                        # ====================================================
                        # Reasoning content
                        # ====================================================
                        if event.kind == "reasoning":
                            if not enable_thinking or not event.text:
                                continue

                            sse_events.append(
                                _make_chat_reasoning_chunk(
                                    prompt_id=prompt_id,
                                    created=created,
                                    model_name=model_name,
                                    text=event.text,
                                    include_role=not role_sent,
                                )
                            )

                            role_sent = True
                            continue

                        # ====================================================
                        # Start of an OpenAI tool call
                        # ====================================================
                        if event.kind == "tool_start":
                            if (
                                event.index is None
                                or not event.call_id
                                or not event.name
                            ):
                                _app_log.warning(
                                    "Ignoring invalid tool_start event: %r",
                                    event,
                                )
                                continue

                            sse_events.append(
                                _make_chat_tool_chunk(
                                    prompt_id=prompt_id,
                                    created=created,
                                    model_name=model_name,
                                    call_index=event.index,
                                    call_id=event.call_id,
                                    function_name=event.name,
                                    arguments_delta="",
                                    include_role=not role_sent,
                                )
                            )

                            role_sent = True
                            continue

                        # ====================================================
                        # OpenAI tool-call arguments
                        # ====================================================
                        if event.kind == "arguments_delta":
                            if event.index is None:
                                _app_log.warning(
                                    "Ignoring arguments event without an index: %r",
                                    event,
                                )
                                continue

                            sse_events.append(
                                _make_chat_tool_chunk(
                                    prompt_id=prompt_id,
                                    created=created,
                                    model_name=model_name,
                                    call_index=event.index,
                                    arguments_delta=event.text,
                                )
                            )

                            continue

                        # ====================================================
                        # End of a tool call
                        # ====================================================
                        if event.kind == "tool_end":
                            # OpenAI streaming does not require a separate tool_end
                            # chunk. The final response uses:
                            #
                            #     finish_reason = "tool_calls"
                            #
                            continue

                        # ====================================================
                        # Parser warnings stay in server logs
                        # ====================================================
                        if event.kind == "warning":
                            _app_log.warning(
                                "Model protocol parser warning: %s",
                                event.text,
                            )

                    return sse_events

                async def finalize_protocol_stream():
                    """Flush EOS and protocol-parser tails exactly once.

                    The old code only finalized from the worker's ``done`` item.
                    Local termination (EOS marker, parser error, disconnect) could
                    bypass ``eos_filter.finish()`` / ``protocol_parser.finish()``.
                    """
                    nonlocal parser_finalized
                    if parser_finalized:
                        return []
                    parser_finalized = True
                    output = []
                    eos_tail = eos_filter.finish()
                    if eos_tail:
                        output.extend(
                            serialize_parser_events(protocol_parser.feed(eos_tail))
                        )
                    output.extend(serialize_parser_events(protocol_parser.finish()))
                    return output

                try:
                    while True:
                        if SERVER_SHUTTING_DOWN.is_set():
                            _llm_log.info(
                                "HTTP chat stream ending because "
                                "server is shutting down"
                            )
                            stop_event.set()
                            return

                        if await request.is_disconnected():
                            _llm_log.info("Client disconnected, stopping generation")
                            stop_event.set()
                            return

                        try:
                            item = await asyncio.to_thread(
                                result_queue.get,
                                timeout=0.1,
                            )
                        except queue.Empty:
                            continue

                        if not isinstance(item, tuple):
                            continue

                        item_type = item[0]

                        payload = item[1] if len(item) > 1 else None

                        if item_type == "prompt":
                            continue

                        if item_type == "error":
                            yield _chat_sse_data(
                                {
                                    "error": {
                                        "message": str(payload),
                                        "type": "server_error",
                                    }
                                }
                            )

                            yield _SSE_DONE_FRAME
                            return

                        if item_type == "done":
                            worker_finish_reason = payload or "stop"

                            for sse_event in await finalize_protocol_stream():
                                yield sse_event

                            # ========================================================
                            # Decide OpenAI finish_reason
                            # ========================================================
                            if protocol_parser.error:
                                _llm_log.warning(
                                    "Protocol parser finished with error: %s",
                                    protocol_parser.error,
                                )

                                finish_reason = "stop"

                            elif protocol_parser.completed_calls > 0:
                                finish_reason = "tool_calls"

                            elif tool_choice_mode in (
                                "required",
                                "forced",
                            ):
                                # This normally also sets protocol_parser.error in
                                # protocol_parser.finish(), but keep the check explicit.
                                _llm_log.warning(
                                    "Model did not produce a valid required "
                                    "tool call: mode=%s",
                                    tool_choice_mode,
                                )

                                finish_reason = "stop"

                            elif worker_finish_reason in (
                                "stop",
                                "length",
                                "content_filter",
                            ):
                                finish_reason = worker_finish_reason

                            else:
                                finish_reason = "stop"

                            break

                        if item_type == "token_text":
                            token_text = str(payload or "")

                        elif item_type == "token":
                            gen_resp = payload

                            token_text = str(
                                getattr(
                                    gen_resp,
                                    "text",
                                    "",
                                )
                                or ""
                            )

                        else:
                            continue

                        if not token_text:
                            continue

                        # ============================================================
                        # Step 1: filter actual EOS markers
                        # ============================================================
                        #
                        # Do not call cut_at_llm_stop_marker() here.
                        #
                        # Its marker list contains tool-call markers, which would destroy
                        # a valid tool call before protocol_parser can parse it.
                        #
                        filtered_text, hit_eos = eos_filter.feed(token_text)

                        # ============================================================
                        # Step 2: parse channels, reasoning, content, and tool calls
                        # ============================================================
                        if filtered_text:
                            parser_events = protocol_parser.feed(filtered_text)

                            # ========================================================
                            # Step 3: convert parser events to OpenAI SSE
                            # ========================================================
                            for sse_event in serialize_parser_events(parser_events):
                                yield sse_event

                        # ============================================================
                        # Step 4: stop on fatal protocol errors
                        # ============================================================
                        if protocol_parser.error:
                            _llm_log.warning(
                                "Protocol parser stopped generation: %s",
                                protocol_parser.error,
                            )

                            finish_reason = "stop"
                            stop_event.set()
                            break

                        # ============================================================
                        # Step 5: stop when an actual EOS marker was reached
                        # ============================================================
                        if hit_eos:
                            finish_reason = "stop"
                            stop_event.set()
                            break

                    # Required for every local break path, not just worker done.
                    for sse_event in await finalize_protocol_stream():
                        yield sse_event

                    if protocol_parser.error:
                        finish_reason = "stop"
                    elif protocol_parser.completed_calls > 0:
                        finish_reason = "tool_calls"
                    elif finish_reason is None:
                        finish_reason = "stop"

                    yield _make_chat_finish_chunk(
                        prompt_id=prompt_id,
                        created=created,
                        model_name=model_name,
                        finish_reason=(finish_reason or "stop"),
                    )

                    if include_stream_usage:
                        usage_chunk = {
                            "id": prompt_id,
                            "object": "chat.completion.chunk",
                            "created": created,
                            "model": model_name,
                            "choices": [],
                            "usage": {
                                "prompt_tokens": 0,
                                "completion_tokens": 0,
                                "total_tokens": 0,
                            },
                        }

                        yield _chat_sse_data(usage_chunk)

                    yield _SSE_DONE_FRAME

                except asyncio.CancelledError:
                    stop_event.set()
                    raise

                finally:
                    stop_event.set()

                    try:
                        while True:
                            result_queue.get_nowait()
                    except queue.Empty:
                        pass

            return StreamingResponse(
                stream_chat_completions(),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                    "X-Accel-Buffering": "no",
                    "Access-Control-Allow-Origin": "*",
                },
            )

        # Non-streaming mode
        try:
            result = await asyncio.to_thread(
                _generate_llm_text_via_worker,
                messages=messages,
                model=resolved_model,
                max_tokens=max_tokens,
                temperature=temperature,
                top_p=top_p_val,
                clean_artifacts=not tool_mode,
                remove_reasoning=False,
                allow_tool_calls=tool_mode,
                enable_thinking=enable_thinking,
                thinking_budget=thinking_budget,
                source=body.get("source"),
            )

        except LLMQueueFullError as exc:
            return JSONResponse(
                {
                    "error": {
                        "message": str(exc),
                        "type": "server_busy",
                    }
                },
                status_code=503,
                headers={
                    "Retry-After": "1",
                },
            )

        if result is None:
            return JSONResponse({"error": "LLM generation failed"}, status_code=500)

        (
            tool_calls,
            content,
            reasoning_content,
            parse_error,
        ) = parse_complete_response(
            result,
            allowed_tools=allowed_tool_names,
            tool_policy=tool_choice_mode,
            forced_tool=(forced_tool_name if tool_choice_mode == "forced" else None),
            parallel_tool_calls=parallel_tool_calls,
            expose_reasoning=enable_thinking,
        )

        if parse_error:
            _http_log.warning(
                "Model response parse warning: %s",
                parse_error,
            )

        message = {"role": "assistant", "content": content}

        if tool_calls:
            message["tool_calls"] = tool_calls

        if enable_thinking and reasoning_content:
            message["reasoning_content"] = reasoning_content

        completion_id = f"chatcmpl-{time.time_ns()}"
        created = int(time.time())

        return JSONResponse(
            {
                "id": completion_id,
                "object": "chat.completion",
                "created": created,
                "model": model_name,
                "choices": [
                    {
                        "index": 0,
                        "message": message,
                        "finish_reason": "tool_calls" if tool_calls else "stop",
                    }
                ],
                "usage": {
                    "prompt_tokens": 0,
                    "completion_tokens": 0,
                    "total_tokens": 0,
                },
            }
        )

    except ClientDisconnect:
        _http_log.info("Chat API client disconnected")
        return Response(status_code=499)
    except asyncio.CancelledError:
        _http_log.info("Chat API cancelled during shutdown")
        raise
    except Exception as e:
        _http_log.error(f"Chat API error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


async def embeddings_api(request):
    try:
        body = await request.json()

        if not isinstance(body, dict):
            return JSONResponse(
                {"error": "JSON body must be an object"},
                status_code=400,
            )

        input_text = body.get("input")
        if not input_text:
            return JSONResponse({"error": "No input provided"}, status_code=400)

        if isinstance(input_text, str):
            texts = [input_text]
        elif isinstance(input_text, list):
            texts = [str(item) for item in input_text]
        else:
            return JSONResponse(
                {"error": "input must be a string or array"},
                status_code=400,
            )

        empty_indices = [index for index, text in enumerate(texts) if not text.strip()]

        if empty_indices:
            return JSONResponse(
                {
                    "error": (
                        "Embedding input contains empty text "
                        f"at indices: {empty_indices}"
                    )
                },
                status_code=400,
            )

        model = body.get("model") or EMBED_MODEL_ID

        err = reject_wrong_model_namespace(
            model,
            expected_prefix="embed:",
            endpoint_name="/v1/embeddings",
        )

        if err:
            _embedding_log.warning(err)
            return JSONResponse({"error": err}, status_code=400)

        try:
            dimensions = _parse_embedding_dimensions(body.get("dimensions"))
        except ValueError as exc:
            return JSONResponse({"error": str(exc)}, status_code=400)

        encoding_format = body.get("encoding_format", "float")
        if encoding_format not in ("float", "base64"):
            return JSONResponse(
                {"error": "encoding_format must be 'float' or 'base64'"},
                status_code=400,
            )

        (
            normalize_after_truncate,
            bool_error,
        ) = parse_bool_field(
            body,
            "normalize_after_truncate",
            default=EMBEDDING_TRUNCATE_NORMALIZE_DEFAULT,
        )
        if bool_error is not None:
            return bool_error

        try:
            vectors = await asyncio.to_thread(
                _submit_embed_job,
                texts,
                model,
                DEFAULT_EMBED_BATCH_SIZE,
            )

        except LLMQueueFullError as exc:
            return JSONResponse(
                {
                    "error": {
                        "message": str(exc),
                        "type": "server_busy",
                    }
                },
                status_code=503,
                headers={
                    "Retry-After": "1",
                },
            )

        if vectors is None:
            return JSONResponse({"error": "Embedding failed"}, status_code=500)

        try:
            vectors = _apply_embedding_dimensions(
                vectors,
                dimensions,
                normalize_after_truncate=normalize_after_truncate,
            )
        except ValueError as exc:
            return JSONResponse({"error": str(exc)}, status_code=400)

        try:
            data = [
                {
                    "object": "embedding",
                    "index": i,
                    "embedding": _encode_embedding_vector(vec, encoding_format),
                }
                for i, vec in enumerate(vectors)
            ]
        except ValueError as exc:
            return JSONResponse({"error": str(exc)}, status_code=400)

        return JSONResponse(
            {
                "object": "list",
                "model": model,
                "data": data,
                "usage": {
                    "prompt_tokens": 0,
                    "total_tokens": 0,
                },
            }
        )

    except ClientDisconnect:
        _embedding_log.info("Embeddings API client disconnected")
        return Response(status_code=499)

    except asyncio.CancelledError:
        _embedding_log.info("Embeddings API cancelled during shutdown")
        raise

    except Exception as e:
        _embedding_log.error(f"Embeddings API error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


async def rerank_api(request):
    try:
        body = await request.json()

        query = body.get("query", "")
        docs = body.get("documents", [])

        if not query:
            return JSONResponse({"error": "No query provided"}, status_code=400)

        if not docs:
            return JSONResponse({"error": "No documents provided"}, status_code=400)

        docs = [str(d) for d in docs]
        model = body.get("model") or RERANK_MODEL_ID

        err = reject_wrong_model_namespace(
            model,
            expected_prefix="rerank:",
            endpoint_name="/v1/rerank",
        )

        if err:
            _rerank_log.warning(err)
            return JSONResponse({"error": err}, status_code=400)

        try:
            payload = await asyncio.to_thread(
                _submit_rerank_job,
                query,
                docs,
                model,
                DEFAULT_RERANK_BATCH_SIZE,
            )

        except LLMQueueFullError as exc:
            return JSONResponse(
                {
                    "error": {
                        "message": str(exc),
                        "type": "server_busy",
                    }
                },
                status_code=503,
                headers={
                    "Retry-After": "1",
                },
            )

        if payload is None:
            return JSONResponse({"error": "Rerank failed"}, status_code=500)

        scores = payload["scores"]
        score_method = payload["score_method"]

        results = []

        for i, score in enumerate(scores):
            results.append(
                {
                    "index": i,
                    "score": float(score),
                    "document": docs[i],
                }
            )

        results.sort(key=lambda x: x["score"], reverse=True)

        return JSONResponse(
            {
                "model": model,
                "score_method": score_method,
                "results": results,
            }
        )

    except ClientDisconnect:
        _rerank_log.info("Rerank API client disconnected")
        return Response(status_code=499)
    except asyncio.CancelledError:
        _rerank_log.info("Rerank API cancelled during shutdown")
        raise
    except Exception as e:
        _rerank_log.error(f"Rerank API error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


def search_web_sync(
    query: str,
    n: int,
) -> list:
    """
    Search the web through Tavily and return bounded
    Continue ContextItem objects.

    Limits:
    - maximum result count;
    - maximum characters per result;
    - maximum characters across all result content.
    """
    query = str(query or "").strip()

    if not query:
        raise ValueError("Web search query must not be empty")

    try:
        n = int(n)

    except (TypeError, ValueError) as exc:
        raise ValueError("Web search result count must be an integer") from exc

    if n <= 0:
        raise ValueError("Web search result count must be greater than 0")

    n = min(
        n,
        TAVILY_MAX_RESULTS,
    )

    client = _get_tavily_client()

    _app_log.info(
        "[WEB SEARCH] Tavily request: query=%r max_results=%d",
        query,
        n,
    )

    search_kwargs = {
        "query": query,
        "search_depth": TAVILY_SEARCH_DEPTH,
        "topic": TAVILY_TOPIC,
        "max_results": n,
        "include_answer": False,
        "include_raw_content": False,
        "include_images": False,
        "timeout": 30,
    }

    # Advanced search may return multiple snippets for each source.
    # Keep it small to reduce tool-result and LLM context size.
    if TAVILY_SEARCH_DEPTH == "advanced":
        search_kwargs["chunks_per_source"] = 1

    log_memory_state("before Tavily")

    response = client.search(**search_kwargs)

    log_memory_state("after Tavily HTTP response")

    if not isinstance(response, dict):
        raise RuntimeError(
            f"Tavily returned an unexpected response type: {type(response).__name__}"
        )

    raw_results = response.get(
        "results",
        [],
    )

    if not isinstance(raw_results, list):
        raise RuntimeError("Tavily response.results is not an array")

    context_items = []
    total_content_chars = 0

    for index, item in enumerate(raw_results[:n]):
        if not isinstance(item, dict):
            continue

        title = str(item.get("title") or f"Search result {index + 1}").strip()

        url = str(item.get("url") or "").strip()

        # Do not fall back to raw_content. It is intentionally
        # disabled because complete page text can be very large.
        content = str(item.get("content") or "").strip()

        if not content:
            continue

        remaining_chars = TAVILY_MAX_TOTAL_CHARS - total_content_chars

        if remaining_chars <= 0:
            break

        allowed_chars = min(
            TAVILY_MAX_CHARS_PER_RESULT,
            remaining_chars,
        )

        if len(content) > allowed_chars:
            content = content[:allowed_chars].rstrip()

            truncation_marker = "\n[Search result truncated]"

            marker_space = TAVILY_MAX_TOTAL_CHARS - total_content_chars - len(content)

            if marker_space > 0:
                content += truncation_marker[:marker_space]

        if not content:
            continue

        total_content_chars += len(content)

        context_items.append(
            {
                "name": title[:300],
                "description": url[:2_000],
                "content": content,
            }
        )

    serialized_json = json.dumps(
        context_items,
        ensure_ascii=False,
    )

    serialized_chars = len(serialized_json)

    serialized_bytes = len(serialized_json.encode("utf-8"))

    _app_log.info(
        "[WEB SEARCH] Tavily completed: "
        "query=%r results=%d "
        "content_chars=%d "
        "json_chars=%d "
        "json_bytes=%d "
        "result_limit=%d "
        "total_char_limit=%d",
        query,
        len(context_items),
        total_content_chars,
        serialized_chars,
        serialized_bytes,
        TAVILY_MAX_RESULTS,
        TAVILY_MAX_TOTAL_CHARS,
    )

    # Remove references to the larger Tavily response before returning.
    del raw_results
    del response

    return context_items


async def web_search_api(request):
    """
    Local endpoint for Continue WebContextProvider.

    POST /web

    Request:
        {
            "query": "...",
            "n": 5
        }

    Response:
        [
            {
                "name": "...",
                "description": "...",
                "content": "..."
            }
        ]
    """
    try:
        body = await request.json()

        if not isinstance(body, dict):
            return JSONResponse(
                {"error": ("JSON body must be an object")},
                status_code=400,
            )

        query = str(body.get("query") or "").strip()

        if not query:
            return JSONResponse(
                {"error": ("query must not be empty")},
                status_code=400,
            )

        try:
            n = int(body.get("n", 5))
        except (TypeError, ValueError):
            return JSONResponse(
                {"error": ("n must be an integer")},
                status_code=400,
            )

        if n <= 0:
            return JSONResponse(
                {"error": ("n must be greater than 0")},
                status_code=400,
            )

        results = await asyncio.to_thread(
            search_web_sync,
            query,
            n,
        )

        # Continue expects ContextItem[] directly.
        return JSONResponse(results)

    except ClientDisconnect:
        _http_log.info("Web search client disconnected")
        return Response(status_code=499)

    except asyncio.CancelledError:
        _http_log.info("Web search request cancelled")
        raise

    except Exception as exc:
        _http_log.exception("Tavily web search failed")

        return JSONResponse(
            {
                "error": str(exc),
            },
            status_code=500,
        )


