def test_channel_name_split_across_chunks_does_not_leak():
    parser = ModelProtocolParser(
        allowed_tools=[
            "search_web",
        ],
        tool_policy="auto",
        expose_reasoning=False,
    )

    chunks = [
        "<|chan",
        "nel>tho",
        "ught The user is asking to search ",
        "the web for currently popular ",
        "compression algorithms.",
        "<chan",
        "nel|>",
        "Final visible answer.",
    ]

    events = []

    for chunk in chunks:
        events.extend(parser.feed(chunk))

    events.extend(parser.finish())

    visible_content = "".join(event.text for event in events if event.kind == "content")

    reasoning_content = "".join(
        event.text for event in events if event.kind == "reasoning"
    )

    assert visible_content == ("Final visible answer.")

    assert reasoning_content == ""
    assert parser.error is None


