def test_standard_json_tool_call_split_by_character():
    raw = (
        "<tool_call>"
        '{"name":"search_web",'
        '"arguments":{"query":"prime algorithms"}}'
        "</tool_call>"
    )

    parser = ModelProtocolParser(
        allowed_tools=[
            "search_web",
        ],
        tool_policy="auto",
    )

    events: list[ParserEvent] = []

    # 最严格的跨 chunk 测试：每个字符一个 chunk。
    for character in raw:
        events.extend(parser.feed(character))

    events.extend(parser.finish())

    assert parser.error is None
    assert parser.completed_calls == 1

    assert not any(event.kind == "content" for event in events)

    arguments_text = "".join(
        event.text for event in events if event.kind == "arguments_delta"
    )

    assert json.loads(arguments_text) == {"query": "prime algorithms"}


def test_native_tool_call_with_private_quote_tokens():
    parser = ModelProtocolParser(
        allowed_tools=[
            "search_web",
        ],
        tool_policy="auto",
    )

    chunks = [
        "<|tool_",
        "call>call:search_web{query:<|",
        '">current popular or latest ',
        "prime number finding algorithms",
        '<|">}<tool_',
        "call|>",
    ]

    events: list[ParserEvent] = []

    for chunk in chunks:
        events.extend(parser.feed(chunk))

    events.extend(parser.finish())

    assert parser.error is None
    assert parser.completed_calls == 1

    # Tool-call protocol must not leak into assistant content.
    content = "".join(event.text for event in events if event.kind == "content")

    assert content == ""

    tool_start_events = [event for event in events if event.kind == "tool_start"]

    assert len(tool_start_events) == 1

    assert tool_start_events[0].name == "search_web"

    argument_events = [event for event in events if event.kind == "arguments_delta"]

    assert len(argument_events) == 1

    parsed_arguments = json.loads(argument_events[0].text)

    assert parsed_arguments == {
        "query": ("current popular or latest prime number finding algorithms")
    }


