def test_chunk_text():
    samples = [
        "短文本",
        "Hello. World. This is a test.",
        "这是一个很长的中文句子。" * 100,
        "A" * 1000,
        "第一段\n第二段\n第三段",
    ]

    for sample in samples:
        result = chunk_text(
            sample,
            max_length=100,
        )

        assert result

        assert all(chunk.strip() for chunk in result)

        assert all(len(chunk) <= 100 for chunk in result), [
            len(chunk) for chunk in result
        ]


def test_question_recording_single_escape_skips():
    generation = _begin_question_recording_session()

    try:
        assert _handle_escape_during_question_recording()

        time.sleep(ESC_DOUBLE_TAP_WINDOW + 0.1)

        assert QUESTION_RECORDING_SKIP.is_set()
        assert not QUESTION_RECORDING_CANCEL_ALL.is_set()

    finally:
        _end_question_recording_session(generation)


def test_question_recording_double_escape_cancels_all():
    generation = _begin_question_recording_session()

    try:
        assert _handle_escape_during_question_recording()

        time.sleep(0.05)

        assert _handle_escape_during_question_recording()

        assert QUESTION_RECORDING_CANCEL_ALL.is_set()
        assert not QUESTION_RECORDING_SKIP.is_set()

        time.sleep(ESC_DOUBLE_TAP_WINDOW + 0.1)

        # Pending single-ESC timer must remain cancelled.
        assert not QUESTION_RECORDING_SKIP.is_set()

    finally:
        _end_question_recording_session(generation)


