def test_prequeue_partial_downgrades_only_completed():
    completed = LocalPlaybackResult(
        status=TTSPlaybackStatus.COMPLETED,
    )

    failed = LocalPlaybackResult(
        status=TTSPlaybackStatus.FAILED,
        error_code="playback_failed",
        error="playback failed",
    )

    prequeue_partial = {
        "error_code": ("tts_intermediate_chunk_dropped"),
        "error": ("Intermediate chunk dropped"),
        "dropped_chunks": 1,
        "enqueued_chunks": 2,
    }

    assert completed.status is TTSPlaybackStatus.COMPLETED
    assert prequeue_partial["error_code"] == "tts_intermediate_chunk_dropped"
    assert prequeue_partial["dropped_chunks"] == 1
    assert prequeue_partial["enqueued_chunks"] == 2

    assert failed.status is TTSPlaybackStatus.FAILED


