def test_deepseek_minus_one_fragment_targets_current_last_fragment():
    fragments = {0: {"type": "content", "content": "现在是"}}
    wire_index = -1
    resolved_index = max(fragments) if wire_index == -1 and fragments else wire_index
    fragments.setdefault(resolved_index, {"type": "content", "content": ""})[
        "content"
    ] += "2026年7月25日，星期六，17:04:29（北京时间）。"
    emitted = "".join(fragments[index]["content"] for index in sorted(fragments))
    assert emitted == ("现在是2026年7月25日，星期六，17:04:29（北京时间）。")


