def test_doubao_tool_fields_are_ignored_for_plain_chat():
    body = {
        "model": "LLM:doubao",
        "tools": [{"type": "function", "function": {"name": "search"}}],
        "tool_choice": "auto",
        "parallel_tool_calls": True,
        "conversation_id": "conv-1",
    }
    messages = [
        {"role": "system", "content": "Be concise"},
        {"role": "assistant", "content": "", "tool_calls": [{"id": "x"}]},
        {"role": "tool", "tool_call_id": "x", "content": "tool output"},
        {"role": "user", "content": "hello"},
    ]
    clean_body, clean_messages = _sanitize_browser_chat_request(body, messages)
    assert "tools" not in clean_body
    assert "tool_choice" not in clean_body
    assert "parallel_tool_calls" not in clean_body
    assert clean_body["conversation_id"] == "conv-1"
    assert all(message.get("role") != "tool" for message in clean_messages)
    assert all("tool_calls" not in message for message in clean_messages)
    assert clean_messages[-1] == {"role": "user", "content": "hello"}


