def test_chat_max_completion_tokens_precedence_and_validation():
    assert _resolve_chat_completion_max_tokens({}) == 500
    assert _resolve_chat_completion_max_tokens({"max_tokens": 700}) == 700
    assert (
        _resolve_chat_completion_max_tokens(
            {"max_tokens": 700, "max_completion_tokens": 900}
        )
        == 900
    )
    assert (
        _resolve_chat_completion_max_tokens(
            {"max_tokens": 700, "max_completion_tokens": None}
        )
        == 700
    )

    for invalid in (0, -1, "not-an-integer"):
        try:
            _resolve_chat_completion_max_tokens({"max_completion_tokens": invalid})
        except ValueError:
            pass
        else:
            raise AssertionError("invalid max_completion_tokens value was accepted")

    # max_output_tokens belongs to /v1/responses and is not a Chat
    # Completions alias. Until that endpoint exists, it must not affect this
    # route's output budget.
    assert _resolve_chat_completion_max_tokens({"max_output_tokens": 1234}) == 500


def test_doubao_stream_does_not_retry_after_commit():
    async def scenario():
        client = object.__new__(DoubaoClient)
        calls = 0

        def chat_stream(
            text: str,
            bot_id: str = "",
            conversation_id: str = "",
            exclude_accounts: Optional[set] = None,
        ) -> AsyncGenerator[dict, None]:
            del text, bot_id, conversation_id, exclude_accounts
            nonlocal calls
            calls += 1

            async def events():
                yield {"type": "delta", "content": "partial"}
                yield {
                    "type": "error",
                    "message": "connection lost",
                    "retryable": True,
                }

            return events()

        cast(Any, client).chat_stream = chat_stream
        events = [
            event
            async for event in client.stream_with_retry(
                text="hello",
                max_retries=3,
            )
        ]
        assert calls == 1
        assert events[0] == {"type": "delta", "content": "partial"}
        assert events[-1]["type"] == "error"

    asyncio.run(scenario())


