def test_doubao_stream_retry_is_bounded():
    async def scenario():
        client = object.__new__(DoubaoClient)
        calls = 0

        def chat_stream(
            text: str,
            bot_id: str = "",
            conversation_id: str = "",
            exclude_accounts: Optional[set] = None,
        ) -> AsyncGenerator[dict, None]:
            del text, bot_id, conversation_id, exclude_accounts
            nonlocal calls
            calls += 1

            async def events():
                yield {
                    "type": "error",
                    "message": "temporary failure",
                    "retryable": True,
                }

            return events()

        cast(Any, client).chat_stream = chat_stream
        original_sleep = asyncio.sleep

        async def no_delay(seconds: float):
            del seconds

        asyncio.sleep = no_delay
        try:
            events = [
                event
                async for event in client.stream_with_retry(
                    text="hello",
                    max_retries=3,
                )
            ]
        finally:
            asyncio.sleep = original_sleep

        assert calls == 3
        assert len(events) == 1
        assert events[0]["type"] == "error"
        assert events[0]["retryable"] is True

    asyncio.run(scenario())


def test_doubao_runtime_forwards_retrying_stream_events():
    async def scenario():
        runtime = DoubaoRuntime()
        calls = []

        async def initialized():
            return None

        class FakeClient:
            async def stream_with_retry(
                self,
                text: str,
                bot_id: str = "",
                conversation_id: str = "",
                max_retries: Optional[int] = None,
            ) -> AsyncGenerator[dict, None]:
                calls.append(
                    {
                        "text": text,
                        "bot_id": bot_id,
                        "conversation_id": conversation_id,
                        "max_retries": max_retries,
                    }
                )
                yield {"type": "delta", "content": "hello"}
                yield {"type": "done"}

        runtime._initialize = initialized
        runtime._client = cast(DoubaoClient, FakeClient())
        output_queue = queue.Queue()
        await runtime._chat_stream("question", "conversation-1", output_queue)

        output = []
        while not output_queue.empty():
            output.append(output_queue.get_nowait())

        assert calls == [
            {
                "text": "question",
                "bot_id": DOUBAO_DEFAULT_BOT_ID,
                "conversation_id": "conversation-1",
                "max_retries": DOUBAO_STREAM_MAX_RETRIES,
            }
        ]
        assert output == [
            {"type": "delta", "content": "hello"},
            {"type": "done"},
        ]

    asyncio.run(scenario())


