def test_doubao_runtime_exception_emits_only_error_terminal():
    async def scenario():
        runtime = DoubaoRuntime()

        async def initialized():
            return None

        class FakeClient:
            async def stream_with_retry(
                self,
                text: str,
                bot_id: str = "",
                conversation_id: str = "",
                max_retries: Optional[int] = None,
            ) -> AsyncGenerator[dict, None]:
                del bot_id, conversation_id, max_retries
                if text == "question":
                    raise RuntimeError("upstream exploded")
                yield {"type": "done"}

        runtime._initialize = initialized
        runtime._client = cast(DoubaoClient, FakeClient())
        output_queue = queue.Queue()
        await runtime._chat_stream("question", "", output_queue)

        output = []
        while not output_queue.empty():
            output.append(output_queue.get_nowait())

        assert len(output) == 1
        assert output[0]["type"] == "error"
        assert output[0]["source"] == "runtime"
        assert "upstream exploded" in output[0]["message"]

    asyncio.run(scenario())


