def test_stale_recovery_is_limited_to_automatic_restore():
    def allowed(restored_id, explicit_id, explicit_new, visible, attempted):
        return bool(
            restored_id
            and not explicit_id
            and not explicit_new
            and not visible
            and not attempted
        )

    assert allowed("old", "", False, False, False) is True
    assert allowed("old", "explicit", False, False, False) is False
    assert allowed("old", "", True, False, False) is False
    assert allowed("old", "", False, True, False) is False
    assert allowed("old", "", False, False, True) is False


