def test_doubao_engine_stale_error_survives_to_recovery_flag():
    # End-to-end guard for the exact bug that a broad ``except Exception`` in the
    # engine used to flatten DoubaoStaleConversationError into a status=0 error
    # dict (then a type-erased DoubaoHTTPError), so chat_stream never tagged the
    # recovery flag. This drives the REAL chat_stream + _stream_sse + except
    # logic; only the engine/account_pool/session_store are stubbed.
    async def scenario():
        class FakeSession:
            def __init__(self):
                self.session_id = "s1"
                self.account_sessionid = ""
                self.conversation_id = ""
                self.last_message_index = 0

        class FakeAccount:
            sessionid = "acc1"

        session = FakeSession()
        acc = FakeAccount()

        class FakeSessionStore:
            def get_or_create_session(self, bot_id, conversation_id):
                return session

            def get_session(self, session_id):
                return session

            def build_full_payload(self, session_id, text):
                return {"client_meta": {"last_message_index": 0}}

        class FakeAccountPool:
            def __init__(self):
                self.released = 0

            async def acquire_wait(self, wait_seconds=0, exclude=None):
                return acc

            async def pace_request(self, account):
                return None

            def release(self, account):
                self.released += 1

        class FakeEngine:
            async def fetch_chat_stream(
                self, sessionid, request_body, conversation_id=""
            ):
                # The navigation guard raises this typed error deep in the
                # engine. It must reach chat_stream with its type intact.
                raise DoubaoStaleConversationError("s1", "/chat", "/chat/s1")
                yield {}  # pragma: no cover - makes this an async generator

        client = object.__new__(DoubaoClient)
        pool = FakeAccountPool()
        cast(Any, client).engine = FakeEngine()
        cast(Any, client).account_pool = pool
        cast(Any, client).session_store = FakeSessionStore()

        events = [event async for event in client.chat_stream(text="hi")]

        error_events = [e for e in events if e.get("type") == "error"]
        assert len(error_events) == 1, events
        err = error_events[0]
        # The whole point: the typed stale signal survived end-to-end.
        assert err.get("stale_conversation") is True
        assert err.get("error_type") == "doubao_stale_conversation"
        assert err.get("retryable") is False
        # Account ownership is released exactly once even on the error path.
        assert pool.released == 1

    asyncio.run(scenario())


def test_qwen_stale_redirect_probe_detects_root_landing():
    # A deleted Qwen conversation loads /c/<id>, its stream ends without a
    # finished answer, and the SPA then redirects to the site root. The probe
    # must poll the settled path, detect the root landing, and return the
    # deterministic stale signal for the exact conversation. Any other landing
    # (still on the conversation route, or a genuine failure with no redirect)
    # must return None so a real error is not misclassified as stale.
    class FakePage:
        def __init__(self, path_sequence):
            # A list of pathnames returned on successive evaluate() calls,
            # simulating the redirect that completes after a short delay.
            self._paths = list(path_sequence)
            self.url = "https://chat.qwen.ai" + self._paths[0]

        async def evaluate(self, script, *args):
            value = self._paths[0]
            if len(self._paths) > 1:
                self._paths.pop(0)
            self.url = "https://chat.qwen.ai" + value
            return value

        async def wait_for_timeout(self, ms):
            return None

    runtime = object.__new__(QwenBrowserRuntime)

    async def scenario():
        # Redirect completes on the 3rd poll: /c/id -> /c/id -> / .
        delayed = FakePage(["/c/b17a965b", "/c/b17a965b", "/"])
        stale = await runtime._qwen_stale_redirect(delayed, "b17a965b", 5.0)
        assert isinstance(stale, BrowserStaleConversationError)
        assert stale.provider == "qwen"
        assert stale.conversation_id == "b17a965b"
        assert stale.expected_path == "/c/b17a965b"

        # Never redirects (stays on the conversation route) -> genuine error.
        stuck = FakePage(["/c/b17a965b"])
        assert await runtime._qwen_stale_redirect(stuck, "b17a965b", 1.0) is None

        # No known conversation id -> cannot be a stale conversation.
        assert await runtime._qwen_stale_redirect(FakePage(["/"]), "", 1.0) is None

    asyncio.run(scenario())


def test_m365_strip_cite_final_strips_truncated_refid_cite_only():
    # REGRESSION: a truncated citation tag on the AUTHORITATIVE terminal frame
    # (final=True) — e.g. "<cite>turn69file21</c" (open complete, REFID present,
    # partial close) — used to leak verbatim into the visible answer, because
    # final mode deliberately does not hold back tails. The narrow fix strips a
    # trailing UNCLOSED cite ONLY when a REFID is present (unambiguously a broken
    # citation the stream can never complete post-terminal), while still
    # preserving a bare literal "<cite>" (no REFID) and ambiguous single tail
    # chars like "!"/"<" so no real answer text is ever eaten.
    s = _m365_strip_cite
    # (a) truncated REFID-bearing cite is stripped at terminal, at several
    # partial-close stages.
    assert s("正文<cite>turn69file21</c", final=True) == "正文"
    assert s("正文<cite>turn1file1", final=True) == "正文"
    assert s("正文<cite>abc</", final=True) == "正文"
    # (b) a bare literal <cite> (no REFID after) is preserved — the deliberate
    # "literal <cite> not mis-deleted" guarantee.
    assert s("看 <cite> 标签", final=True) == "看 <cite> 标签"
    assert s("这是 <cite>", final=True) == "这是 <cite>"
    # (c) ambiguous trailing chars that final mode must NOT eat.
    assert s("完成!", final=True) == "完成!"
    assert s("a<", final=True) == "a<"
    # (d) no regression on the three complete citation encodings.
    assert s("a\ue200x\ue201b", final=True) == "ab"
    assert s("a<cite>turn1file1</cite>b", final=True) == "ab"
    assert s("a【1-turn1file1】b", final=True) == "ab"
    assert s("【重要】提示", final=True) == "【重要】提示"
    # (e) streaming mode already held back partial cites; unchanged.
    assert s("正文<cite>turn1</c", final=False) == "正文"
    assert s("正文<cite>", final=False) == "正文"


def test_m365_strip_cite_keeps_markdown_links_and_code_literal():
    # Markdown is display text, not a citation transport. A URL may take many
    # snapshots to complete; therefore no stage may hold or delete it.
    def emulate(cumulative_frames, final_text):
        # Mirror the relay's append-only prefix rule over cumulative snapshots.
        best = ""
        dropped = 0
        for frame in cumulative_frames:
            norm = _m365_strip_cite(frame, final=False)
            if len(norm) > len(best) and norm.startswith(best):
                best = norm
            elif norm and norm != best and not best.startswith(norm):
                dropped += 1
        final_norm = _m365_strip_cite(final_text, final=True)
        if len(final_norm) > len(best) and final_norm.startswith(best):
            best = final_norm
        elif (
            final_norm
            and final_norm != best
            and not final_norm.startswith(best)
            and not best.startswith(final_norm)
        ):
            dropped += 1
        return best, dropped

    def cumulative(text):
        return [text[:i] for i in range(1, len(text) + 1)]

    # Download/citation-shaped links are also visible text and stream normally.
    sp_link = "[voice_edge.py](https://x.sharepoint.com/a/voice_edge.py?csf=1&web=1)"
    assert _m365_strip_cite(sp_link, final=True) == sp_link
    ams_link = (
        "[voice_edge.py](https://us-prod.asyncgw.teams.microsoft.com/v1/objects/"
        "0-eus-d6-x/views/original/voice_edge.py)"
    )
    assert _m365_strip_cite(ams_link, final=True) == ams_link
    # Normal links, images, and code brackets are preserved.
    normal = "见 [示例](https://example.com/page) 说明"
    assert _m365_strip_cite(normal, final=True) == normal
    sp_plain = "[site](https://x.sharepoint.com/sites/foo)"
    assert _m365_strip_cite(sp_plain, final=True) == sp_plain
    # Every character of two links and the subsequent heading is streamable.
    stream_full = (
        "文件在这:[voice_edge.py](https://x.sharepoint.com/a.py?csf=1&web=1) 和 "
        "[content-m365.js](https://x.sharepoint.com/b.js?csf=1&web=1)。\n\n## 尾巴正文"
    )
    final = stream_full
    best, dropped = emulate(cumulative(stream_full), final)
    assert dropped == 0, dropped
    assert "## 尾巴正文" in best
    # char-by-char: a normal link and code brackets stream losslessly.
    best_n, dropped_n = emulate(cumulative(normal), normal)
    assert best_n == normal and dropped_n == 0
    code = "取 messages[0] 与 arr[i]，列表 [1,2,3]\n结束"
    best_c, dropped_c = emulate(cumulative(code), code)
    assert best_c == code and dropped_c == 0
    # no regression: the existing three citation encodings still delete, and a
    # literal <cite> / Chinese 【重要】 are never mis-deleted.
    assert _m365_strip_cite("a\ue200x\ue201b", final=True) == "ab"
    assert _m365_strip_cite("a<cite>turn1file1</cite>b", final=True) == "ab"
    assert _m365_strip_cite("a【1-turn1file1】b", final=True) == "ab"
    assert (
        _m365_strip_cite("看 <cite> 和 【重要】提示", final=True)
        == "看 <cite> 和 【重要】提示"
    )


def test_m365_markdown_fixture_snapshots_are_monotonic():
    """The regression fixtures must never make the relay reject a snapshot."""
    fixture_dir = Path(__file__).with_name("tests")
    for fixture in sorted(fixture_dir.glob("*.md")):
        source = fixture.read_text(encoding="utf-8")
        best = ""
        for offset in range(1, len(source) + 1):
            current = _m365_strip_cite(source[:offset], final=False)
            assert current.startswith(best), (
                fixture.name,
                offset,
                best[-80:],
                current[-80:],
            )
            best = current
        final = _m365_strip_cite(source, final=True)
        assert final.startswith(best), fixture.name
        assert "##" in final, fixture.name

    literal = "`<cite>sample-file</cite> 【1-sample-file】 [x](https://x.invalid)`"
    assert _m365_strip_cite(literal, final=True) == literal


def test_m365_stream_pinned_rewrite_frames_stay_monotonic():
    """JS 稳定器钉版后的发出流，经 _m365_strip_cite 必须前缀单调、零丢弃。

    回归场景（tests/test-m365-stream.js 的 Python 侧镜像）：M365 把下载链接的
    临时 URL 原地改写成正式 URL、把【N-x】占位符原地解析为私有区形态；JS 钉版
    保留首发字节，Python 只见前缀一致的累计快照。任何一帧 non-prefix 都会触发
    relay 丢弃 = 正文被吞（"卡在第一个下载链接"的生产 bug）。
    """
    temp = (
        "正文开始\n\n## 下载\n\n"
        "- [下载 报告](https://h.asyncgw.test/v1/objects/temp-a)\n"
        "- [下载 数据](https://h.asyncgw.test/v1/objects/temp-b)\n\n"
        "## xxx\n\n下载后的正文。【1-turn1file1】继续。\n"
    )
    # 钉版后的发出流 = temp 的逐字符前缀（URL 改写被 JS 钉版吸收，保持首发形态）
    best = ""
    stall = 0
    for i in range(1, len(temp) + 1):
        cur = _m365_strip_cite(temp[:i], final=False)
        assert cur.startswith(best), (i, best[-40:], cur[-40:])
        stall = stall + 1 if len(cur) == len(best) else 0
        assert stall <= 40, ("hold window too large", i, stall)
        best = cur
    final = _m365_strip_cite(temp, final=True)
    assert final.startswith(best)
    best = final
    # 占位符被删除；AMS 链接原样保留；## xxx 与尾部正文全量送达
    assert "【1-turn1file1】" not in best
    assert best.endswith("继续。\n")
    assert "## xxx" in best and "temp-a" in best and "temp-b" in best
    # 巨型跨度回归：散文里孤零零的 "【1-" 不得与跨行后真正的 【N-x】 拼成
    # 巨型占位符被整体删除（引用编码恒为单行）。
    assert _m365_strip_cite("【1-\n\n正文【1-x】尾", final=False) == "【1-\n\n正文尾"


