def _parse_mi_list_cli(argv: list[str]) -> Optional[tuple[str, bool, int]]:
    if "--mi-list" not in argv:
        return None
    index = argv.index("--mi-list")
    values = argv[index + 1 :]
    if any(value.startswith("--") for value in values):
        raise ValueError("--mi-list must be the final command-line option")
    if len(values) > 3:
        raise ValueError(
            "Usage: --mi-list [name_keyword|full] "
            "[getVirtualModel=false|true] [getHuamiDevices=0|1]"
        )
    keyword = values[0].strip() if values else ""
    virtual_text = values[1].strip().lower() if len(values) > 1 else "false"
    huami_text = values[2].strip() if len(values) > 2 else "0"
    if virtual_text not in ("false", "true"):
        raise ValueError("getVirtualModel must be false or true")
    if huami_text not in ("0", "1"):
        raise ValueError("getHuamiDevices must be 0 or 1")
    return keyword, virtual_text == "true", int(huami_text)


async def _run_mi_list_cli(
    name_keyword: str, get_virtual_model: bool, get_huami_devices: int
) -> int:
    token_path = Path.home() / ".mi.token"
    timeout = aiohttp.ClientTimeout(total=30, connect=10, sock_read=20)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        account = EmbeddedMiAccount(
            session,
            os.getenv("MI_USER", "").strip(),
            os.getenv("MI_PASS", "").strip(),
            token_path,
            otp_callback=_xiaoai_otp_input,
        )
        if not account.has_service_token("xiaomiio"):
            if not account.username or not account._password:
                raise RuntimeError(
                    "No cached xiaomiio token in ~/.mi.token; set MI_USER and MI_PASS once"
                )
            if not await account.login("xiaomiio"):
                raise RuntimeError(
                    account.login_error or "Xiaomi xiaomiio login failed"
                )
        service = XiaoAIMiIOClient(
            account, region=os.getenv("MI_REGION", "cn").strip().lower()
        )
        devices = await service.device_list(
            get_virtual_model=get_virtual_model,
            get_huami_devices=get_huami_devices,
        )
        full = name_keyword.casefold() == "full"
        keyword = "" if full else name_keyword.casefold()
        selected = [
            d
            for d in devices
            if not keyword or keyword in str(d.get("name", "")).casefold()
        ]
        output = []
        for device in selected:
            item = (
                dict(device)
                if full
                else {
                    key: device.get(key)
                    for key in ("name", "did", "mac", "localip", "token", "model")
                    if device.get(key) not in (None, "")
                }
            )
            did = str(device.get("did") or "")
            if did.startswith("blt."):
                try:
                    beacon_key = await service.beacon_key(did)
                except Exception as exc:
                    item["ble_key_error"] = str(exc)
                else:
                    if beacon_key:
                        item["ble_key"] = beacon_key
            output.append(item)
        print(json.dumps(output, ensure_ascii=False, indent=2))
        return 0


# Top-level entries that belong to the Hugging Face hub layout itself and must
# never be swept into a snapshot directory during reorganization.
_HF_HUB_RESERVED_ENTRIES = frozenset({"trees", "blobs", "refs", "snapshots"})


def _hf_cache_home() -> Path:
    """Return the Hugging Face cache home, mirroring huggingface_hub resolution.

    Honors ``HF_HOME`` when set and otherwise falls back to ``~/.cache/huggingface``.
    """

    hf_home = os.environ.get("HF_HOME", "").strip()
    if hf_home:
        return Path(hf_home).expanduser()
    return Path.home() / ".cache" / "huggingface"


def _resolve_hf_head_revision(model_name: str) -> str:
    """Resolve the remote HEAD commit hash for a HF repo via ``huggingface_hub.HfApi``.

    An access token is read from the usual environment variable when present so
    private repos resolve, without a token the request is made anonymously.
    """

    try:
        from huggingface_hub import HfApi
    except ImportError as exc:
        raise RuntimeError(
            "huggingface_hub is required to resolve the Hugging Face HEAD revision; "
            "install it with 'pip install huggingface_hub'"
        ) from exc

    token = os.environ.get("HUGGINGFACEHUB_API_TOKEN", "").strip() or None

    try:
        info = HfApi(token=token).model_info(model_name)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to resolve Hugging Face HEAD for {model_name}: {exc}"
        ) from exc

    revision = str(getattr(info, "sha", "") or "").strip()
    if not revision:
        raise RuntimeError(f"Failed to resolve Hugging Face HEAD for {model_name}")
    return revision


def _move_into_snapshot(entry: Path, snapshot_dir: Path) -> None:
    """Move one top-level entry into ``snapshot_dir`` (GNU ``gmv -t`` equivalent).

    Any pre-existing target with the same name (e.g. from an interrupted prior
    run) is removed first so the freshly downloaded copy wins, and the move stays
    within the same hub directory so it is a cheap rename on the same filesystem.
    """

    target = snapshot_dir / entry.name
    if target.is_symlink() or target.is_file():
        target.unlink()
    elif target.is_dir():
        shutil.rmtree(target)
    shutil.move(str(entry), str(target))


def _download_modelscope_into_hf_cache(model_name: str) -> int:
    """Download a repo via the ModelScope Python API and lay it out as an HF hub snapshot.

    It resolves the HF HEAD revision, short-circuits when a valid snapshot already exists,
    downloads with ``modelscope.hub.snapshot_download. snapshot_download(model_name,
    local_dir=<hub_dir>)``, then reorganizes the flat download into
    ``<hub_dir>/snapshots/<revision>`` and writes ``<hub_dir>/refs/main``.
    Returns a process exit code.
    """

    model_name = str(model_name or "").strip()
    if not model_name or model_name.startswith("-") or "/" not in model_name:
        print(
            f"--modelscope requires a repo id like 'org/model', got: {model_name!r}",
            file=sys.stderr,
        )
        return 2

    hf_dir = _hf_cache_home() / "hub" / f"models--{model_name.replace('/', '--')}"

    revision = _resolve_hf_head_revision(model_name)
    snapshot_dir = hf_dir / "snapshots" / revision
    refs_main = hf_dir / "refs" / "main"

    # Skip re-downloading when refs/main already points at this revision and the
    # snapshot directory looks complete (config.json present).
    if refs_main.is_file():
        existing = refs_main.read_text(encoding="utf-8", errors="ignore").strip()
        if (
            existing
            and existing == revision
            and snapshot_dir.is_dir()
            and (snapshot_dir / "config.json").is_file()
        ):
            print(f"Existing valid snapshot: {revision}")
            return 0

    print(f"Downloading {model_name} from ModelScope into {hf_dir} ...")

    try:
        from modelscope_hub import HubApi
    except ImportError as exc:
        raise RuntimeError(
            "modelscope-hub is not installed; install it with 'pip install modelscope-hub'"
        ) from exc

    token = os.environ.get("MODELSCOPE_API_TOKEN", "").strip() or None

    try:
        api = HubApi(token=token)
        api.download_repo(model_name, repo_type="model", local_dir=str(hf_dir))
    except Exception as exc:
        raise RuntimeError(
            f"modelscope download failed for {model_name}: {exc}"
        ) from exc

    # Reorganize the flat download into the HF hub snapshot layout.
    snapshot_dir.mkdir(parents=True, exist_ok=True)
    for entry in list(hf_dir.iterdir()):
        if entry.name in _HF_HUB_RESERVED_ENTRIES:
            continue
        _move_into_snapshot(entry, snapshot_dir)

    refs_main.parent.mkdir(parents=True, exist_ok=True)
    refs_main.write_text(revision, encoding="utf-8")

    print(f"Prepared Hugging Face snapshot: {snapshot_dir}")
    print(f"refs/main -> {revision}")
    return 0


def _run_modelscope_from_argv(argv: list[str]) -> bool:
    """Handle ``--modelscope <repo_id>`` and exit; otherwise return False."""

    if "--modelscope" not in argv:
        return False

    idx = argv.index("--modelscope")
    rest = argv[idx + 1 :]
    if not rest or rest[0].startswith("--"):
        print("Usage: python voice_edge.py --modelscope <org/model>", file=sys.stderr)
        raise SystemExit(2)

    model_name = rest[0]

    try:
        result = _download_modelscope_into_hf_cache(model_name)
    except (EOFError, KeyboardInterrupt):
        print("--modelscope cancelled", file=sys.stderr)
        raise SystemExit(1) from None
    except Exception as exc:
        print(f"--modelscope failed: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc
    raise SystemExit(result)


def _run_mi_list_from_argv(argv: list[str]) -> bool:
    try:
        parsed = _parse_mi_list_cli(argv)
        if parsed is None:
            return False
        result = asyncio.run(_run_mi_list_cli(*parsed))
    except Exception as exc:
        print(f"--mi-list failed: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc
    raise SystemExit(result)


def _prompt_mi_login_value(label: str, env_name: str, *, secret: bool = False) -> str:
    env_value = os.getenv(env_name, "").strip()
    prompt = f"{label} [{env_name}]: " if env_value else f"{label}: "
    if secret:
        from getpass import getpass

        entered = getpass(prompt)
    else:
        entered = input(prompt)
    value = str(entered or "").strip() or env_value
    if not value:
        raise RuntimeError(f"{env_name} was not provided")
    return value


async def _mi_login_otp_input(otp_method: str) -> str:
    code = await asyncio.to_thread(
        input,
        f"Xiaomi {otp_method} OTP: ",
    )
    code = str(code or "").strip()
    if not code:
        raise RuntimeError("Xiaomi OTP was not provided")
    return code


async def _run_mi_login_cli(username: str, password: str) -> int:
    token_path = Path.home() / ".mi.token"
    timeout = aiohttp.ClientTimeout(total=30, connect=10, sock_read=20)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        account = EmbeddedMiAccount(
            session,
            username,
            password,
            token_path,
            otp_callback=_mi_login_otp_input,
        )
        # Refresh both service tokens used by this script into the same store.
        for sid in ("xiaomiio", "micoapi"):
            if not await account.login(sid):
                raise RuntimeError(
                    account.login_error or f"Xiaomi login failed for sid={sid}"
                )
    print(f"Xiaomi login succeeded; tokens saved to {token_path}")
    return 0


def _run_mi_login_from_argv(argv: list[str]) -> bool:
    if "--mi-login" not in argv:
        return False
    if argv != ["--mi-login"]:
        print("Usage: python voice_edge.py --mi-login", file=sys.stderr)
        raise SystemExit(2)
    try:
        username = _prompt_mi_login_value("MI_USER", "MI_USER")
        password = _prompt_mi_login_value("MI_PASS", "MI_PASS", secret=True)
        result = asyncio.run(_run_mi_login_cli(username, password))
    except (EOFError, KeyboardInterrupt):
        print("--mi-login cancelled", file=sys.stderr)
        raise SystemExit(1) from None
    except Exception as exc:
        print(f"--mi-login failed: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc
    raise SystemExit(result)


_PROCESS_INSTANCE_LOCK_FD: int | None = None


def _validate_command_line(argv: list[str]) -> None:
    """Reject unknown options and unsupported option combinations before startup."""

    accepted = {"--http", "--self-test"}
    if not argv or (set(argv) <= accepted and len(argv) == len(set(argv))):
        return
    if argv in (
        ["--mi-login"],
        ["--ble-scan"],
        ["--ble-listen"],
        ["--fix-env-registry"],
    ):
        return
    if argv and argv[0] == "--mi-list" and 1 <= len(argv) <= 4:
        if not any(value.startswith("--") for value in argv[1:]):
            return
    if argv and argv[0] == "--modelscope" and len(argv) == 2:
        if not argv[1].startswith("--"):
            return
    print(
        "Usage:\n"
        "  python voice_edge.py [--http] [--self-test]\n"
        "  python voice_edge.py --mi-login\n"
        "  python voice_edge.py --mi-list [name_keyword|full] [false|true] [0|1]\n"
        "  python voice_edge.py --modelscope <org/model>\n"
        "  python voice_edge.py --ble-scan\n"
        "  python voice_edge.py --ble-listen\n"
        "  python voice_edge.py --fix-env-registry",
        file=sys.stderr,
    )
    raise SystemExit(2)


def _acquire_process_instance_lock() -> None:
    """Hold a non-blocking process lock so a second Voice Edge cannot start."""

    global _PROCESS_INSTANCE_LOCK_FD
    lock_path = Path(tempfile.gettempdir()) / f"voice-edge-{os.getuid()}.lock"
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        os.close(fd)
        print("Voice Edge is already running", file=sys.stderr)
        raise SystemExit(1) from None
    except BaseException:
        os.close(fd)
        raise
    os.ftruncate(fd, 0)
    os.write(fd, f"{os.getpid()}\n".encode("ascii"))
    _PROCESS_INSTANCE_LOCK_FD = fd


def _initialize_main_runtime() -> None:
    """Perform all process side effects after main() has selected its command."""
    _initialize_logging_and_preloads()
    _initialize_sounddevice()
    _validate_ffmpeg_runtime()
    _install_process_signal_handlers()
    _register_process_cleanup()


def main():
    global _main_event_loop

    # Validate and lock before any command initializes BLE, audio, models,
    # logging, browser runtimes, workers, or other process-wide resources.
    argv = sys.argv[1:]
    _validate_command_line(argv)

    if "--self-test" in sys.argv:
        run_self_tests()
        return

    if sys.argv[1:] == ["--fix-env-registry"]:
        raise SystemExit(_fix_env_registry_line_numbers(Path(__file__)))

    _run_ble_cli_from_argv(argv)
    _run_mi_login_from_argv(argv)
    _run_mi_list_from_argv(argv)

    os.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")

    _run_modelscope_from_argv(argv)

    os.environ.setdefault("HF_HUB_OFFLINE", "1")
    os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")

    _acquire_process_instance_lock()
    _initialize_main_runtime()

    try:
        _main_event_loop = asyncio.get_running_loop()
    except RuntimeError:
        _main_event_loop = asyncio.new_event_loop()
        asyncio.set_event_loop(_main_event_loop)

    class GracefulUvicornServer(uvicorn.Server):
        def install_signal_handlers(self):
            # 子线程中禁用 Uvicorn 信号处理，全部交给主线程
            pass

    validate_local_model_cache()

    start_llm_worker()
    start_llm_control_fifo_worker()
    ensure_auth_sync_native_host()
    AUTH_SYNC_SERVER.start()

    if M365_ENTRY_URL:
        try:
            M365_BROWSER_RUNTIME.start()
        except Exception:
            _m365_log.warning(
                "M365 bridge unavailable; other providers continue",
                exc_info=True,
            )
        else:
            _m365_log.info(
                "M365 bridge ready at ws://%s:%d/ws",
                M365_BRIDGE_HOST,
                M365_BRIDGE_PORT,
            )
    else:
        _m365_log.info("M365 bridge disabled because M365_ENTRY_URL is not configured")

    # 1. OpenAI-compatible HTTP gateway
    config = uvicorn.Config(
        app,
        host="127.0.0.1",
        port=HTTP_PORT,
        log_level="warning",
        timeout_graceful_shutdown=2,
        lifespan="off",
    )

    http_server = GracefulUvicornServer(config=config)

    def run_http_gateway():
        try:
            http_server.run()
        except Exception as e:
            _http_log.debug(f"HTTP gateway thread exited with error: {e}")

    http_thread = threading.Thread(target=run_http_gateway, daemon=False)
    http_thread.start()
    _http_log.info(f"🚀 HTTP API Gateway serving on port {HTTP_PORT}")

    # Optional Xiaomi bridge; disabled unless XIAOAI_ENABLED=1.
    start_xiaoai_bridge()

    # Optional local wake-word voice chat; disabled unless VE_VOICE_CHAT_ENABLED=1.
    start_voice_chat_subsystem()

    # 2. Keyboard listener / TTS consumer
    _start_quartz_keyboard_event_tap()
    _start_appkit_media_monitor()

    route_monitor_ok = start_audio_route_monitor()

    if not route_monitor_ok:
        _tts_log.warning(
            "CoreAudio route monitor is unavailable; "
            "TTS will use on-demand output recovery"
        )

    if not start_tts_async_loop():
        raise RuntimeError("Unable to start process-wide Edge-TTS asyncio loop")

    # voice chat 开启时不在启动阶段预启动 TTS consumer: consumer 启动会立即建
    # 44.1k 输出流, 而 voice chat 监听需要耳机停在 HFP(无输出流), 预启动只会
    # 造成"建了又被 stop"的竞态(启动日志里的 Cannot stop ... pending close)。
    # 改懒启动: speak_local_async / speak_local_sync_and_wait_result /
    # _nudge_audio_recovery 入口幂等调用 start_tts_consumer_worker()(已运行则直接
    # 返回), 首次播报前 consumer 启动并复用 voice chat 会话结束已恢复的输出流。
    if not VE_VOICE_CHAT_ENABLED:
        start_tts_consumer_worker()

    use_http = "--http" in sys.argv

    mcp_http_server = None
    mcp_http_thread = None

    try:
        if use_http:
            _http_log.info(
                f"⚡ Starting FastMCP ASGI Streamable HTTP on port {MCP_PORT}..."
            )

            mcp_asgi_app = _build_mcp_asgi_app()
            mcp_asgi_app = ShutdownSafeASGI(mcp_asgi_app, name="FastMCP")

            # 重要：
            # MCP ASGI app 不建议 lifespan='off'。
            # FastMCP 文档提到 Streamable HTTP 的 session manager 依赖 lifespan 初始化；
            # 如果你以后把 MCP app mount 到别的 Starlette app，也要传递其 lifespan_context。
            # 直接作为 Uvicorn app 运行时，保持 Uvicorn 默认 lifespan='auto' 即可。
            mcp_config = uvicorn.Config(
                mcp_asgi_app,
                host="127.0.0.1",
                port=MCP_PORT,
                log_level="warning",
                timeout_graceful_shutdown=5,
            )

            mcp_http_server = GracefulUvicornServer(config=mcp_config)

            def run_mcp_http():
                try:
                    mcp_http_server.run()
                except Exception as e:
                    _http_log.debug(f"MCP HTTP server thread exited with error: {e}")

            mcp_http_thread = threading.Thread(target=run_mcp_http, daemon=False)
            mcp_http_thread.start()

            _http_log.info(
                f"🔗 FastMCP ASGI server serving on http://127.0.0.1:{MCP_PORT}/mcp"
            )

            # 主线程保持存活，直到 Ctrl+C / SIGTERM
            while not _shutdown_complete.is_set():
                time.sleep(0.5)

        else:
            _app_log.info(
                "🔌 Starting FastMCP Server over STDIO (Claude Plugin Mode)..."
            )
            mcp.run()

    except (KeyboardInterrupt, SystemExit):
        _app_log.info("🛑 接收到终止信号，正在触发安全退出流...")

    except Exception as e:
        _http_log.error(f"❌ Server error: {e}")

    finally:
        _app_log.info("🧹 正在清理资源...")

        # 0. Stop the Xiaomi watcher/streams while the local OpenAI API is alive.
        try:
            stop_xiaoai_bridge()
        except Exception as e:
            _app_log.debug(f"stop_xiaoai_bridge ignored error: {e}")

        # Stop the local wake-word voice chat subsystem (no-op if disabled).
        try:
            stop_voice_chat_subsystem()
        except Exception as e:
            _app_log.debug(f"stop_voice_chat_subsystem ignored error: {e}")

        # 1. 进入 shutdown 状态：拒绝新的 tool call / stream
        SERVER_SHUTTING_DOWN.set()
        for provider_name, request_shutdown in (
            ("doubao", DOUBAO_RUNTIME.begin_shutdown),
            ("qwen", QWEN_BROWSER_RUNTIME.begin_shutdown),
            ("deepseek", DEEPSEEK_BROWSER_RUNTIME.begin_shutdown),
            ("m365", M365_BROWSER_RUNTIME.request_shutdown),
        ):
            _shutdown_log.debug("Shutdown signal stage: requesting %s", provider_name)
            completed, _result = _run_shutdown_call_bounded(
                f"{provider_name}-shutdown-request", request_shutdown, timeout=1.0
            )
            if not completed:
                _shutdown_log.error(
                    "Shutdown signal stage timed out for %s; continuing", provider_name
                )

        stop_tts_immediately(reason="server_shutdown")

        wake_llm_control_fifo()

        try:
            if LLM_CONTROL_THREAD and LLM_CONTROL_THREAD.is_alive():
                LLM_CONTROL_THREAD.join(timeout=2.0)
        except Exception:
            pass

        # End the BLE scanner and wake its persistent NDJSON responses before
        # asking Uvicorn to close connections. This mirrors the existing TTS
        # queue shutdown-marker pattern and lets StreamingResponse finish
        # normally instead of being cancelled at the graceful timeout.
        _stop_ble_remote_scanner()

        # 给流式 response / MCP session 一点时间看到 shutdown flag
        deadline = time.monotonic() + 1.0

        while (
            mcp_http_thread is not None
            and mcp_http_thread.is_alive()
            and time.monotonic() < deadline
        ):
            time.sleep(0.05)

        # 1. 先强制断开 FastMCP ASGI HTTP 长连接
        if mcp_http_server is not None:
            try:
                mcp_http_server.should_exit = True

                if mcp_http_thread is not None:
                    mcp_http_thread.join(timeout=6.0)

                    if mcp_http_thread.is_alive():
                        _http_log.warning(
                            "MCP HTTP server thread did not exit; force closing active connections"
                        )

                        # Last resort only. Do not cancel tasks.
                        _force_close_uvicorn_connections(
                            mcp_http_server,
                            cancel_tasks=False,
                        )

                        mcp_http_thread.join(timeout=2.0)

            except Exception as e:
                _http_log.debug(f"force close MCP uvicorn ignored error: {e}")

        # 2. 再关闭 OpenAI-compatible HTTP gateway
        try:
            _force_close_uvicorn_connections(
                http_server,
                cancel_tasks=False,
            )
        except Exception as e:
            _http_log.debug(f"force close HTTP gateway ignored error: {e}")

        try:
            http_server.should_exit = True
            http_thread.join(timeout=5.0)

            if http_thread.is_alive():
                _http_log.warning("HTTP gateway thread did not exit within timeout")
        except Exception as e:
            _http_log.debug(f"HTTP gateway shutdown ignored error: {e}")

        # 3. 清理应用资源
        _shutdown_log.debug("Main shutdown debug stage begin: cleanup_service")
        stage_started_at = time.monotonic()
        try:
            cleanup_service()
        except Exception as e:
            _shutdown_log.exception(
                "cleanup_service failed during main shutdown: %s", e
            )
        finally:
            _shutdown_log.debug(
                "Main shutdown debug stage end: cleanup_service elapsed=%.3fs",
                time.monotonic() - stage_started_at,
            )

        _shutdown_log.debug("Main shutdown debug stage begin: stop_llm_worker")
        stage_started_at = time.monotonic()
        try:

            def stop_llm_worker_for_shutdown() -> None:
                stop_llm_worker(timeout=1.0)

            completed, _ = _run_shutdown_call_bounded(
                "stop-llm-worker",
                stop_llm_worker_for_shutdown,
                timeout=1.5,
            )
            _shutdown_log.debug(
                "Main shutdown debug stage end: stop_llm_worker completed=%s elapsed=%.3fs",
                completed,
                time.monotonic() - stage_started_at,
            )
        except Exception as e:
            _shutdown_log.exception(
                "stop_llm_worker failed during main shutdown: %s", e
            )

        # 4. 不要 mass-cancel asyncio.all_tasks()
        try:
            if (
                _main_event_loop
                and not _main_event_loop.is_closed()
                and not _main_event_loop.is_running()
            ):
                _main_event_loop.close()
        except Exception as e:
            _app_log.debug(f"Loop close ignored error: {e}")

        _log_shutdown_thread_snapshot("main-finally-end")
        _app_log.info("✨ 服务器已完全关闭，所有资源均已释放。")


app = Starlette(
    routes=[
        Route("/", endpoint=home, methods=["GET"]),
        Route("/health", endpoint=health, methods=["GET"]),
        Route("/ble-remote/events", endpoint=ble_remote_events_api, methods=["GET"]),
        Route(
            "/internal/audio/runtime",
            endpoint=audio_runtime_status_api,
            methods=["GET"],
        ),
        Route("/v1/models", endpoint=models_list, methods=["GET"]),
        Route("/v1/models/{model_id:path}", endpoint=models_retrieve, methods=["GET"]),
        Route("/v1/audio/speech", endpoint=speech_api, methods=["POST"]),
        Route("/v1/audio/transcriptions", endpoint=transcribe_api, methods=["POST"]),
        Route("/v1/chat/completions", endpoint=chat_api, methods=["POST"]),
        Route("/v1/embeddings", endpoint=embeddings_api, methods=["POST"]),
        Route("/v1/rerank", endpoint=rerank_api, methods=["POST"]),
        Route("/v1/completions", endpoint=completions_api, methods=["POST"]),
        Route("/v1/fim/completions", endpoint=completions_api, methods=["POST"]),
        Route("/web", endpoint=web_search_api, methods=["POST"]),
    ],
    middleware=[
        Middleware(
            CORSMiddleware,
            allow_origins=["*"],
            allow_credentials=False,
            allow_methods=["*"],
            allow_headers=["*"],
        ),
    ],
)


# ==================== Main Entry ====================

if __name__ == "__main__":
    main()
